g directly."}, [55]={npc="Pilot Bellowfiz", tgt="Pilot Bellowfiz"}, [56]={npc="Father Gavin", tgt="Father Gavin"}, [57]={npc="Father Gavin", tgt="Father Gavin"}, [58]={hint="Collect 14 pieces of firewood."}, [59]={npc="Father Gavin", tgt="Father Gavin"}, [60]={npc="Father Gavin", tgt="Father Gavin"}, [61]={npc="Father Gavin", tgt="Father Gavin"}, [62]={hint="Collect the rifles of fallen mountaineers."}, [63]={hint="Destroy 10 minor ice elementals."}, [64]={npc="Father Gavin", tgt="Father Gavin"}, [65]={npc="Father Gavin", tgt="Father Gavin"}, [66]={npc="Father Gavin", tgt="Father Gavin"}, [67]={hint="Kill Avala and retrieve its core."}, [68]={npc="Father Gavin", tgt="Father Gavin"}, [69]={npc="Maxan Anvol", tgt="Maxan Anvol"}, [70]={npc="Maxan Anvol", tgt="Maxan Anvol", desc="Cast Lesser Heal and Power Word: Fortitude on the wounded mountaineers. Rewards cloth armor."}, [71]={hint="Find Mountaineer Dolf and heal his wounds using Lesser Heal (Rank 2). Afterwards, grant him Power Word: Fortitude and then return to Maxan Anvol in Kharanos.", desc="Cast Lesser Heal and Power Word: Fortitude on the wounded mountaineers. Rewards cloth armor."}, [72]={npc="Maxan Anvol", tgt="Maxan Anvol", desc="Cast Lesser Heal and Power Word: Fortitude on the wounded mountaineers. Rewards cloth armor."}}},
