    ["01-7"] = {tips={{k="交通", text="Skyborne starting area. Alliance and Horde share the island's starting quests and only split by faction when leaving the island.", s={{"Skyborne starting area. Alliance and Horde share the island's starting quests and only split by faction when leaving the island.", {race={"Skyborne"}}}}}}, grind={[1]={mob="Cirrusfly Soldier", note="The swarm on the east side of Thendal Grove; there are lots of them, and it's on your way to kill the queen."}, [2]={mob="Scrawny Ursera", note="The woods west of the watchtower; normal mobs that can be pulled one at a time."}}, steps={[1]={npc="Dalia the Collector", tgt="Ailee Farheart"}, [2]={npc="Ailee Farheart", tgt="Rorian the Dayseeker"}, [3]={npc="Ailee Farheart", tgt="Rorian the Dayseeker"}, [4]={npc="Falorne Fallwind", tgt="Elatrell Featherlight"}, [5]={hint="Slay 8 Vuldren Juveniles in Thendal Grove."}, [6]={hint="Slay 8 Pesky Cirrusflies in Thendal Grove."}, [7]={npc="Falorne Fallwind", tgt="Elatrell Featherlight"}, [8]={npc="Falorne Fallwind", tgt="Elatrell Featherlight"}, [9]={npc="Halaan Hawk-Eye", tgt="Halaan Hawk-Eye"}, [10]={npc="Halaan Hawk-Eye", tgt="Halaan Hawk-Eye"}, [11]={npc="Myriaal Mistwake", tgt="Myriaal Mistwake"}, [12]={hint="Jump from the top of the watchtower in Thendal Grove and use your Walk on Air ability to slow your fall.", desc="Use your Skyborne racial while jumping toward the Cirrusfly Queen."}, [13]={desc="If you're not level 3 yet, grind Cirrusfly Soldiers and Scrawny Ursera in Thendal Grove below the tower until you're 3."}, [14]={hint="Destroy the Cirrusfly Queen in Thendal Grove."}, [15]={npc="Falorne Fallwind", tgt="Elatrell Featherlight"}, [16]={npc="Ailee Farheart", tgt="Rorian the Dayseeker"}, [17]={npc="Ailee Farheart", tgt="Rorian the Dayseeker"}, [18]={npc="Ailee Farheart", tgt="Rorian the Dayseeker"}, [19]={npc="Rorian the Dayseeker", tgt="Rorian the Dayseeker"}, [20]={npc="Ailee Farheart", tgt="Rorian the Dayseeker"}, [21]={npc="Ailee Farheart", tgt=