    ["02-10"] = {steps={[1]={npc="Wizbang Cranktoggle", tgt="Wizbang Cranktoggle"}, [2]={npc="Gwennyth Bly'Leggonde", tgt="Gwennyth Bly'Leggonde"}, [3]={node="Auberdine"}, [4]={hint="Collect 6 Crawler Legs and place them in Buzzbox 827.", desc="Collect legs from level 9-10 Pygmy Tide Crawlers on the shore south of Auberdine. If you still need Washed Ashore, pick it up the next time you pass the docks at level 11 or above."}, [5]={hint="Recover Sea Creature Bones from the beached sea creature just south of Auberdine, and then return with it to Gwennyth Bly'Leggonde in Auberdine."}, [6]={npc="Buzzbox 827", npcObj=true}, [7]={npc="Buzzbox 827", npcObj=true}, [8]={npc="Gwennyth Bly'Leggonde", tgt="Gwennyth Bly'Leggonde"}, [9]={npc="Gwennyth Bly'Leggonde", tgt="Gwennyth Bly'Leggonde"}, [10]={hint="Bring 8 loads of Elunite Ore and the Medallion of Elura to Elanaria in Darnassus."}, [11]={npc="Cerellean Whiteclaw", tgt="Cerellean Whiteclaw"}, [12]={hint="Recover the Sea Turtle Remains from the Skeletal Sea Turtle in the waters west of Auberdine, and then speak with Gwennyth Bly'Leggonde back in Auberdine."}, [13]={hint="Collect 3 Thresher Eyes from Darkshore Threshers in the deep sea near Buzzbox 411."}, [14]={npc="Thundris Windweaver", tgt="Thundris Windweaver"}, [15]={npc="Thundris Windweaver", tgt="Thundris Windweaver"}, [16]={npc="Tharnariun Treetender", tgt="Tharnariun Treetender"}, [17]={npc="Terenthis", tgt="Terenthis"}, [18]={hint="Capture a living Rabid Thistle Bear and bring it back to Tharnariun."}, [19]={hint="Use the Cenarion Moondust on the Moonkin Stone of Auberdine to bring forth Lunaclaw. From there, you must face Lunaclaw and earn the strength of body and heart it possesses."}, [20]={npc="Asterion", tgt="Asterion"}, [21]={npc="Asterion", tgt="Asterion"}, [22]={hint="Acquire 8 Grell Earrings for Asterion in Bashal'Aran."}, [23]={npc="Asterion", tgt="Asterion"}, [24]={npc="Asterion", tgt="Asterion"}, [25]={hint="Obtain the Ancient Moonstone Seal and bring i