    ["05-d1"] = {name="The Hall of Thanes", entrance="Ironforge 27.63, 47.83", pickup="On your way through Dun Morogh and Loch Modan, pick up the pre-dungeon quests first; there's no need to backtrack just before entering. Skyborne skip {s:01-9}: on your first visit to Ironforge, head east to Dun Morogh to find Earthseer Farsen, finish Farsen's Watch, Nip 'Em in the Bud and Underground Map, then return to Ironforge. If you'd rather not detour, skip the Old Ironforge Incursion.", pickupS={{"On your way through Dun Morogh and Loch Modan, pick up the pre-dungeon quests first; there's no need to backtrack just before entering"}, {"Skyborne skip {s:01-9}: on your first visit to Ironforge, head east to Dun Morogh to find Earthseer Farsen, finish Farsen's Watch, Nip 'Em in the Bud and Underground Map, then return to Ironforge", {race={"Skyborne"}}}, {"If you'd rather not detour, skip the Old Ironforge Incursion"}}, steps={[1]={npc="Dark Iron Map", npcObj=true, tag="Dungeon prereq"}, [2]={npc="Earthseer Farsen", tgt="Earthseer Farsen", tag="Dungeon prereq"}, [3]={npc="Earthseer Farsen", tgt="Earthseer Farsen"}, [4]={npc="Afadra Dunwall", tgt="Afadra Dunwall"}, [5]={npc="Thom Filch", tgt="Thom Filch"}, [6]={text="The Hall of Thanes entrance"}, [7]={npc="Ghostly Attendant", tgt="Ghostly Attendant"}, [8]={hint="Put the spirit of Faldrim Anvilmar to rest and then return to the Ghostly Attendant in the Hall of Thanes."}, [9]={npc="Ghostly Attendant", tgt="Ghostly Attendant"}, [10]={hint="Kill 15 Enraged Apparitions, 10 Tormented Souls and put the spirit of Anvilmar to rest."}, [11]={hint="Collect 8 Dwarven Heirlooms from the Hall of Thanes."}, [12]={hint="Enter the Hall of Thanes beneath Old Ironforge and claim the Head of Durgen Dirgehammer."}, [13]={npc="Treaty of Understanding", npcObj=true, desc="Right-click Treaty of Understanding in your bags to start the quest. The last boss fears at about 35% health. Clear the adds first, then pull the boss back into the previous room. There's a lever next to the quest giver. Pull it to open the door and run straight out."}, [14]={npc="Thom Filch", tgt="Thom Filch"}, [15]={npc="Afadra Dunwall", tgt="Afadra Dunwall"}, [16]={npc="King Magni Bronzebeard", tgt="King Magni Bronzebeard"}, [17]={npc="King Magni Bronzebeard", tgt="King Magni Bronzebeard"}}},
    ["02-12"] = {steps={[1]={npc="Gryth Thurden", tgt="Gryth Thurden"}, [2]={node="Ironforge"}, [3]={to="Thelsamar"}, [4]={text="Leave Ironforge and follow the road east, pass through the tunnel in the eastern pass into Loch Modan, then follow the road northeast to Thelsamar.", tag="Flight path locked. Travel there on foot the first time."}, [5]={node="Thelsamar"}, [6]={npc="Mountaineer Kadrell", tgt="Mountaineer Kadrell", desc="Mountaineer Kadrell walks back and forth along the Thelsamar road (32.6, 49.7 to 36.8, 42.0). If he isn't here, follow the road."}, [7]={npc="Mountaineer Ylva", tgt="Mountaineer Ylva"}, [8]={hint="Mountaineer Gravelgaw in the southern guard tower wants you to kill 10 Stonesplinter Skullthumpers and 10 Stonesplinter Seers and report back to him."}, [9]={hint="Raise the standard of Ironforge, call out the trogg Headsplitter and kill it, then report to Captain Rugelfuss."}, [10]={npc="Mountaineer Gravelgaw", tgt="Mountaineer Gravelgaw"}, [11]={npc="Mountaineer Wallbang", tgt="Mountaineer Wallbang"}, [12]={hint="Mountaineer Wallbang in the southern guard tower wants you to kill 10 Stonesplinter Shaman and 10 Stonesplinter Bonesnappers."}, [13]={npc="Mountaineer Wallbang", tgt="Mountaineer Wallbang"}, [14]={npc="Captain Rugelfuss", tgt="Captain Rugelfuss"}, [15]={hint="Take the Symbol of Life and resurrect Narm Faulk in Dun Morogh."}, [16]={npc="Narm Faulk", tgt="Narm Faulk"}, [17]={npc="Narm Faulk", tgt="Narm Faulk"}, [18]={hint="Retrieve a Dark Iron Script from the Dark Iron dwarves near Helm's Bed, and return to Muiredon Battleforge in Ironforge."}, [19]={npc="Muiredon Battleforge", tgt="Muiredon Battleforge"}, [20]={npc="Muiredon Battleforge", tgt="Muiredon Battleforge", desc="Turn in to learn Redemption."}, [21]={npc="Tiza Battleforge", tgt="Tiza Battleforge", desc="Turn in to learn Redemption."}, [22]={npc="Jern Hornhelm", tgt="Jern Hornhelm"}, [23]={npc="Brock Stoneseeker", tgt="Brock Stoneseeker"}, [24]={npc="Magmar Fellhew", tgt="Magmar Fellhew"}, [25]={npc="Magmar Fellhew", tgt="Magmar Fellhew"}, [26]={npc="Prospector Ironband", tgt="Prospector Ironband"}, [27]={npc="Daryl the Youngling", tgt="Daryl the Youngling"}, [28]={hint="Kill 6 Mountain Buzzards and return to Daryl the Youngling in the Farstrider Lodge within 15 minutes."}, [29]={npc="Daryl the Youngling", tgt="Daryl the Youngling"}, [30]={npc="Daryl the Youngling", tgt="Daryl the Youngling"}, [31]={hint="Kill 5 Elder Mountain Boars and return to Daryl the Youngling in the Farstrider Lodge within 12 minutes."}, [32]={npc="Daryl the Youngling", tgt="Daryl the Youngling"}, [33]={npc="Marek Ironheart", tgt="Marek Ironheart"}, [34]={npc="Marek Ironheart", tgt="Marek Ironheart"}, [35]={npc="Bingles Blastenheimer", tgt="Bingles Blastenheimer"}, [36]={npc="Bingles Blastenheimer", tgt="Bingles Blastenheimer"}, [37]={hint="Find and defeat the crocolisk Daggerfang and bring back Marek's knife."}, [38]={hint="Get 5 pieces of Crocolisk Meat and 6 Crocolisk Skins for Marek Ironheart at the Farstrider Lodge."}, [39]={hint="Find and return Bingles' supplies:"}, [40]={npc="Chief Engineer Hinderweir VII", tgt="Chief Engineer Hinderweir VII"}, [41]={npc="Suspicious Barrel", npcObj=true}, [42]={npc="Suspicious Barrel", npcObj=true}, [43]={npc="Chief Engineer Hinderweir VII", tgt="Chief Engineer Hinderweir VII"}, [44]={npc="Mountaineer Stormpike", tgt="Mountaineer Stormpike", desc="From the dam, follow the northern road west to the outpost at the pass."}, [45]={npc="Bingles Blastenheimer", tgt="Bingles Blastenheimer"}, [46]={npc="Marek Ironheart", tgt="Marek Ironheart"}, [47]={npc="Marek Ironheart", tgt="Marek Ironheart"}, [48]={hint="Bring Magmar Fellhew 8 Carved Stone Idols."}, [49]={npc="Magmar Fellhew", tgt="Magmar Fellhew"}, [50]={npc="Jern Hornhelm", tgt="Jern Hornhelm"}, [51]={npc="Jern Hornhelm", tgt="Jern Hornhelm"}, [52]={bind="Stormwind"}, [53]={npc="Argos Nightwhisper", tgt="Argos Nightwhisper"}, [54]={to="Auberdine", from="Stormwind", desc="Board at the pier in Stormwind Harbor."}}},
    ["02-13"] = {steps={[1]={npc="Gubber Blump", tgt="Gubber Blump"}, [2]={npc="WANTED: Murkdeep!", npcObj=true}, [3]={npc="Archaeologist Hollee", tgt="Archaeologist Hollee"}, [4]={npc="Archaeologist Hollee", tgt="Archaeologist Hollee"}, [5]={npc="Thundris Windweaver", tgt="Thundris Windweaver"}, [6]={npc="Gorbold Steelhand", tgt="Gorbold Steelhand"}, [7]={npc="Gorbold Steelhand", tgt="Gorbold Steelhand"}, [8]={npc="Gershala Nightwhisper", tgt="Gershala Nightwhisper"}, [9]={npc="Terenthis", tgt="Terenthis"}, [10]={npc="Terenthis", tgt="Terenthis"}, [11]={npc="Mysterious Red Crystal", npcObj=true}, [12]={npc="Mysterious Red Crystal", npcObj=true}, [13]={npc="Asterion", tgt="Asterion"}, [14]={npc="Beached Sea Creature", npcObj=true}, [15]={hint="Recover the Silver Dawning's Lockbox and the Mist Veil's Lockbox for Gorbold Steelhand in Auberdine. Both items should be found aboard the wreckage of the ships to the north of the village."}, [16]={npc="Buzzbox 411", npcObj=true}, [17]={npc="Buzzbox 411", npcObj=true}, [18]={npc="Beached Sea Turtle", npcObj=true}, [19]={text="Jump into the river here and swim to the pool below the waterfall. From here on, kill any Moonstalker Runts and Rabid Thistle Bears you see."}, [20]={hint="Travel north of Auberdine to the first waterfall along the Cliffspring River and draw a sample from the pool there."}, [21]={hint="Collect 6 Fine Crab Chunks for Gubber Blump in Auberdine."}, [22]={npc="Beached Sea Turtle", npcObj=true}, [23]={npc="Balthule Shadowstrike", tgt="Balthule Shadowstrike"}, [24]={npc="Balthule Shadowstrike", tgt="Balthule Shadowstrike"}, [25]={hint="Collect 4 Worn Parchments for Balthule Shadowstrike near the Tower of Althalaxx."}, [26]={npc="Balthule Shadowstrike", tgt="Balthule Shadowstrike"}, [27]={npc="Balthule Shadowstrike", tgt="Balthule Shadowstrike"}, [28]={hint="Cleanse the forest of 20 Rabid Thistle Bears and return to Tharnariun Treetender in Darkshore."}, [29]={hint="Collect 6 Moonstalker Fangs and place them in Buzzbox 323."}, [30]={hint="Bring 5 Scaber Stalks and 1 Death Cap to Barithras Moonshade in Auberdine."}, [31]={npc="Buzzbox 323", npcObj=true}, [32]={npc="Buzzbox 323", npcObj=true}, [33]={npc="Tharnariun Treetender", tgt="Tharnariun Treetender"}, [34]={npc="Tharnariun Treetender", tgt="Tharnariun Treetender"}, [35]={npc="Gorbold Steelhand", tgt="Gorbold Steelhand"}, [36]={npc="Thundris Windweaver", tgt="Thundris Windweaver"}, [37]={npc="Thundris Windweaver", tgt="Thundris Windweaver"}, [38]={npc="Sentinel Glynda Nal'Shea", tgt="Sentinel Glynda Nal'Shea"}, [39]={npc="Barithras Moonshade", tgt="Barithras Moonshade", desc="Fill the Empty Cleansing Bowl at the moonwell."}, [40]={npc="Barithras Moonshade", tgt="Barithras Moonshade"}, [41]={npc="Gwennyth Bly'Leggonde", tgt="Gwennyth Bly'Leggonde"}, [42]={npc="Gwennyth Bly'Leggonde", tgt="Gwennyth Bly'Leggonde"}, [43]={npc="Gwennyth Bly'Leggonde", tgt="Gwennyth Bly'Leggonde"}, [44]={npc="Gubber Blump", tgt="Gubber Blump"}, [45]={npc="Beached Sea Creature", npcObj=true}, [46]={npc="Beached Sea Creature", npcObj=true, desc="The event only triggers near the campfire. Do it now or when the route passes by again later."}, [47]={npc="Beached Sea Turtle", npcObj=true}, [48]={npc="Beached Sea Turtle", npcObj=true}, [49]={npc="Beached Sea Creature", npcObj=true}, [50]={npc="Sentinel Aynasha", tgt="Sentinel Aynasha", desc="On the way to the next quest, kill any Moonstalker Sire you see (the runts and matriarch will come with it)."}, [51]={hint="Protect Sentinel Aynasha, then speak with Onaeya at Maestra's Post in Ashenvale."}, [52]={npc="Onu", tgt="Onu"}, [53]={npc="Onu", tgt="Onu"}, [54]={npc="Scrying Bowl", npcObj=true, desc="Go to 39.2, 86.9 and use the vial Onu gave you to place it on the ground."}, [55]={npc="Scrying Bowl", npcObj=true}, [56]={npc="Twilight Tome", npcObj=true}, [57]={npc="Twilight Tome", npcObj=true}, [58]={npc="Twilight Tome", npcObj=true}, [59]={hint="Obtain a Peerless Eye from a Twilight Disciple or Thug at the Master's Glaive in Darkshore and find someone in Auberdine who is willing to take it."}, [60]={npc="Therylune", tgt="Therylune", desc="Escort quest: in a group, wait until everyone is at the same step before accepting, and turn off auto-accept."}, [61]={hint="Help Therylune escape, then tell Therysil at the Shrine of Aessina that her sister is safe."}, [62]={npc="Book: The Powers Below", npcObj=true, tag="Optional", desc="Right-click Book: The Powers Below in your bags to start the quest. Mobs in the pit have a low chance to drop Book: The Powers Below. Only accept it if it drops."}, [63]={npc="Prospector Remtravel", tgt="Prospector Remtravel", desc="Escort quest: in a group, wait until everyone is at the same step before accepting, and turn off auto-accept. Let Prospector Remtravel run ahead, and only fight mobs that attack him first."}, [64]={npc="Prospector Remtravel", tgt="Prospector Remtravel"}, [65]={hint="Protect Prospector Remtravel as he searches for the mysterious fossil, then return to Archaeologist Hollee in Auberdine."}, [66]={hint="Collect 4 Grizzled Scalps from Grizzled Thistle Bears to the south of Auberdine and place them in Buzzbox 525."}, [67]={npc="Buzzbox 525", npcObj=true}, [68]={hint="Find 5 Fine Moonstalker Pelts and return them to Terenthis in Auberdine."}, [69]={npc="Onu", tgt="Onu"}, [70]={npc="Onu", tgt="Onu"}, [71]={npc="Arbal", tgt="Arbal"}, [72]={hint="Find and slay the murloc known as Murkdeep. The creature is thought to be defending the murloc huts south of Auberdine along the water.", desc="Several waves of murlocs come, 2-3 per wave. Pull the last murloc of each wave away from the campfire before killing it, eat and drink, then pull the next wave. Or find a group."}, [73]={npc="Gwennyth Bly'Leggonde", tgt="Gwennyth Bly'Leggonde"}, [74]={npc="Gwennyth Bly'Leggonde", tgt="Gwennyth Bly'Leggonde"}, [75]={npc="Gwennyth Bly'Leggonde", tgt="Gwennyth Bly'Leggonde"}, [76]={npc="Gwennyth Bly'Leggonde", tgt="Gwennyth Bly'Leggonde"}, [77]={npc="Gwennyth Bly'Leggonde", tgt="Gwennyth Bly'Leggonde"}, [78]={npc="Gwennyth Bly'Leggonde", tgt="Gwennyth Bly'Leggonde"}, [79]={npc="Sentinel Glynda Nal'Shea", tgt="Sentinel Glynda Nal'Shea"}, [80]={npc="Archaeologist Hollee", tgt="Archaeologist Hollee"}, [81]={npc="Archaeologist Hollee", tgt="Archaeologist Hollee"}, [82]={npc="Thundris Windweaver", tgt="Thundris Windweaver"}, [83]={npc="Terenthis", tgt="Terenthis"}, [84]={npc="Terenthis", tgt="Terenthis"}, [85]={to="Rut'theran Village", from="Auberdine"}, [86]={to="Rut'theran Village"}, [87]={npc="Nessa Shadowsong", tgt="Nessa Shadowsong"}, [88]={text="Step into the portal in Rut'theran Village to Darnassus."}, [89]={npc="Chief Archaeologist Greywhisker", tgt="Chief Archaeologist Greywhisker"}, [90]={npc="Chief Archaeologist Greywhisker", tgt="Chief Archaeologist Greywhisker"}, [91]={npc="Elanaria", tgt="Elanaria"}, [92]={npc="Elanaria", tgt="Elanaria"}, [93]={npc="Mathiel", tgt="Mathiel"}, [94]={npc="Mathiel", tgt="Mathiel", desc="Rewards an Elunite weapon."}, [95]={npc="Mathiel", tgt="Mathiel", desc="Rewards an Elunite weapon."}, [96]={npc="Mathrengyl Bearwalker", tgt="Mathrengyl Bearwalker", desc="After finishing Body and Heart at the Moonkin Stone in Auberdine, return to Darnassus to turn in and learn Bear Form."}, [97]={npc="Mathrengyl Bearwalker", tgt="Mathrengyl Bearwalker", tag="You can buy 5 Earthroot at the Auction House now, or have an alt mail it (for Gathering the Cure later)."}, [98]={npc="Dendrite Starblaze", tgt="Dendrite Starblaze"}, [99]={npc="Dendrite Starblaze", tgt="Dendrite Starblaze"}, [100]={hint="Use the Empty Cliffspring Falls Sampler to draw a sample of water from the mouth of the cave by the falls.", desc="Take the druid-only flight from Nighthaven to Rut'theran Village, then fly to Auberdine."}, [101]={npc="Alanndarian Nightsong", tgt="Alanndarian Nightsong"}, [102]={npc="Alanndarian Nightsong", tgt="Alanndarian Nightsong", desc="Gather Earthroot and Lunar Fungus in Darkshore, then turn them in at Auberdine. Earthroot ×5 can be bought at the Auction House."}, [103]={hint="Bring 5 Earthroot and 12 Lunar Funguses to Alanndarian Nightsong in Auberdine so she may make a curative salve.", desc="Gather Earthroot and Lunar Fungus in Darkshore, then turn them in at Auberdine."}, [104]={npc="Alanndarian Nightsong", tgt="Alanndarian Nightsong", desc="Gather Earthroot and Lunar Fungus in Darkshore, then turn them in at Auberdine."}, [105]={npc="Alanndarian Nightsong", tgt="Alanndarian Nightsong", desc="Use the cure on the sick deer in Darkshore."}, [106]={hint="Use the Curative Animal Salve on 10 Sickly Deer that are located throughout Darkshore; doing so should cure them. Sickly Deer have been reported starting south of the Cliffspring River to the north of Auberdine and extending all the way into southern Darkshore where the edge of Ashenvale begins.", desc="Use the cure on the sick deer in Darkshore."}, [107]={npc="Dendrite Starblaze", tgt="Dendrite Starblaze", desc="After curing 10 deer, use Teleport: Moonglade to go back and turn in."}, [108]={npc="Dendrite Starblaze", tgt="Dendrite Starblaze", desc="Turn in to learn Cure Poison."}, [109]={npc="Mathrengyl Bearwalker", tgt="Mathrengyl Bearwalker", desc="Turn in the quest to learn Cure Poison. Take the druid-only flight from Nighthaven to Rut'theran Village, then use the portal in the village to enter Darnassus."}, [110]={npc="Mathrengyl Bearwalker", tgt="Mathrengyl Bearwalker"}, [111]={npc="Dendrite Starblaze", tgt="Dendrite Starblaze"}, [112]={npc="Dendrite Starblaze", tgt="Dendrite Starblaze", desc="Find the Shrine Bauble at the bottom of Lake Elune'ara."}, [113]={hint="Find a Shrine Bauble in Lake Elune'ara, and take it to the Shrine of Remulos in northwestern Moonglade. Once there, use the Shrine Bauble.", desc="Find the Shrine Bauble at the bottom of Lake Elune'ara."}, [114]={npc="Tajarri", tgt="Tajarri", desc="Find the Shrine Bauble at the bottom of Lake Elune'ara."}, [115]={npc="Tajarri", tgt="Tajarri", desc="The two strange locked chests each hold half of a pendant: one is on the sea floor north of Auberdine in Darkshore, the other is on the sea floor off the northwest coast of Westfall."}, [116]={hint="Find the Half Pendant of Aquatic Agility and the Half Pendant of Aquatic Endurance. Speak with the residents of Moonglade to learn clues as to where these items may be located.", desc="Take the druid-only flight from Nighthaven to Rut'theran Village, fly to Auberdine, and swim north to the locked chest on the sea floor. Then take the boat from Auberdine to Stormwind, fly to Sentinel Hill, and head northwest to the coast and dive in to open the other locked chest."}, [117]={text="Once you have both halves, use Teleport: Moonglade to go back and combine the pendant halves near the Shrine of Remulos."}, [118]={npc="Dendrite Starblaze", tgt="Dendrite Starblaze"}, [119]={npc="Dendrite Starblaze", tgt="Dendrite Starblaze", desc="Turn in to learn Aquatic Form."}, [120]={npc="Mathrengyl Bearwalker", tgt="Mathrengyl Bearwalker", desc="Turn in the quest to learn Aquatic Form. Take the druid-only flight from Nighthaven to Rut'theran Village, then use the portal in the village to enter Darnassus."}, [121]={text="Step into the portal in Darnassus back to Rut'theran Village."}, [122]={node="Rut'theran Village"}, [123]={to="Auberdine"}, [124]={hint="Find and kill the Den Mother."}, [125]={hint="Fill the Empty Cleansing Bowl at the Auberdine Moonwell."}, [126]={hint="Bring 6 Mathystra Relics to Onu at the Grove of the Ancients."}, [127]={hint="Eliminate 12 Stormscale Myrmidons, 8 Stormscale Sorceresses, and 6 Stormscale Warriors for Arbal at the Grove of the Ancients."}, [128]={hint="Find a Stormscale Beastmistress, slay her, and bring back her Rod of Deep Dominion."}, [129]={bind="Stormwind"}}},
    ["05-d2"] = {name="Ruins of Lordaeron", entrance="Undercity 72.41, 11.37", steps={[1]={text="Optional, far-off quest: the entrance is in the Ruins of Lordaeron above Undercity, which means crossing Horde territory. From Auberdine, sail first to Menethil Harbor, then take the northern boat route to Southshore. Get off there and unlock its flight point, then go north through Hillsbrad Foothills and Silverpine Forest to Tirisfal Glades. After the dungeon, hearth back to Stormwind and rejoin {s:02-14}.", tag="Optional"}, [2]={text="Ruins of Lordaeron entrance"}, [3]={}, [4]={npc="Bloodied Insignia", npcObj=true, tag="If it drops, Optional", desc="Right-click Bloodied Insignia in your bags to start the quest."}, [5]={hint="Collect 10 Bloodied Insignias and take them to General Marcus Jonathan in Stormwind City.", tag="Optional"}, [6]={npc="Crest of Lordaeron", npcObj=true, desc="Right-click Crest of Lordaeron in your bags to start the quest."}, [7]={npc="Blood-Stained Parchment", npcObj=true, desc="Right-click Blood-Stained Parchment in your bags to start the quest."}, [8]={}, [9]={npc="Orphan Matron Nightingale", tgt="Orphan Matron Nightingale"}, [10]={npc="Lady Dena Kennedy", tgt="Lady Dena Kennedy"}, [11]={npc="General Marcus Jonathan", tgt="General Marcus Jonathan", tag="Optional"}}},
    ["02-14"] = {grind={[1]={mob="Redridge Basher", note="Gnoll camp north of Lakeshire; normal mobs, close to the flight path."}, [2]={mob="Blackrock Outrunner", note="Blackrock orcs on the northeast shore of Lake Everstill; a better level match, with grunts mixed in, so pull from the edge."}}, steps={[1]={npc="Renzik The Shiv", tgt="Renzik The Shiv"}, [2]={npc="High Priestess Laurena", tgt="High Priestess Laurena", desc="Accept it in Stormwind, turn it in at Ironforge and learn Fear Ward."}, [3]={npc="High Priest Rohan", tgt="High Priest Rohan", desc="Accept it in Stormwind, turn it in at Ironforge and learn Fear Ward."}, [4]={text="Take the Deeprun Tram from Ironforge back to Stormwind."}, [5]={npc="High Priestess Laurena", tgt="High Priestess Laurena", desc="Accept it in Stormwind and turn it in at Dun Morogh."}, [6]={npc="High Priestess Mims", tgt="High Priestess Mims", desc="Accept it in Stormwind and turn it in at Dun Morogh."}, [7]={text="Return to Ironforge and take the Deeprun Tram to Stormwind."}, [8]={npc="Jennea Cannon", tgt="Jennea Cannon", desc="The Blue Recluse tavern is in the Mage Quarter of Stormwind."}, [9]={componentNpc="Rift Spawn", hint="At the Blue Recluse in Stormwind's Mage Quarter, use the cantation. Weaken a Rift Spawn until stunned, use the chest, then loot the coffer on the ground. Collect three.", desc="The Blue Recluse tavern is in the Mage Quarter of Stormwind."}, [10]={npc="Jennea Cannon", tgt="Jennea Cannon", desc="The Blue Recluse tavern is in the Mage Quarter of Stormwind."}, [11]={npc="Jennea Cannon", tgt="Jennea Cannon", desc="Bring 10 Linen Cloth and 6 Charged Rift Gems. On a later visit to Loch Modan, enter Silver Stream Mine from the north (about 35.9,18.2) and open the miners' chests. Continue your route while short on materials. Visit Wynne in Stormwind when your journal shows the quest is ready."}, [12]={npc="Wynne Larson", tgt="Wynne Larson", desc="Bring 10 Linen Cloth and 6 Charged Rift Gems. On a later visit to Loch Modan, enter Silver Stream Mine from the north (about 35.9,18.2) and open the miners' chests. Continue your route while short on materials. Visit Wynne in Stormwind when your journal shows the quest is ready."}, [13]={npc="Wynne Larson", tgt="Wynne Larson", desc="Rewards Manaweave Robe."}, [14]={npc="Wynne Larson", tgt="Wynne Larson", desc="Rewards Manaweave Robe."}, [15]={npc="Gakin the Darkbinder", tgt="Gakin the Darkbinder"}, [16]={npc="Takar the Seer", tgt="Takar the Seer", desc="Take the boat from Stormwind harbor to Auberdine, follow the Darkshore coast south into Ashenvale, then enter the Barrens from the east through Mor'shan Rampart and head south to find Takar. The Crossroads and Camp Taurajo are Horde strongholds; go around them."}, [17]={npc="Takar the Seer", tgt="Takar the Seer"}, [18]={npc="Takar the Seer", tgt="Takar the Seer"}, [19]={hint="Retrieve the Heartswood from Ashenvale and bring it to Gakin the Darkbinder in the Mage Quarter of Stormwind.", desc="Clear the monsters by the tree first, then click that Cenarion tree to get the heartswood."}, [20]={hint="Retrieve the Wooden Figurine and bring it to Gakin the Darkbinder in the Mage Quarter of Stormwind."}, [21]={npc="Gakin the Darkbinder", tgt="Gakin the Darkbinder", desc="After finishing Ashenvale, hearth back to Stormwind. If your Hearthstone is on cooldown, head north back to Auberdine and take the boat to Stormwind."}, [22]={npc="Gakin the Darkbinder", tgt="Gakin the Darkbinder"}, [23]={npc="Gakin the Darkbinder", tgt="Gakin the Darkbinder", desc="Use it at the summoning circle next to Gakin the Darkbinder and defeat the summoned succubus."}, [24]={hint="Using the Heartswood Core, summon and subdue a succubus, then return the Heartswood Core to Gakin the Darkbinder in the Slaughtered Lamb.", desc="Use it at the summoning circle next to Gakin the Darkbinder and defeat the summoned succubus."}, [25]={npc="Gakin the Darkbinder", tgt="Gakin the Darkbinder", desc="Use it at the summoning circle next to Gakin the Darkbinder and defeat the summoned succubus."}, [26]={npc="Gakin the Darkbinder", tgt="Gakin the Darkbinder"}, [27]={hint="Using the Wooden Figurine, summon and subdue an incubus, then return the Wooden Figurine to Gakin the Darkbinder in the Slaughtered Lamb."}, [28]={npc="Gakin the Darkbinder", tgt="Gakin the Darkbinder"}, [29]={text="From Stormwind, follow the Elwynn Forest road east; first go to the Tower of Azora and get A Watchful Eye from Theocritus; then continue east to the Redridge Mountains entrance to find Guard Parker, and follow the road into Lakeshire.", tag="Flight path locked. Travel there on foot the first time., Before heading to Redridge, you can buy 8 Murloc Fin (for Murloc Poachers) at the Auction House, or have an alt mail them."}, [30]={npc="Theocritus", tgt="Theocritus"}, [31]={npc="Guard Parker", tgt="Guard Parker"}, [32]={to="Lakeshire", tag="Before heading to Redridge, you can buy 8 Murloc Fin (for Murloc Poachers) at the Auction House, or have an alt mail them.", desc="If you haven't unlocked the Lakeshire flight point, walk east from Stormwind along the Elwynn Forest road to Lakeshire."}, [33]={npc="Guard Parker", tgt="Guard Parker", desc="Guard Parker is at the junction on the main road west of Redridge that leads to Elwynn Forest."}, [34]={npc="Darcy", tgt="Darcy"}, [35]={npc="Wiley the Black", tgt="Wiley the Black"}, [36]={npc="Wiley the Black", tgt="Wiley the Black"}, [37]={npc="Dockmaster Baren", tgt="Dockmaster Baren"}, [38]={npc="Dockmaster Baren", tgt="Dockmaster Baren", desc="Murloc Fin can be bought at the Auction House. With 8 you can skip the farming."}, [39]={npc="Magistrate Solomon", tgt="Magistrate Solomon"}, [40]={npc="Verner Osgood", tgt="Verner Osgood"}, [41]={npc="Deputy Feldon", tgt="Deputy Feldon"}, [42]={npc="Deputy Feldon", tgt="Deputy Feldon"}, [43]={npc="Deputy Feldon", tgt="Deputy Feldon"}, [44]={npc="Lucius", tgt="Lucius"}, [45]={npc="Lucius", tgt="Lucius", desc="Use Pick Lock on the chest near A