    ["05-d3"] = {name="The Deadmines", entrance="Westfall 42.50, 71.70", pickup="On your first Redridge visit, after you hand in the escort back in Westfall, pick up The Defias Brotherhood and Red Silk Bandanas at Sentinel Hill. On your last return to Stormwind, pick up Underground Assault, Oh Brother... and Collecting Memories, so you don't need a special trip before the dungeon.", pickupS={{"On your first Redridge visit, after you hand in the escort back in Westfall, pick up The Defias Brotherhood and Red Silk Bandanas at Sentinel Hill"}, {"On your last return to Stormwind, pick up Underground Assault, Oh Brother... and Collecting Memories, so you don't need a special trip before the dungeon"}}, steps={[1]={npc="Gryan Stoutmantle", tgt="Gryan Stoutmantle", tag="Dungeon prereq"}, [2]={npc="Wiley the Black", tgt="Wiley the Black", tag="Dungeon prereq"}, [3]={npc="Wiley the Black", tgt="Wiley the Black", tag="Dungeon prereq"}, [4]={npc="Gryan Stoutmantle", tgt="Gryan Stoutmantle", tag="Dungeon prereq"}, [5]={npc="Gryan Stoutmantle", tgt="Gryan Stoutmantle", tag="Dungeon prereq"}, [6]={npc="Master Mathias Shaw", tgt="Master Mathias Shaw", tag="Dungeon prereq"}, [7]={npc="Master Mathias Shaw", tgt="Master Mathias Shaw", tag="Dungeon prereq"}, [8]={npc="Gryan Stoutmantle", tgt="Gryan Stoutmantle", tag="Dungeon prereq"}, [9]={npc="Gryan Stoutmantle", tgt="Gryan Stoutmantle", tag="Dungeon prereq"}, [10]={hint="Track down the Defias Messenger in Westfall and bring his message to Stoutmantle.", tag="Dungeon prereq"}, [11]={npc="Gryan Stoutmantle", tgt="Gryan Stoutmantle", tag="Dungeon prereq"}, [12]={npc="The Defias Traitor", tgt="The Defias Traitor", tag="Dungeon prereq"}, [13]={npc="Gryan Stoutmantle", tgt="Gryan Stoutmantle", tag="Dungeon prereq"}, [14]={npc="Gryan Stoutmantle", tgt="Gryan Stoutmantle"}, [15]={npc="Scout Riell", tgt="Scout Riell"}, [16]={npc="Alba Fairmoon", tgt="Alba Fairmoon", tag="Dungeon prereq"}, [17]={hint="Use the Well Water Sample Kit to collect 