    ["02-15"] = {steps={[1]={to="Lakeshire"}, [2]={npc="Marshal Marris", tgt="Marshal Marris"}, [3]={npc="Marshal Marris", tgt="Marshal Marris"}, [4]={npc="Foreman Oslow", tgt="Foreman Oslow"}, [5]={npc="Verner Osgood", tgt="Verner Osgood"}, [6]={npc="Verner Osgood", tgt="Verner Osgood"}, [7]={npc="Verner Osgood", tgt="Verner Osgood"}, [8]={npc="Guard Berton", tgt="Guard Berton", tag="Group, Optional"}, [9]={npc="Shawn", tgt="Shawn"}, [10]={hint="Find Hilary's Necklace, and return it to Hilary in Lakeshire."}, [11]={npc="Guard Parker", tgt="Guard Parker"}, [12]={npc="Guard Parker", tgt="Guard Parker"}, [13]={hint="Collect 5 Spiked Collars from Redridge Thrashers for Deputy Feldon near Lakeshire.", desc="Kill extra Redridge Mongrels around 10.8, 63.7."}, [14]={hint="Kill 10 Redridge Mongrels and 6 Redridge Poachers, then report back to Deputy Feldon in Lakeshire."}, [15]={hint="Gather 6 Underbelly Whelp Scales from Black Dragon Whelps, and bring them to Verner Osgood in Redridge."}, [16]={hint="Bring 10 Spotted Sunfish to Dockmaster Baren in Lakeshire."}, [17]={hint="Bring 8 Murloc Fins to Dockmaster Baren in Lakeshire."}, [18]={hint="Bring 8 Stolen Weapons and 10 Blackrock Supplies to Marshal Marris in Lakeshire."}, [19]={hint="Bring 10 Battleworn Axes to Marshal Marris in Lakeshire."}, [20]={hint="Foreman Oslow of Lakeshire wants you to retrieve his toolbox from the bottom of Lake Everstill."}, [21]={npc="Verner Osgood", tgt="Verner Osgood"}, [22]={npc="Marshal Marris", tgt="Marshal Marris"}, [23]={npc="Marshal Marris", tgt="Marshal Marris"}, [24]={npc="Marshal Marris", tgt="Marshal Marris", tag="Optional"}, [25]={npc="Marshal Marris", tgt="Marshal Marris", tag="Optional"}, [26]={npc="Foreman Oslow", tgt="Foreman Oslow"}, [27]={npc="Foreman Oslow", tgt="Foreman Oslow"}, [28]={npc="Magistrate Solomon", tgt="Magistrate Solomon"}, [29]={npc="Magistrate Solomon", tgt="Magistrate Solomon"}, [30]={npc="Bailiff Conacher", tgt="Bailiff Conacher"}, [31]={npc="Dockmaster Baren", tgt="Dockmaster Baren"}, [32]={npc="Dockmaster Baren", tgt="Dockmaster Baren"}, [33]={npc="Martie Jainrose", tgt="Martie Jainrose"}, [34]={npc="Martie Jainrose", tgt="Martie Jainrose"}, [35]={hint="Kill 10 Redridge Brutes and 8 Redridge Mystics, then return to Verner Osgood."}, [36]={hint="Bring 5 Iron Pikes and 5 Iron Rivets to Foreman Oslow in Lakeshire."}, [37]={npc="Darcy", tgt="Darcy"}, [38]={npc="Verner Osgood", tgt="Verner Osgood"}, [39]={npc="Foreman Oslow", tgt="Foreman Oslow"}, [40]={npc="Hilary", tgt="Hilary"}, [41]={npc="Deputy Feldon", tgt="Deputy Feldon"}, [42]={npc="Deputy Feldon", tgt="Deputy Feldon"}, [43]={bind="Stormwind"}, [44]={npc="Argos Nightwhisper", tgt="Argos Nightwhisper", tag="Optional"}, [45]={to="Auberdine", from="Stormwind", desc="Board at the pier in Stormwind Harbor."}}},
    ["02-16"] = {steps={[1]={npc="Thundris Windweaver", tgt="Thundris Windweaver"}, [2]={npc="Tharnariun Treetender", tgt="Tharnariun Treetender"}, [3]={npc="Gershala Nightwhisper", tgt="Gershala Nightwhisper"}, [4]={npc="Gwennyth Bly'Leggonde", tgt="Gwennyth Bly'Leggonde"}, [5]={text="Fly from Auberdine to Rut'theran Village (take the boat if it's not on your flight map), then take the portal in the village into Darnassus."}, [6]={npc="Mathiel", tgt="Mathiel"}, [7]={npc="Mathiel", tgt="Mathiel"}, [8]={hint="Bring 20 Sunscorched Shells to Mathiel in Darnassus."}, [9]={npc="Mathiel", tgt="Mathiel"}, [10]={npc="Mathiel", tgt="Mathiel"}, [11]={npc="Mathiel", tgt="Mathiel"}, [12]={text="Take the portal back to Rut'theran Village and fly to Auberdine to rejoin the route."}, [13]={text="Fly from Auberdine to Rut'theran Village (take the boat if it's not on your flight map), then take the portal in the village into Darnassus."}, [14]={npc="Priestess Alathea", tgt="Priestess Alathea", desc="Learn Elune's Grace."}, [15]={npc="Priestess Alathea", tgt="Priestess Alathea", desc="Learn Elune's Grace."}, [16]={text="Take the portal back to Rut'theran Village and fly to Auberdine to rejoin the route."}, [17]={text="Fly from Auberdine to Rut'theran Village (take the boat if it's not on your flight map), then take the portal in the village into Darnassus."}, [18]={npc="Mathrengyl Bearwalker", tgt="Mathrengyl Bearwalker"}, [19]={npc="Dendrite Starblaze", tgt="Dendrite Starblaze"}, [20]={npc="Dendrite Starblaze", tgt="Dendrite Starblaze"}, [21]={npc="Avatar of Saeyleenan", tgt="Avatar of Saeyleenan", desc="The Avatar of Saeyleenan is in southern Moonglade."}, [22]={npc="Avatar of Saeyleenan", tgt="Avatar of Saeyleenan"}, [23]={hint="Recover the Relic of the Fang, Relic of the Claw, and Relic of the Silent Shadow from the Stormrage Barrow Den, and return them to the Avatar of Saeyleenan.", desc="At the entrance of the Stormrage Barrow Dens, use the statue that grants stealth, then take one of each of the three relics."}, [24]={npc="Avatar of Saeyleenan", tgt="Avatar of Saeyleenan"}, [25]={npc="Avatar of Saeyleenan", tgt="Avatar of Saeyleenan"}, [26]={npc="Dendrite Starblaze", tgt="Dendrite Starblaze", desc="Return to Nighthaven and turn in to Dendrite Starblaze."}, [27]={npc="Dendrite Starblaze", tgt="Dendrite Starblaze"}, [28]={npc="Great Cat Spirit", tgt="Great Cat Spirit"}, [29]={npc="Great Cat Spirit", tgt="Great Cat Spirit"}, [30]={hint="Recover the Relic of the Fang, Relic of the Claw, and Relic of the Silent Shadow from the Stormrage Barrow Den, and return them to the Great Cat Spirit."}, [31]={npc="Great Cat Spirit", tgt="Great Cat Spirit"}, [32]={npc="Great Cat Spirit", tgt="Great Cat Spirit"}, [33]={npc="Dendrite Starblaze", tgt="Dendrite Starblaze"}, [34]={npc="Dendrite Starblaze", tgt="Dendrite Starblaze"}, [35]={npc="Mathrengyl Bearwalker", tgt="Mathrengyl Bearwalker", desc="Find Silva Fil'naveth at Nighthaven for the druid-only flight to Rut'theran Village, then use the portal in the village to enter Darnassus."}, [36]={text="Take the portal back to Rut'theran Village and fly to Auberdine to rejoin the route."}, [37]={npc="Onu", tgt="Onu"}, [38]={npc="Arbal", tgt="Arbal"}, [39]={npc="Volcor", tgt="Volcor", desc="Escort quest: in a group, wait until everyone is at the same step before accepting, and turn off auto-accept."}, [40]={npc="Volcor", tgt="Volcor"}, [41]={hint="Protect Volcor until you reach the road, then speak to Terenthis in Auberdine."}, [42]={text="From the south of Darkshore, follow the road south into Ashenvale and go to Maestra's Post first.", tag="Flight path locked. Travel there on foot the first time."}, [43]={npc="Sentinel Onaeya", tgt="Sentinel Onaeya"}, [44]={npc="Delgren the Purifier", tgt="Delgren the Purifier"}, [45]={npc="Delgren the Purifier", tgt="Delgren the Purifier"}, [46]={npc="Orendil Broadleaf", tgt="Orendil Broadleaf"}, [47]={hint="Collect a Glowing Soul Gem and return it to Delgren the Purifier at Maestra's Post."}, [48]={hint="Bring 5 Bathran's Hair to Orendil Broadleaf in Ashenvale."}, [49]={npc="Orendil Broadleaf", tgt="Orendil Broadleaf"}, [50]={npc="Orendil Broadleaf", tgt="Orendil Broadleaf"}, [51]={npc="Delgren the Purifier", tgt="Delgren the Purifier"}, [52]={npc="Delgren the Purifier", tgt="Delgren the Purifier"}, [53]={npc="Therysil", tgt="Therysil"}, [54]={node="Astranaar"}, [55]={npc="Shindrell Swiftfire", tgt="Shindrell Swiftfire"}, [56]={npc="Sentinel Thenysil", tgt="Sentinel Thenysil"}, [57]={npc="Raene Wolfrunner", tgt="Raene Wolfrunner"}, [58]={npc="Pelturas Whitemoon", tgt="Pelturas Whitemoon"}, [59]={npc="Pelturas Whitemoon", tgt="Pelturas Whitemoon"}, [60]={npc="Teronis' Corpse", tgt="Teronis' Corpse"}, [61]={npc="Teronis' Corpse", tgt="Teronis' Corpse"}, [62]={hint="Find the Glowing Gem and return to Raene Wolfrunner in Astranaar with Teronis' Journal."}, [63]={npc="Talen", tgt="Talen"}, [64]={hint="Bring the Ancient Statuette to Talen, in his camp near the Zoram Strand."}, [65]={npc="Talen", tgt="Talen"}, [66]={npc="Talen", tgt="Talen"}, [67]={hint="Bring the Ring of Zoram to Talen near the Zoram Strand.", tag="Optional", desc="Only fight Ruuzel with a group. Mages, Warlocks and Hunters can try it solo."}, [68]={hint="Bring 20 Wrathtail Heads to Shindrell Swiftfire in Astranaar."}, [69]={npc="Talen", tgt="Talen"}, [70]={npc="Shindrell Swiftfire", tgt="Shindrell Swiftfire"}, [71]={npc="Raene Wolfrunner", tgt="Raene Wolfrunner"}, [72]={npc="Llana", tgt="Llana", desc="Delivery only: take the boat to Menethil Harbor and turn it in to Caitlin Grassman; skip it if you're not level 24 yet, no need to come back for it."}, [73]={to="Auberdine"}, [74]={to="Menethil Harbor", from="Auberdine", desc="In Auberdine, board the boat to Menethil Harbor. Get off at the next stop."}}},
    ["05-d15"] = {name="Wailing Caverns", entrance="The Barrens 46.00, 36.30", tips={{k="取捨", text="The Glowing Shard, Trouble at the Docks and Smart Drinks all need trips to Ratchet. Alliance hasn't unlocked Ratchet yet at this point, so they're not listed."}, {k="說明", text="Enter the outer cave at the Lushwater Oasis (47.70, 35.00) and follow the tunnel to the portal. Pick up quests from Nalpak and Ebru in the alcove above the outer entrance first.", s={{"Enter the outer cave at the Lushwater Oasis (47.70, 35.00) and follow the tunnel to the portal"}, {"Pick up quests from Nalpak and Ebru in the alcove above the outer entrance first"}}}}, steps={[1]={text="Optional, far-off dungeon: before boarding the boat in Auberdine, fly back to Astranaar. Follow the road east, take the eastern Ashenvale road south past Mor'shan Rampart into the Barrens, then follow the north road south to the oasis southwest of the Crossroads to find the cave mouth. The whole way is Horde territory. After the dungeon, return to Astranaar, fly to Auberdine, take the boat to Menethil Harbor and rejoin {s:02-21}.", tag="Optional"}, [2]={npc="Nalpak", tgt="Nalpak"}, [3]={npc="Ebru", tgt="Ebru"}, [4]={text="Wailing Caverns entrance"}, [5]={hint="Nalpak in the Wailing Caverns wants 20 Deviate Hides.", desc="Deviate Slayers are in the outer cave in front of the instance entrance. Location: Clear the deviate beasts at the shallow forks and both flanks, looting hides as you push toward the bosses.", spot="Kill deviates at the shallow fork and in both wings. Loot hides as you go."}, [6]={hint="Ebru in the Wailing Caverns wants you to kill 7 Deviate Ravagers, 7 Deviate Vipers, 7 Deviate Shamblers and 7 Deviate Dreadfangs.", desc="Location: Clear the shallow fork, then finish all four mobs in the west and east wings.", spot="Clear the shallow fork, then finish all four mobs in the west and east wings."}, [7]={npc="Nalpak", tgt="Nalpak"}, [8]={npc="Ebru", tgt="Ebru"}}},
    ["02-21"] = {steps={[1]={npc="James Halloran", tgt="James Halloran"}, [2]={npc="Karl Boran", tgt="Karl Boran"}, [3]={node="Menethil Harbor"}, [4]={npc="First Mate Fitzsimmons", tgt="First Mate Fitzsimmons"}, [5]={npc="First Mate Fitzsimmons", tgt="First Mate Fitzsimmons"}, [6]={text="Flagon of Mead", npc="Innkeeper Helbrek"}, [7]={npc="Archaeologist Flagongut", tgt="Archaeologist Flagongut"}, [8]={npc="Archaeologist Flagongut", tgt="Archaeologist Flagongut"}, [9]={npc="First Mate Fitzsimmons", tgt="First Mate Fitzsimmons"}, [10]={npc="Caitlin Grassman", tgt="Caitlin Grassman"}, [11]={npc="Caitlin Grassman", tgt="Caitlin Grassman"}, [12]={npc="Sida", tgt="Sida"}, [13]={npc="Valstag Ironjaw", tgt="Valstag Ironjaw"}, [14]={npc="Tarrel Rockweaver", tgt="Tarrel Rockweaver"}, [15]={npc="Tarrel Rockweaver", tgt="Tarrel Rockweaver"}, [16]={hint="Recover 6 Khaz Modan Timber and 30 Khaz Modan Iron from Menethil Harbor for Valstag Ironjaw."}, [17]={hint="Kill 12 Bluegill Murlocs.", desc="From now on, kill Young Wetlands Crocolisks along the way for their skins."}, [18]={text="Follow the main road east first, then turn south down into the dig site at the turnoff north of it."}, [19]={npc="Ormer Ironbraid", tgt="Ormer Ironbraid"}, [20]={npc="Merrin Rockweaver", tgt="Merrin Rockweaver"}, [21]={npc="Merrin Rockweaver", tgt="Merrin Rockweaver"}, [22]={hint="Archaeologist Flagongut in Menethil Harbor wants you to bring him the Stone of Relu and Flagongut's Fossil."}, [23]={hint="Ormer Ironbraid at the Whelgar Excavation Site wants you to kill 10 Mottled Screechers and 10 Mottled Raptors."}, [24]={npc="Ormer Ironbraid", tgt="Ormer Ironbraid"}, [25]={hint="Obtain 4 Young Crocolisk Skins for James Halloran in Menethil Harbor."}, [26]={npc="Rethiel the Greenwarden", tgt="Rethiel the Greenwarden"}, [27]={npc="Rethiel the Greenwarden", tgt="Rethiel the Greenwarden"}, [28]={hint="Collect an Unruptured Stalker Gland from Thelgen Rock for Caitlin Grassman in Menethil Harbor."}, [29]={hin