    ["02-17"] = {steps={[1]={to="Lakeshire", tag="Flight path locked. Travel there on foot the first time.", desc="If you've unlocked the Darkshire flight point, fly straight to Darkshire. If not, fly to Lakeshire, then follow the road west to the junction on the west side of Redridge Mountains and head south through Duskwood to Darkshire."}, [2]={npc="Madame Eva", tgt="Madame Eva", desc="While crossing Duskwood, kill spiders for Gooey Spider Legs."}, [3]={npc="Madame Eva", tgt="Madame Eva"}, [4]={npc="Clerk Daltry", tgt="Clerk Daltry"}, [5]={npc="Clerk Daltry", tgt="Clerk Daltry"}, [6]={npc="Sirra Von'Indi", tgt="Sirra Von'Indi"}, [7]={npc="Commander Althea Ebonlocke", tgt="Commander Althea Ebonlocke"}, [8]={npc="Elaine Carevin", tgt="Elaine Carevin"}, [9]={npc="Elaine Carevin", tgt="Elaine Carevin"}, [10]={npc="Elaine Carevin", tgt="Elaine Carevin"}, [11]={node="Darkshire"}, [12]={text="Bronze Tube", desc="Limited stock. Buy only if it's available and you don't have one yet."}, [13]={npc="Viktori Prism'Antras", tgt="Viktori Prism'Antras", desc="The stargazing quest line needs a Bronze Tube to start. If you don't have one, do the other parts first and buy it at the Auction House later."}, [14]={npc="Merrick's Bow", npcObj=true, tag="Optional", desc="Right-click Merrick's Bow in your bags to start the quest."}, [15]={npc="Bath'rah the Windwatcher", tgt="Bath'rah the Windwatcher", npcObj=true, tag="Optional", desc="Right-click Ira's Dagger in your bags to start the quest."}, [16]={npc="Viktori Prism'Antras", tgt="Viktori Prism'Antras"}, [17]={npc="Viktori Prism'Antras", tgt="Viktori Prism'Antras"}, [18]={npc="Blind Mary", tgt="Blind Mary"}, [19]={npc="Blind Mary", tgt="Blind Mary"}, [20]={hint="Retrieve Blind Mary's Looking Glass from the Insane Ghoul and give it to Viktori in Darkshire."}, [21]={hint="Commander Althea Ebonlocke of Darkshire wants you to kill 8 Skeletal Warriors and 6 Skeletal Mages."}, [22]={npc="Watcher Dodds", tgt="Watcher Dodds"}, [23]={hint="Search Raven Hill for anything of interest and return to Sirra Von'Indi in Darkshire."}, [24]={npc="Jitters", tgt="Jitters"}, [25]={npc="Jitters", tgt="Jitters"}, [26]={npc="Sven Yorgen", tgt="Sven Yorgen"}, [27]={npc="Sven Yorgen", tgt="Sven Yorgen"}, [28]={npc="Lars", tgt="Lars"}, [29]={hint="Kill 12 Starving Dire Wolves and 8 Rabid Dire Wolves, then return to Lars at Sven's Camp on the western border of Duskwood.", desc="Keep your Gooey Spider Legs; don't sell them. You'll turn them in later."}, [30]={hint="Kill 15 Pygmy Venom Web Spiders, and then report back to Watcher Dodds in Duskwood."}, [31]={hint="Defeat 8 Splinter Fist Warriors and 4 Splinter Fist Taskmasters then return to Sirra Von'Indi in Darkshire for more information.", tag="Optional", desc="Do this only if you have Merrick's Bow."}, [32]={hint="Defeat 10 Young Black Ravagers and 7 Black Ravagers then return to Sirra Von'Indi in Darkshire for more information.", tag="Optional", desc="Do this only if you have Ira's Dagger."}, [33]={npc="Abercrombie", tgt="Abercrombie"}, [34]={npc="Abercrombie", tgt="Abercrombie"}, [35]={npc="Lars", tgt="Lars"}, [36]={npc="Gryan Stoutmantle", tgt="Gryan Stoutmantle"}, [37]={npc="Gryan Stoutmantle", tgt="Gryan Stoutmantle"}, [38]={npc="Old Footlocker", npcObj=true}, [39]={npc="Old Footlocker", npcObj=true}, [40]={to="Darkshire"}, [41]={npc="Madame Eva", tgt="Madame Eva"}, [42]={npc="Madame Eva", tgt="Madame Eva"}, [43]={npc="Chef Grual", tgt="Chef Grual"}, [44]={npc="Chef Grual", tgt="Chef Grual"}, [45]={npc="Commander Althea Ebonlocke", tgt="Commander Althea Ebonlocke"}, [46]={npc="Clerk Daltry", tgt="Clerk Daltry"}, [47]={npc="Clerk Daltry", tgt="Clerk Daltry"}, [48]={npc="Sirra Von'Indi", tgt="Sirra Von'Indi"}, [49]={npc="Sirra Von'Indi", tgt="Sirra Von'Indi", tag="Optional"}, [50]={npc="Sirra Von'Indi", tgt="Sirra Von'Indi", tag="Optional"}, [51]={npc="Blind Mary", tgt="Blind Mary"}, [52]={npc="Blind Mary", tgt="Blind Mary"}, [53]={npc="Viktori Prism'Antras", tgt="Vikt