    ["05-d4"] = {name="The Stockade", entrance="Stormwind 52.41, 70.01", pickup="Pick up \"What Comes Around...\" in Lakeshire and \"Crime and Punishment\" in Darkshire. \"The Stockade Riots\" requires turning in the letter dropped by VanCleef. If you lack the letter, continue with the other quests. Group up for \"The Fury Runs Deep\" after completing \"The Dark Iron War\" in the Wetlands.", pickupS={{"Pick up \"What Comes Around...\" in Lakeshire and \"Crime and Punishment\" in Darkshire. \"The Stockade Riots\" requires turning in the letter dropped by VanCleef"}, {"If you lack the letter, continue with the other quests"}, {"Group up for \"The Fury Runs Deep\" after completing \"The Dark Iron War\" in the Wetlands"}}, steps={[1]={npc="Councilman Millstipe", tgt="Councilman Millstipe"}, [2]={text="Prerequisite: What Comes Around..."}, [3]={npc="An Unsent Letter", npcObj=true, tag="If it drops", desc="Dropped by VanCleef in the Deadmines: right-click it to accept the quest."}, [4]={npc="Baros Alexston", tgt="Baros Alexston"}, [5]={npc="Baros Alexston", tgt="Baros Alexston"}, [6]={npc="Warden Thelwater", tgt="Warden Thelwater"}, [7]={npc="Warden Thelwater", tgt="Warden Thelwater"}, [8]={npc="Warden Thelwater", tgt="Warden Thelwater"}, [9]={npc="Nikova Raskol", tgt="Nikova Raskol"}, [10]={text="The Stockade entrance"}, [11]={hint="Warden Thelwater of Stormwind wants you to kill 10 Defias Prisoners, 8 Defias Convicts, and 8 Defias Insurgents in The Stockade."}, [12]={hint="Kill Bazil Thredd and bring his head back to Warden Thelwater at the Stockade."}, [13]={hint="Nikova Raskol of Stormwind wants you to collect 10 Red Wool Bandanas."}, [14]={hint="Councilman Millstipe of Darkshire wants you to bring him the hand of Dextren Ward."}, [15]={hint="Bring the head of Targorr the Dread to Guard Berton in Lakeshire.", tag="Group, Optional"}, [16]={hint="Motley Garmason wants Kam Deepfury's head brought to him at Dun Modr.", tag="Group, Optional"}, [17]={npc="Warden Thelwater", tgt="Warden Thelwater"}, [18]={npc="Warden Thelwater", tgt="Warden Thelwater"}, [19]={npc="Nikova Raskol", tgt="Nikova Raskol"}, [20]={npc="Guard Berton", tgt="Guard Berton", tag="Group, Optional, Later, on the way", desc="Hold it until {s:02-19} and turn it in when passing through Lakeshire."}, [21]={npc="Councilman Millstipe", tgt="Councilman Millstipe", tag="Optional, Group, Later, on the way", desc="Hold it until {s:03-22} and turn it in when passing through Darkshire."}, [22]={npc="Motley Garmason", tgt="Motley Garmason", tag="Group, Later, on the way"}}},
    ["02-18"] = {steps={[1]={npc="Warden Thelwater", tgt="Warden Thelwater", desc="Only available after you've run the Stormwind Stockade (The Stockade Riots)."}, [2]={npc="Baros Alexston", tgt="Baros Alexston"}, [3]={npc="Baros Alexston", tgt="Baros Alexston"}, [4]={npc="Master Mathias Shaw", tgt="Master Mathias Shaw"}, [5]={npc="Master Mathias Shaw", tgt="Master Mathias Shaw"}, [6]={npc="Elling Trias", tgt="Elling Trias"}, [7]={npc="Elling Trias", tgt="Elling Trias"}, [8]={npc="Tyrion", tgt="Tyrion"}, [9]={npc="Tyrion", tgt="Tyrion", tag="Optional, When you have the items", desc="Silk Cloth ×3 can be bought at the Auction House."}}},
    ["02-19"] = {steps={[1]={to="Lakeshire"}, [2]={npc="Foreman Oslow", tgt="Foreman Oslow"}, [3]={npc="Verner Osgood", tgt="Verner Osgood"}, [4]={npc="Dorin Songblade", tgt="Dorin Songblade", tag="Optional, Group"}, [5]={npc="Dorin Songblade", tgt="Dorin Songblade", tag="Optional, Group", desc="If you have already cleared the Wetlands Excavation Site, pick this up in Lakeshire and look for Daewyn on your next group run."}, [6]={npc="Wanted: Gath'Ilzogg", npcObj=true, tag="Optional, Group"}, [7]={npc="Wanted: Incinerator Gar'im", npcObj=true, tag="Optional, Group"}, [8]={npc="Magistrate Solomon", tgt="Magistrate Solomon"}, [9]={npc="Magistrate Solomon", tgt="Magistrate Solomon"}, [10]={npc="Wanted: Lieutenant Fangore", npcObj=true}, [11]={npc="Martie Jainrose", tgt="Martie Jainrose"}, [12]={hint="Martie Jainrose of Lakeshire wants you to kill Bellygrub. Bring her his tusk as proof."}, [13]={npc="Marshal Haggard", tgt="Marshal Haggard"}, [14]={npc="Marshal Haggard", tgt="Marshal Haggard"}, [15]={npc="Marshal Haggard", tgt="Marshal Haggard", desc="Go upstairs and loot the chest."}, [16]={npc="Marshal Haggard", tgt="Marshal Haggard"}, [17]={npc="Theocritus", tgt="Theocritus"}, [18]={npc="Guard Howe", tgt="Guard Howe"}, [19]={hint="Deliver the Broken Staff of Incinerator Gar'im to Magistrate Solomon in Lakeshire.", tag="Optional, Group"}, [20]={npc="Old Lion Statue", npcObj=true, desc="Find the lion statue outside, east of the Tower of Ilgalar, and place the glyph there."}, [21]={npc="Old Lion Statue", npcObj=true, tag="Optional, Group", desc="If the issued glyph is missing, check your bags, bank and quest log."}, [22]={hint="Head west from the lion to the intact watchtower beside Stonewatch Keep. Follow the ramp to the roof and find the empty jar on the barrels. Watch for elite guards.", tag="Optional, Group"}, [23]={npc="An Empty Jar", npcObj=true, tag="Optional, Group", desc="The empty jar is at the top of the watchtower; the follow-up Morganth isn't on the route."}, [24]={hint="Kill Gath'Ilzogg and bring his head to Magistrate Solomon in Lakeshire for the reward.", tag="Optional, Group"}, [25]={hint="Bring Tharil'zun's Head to Marshal Marris in Redridge.", tag="Optional, Group"}, [26]={hint="Bring 3 Midnight Orbs to Marshal Marris in Lakeshire.", tag="Optional, Group"}, [27]={hint="Bring 10 Shadowhide Pendants to Bailiff Conacher in the Lakeshire Town Hall.", desc="Head north along the east side of the valley, collecting pendants from Shadowhide gnolls on the way to the northern camp. Lower-level gnolls also roam the edge of the valley."}, [28]={hint="Climb the stairs inside the Tower of Ilgalar in Redridge and take the book from the bookshelf. Guards and an elite patrol the tower. Return later if the way is unsafe.", desc="Climb the stairs inside the Tower of Ilgalar in Redridge and take the book from the bookshelf. Guards and an elite patrol the tower. Return later if the way is unsafe."}, [29]={hint="Kill Lieutenant Fangore and return to Magistrate Solomon in Lakeshire with his paw.", desc="Follow the east side of the valley north to find Lieutenant Fangore. Clear the nearby Shadowhide gnolls from the edge of the camp before approaching him. Collect pendants along the way if you still need them."}, [30]={hint="Slay 12 Greater Tarantulas and destroy 6 Tarantula Eggs in Alther's Mill for Foreman Oslow in Redridge."}, [31]={hint="Kill 15 Blackrock Champions and Guard Howe in Lakeshire will reward you.", desc="Follow the road toward the Burning Steppes to the camp on its west side. Look for Blackrock Champions near the cave mouth first. Enter the cave if you still need kills according to your quest log."}, [32]={hint="Bring Yowler's Paw to Verner Osgood in Lakeshire."}, [33]={npc="Martie Jainrose", tgt="Martie Jainrose"}, [34]={npc="Bailiff Conacher", tgt="Bailiff Conacher"}, [35]={npc="Magistrate Solomon", tgt="Magistrate Solomon", tag="Optional, Group"}, [36]={npc="Magistrate Solomon", tgt="Magistrate Solomon"}, [37]={npc="Magistrate Solomon", tgt="Magistrate Solomon", tag="Optional, Group"}, [38]={npc="Verner Osgood", tgt="Verner Osgood"}, [39]={npc="Foreman Oslow", tgt="Foreman Oslow"}, [40]={npc="Marshal Marris", tgt="Marshal Marris", tag="Optional"}, [41]={npc="Marshal Marris", tgt="Marshal Marris", tag="Optional"}, [42]={npc="Guard Howe", tgt="Guard Howe"}, [43]={to="Darkshire"}, [44]={npc="Tavernkeep Smitts", tgt="Tavernkeep Smitts"}, [45]={npc="Tavernkeep Smitts", tgt="Tavernkeep Smitts"}, [46]={npc="Chef Grual", tgt="Chef Grual"}, [47]={npc="Chef Grual", tgt="Chef Grual"}, [48]={npc="Commander Althea Ebonlocke", tgt="Commander Althea Ebonlocke"}, [49]={npc="Commander Althea Ebonlocke", tgt="Commander Althea Ebonlocke"}, [50]={npc="Clerk Daltry", tgt="Clerk Daltry"}, [51]={npc="Clerk Daltry", tgt="Clerk Daltry"}, [52]={npc="Lord Ello Ebonlocke", tgt="Lord Ello Ebonlocke"}, [53]={npc="Commander Althea Ebonlocke", tgt="Commander Althea Ebonlocke"}, [54]={npc="Commander Althea Ebonlocke", tgt="Commander Althea Ebonlocke"}, [55]={hint="Collect 8 quest silks. Look for Black Widow Hatchling southeast of Darkshire. On the surface at Raven Hill in the west, either Black Widow Hatchling or Carrion Recluse can drop the silk."}, [56]={bind="Stormwind"}, [57]={npc="Wynne Larson", tgt="Wynne Larson", desc="Bring 10 Linen Cloth and 6 Charged Rift Gems. On a later visit to Loch Modan, enter Silver Stream Mine from the north (about 35.9,18.2) and open the miners' chests. Continue your route while short on materials. Visit Wynne in Stormwind when your journal shows the quest is ready."}, [58]={npc="Wynne Larson", tgt="Wynne Larson", desc="Rewards Manaweave Robe."}, [59]={npc="Wynne Larson", tgt="Wynne Larson", desc="Rewards Manaweave Robe."}, [60]={npc="High Sorcerer Andromath", tgt="High Sorcerer Andromath"}, [61]={npc="High Sorcerer Andromath", tgt="High Sorcerer Andromath"}, [62]={npc="High Sorcerer Andromath", tgt="High Sorcerer Andromath", desc="After accepting, collect the silk when your route takes you through Duskwood. The Totem of Infliction takes you to the same spiders near Raven Hill."}, [63]={npc="Wynne Larson", tgt="Wynne Larson"}, [64]={npc="Wynne Larson", tgt="Wynne Larson", desc="Rewards Astral Knot Garment."}, [65]={npc="Wynne Larson", tgt="Wynne Larson", desc="Rewards Astral Knot Garment."}}},
    ["02-20"] = {steps={[1]={to="Auberdine", from="Stormwind", desc="Board at the pier in Stormwind Harbor."}, [2]={npc="Terenthis", tgt="Terenthis"}, [3]={to="Astranaar"}, [4]={npc="Faldreas Goeth'Shael", tgt="Faldreas Goeth'Shael"}, [5]={npc="Raene Wolfrunner", tgt="Raene Wolfrunner"}, [6]={npc="Raene Wolfrunner", tgt="Raene Wolfrunner"}, [7]={npc="Raene Wolfrunner", tgt="Raene Wolfrunner"}, [8]={text="Leave Astranaar heading east to the fork, then follow the road north."}, [9]={hint="Bring Dal Bloodclaw's Skull to Raene Wolfrunner in Astranaar."}, [10]={hint="Bring Elune's Tear to Pelturas in Astranaar."}, [11]={text="Swim south from the lake island back to shore (46.80, 49.20 → 47.00, 51.70), then head east."}, [12]={npc="Shael'dryn", tgt="Shael'dryn"}, [13]={npc="Shael'dryn", tgt="Shael'dryn"}, [14]={hint="Find the Wooden Key and a piece of Dartol's Rod before returning to Shael'dryn at the moonwell."}, [15]={npc="Shael'dryn", tgt="Shael'dryn"}, [16]={npc="Shael'dryn", tgt="Shael'dryn"}, [17]={hint="Kill 1 Den Watcher, 2 Ursas, 10 Totemics, and 12 Warriors of the Foulweald tribe, and then return to Raene Wolfrunner in Astranaar."}, [18]={hint="Find the final piece of Dartol's Rod and return to Shael'dryn at the moonwell."}, [19]={npc="Gleaming Crescent Pendant", npcObj=true}, [20]={npc="Shael'dryn", tgt="Shael'dryn"}, [21]={npc="Shael'dryn", tgt="Shael'dryn"}, [22]={npc="Hidden Shrine", npcObj=true}, [23]={npc="Hidden Shrine", npcObj=true}, [24]={npc="Shael'dryn", tgt="Shael'dryn"}, [25]={npc="Shael'dryn", tgt="Shael'dryn"}, [26]={npc="Pelturas Whitemoon", tgt="Pelturas Whitemoon"}, [27]={npc="Pelturas Whitemoon", tgt="Pelturas Whitemoon"}, [28]={npc="Raene Wolfrunner", tgt="Raene Wolfrunner"}, [29]={npc="Raene Wolfrunner", tgt="Raene Wolfrunner"}, [30]={npc="Raene Wolfrunner", tgt="Raene Wolfrunner"}, [31]={npc="Maliynn", tgt="Maliynn"}, [32]={hint="Bring Ilkrud Magthrull's Tome to Delgren the Purifier at Maestra's Post."}, [33]={npc="Delgren the Purifier", tg