    ["05-d5"] = {name="Blackfathom Deeps", entrance="Ashenvale 14.50, 14.20", pickup="On reaching Darkshore (2nd visit), first pick up Researching the Corruption. The three quests in Darnassus and Ironforge require levels 18-20; pick them up when you pass through at that level.", pickupS={{"On reaching Darkshore (2nd visit), first pick up Researching the Corruption"}, {"The three quests in Darnassus and Ironforge require levels 18-20; pick them up when you pass through at that level"}}, steps={[1]={npc="Gershala Nightwhisper", tgt="Gershala Nightwhisper"}, [2]={npc="Argent Guard Manados", tgt="Argent Guard Manados", desc="Requires level 20. If you're not high enough when you enter Darnassus at {s:02-13}, pick it up the next time you pass through, or skip it."}, [3]={npc="Dawnwatcher Shaedlass", tgt="Dawnwatcher Shaedlass", desc="Requires level 18; pick it up in passing when you enter Darnassus at {s:02-13}."}, [4]={npc="Gerrig Bonegrip", tgt="Gerrig Bonegrip", desc="Requires level 18. The next time you pass through Stormwind, take the Deeprun Tram to Ironforge to accept it, or skip it if you don't want to make a special trip."}, [5]={text="Blackfathom Deeps entrance"}, [6]={hint="Bring the Lorgalis Manuscript to Gerrig Bonegrip in the Forlorn Cavern in Ironforge."}, [7]={hint="Gershala Nightwhisper in Auberdine wants 8 Corrupt Brain stems."}, [8]={npc="Argent Guard Thaelrid", tgt="Argent Guard Thaelrid"}, [9]={npc="Argent Guard Thaelrid", tgt="Argent Guard Thaelrid"}, [10]={hint="Bring 10 Twilight Pendants to Argent Guard Manados in Darnassus."}, [11]={hint="Bring the head of Twilight Lord Kelris to Dawnwatcher Selgorm in Darnassus."}, [12]={npc="Gershala Nightwhisper", tgt="Gershala Nightwhisper"}, [13]={npc="Argent Guard Manados", tgt="Argent Guard Manados"}, [14]={npc="Dawnwatcher Selgorm", tgt="Dawnwatcher Selgorm"}, [15]={npc="Gerrig Bonegrip", tgt="Gerrig Bonegrip"}}},
    ["03-22"] = {steps={[1]={npc="Clavicus Knavingham", tgt="Clavicus Knavingham", desc="Wool Cloth can be bought at the Auction House. You need 60."}, [2]={npc="Clavicus Knavingham", tgt="Clavicus Knavingham"}, [3]={npc="Zardeth of the Black Claw", tgt="Zardeth of the Black Claw"}, [4]={to="Darkshire"}, [5]={hint="Zardeth the Black Claw wants you to bring him a Tear of Tilloa from Darkshire and a Musquash Root from the Wetlands."}, [6]={npc="Commander Althea Ebonlocke", tgt="Commander Althea Ebonlocke"}, [7]={npc="Calor", tgt="Calor"}, [8]={hint="Kill 6 Nightbane Shadow Weaver worgen for Calor in Darkshire."}, [9]={npc="Calor", tgt="Calor"}, [10]={npc="Calor", tgt="Calor"}, [11]={hint="Kill 12 Nightbane Dark Runner worgen for Calor in Darkshire."}, [12]={npc="Mound of loose dirt", npcObj=true}, [13]={npc="Mound of loose dirt", npcObj=true}, [14]={npc="Watcher Dodds", tgt="Watcher Dodds"}, [15]={hint="Bring 10 Ghoul Fangs, 10 Skeleton Fingers and 5 Vials of Spider Venom to Madame Eva in Darkshire."}, [16]={hint="Collect 8 quest silks. Look for Black Widow Hatchling southeast of Darkshire. On the surface at Raven Hill in the west, either Black Widow Hatchling or Carrion Recluse can drop the silk."}, [17]={npc="Jitters", tgt="Jitters"}, [18]={hint="Commander Althea Ebonlocke of Darkshire wants you to kill 15 Skeletal Fiends and 15 Skeletal Horrors."}, [19]={npc="Abercrombie", tgt="Abercrombie"}, [20]={npc="Abercrombie", tgt="Abercrombie"}, [21]={npc="A Weathered Grave", npcObj=true}, [22]={npc="Sven Yorgen", tgt="Sven Yorgen"}, [23]={npc="Sven Yorgen", tgt="Sven Yorgen"}, [24]={text="Head west into Westfall and take a flight from Sentinel Hill."}, [25]={to="Darkshire"}, [26]={npc="Madame Eva", tgt="Madame Eva"}, [27]={npc="Madame Eva", tgt="Madame Eva"}, [28]={npc="Commander Althea Ebonlocke", tgt="Commander Althea Ebonlocke"}, [29]={npc="Commander Althea Ebonlocke", tgt="Commander Althea Ebonlocke"}, [30]={npc="Clerk Daltry", tgt="Clerk Daltry"}, [31]={npc="Clerk Dal