={npc="Wynne Larson", tgt="Wynne Larson"}, [63]={npc="Wynne Larson", tgt="Wynne Larson", desc="Rewards Astral Knot Garment."}, [64]={npc="Wynne Larson", tgt="Wynne Larson", desc="Rewards Astral Knot Garment."}, [65]={hint="Bring 3 Silk Cloth and 2 of Clara's Fresh Apples to Tyrion in Stormwind.", tag="Optional"}, [66]={npc="Thomas", tgt="Thomas"}, [67]={npc="Bishop Farthing", tgt="Bishop Farthing"}, [68]={npc="Bishop Farthing", tgt="Bishop Farthing"}, [69]={npc="Highlord Bolvar Fordragon", tgt="Highlord Bolvar Fordragon"}, [70]={npc="Highlord Bolvar Fordragon", tgt="Highlord Bolvar Fordragon"}, [71]={npc="Bishop DeLavey", tgt="Bishop DeLavey"}, [72]={npc="Bishop DeLavey", tgt="Bishop DeLavey"}, [73]={npc="Tyrion", tgt="Tyrion", tag="Optional"}, [74]={npc="Tyrion", tgt="Tyrion", tag="Optional, Group"}, [75]={hint="Remain in the garden until Lord Gregor Lescovar and Marzon the Silent Blade have had their conversation. Afterwards, kill them both before returning to Elling Trias in Stormwind.", tag="Optional, Group"}, [76]={npc="Jorgen", tgt="Jorgen"}, [77]={npc="Jorgen", tgt="Jorgen"}, [78]={npc="Elling Trias", tgt="Elling Trias"}, [79]={npc="Elling Trias", tgt="Elling Trias"}, [80]={npc="Elling Trias", tgt="Elling Trias", tag="Optional, Group"}, [81]={npc="Elling Trias", tgt="Elling Trias"}, [82]={npc="Master Mathias Shaw", tgt="Master Mathias Shaw"}, [83]={npc="Master Mathias Shaw", tgt="Master Mathias Shaw"}, [84]={npc="Baros Alexston", tgt="Baros Alexston"}, [85]={npc="Baros Alexston", tgt="Baros Alexston"}, [86]={npc="Lady Katrana Prestor", tgt="Lady Katrana Prestor"}}},
    ["03-23"] = {steps={[1]={npc="Brother Sarno", tgt="Brother Sarno"}, [2]={npc="Shoni the Shilent", tgt="Shoni the Shilent", tag="Group, Optional", desc="A Gnomeregan dungeon quest; accept it only if you're going to run Gnomeregan."}, [3]={to="Menethil Harbor"}, [4]={npc="Sylessa Duskwhisper", tgt="Sylessa Duskwhisper"}, [5]={npc="Glorin Steelbrow", tgt="Glorin Steelbrow"}, [6]={npc="Glorin Steelbrow", tgt="Glorin Steelbrow"}, [7]={npc="First Mate Fitzsimmons", tgt="First Mate Fitzsimmons"}, [8]={npc="Harlo Barnaby", tgt="Harlo Barnaby"}, [9]={npc="Captain Stoutfist", tgt="Captain Stoutfist"}, [10]={npc="Captain Stoutfist", tgt="Captain Stoutfist"}, [11]={npc="Waterlogged Chest", npcObj=true}, [12]={npc="Waterlogged Chest", npcObj=true}, [13]={hint="Recover Nord'el for Sylessa Duskwhisper in Menethil Harbor."}, [14]={npc="Sylessa Duskwhisper", tgt="Sylessa Duskwhisper"}, [15]={hint="Gather 5 Lightforge Ingots, then return to Glorin Steelbrow in the Wetlands."}, [16]={npc="Glorin Steelbrow", tgt="Glorin Steelbrow"}, [17]={npc="Glorin Steelbrow", tgt="Glorin Steelbrow"}, [18]={hint="Kill 13 Cursed Sailors, 5 Cursed Marines and First Mate Snellig. Bring Snellig's Snuffbox to First Mate Fitzsimmons in Menethil Harbor."}, [19]={npc="First Mate Fitzsimmons", tgt="First Mate Fitzsimmons"}, [20]={npc="First Mate Fitzsimmons", tgt="First Mate Fitzsimmons"}, [21]={hint="Get the Intrepid Strongbox Key from Captain Halyndor.", desc="Captain Halyndor is on the beached Intrepid; kill him for the key, then open the strongbox on the ship."}, [22]={npc="Intrepid's Locked Strongbox", npcObj=true}, [23]={npc="Intrepid's Locked Strongbox", npcObj=true}, [24]={npc="Ormer Ironbraid", tgt="Ormer Ironbraid"}, [25]={npc="Prospector Whelgar", tgt="Prospector Whelgar"}, [26]={hint="Ormer Ironbraid wants you to kill 10 Mottled Scytheclaw raptors and 10 Mottled Razormaw raptors then return to him at the Whelgar Excavation Site."}, [27]={hint="Prospector Whelgar wants you to scour the excavation site in search of the 4 missing tablet fragments: Ados, Modr, Golm and Neru."}, [28]={npc="Ormer Ironbraid", tgt="Ormer Ironbraid"}, [29]={npc="Ormer Ironbraid", tgt="Ormer Ironbraid"}, [30]={npc="Prospector Whelgar", tgt="Prospector Whelgar"}, [31]={npc="Titan Relic", npcObj=true, tag="Optional, If it drops", desc="If you loot the Titan Relic from the Relic Guardian, right-click it to start the quest."}, [32]={npc="Prospector Whelgar", tgt="Prospector Whelgar"}, [33]={npc="Prospector Whelgar", tgt="Prospector Whelgar"}, [34]={text="Sarltooth is up on the hillside; follow the arrow around and up from the west (31.99, 48.68 → 31.15, 49.05 → 32.41, 50.92)."}, [35]={hint="Ormer Ironbraid at the Whelgar Excavation Site wants you to kill Sarltooth and return to him with one of his talons once the task is fulfilled."}, [36]={npc="Ormer Ironbraid", tgt="Ormer Ironbraid"}, [37]={npc="Howin Kindfeather", tgt="Howin Kindfeather"}, [38]={npc="Howin Kindfeather", tgt="Howin Kindfeather"}, [39]={npc="Einar Stonegrip", tgt="Einar Stonegrip", desc="A delivery quest; hand it to James Halloran when you return to Menethil Harbor."}, [40]={hint="Captain Stoutfist in Menethil Keep wants you to destroy the 4 sets of Attack Plans in the Angerfang Encampment."}, [41]={npc="Tattered Spellbook", npcObj=true, desc="A book in the Angerfang Encampment; pick it up and bring it back to Menethil Harbor."}, [42]={hint="Zardeth the Black Claw wants you to bring him a Tear of Tilloa from Darkshire and a Musquash Root from the Wetlands."}, [43]={hint="Collect 8 Pristine Crimson Scales and bring them to James Halloran in Menethil Harbor."}, [44]={hint="Gather 12 Perfect Razormaw Eggs for Howin Kindfeather."}, [45]={hint="Collect 10 Razormaw Incisors for Howin Kindfeather."}, [46]={hint="Bring 8 Dragonmaw War Banners to Captain Stoutfist."}, [47]={npc="Howin Kindfeather", tgt="Howin Kindfeather"}, [48]={npc="Howin Kindfeather", tgt="Howin Kindfeather"}, [49]={npc="Longbraid the Grim", tgt="Longbraid the Grim"}, [50]={npc="Longbraid the Grim", tgt="Longbraid the Grim", tag="Optional, Group", desc="The follow-ups are elite quests. Only do them with a group."}, [51]={npc="Motley Garmason", tgt="Motley Garmason", tag="Optional, Group"}, [52]={hint="Kill Balgaras the Foul and bring his ear to Longbraid the Grim outside of Dun Modr.", tag="Optional, Group"}, [53]={hint="Motley Garmason at Dun Modr wants you to kill 10 Dark Iron Dwarves, 5 Dark Iron Tunnelers, 5 Dark Iron Saboteurs and 5 Dark Iron Demolitionists.", tag="Optional, Group"}, [54]={npc="Longbraid the Grim", tgt="Longbraid the Grim", tag="Optional, Group"}, [55]={npc="Motley Garmason", tgt="Motley Garmason", tag="Optional, Group"}, [56]={npc="Motley Garmason", tgt="Motley Garmason", tag="Group, Optional", desc="Pick this up when you turn in \"The Dark Iron War\". Complete it on your next Stockade run and turn it in on your next visit to Dun Modr."}, [57]={npc="Rhag Garmason", tgt="Rhag Garmason"}, [58]={npc="Ebenezer Rustlocke's Corpse", npcObj=true, desc="From the Wetlands side, find the stairs inside the eastern span and descend to Ebenezer. Turn in and take the next quest from the same corpse, then climb the same stairs and return to Dun Modr. There are elites nearby. Wait for an opening or bring help if alone."}, [59]={npc="Ebenezer Rustlocke's Corpse", npcObj=true}, [60]={npc="Rhag Garmason", tgt="Rhag Garmason"}, [61]={npc="Rhag Garmason", tgt="Rhag Garmason"}, [62]={hint="Destroy the cache of explosives.", desc="From Dun Modr, head north across the intact stone bridge. Turn right at the Arathi Highlands end and cross the small suspension bridge into the Dark Iron camp. Destroy the explosives on the cart."}, [63]={text="Pick up the letter on your way back to Dun Modr. Before entering the water, find a bank you can use to climb back out. Dive to the riverbed under the broken bridge. Loot the waterlogged envelope beside the dwarf's hand under the rubble, then right-click it to accept the quest. Return to the bank where you entered and go back to Rhag in the Wetlands."}, [64]={npc="Waterlogged Envelope", npcObj=true, desc="Right-click Waterlogged Envelope in your bags to start the quest."}, [65]={npc="Rhag Garmason", tgt="Rhag Garmason"}, [66]={npc="Rhag Garmason", tgt="Rhag Garmason"}, [67]={npc="Captain Nials", tgt="Captain Nials"}, [68]={node="Refuge Pointe"}, [69]={to="Ironforge"}, [70]={npc="Prospector Stormpike", tgt="Prospector Stormpike"}, [71]={npc="Sara Balloo", tgt="Sara Balloo", desc="Give Sara in Ironforge the letter you received on accepting the quest. The Waterlogged Envelope starts the quest."}, [72]={npc="Sara Balloo", tgt="Sara Balloo"}, [73]={npc="King Magni Bronzebeard", tgt="King Magni Bronzebeard"}, [74]={npc="King Magni Bronzebeard", tgt="King Magni Bronzebeard"}, [75]={npc="Pilot Longbeard", tgt="Pilot Longbeard"}, [76]={npc="Grand Mason Marblesten", tgt="Grand Mason Marblesten"}, [77]={npc="Grand Mason Marblesten", tgt="Grand Mason Marblesten"}, [78]={npc="Tinkmaster Overspark", tgt="Tinkmaster Overspark"}, [79]={npc="Tinkmaster Overspark", tgt="Tinkmaster Overspark", tag="Group, Optional", desc="A Gnomeregan dungeon quest; accept it only if you're going to run Gnomeregan."}, [80]={npc="High Tinker Mekkatorque", tgt="High Tinker Mekkatorque", tag="Group, Optional"}, [81]={npc="Master Mechanic Castpipe", tgt="Master Mechanic Castpipe", tag="Group, Optional"}, [82]={to="Menethil Harbor"}, [83]={npc="Captain Stoutfist", tgt="Captain Stoutfist"}, [84]={npc="Captain Stoutfist", tgt="Captain Stoutfist"}, [85]={npc="Captain Stoutfist", tgt="Captain Stoutfist"}, [86]={npc="Captain Stoutfist", tgt="Captain Stoutfist", tag="If passing by, Optional"}, [87]={npc="James Halloran", tgt="James Halloran"}, [88]={npc="James Halloran", tgt="James Halloran"}, [89]={npc="James Halloran", tgt="James Halloran", desc="Hand it to Howin Kindfeather on the way to the catapults."}, [90]={npc="Glorin Steelbrow", tgt="Glorin Steelbrow"}, [91]={npc="Glorin Steelbrow", tgt="Glorin Steelbrow"}, [92]={npc="Howin Kindfeather", tgt="Howin Kindfeather"}, [93]={npc="Dragonmaw Catapult", npcObj=true, tag="If passing by, Optional"}, [94]={npc="Dragonmaw Catapult", npcObj=true, tag="Optional, Group", desc="The follow-ups are elite quests. Only do them with a group."}, [95]={hint="Kill Chieftain Nek'rosh", tag="Optional, Group"}, [96]={npc="Captain Stoutfist", tgt="Captain Stoutfist", tag="Optional, Group"}}},
    ["05-d7"] = {name="Gnomeregan", entrance="Dun Morogh 24.30, 39.80", pickup="Pick up the pre-dungeon quests when you reach Ashenvale (2nd visit); no need for a special trip back before the dungeon.", pickupS={{"Pick up the pre-dungeon quests when you reach Ashenvale (2nd visit); no need for a special trip back before the dungeon"}}, tips={{k="說明", text="For Data Rescue, loot a white punch card from the nearby enemies. Before entering the dungeon, use 3005-A in the outer passage north of the elevator to get a yellow card.", s={{"For Data Rescue, loot a white punch card from the nearby enemies"}, {"Before entering the dungeon, use 3005-A in the outer passage north of the elevator to get a yellow card"}}}}, steps={[1]={npc="Gaxim Rustfizzle", tgt="Gaxim Rustfizzle"}, [2]={npc="Brother Sarno", tgt="Brother Sarno"}, [3]={npc="Shoni the Shilent", tgt="Shoni the Shilent", tag="Group, Optional"}, [4]={npc="Tinkmaster Overspark", tgt="Tinkmaster Overspark", tag="Group, Optional"}, [5]={npc="High Tinker Mekkatorque", tgt="High Tinker Mekkatorque", tag="Group, Optional"}, [6]={npc="Master Mechanic Castpipe", tgt="Master Mechanic Castpipe", tag="Group, Optional"}, [7]={npc="Klockmort Spannerspan", tgt="Klockmort Spannerspan"}, [8]={npc="Gnoarn", tgt="Gnoarn", tag="Optional, Group"}, [9]={npc="Ozzie Togglevolt", tgt="Ozzie Togglevolt"}, [10]={npc="Ozzie Togglevolt", tgt="Ozzie Togglevolt", tag="Optional, Group"}, [11]={npc="Ozzie Togglevolt", tgt="Ozzie Togglevolt", tag="Optional, Group"}, [12]={npc="Mathiel", tgt="Mathiel", tag="Optional", desc="Accept it in Darnassus, requires level 24: fly from Auberdine to Rut'theran Village and take the portal into the city. If you don't want the detour, skip it together with the turn-in after the dungeon."}, [13]={text="Fly from Menethil Harbor to Ironforge, leave through the city gates and follow the Dun Morogh road west to Gnomeregan."}, [14]={text="Gnomeregan entrance"}, [15]={hint="Use the Empty Leaden Collection Phial on Irradiated Invaders or Irradiated Pillagers to collect radioactive fallout. Once it is full, take it back to Ozzie Togglevolt in Kharanos.", tag="Optional, Group", spot="You can split this chain across runs. Collect the first sample in the entrance tunnels or inside the instance. Turn it in to Ozzie in Kharanos for the heavy vial."}, [16]={hint="Travel to Gnomeregan and bring back High Potency Radioactive Fallout. Be warned, the fallout is unstable and will collapse rather quickly.", tag="Optional, Group", spot="Use the heavy vial on an Irradiated Slime, Corrosive Lurker, or Irradiated Horror. The sample lasts two hours. If you cannot reach Kharanos in time, collect it on your next group run."}, [17]={hint="Bring a Prismatic Punch Card to Master Mechanic Castpipe in Ironforge.", tag="Optional, Group"}, [18]={hint="Bring twenty-four Robo-mechanical Guts to Shoni in Stormwind.", tag="Group, Optional", desc="Drops from the mechanical mobs; turn in when you return to Stormwind."}, [19]={npc="Grime-Encrusted Ring", npcObj=true, tag="If it drops, Optional"}, [20]={hint="Figure out a way to remove the grime from the Grime-Encrusted Ring.", tag="Optional", spot="Sparklematic 5200 in the Clean Zone. Bring 3 silver."}, [21]={npc="The Sparklematic 5200", npcObj=true, tag="Optional"}, [22]={npc="The Sparklematic 5200", npcObj=true, tag="Optional"}, [23]={npc="Kernobee", tgt="Kernobee", tag="Optional, Group", spot="In the dormitory by the Clean Zone. Clear the path back to the exit and wait for the whole party before speaking to Kernobee."}, [24]={hint="Escort Kernobee to the Clockwerk Run exit and then report to Scooty in Booty Bay.", tag="Escort, Optional, Group", desc="Turn in to Scooty during your first pass through Booty Bay in Stranglethorn Vale."}, [25]={npc="Ozzie Togglevolt", tgt="Ozzie Togglevolt", tag="Optional, Group"}, [26]={npc="Ozzie Togglevolt", tgt="Ozzie Togglevolt", tag="Optional, Group"}, [27]={npc="Tinkmaster Overspark", tgt="Tinkmaster Overspark"}, [28]={npc="Tinkmaster Overspark", tgt="Tinkmaster Overspark", tag="Optional, Group"}, [29]={npc="Master Mechanic Castpipe", tgt="Master Mechanic Castpipe"}, [30]={npc="Master Mechanic Castpipe", tgt="Master Mechanic Castpipe", tag="Optional, Group"}, [31]={npc="High Tinker Mekkatorque", tgt="High Tinker Mekkatorque", tag="Optional, Group"}, [32]={npc="Klockmort Spannerspan", tgt="Klockmort Spannerspan", tag="Optional, Group"}, [33]={npc="Klockmort Spannerspan", tgt="Klockmort Spannerspan", tag="Optional"}, [34]={npc="Talvash del Kissel", tgt="Talvash del Kissel", tag="Optional"}, [35]={to="Menethil Harbor", desc="After turning in, return to Menethil Harbor and take the boat for Hillsbrad Foothills."}}},
    ["03-24"] = {name="Hillsbrad Foothills", steps={[1]={to="Southshore", from="Menethil Harbor", desc="Board the boat to Auberdine at the north dock in Menethil Harbor and get off at Southshore on the way."}, [2]={npc="Phin Odelic", tgt="Phin Odelic"}, [3]={npc="Lieutenant Farren Orinelle", tgt="Lieutenant Farren Orinelle"}, [4]={npc="Barkeep Kelly", tgt="Barkeep Kelly"}, [5]={npc="Brewmeister Bilger", tgt="Brewmeister Bilger"}, [6]={npc="Magistrate Henry Maleb", tgt="Magistrate Henry Maleb"}, [7]={npc="Darren Malvew", tgt="Darren Malvew", tag="Optional"}, [8]={hint="Kill 10 Torn Fin Tidehunters and 10 Torn Fin Oracles for Lieutenant Farren Orinelle in Southshore."}, [9]={npc="Lieutenant Farren Orinelle", tgt="Lieutenant Farren Orinelle"}, [10]={npc="Lieutenant Farren Orinelle", tgt="Lieutenant Farren Orinelle"}, [11]={hint="Collect 10 Murloc Heads from the murlocs on the Western Strand for Lieutenant Farren Orinelle in Southshore."}, [12]={npc="Lieutenant Farren Orinelle", tgt="Lieutenant Farren Orinelle"}, [13]={npc="Lieutenant Farren Orinelle", tgt="Lieutenant Farren Orinelle"}, [14]={npc="Marshal Redpath", tgt="Marshal Redpath"}, [15]={npc="Marshal Redpath", tgt="Marshal Redpath"}, [16]={npc="Lieutenant Farren Orinelle", tgt="Lieutenant Farren Orinelle"}, [17]={npc="Lieutenant Farren Orinelle", tgt="Lieutenant Farren Orinelle"}, [18]={hint="Kill 10 Daggerspine Shorehunters and 10 Daggerspine Sirens for Lieutenant Farren Orinelle in Southshore."}, [19]={hint="Deliver the bottles of Fallrook Varietal to Dun Garok in southeast Hillsbrad Foothills, and bring back a sack of their Homebrew Hops."}, [20]={npc="Lieutenant Farren Orinelle", tgt="Lieutenant Farren Orinelle"}, [21]={npc="Lieutenant Farren Orinelle", tgt="Lieutenant Farren Orinelle"}, [22]={npc="Brewmeister Bilger", tgt="Brewmeister Bilger"}, [23]={hint="Grand Mason Marblesten of Ironforge wants 5 pieces of Alterac Granite."}, [24]={hint="Kill 12 Syndicate Footpads and 8 Syndicate Thieves, then return to Magistrate Henry Maleb in Southshore."}, [25]={npc="Syndicate Documents", npcObj=true}, [26]={npc="Syndicate Documents", npcObj=true}, [27]={hint="Darren Malvew of Southshore wants you to kill 8 Mountain Lions and 10 Hulking Mountain Lions.", tag="Optional", desc="This is a dedicated detour with no other objectives nearby. Skip it if you're in a hurry."}, [28]={npc="Magistrate Henry Maleb", tgt="Magistrate Henry Maleb"}, [29]={npc="Magistrate Henry Maleb", tgt="Magistrate Henry Maleb"}, [30]={npc="Loremaster Dibbs", tgt="Loremaster Dibbs"}, [31]={npc="Loremaster Dibbs", tgt="Loremaster Dibbs"}, [32]={npc="Darren Malvew", tgt="Darren Malvew", tag="Optional"}, [33]={node="Southshore"}, [34]={npc="Elegant Letter", npcObj=true, desc="Your trainer starts Elegant Letter. Use Detect Traps on the boxes in the passage."}, [35]={hint="Take the Seal of Ravenholdt to Fahrad at Ravenholdt Manor, hidden away in the hills of Hillsbrad.", desc="Your trainer starts Elegant Letter. Use Detect Traps on the boxes in the passage."}, [36]={npc="Fahrad", tgt="Fahrad", desc="Your trainer starts Elegant Letter. Use Detect Traps on the boxes in the passage."}, [37]={npc="Ravenholdt Guard", tgt="Ravenholdt Guard", tag="Optional", desc="Turn in Syndicate Emblems. Repeatable."}, [38]={npc="Ravenholdt Guard", tgt="Ravenholdt Guard", tag="Optional", desc="Turn in Syndicate Emblems. Repeatable."}, [39]={npc="Myrokos Silentform", tgt="Myrokos Silentform"}, [40]={hint="Find Lord Tomas inside Durnholde Keep, in Hillsbrad Foothills, and kill him. Then, return to Myrokos Silentform."}, [41]={npc="Myrokos Silentform", tgt="Myrokos Silentform"}, [42]={npc="Myrokos Silentform", tgt="Myrokos Silentform"}, [43]={hint="Steal Barton's Scouting Report by pickpocketing it from him. Then, bring the report to Myrokos Silentform at Ravenholdt Manor."}, [44]={npc="Myrokos Silentform", tgt="Myrokos Silentform"}, [45]={npc="Myrokos Silentform", tgt="Myrokos Silentform"}, [46]={hint="Find the Blade of House Perenolde and the Royal Aegis of Perenolde among the ruins of Alterac. Then, bring them to Myrokos Silentform."}, [47]={npc="Myrokos Silentform", tgt="Myrokos Silentform"}, [48]={npc="Myrokos Silentform", tgt="Myrokos Silentform"}, [49]={bind="Stormwind"}}},
    ["05-d16"] = {name="City of Dalaran", entrance="Alterac Mountains 8.46, 59.21", pickup="On your first Stormwind visit, pick up A Green Sample and Power Overwhelming. Once you're level 30 in Hillsbrad Foothills, get An Alarming Request from Emissary Jacques in Southshore.", pickupS={{"On your first Stormwind visit, pick up A Green Sample and Power Overwhelming"}, {"Once you're level 30 in Hillsbrad Foothills, get An Alarming Request from Emissary Jacques in Southshore"}}, tips={{k="說明", text="Modera's image and the dungeon portal are at separate spots. Approach from the Lordamere Lake sewer side. Faction restrictions apply to the outdoor city gates and NPC access.", s={{"Modera's image and the dungeon portal are at separate spots"}, {"Approach from the Lordamere Lake sewer side"}, {"Faction restrictions apply to the outdoor city gates and NPC access"}}}}, steps={[1]={npc="Shylamiir", tgt="Shylamiir"}, [2]={npc="High Sorcerer Andromath", tgt="High Sorcerer Andromath"}, [3]={npc="Emissary Jacques", tgt="Emissary Jacques"}, [4]={text="Optional: fly from Stormwind to Southshore, go north through Hillsbrad Foothills into the Alterac Mountains, follow the north shore of Lordamere Lake west, and find the Image of Archmage Modera outside the Dalaran sewers. After the dungeon, hearth back to Stormwind and rejoin {s:03-25}.", tag="Optional"}, [5]={npc="Image of Archmage Modera", tgt="Image of Archmage Modera"}, [6]={npc="Image of Archmage Modera", tgt="Image of Archmage Modera"}, [7]={npc="Image of Archmage Modera", tgt="Image of Archmage Modera", desc="Accepting the quest gives you the Dalaran sewers key."}, [8]={text="City of Dalaran entrance"}, [9]={hint="Defeat 8 Seeking Remnants, 8 Saturated Remnants, and 8 Mana Echoes inside the City of Dalaran for Archmage Modera outside of Dalaran.", desc="Location: Clear along the sewers and the streets; you'll meet all three kinds.", spot="Clear along the sewers and the streets; you'll meet all three kinds"}, [10]={hint="Slay the Mana Elemental in the City of Dalaran for High Sorcerer Andromath in Stormwind City."}, [11]={hint="Collect a Fel Infused Blossom from the City of Dalaran for Shylamiir in Stormwind City."}, [12]={hint="Collect the Arcane Mote for the Image of Archmage Modera near the City of Dalaran.", desc="Location: Use the Violet Citadel portal to the Violet Parlor. Kill the Archmage's Shade.", spot="Use the Violet Citadel portal to the Violet Parlor. Kill the Archmage's Shade."}, [13]={npc="Image of Archmage Modera", tgt="Image of Archmage Modera"}, [14]={npc="Image of Archmage Modera", tgt="Image of Archmage Modera"}, [15]={npc="Image of Archmage Modera", tgt="Image of Archmage Modera"}, [16]={npc="Archmage Celindra", tgt="Archmage Celindra"}, [17]={bind="Stormwind"}, [18]={npc="Shylamiir", tgt="Shylamiir"}, [19]={npc="High Sorcerer Andromath", tgt="High Sorcerer Andromath"}}},
    ["03-25"] = {steps={[1]={npc="Wu Shen", tgt="Wu Shen"}, [3]={npc="Clavicus Knavingham", tgt="Clavicus Knavingham", tag="Optional"}, [4]={npc="Clavicus Knavingham", tgt="Clavicus Knavingham", tag="Optional", desc="Turn in only if you already have 60 Silk Cloth."}, [5]={npc="Zardeth of the Black Claw", tgt="Zardeth of the Black Claw"}, [6]={npc="Zardeth of the Black Claw", tgt="Zardeth of the Black Claw"}, [7]={npc="Archmage Malin", tgt="Archmage Malin"}, [8]={npc="Lord Grayson Shadowbreaker", tgt="Lord Grayson Shadowbreaker"}, [9]={npc="Archbishop Benedictus", tgt="Archbishop Benedictus"}, [10]={npc="Grimand Elmore", tgt="Grimand Elmore"}, [11]={npc="Grimand Elmore", tgt="Grimand Elmore"}, [12]={npc="Shoni the Shilent", tgt="Shoni the Shilent", tag="Group, Optional", desc="Turn in only if you've run Gnomeregan and collected all the Robo-mechanical Guts."}, [13]={npc="Lord Baurles K. Wishock", tgt="Lord Baurles K. Wishock"}, [14]={npc="Major Samuelson", tgt="Major Samuelson"}, [15]={to="Darkshire"}, [16]={npc="Madame Eva", tgt="Madame Eva"}, [17]={npc="Watcher Backus", tgt="Watcher Backus"}, [18]={npc="Watcher Backus", tgt="Watcher Backus"}, [19]={npc="Commander Althea Ebonlocke", tgt="Commander Althea Ebonlocke"}, [20]={hint="Kill Stalvan Mistmantle and show Madame Eva his family ring."}, [21]={npc="Madame Eva", tgt="Madame Eva"}, [22]={hint="Kill 8 Nightbane Vile Fang and 8 Nightbane Tainted One worgen for Calor in Darkshire."}, [23]={hint="Locate Zzarc'Vul in the southern ogre mound in Duskwood and return his monocle to Viktori in Darkshire."}, [24]={hint="Return Abercrombie's Crate to Abercrombie."}, [25]={hint="Find the Defias Docket and return it to Watcher Backus in Duskwood."}, [26]={npc="Calor", tgt="Calor"}, [27]={npc="Calor", tgt="Calor"}, [28]={npc="Jonathan Carevin", tgt="Jonathan Carevin"}, [29]={npc="Watcher Backus", tgt="Watcher Backus"}, [30]={npc="Watcher Backus", tgt="Watcher Backus"}, [31]={npc="Viktori Prism'Antras", tgt="Viktori Prism'Antras"}, [32]={npc="Abercrombie", tgt="Abercrombie"}}},
    ["03-26"] = {name="Stranglethorn Vale", steps={[1]={npc="Sven Yorgen", tgt="Sven Yorgen"}, [2]={npc="Sven Yorgen", tgt="Sven Yorgen", tag="Optional, Group"}, [3]={hint="Use Morbent's Bane on Morbent Fel, kill Morbent Fel, then return Morbent's Bane to Sven at his camp.", tag="Optional, Group", desc="The follow-ups are elite quests. Only do them with a group."}, [4]={npc="Sven Yorgen", tgt="Sven Yorgen", tag="Optional, Group"}, [5]={text="From the west side of Duskwood, follow the road south into Stranglethorn Vale and go to Rebel Camp first."}, [6]={npc="Private Thorsen", tgt="Private Thorsen", tag="Optional, If you see it", desc="He patrols the road and only gives the quest if you save him when he's ambushed; skip it if you don't run into him."}, [7]={npc="Sergeant Yohwa", tgt="Sergeant Yohwa"}, [8]={npc="Sergeant Yohwa", tgt="Sergeant Yohwa"}, [9]={npc="Lieutenant Doren", tgt="Lieutenant Doren", tag="Optional"}, [10]={npc="Lieutenant Doren", tgt="Lieutenant Doren"}, [11]={npc="Barnil Stonepot", tgt="Barnil Stonepot"}, [12]={npc="Hemet Nesingwary", tgt="Hemet Nesingwary"}, [13]={npc="Hemet Nesingwary", tgt="Hemet Nesingwary"}, [14]={npc="Barnil Stonepot", tgt="Barnil Stonepot", tag="Optional", desc="Pages drop randomly from Stranglethorn mobs. Buy missing pages at the Auction House, and turn in once all four chapters are complete."}, [15]={npc="Barnil Stonepot", tgt="Barnil Stonepot", tag="Optional"}, [16]={npc="Barnil Stonepot", tgt="Barnil Stonepot", tag="Optional"}, [17]={npc="Barnil Stonepot", tgt="Barnil Stonepot", tag="Optional"}, [18]={npc="Barnil Stonepot", tgt="Barnil Stonepot", tag="Optional"}, [19]={npc="Ajeck Rouack", tgt="Ajeck Rouack"}, [20]={npc="Sir S. J. Erlgadin", tgt="Sir S. J. Erlgadin"}, [21]={hint="Ajeck Rouack of Nesingwary's Expedition wants you to kill 10 Young Stranglethorn Tigers."}, [22]={npc="Ajeck Rouack", tgt="Ajeck Rouack"}, [23]={npc="Ajeck Rouack", tgt="Ajeck Rouack"}, [24]={hint="Sir S. J. Erlgadin of Nesingwary's Expedition wants you to kill 10 Young Panthers."}, [25]={hint="Ajeck Rouack of Nesingwary's Expedition wants you to kill 10 Stranglethorn Tigers."}, [26]={hint="Kill 15 Kurzen Jungle Fighters."}, [27]={hint="Bring 7 Jungle Remedies and 1 Venom Fern Extract to Sergeant Yohwa at the Rebel Camp."}, [28]={npc="Bookie Herod's Records", npcObj=true, desc="The files in Kurzen's Compound; the follow-up is in the same camp, so take it if you have time."}, [29]={npc="Ajeck Rouack", tgt="Ajeck Rouack"}, [30]={npc="Ajeck Rouack", tgt="Ajeck Rouack"}, [31]={npc="Sir S. J. Erlgadin", tgt="Sir S. J. Erlgadin"}, [32]={npc="Sir S. J. Erlgadin", tgt="Sir S. J. Erlgadin"}, [33]={hint="Sir S. J. Erlgadin of Nesingwary's Expedition wants you to kill 10 Panthers."}, [34]={hint="Hemet Nesingwary wants you to kill 10 Stranglethorn Raptors."}, [35]={hint="Ajeck Rouack of Nesingwary's Expedition wants you to kill 10 Elder Stranglethorn Tigers."}, [36]={npc="Sir S. J. Erlgadin", tgt="Sir S. J. Erlgadin"}, [37]={npc="Sir S. J. Erlgadin", tgt="Sir S. J. Erlgadin"}, [38]={npc="Ajeck Rouack", tgt="Ajeck Rouack"}, [39]={npc="Ajeck Rouack", tgt="Ajeck Rouack"}, [40]={npc="Hemet Nesingwary", tgt="Hemet Nesingwary"}, [41]={npc="Hemet Nesingwary", tgt="Hemet Nesingwary"}, [42]={npc="Sergeant Yohwa", tgt="Sergeant Yohwa"}, [43]={npc="Sergeant Yohwa", tgt="Sergeant Yohwa"}, [44]={npc="Corporal Kaleb", tgt="Corporal Kaleb"}, [45]={text="Follow the Stranglethorn Vale road all the way south to Booty Bay and keep well clear of the Horde camp when you pass near Grom'gol.", tag="Flight path locked. Travel there on foot the first time."}, [46]={npc="Krazek", tgt="Krazek"}, [47]={npc="Krazek", tgt="Krazek"}, [48]={npc="Baron Revilgaz", tgt="Baron Revilgaz"}, [49]={npc="Baron Revilgaz", tgt="Baron Revilgaz", tag="Optional"}, [50]={npc="Nixxrax Fillamug", tgt="Nixxrax Fillamug"}, [51]={npc="Drizzlik", tgt="Drizzlik"}, [52]={npc="Kebok", tgt="Kebok"}, [53]={npc="Scooty", tgt="Scooty", tag="Optional"}, [54]={node="Booty Bay"}, [55]={to="Ratchet", from="Booty Bay"}, [56]={node="Ratchet"}, [57]={bind="Stormwind"}}},
    ["03-27"] = {steps={[1]={npc="Jennea Cannon", tgt="Jennea Cannon", tag="You can buy 1 Jade at the Auction House now, or have an alt mail it (for Items of Power in Dustwallow Marsh later).", desc="Turn it in to Tabetha in Dustwallow Marsh."}, [3]={npc="Elling Trias", tgt="Elling Trias"}, [4]={npc="Elling Trias", tgt="Elling Trias"}, [5]={npc="Dashel Stonefist", tgt="Dashel Stonefist"}, [6]={npc="Dashel Stonefist", tgt="Dashel Stonefist"}, [7]={hint="Defeat Dashel Stonefist in Stormwind."}, [8]={npc="Dashel Stonefist", tgt="Dashel Stonefist"}, [9]={npc="Dashel Stonefist", tgt="Dashel Stonefist"}, [10]={npc="Elling Trias", tgt="Elling Trias"}, [11]={npc="Elling Trias", tgt="Elling Trias"}, [12]={text="Go to the Dwarven District in Stormwind and take the Deeprun Tram to Ironforge."}, [13]={npc="Grand Mason Marblesten", tgt="Grand Mason Marblesten"}, [14]={npc="Grand Mason Marblesten", tgt="Grand Mason Marblesten"}, [15]={npc="King Magni Bronzebeard", tgt="King Magni Bronzebeard"}, [16]={npc="Gerrig Bonegrip", tgt="Gerrig Bonegrip", tag="Optional", desc="Turn in only if you picked up Book: The Powers Below in Darkshore."}, [17]={npc="Roetten Stonehammer", tgt="Roetten Stonehammer", desc="Take it to Nijel's Point in Desolace."}, [18]={npc="High Explorer Magellas", tgt="High Explorer Magellas"}, [19]={npc="Prospector Stormpike", tgt="Prospector Stormpike"}, [20]={npc="Prospector Stormpike", tgt="Prospector Stormpike"}, [21]={npc="Prospector Stormpike", tgt="Prospector Stormpike"}, [22]={npc="Prospector Stormpike", tgt="Prospector Stormpike"}, [23]={npc="Lago Blackwrench", tgt="Lago Blackwrench"}, [24]={npc="Strahad Farsan", tgt="Strahad Farsan", desc="Fly from Ironforge to Booty Bay (changing at Stormwind), then take the boat to Ratchet."}, [25]={npc="Strahad Farsan", tgt="Strahad Farsan"}, [26]={npc="Krom Stoutarm", tgt="Krom Stoutarm", desc="Take the boat from Ratchet to Booty Bay, then fly to Ironforge."}, [27]={npc="Krom Stoutarm", tgt="Krom Stoutarm"}, [28]={hint="Retrieve the Moldy Tome and Tattered Manuscript for Krom Stoutarm in Ironforge.", desc="Fly from Ironforge to Southshore, and fly back to Ironforge on the return."}, [29]={npc="Krom Stoutarm", tgt="Krom Stoutarm"}, [30]={npc="Krom Stoutarm", tgt="Krom Stoutarm"}, [31]={hint="Bring the Reconstructed Tome and 3 Rods of Channeling to Strahad Farsan in Ratchet.", desc="Fly from Ironforge to Menethil Harbor for the Wetlands section."}, [32]={npc="Strahad Farsan", tgt="Strahad Farsan", desc="Take the boat from the south dock at Menethil Harbor to Theramore, unlock its flight point, then fly to Ratchet. Or fly from Menethil Harbor to Booty Bay (changing at Ironforge and Stormwind) and take the boat from there."}, [33]={npc="Strahad Farsan", tgt="Strahad Farsan", desc="Summon and defeat the felhunter at the circle near Strahad Farsan."}, [34]={hint="Using the Tome of the Cabal, summon and subdue a felhunter, then return the Tome of the Cabal to Strahad Farsan in Ratchet.", desc="Summon and defeat the felhunter at the circle near Strahad Farsan."}, [35]={npc="Strahad Farsan", tgt="Strahad Farsan", desc="Summon and defeat the felhunter at the circle near Strahad Farsan."}, [36]={text="From Ratchet, follow the Barrens road north, continue north past the Crossroads into Ashenvale, then follow the Ashenvale road west to Astranaar (34.41, 47.99).", desc="The Crossroads and Splintertree Post are Horde bases; go around them. If Theramore is on your flight map, you can fly straight to Astranaar (connecting through Theramore and Auberdine)."}, [37]={npc="Klockmort Spannerspan", tgt="Klockmort Spannerspan"}, [38]={npc="Eldrun Stormbreaker", tgt="Eldrun Stormbreaker", desc="Call of Air: find Veyric Thunderhame in Arathi Highlands."}, [39]={to="Menethil Harbor"}, [40]={npc="Mikhail", tgt="Mikhail"}, [41]={npc="Mikhail", tgt="Mikhail"}, [42]={hint="Subdue Tapoke Jahn before he escapes, and then return to Mikhail in Menethil."}, [43]={npc="Mikhail", tgt="Mikhail"}, [44]={npc="Tapoke Slim Jahn", tgt="Tapoke Slim Jahn"}, [45]={npc="Mikhail", tgt="Mikhail"}, [46]={npc="Mikhail", tgt="Mikhail"}, [47]={npc="Vincent Hyal", tgt="Vincent Hyal", desc="In the same inn; deliver the letter to Theramore."}, [48]={to="Auberdine", from="Menethil Harbor", desc="This boat stops at Southshore on the way. Don't get off until Auberdine."}}},
    ["03-28"] = {steps={[1]={to="Astranaar"}, [2]={npc="Sentinel Melyria Frostshadow", tgt="Sentinel Melyria Frostshadow"}, [3]={npc="Illiyana", tgt="Illiyana"}, [4]={npc="Pelturas Whitemoon", tgt="Pelturas Whitemoon"}, [5]={text="Go around to the north side and enter the Howling Vale from here."}, [6]={hint="Go to the Howling Vale and study the Tome of Mel'Thandris, then return to Sentinel Melyria Frostshadow at Forest Song.", desc="Enter the cave to get the book. It's easy to pull extra mobs, and harder when the rare is up."}, [7]={hint="Retrieve a Fallen Moonstone from the Shadethicket Oracle, then bring it to Pelturas in Astranaar."}, [8]={text="Head back to the main road to the north and enter Night Run at this turnoff."}, [9]={hint="Free the trapped Highborne souls in Night Run and Satyrnaar, then return to Delgren the Purifier at Maestra's Post."}, [10]={npc="Anilia", tgt="Anilia"}, [11]={npc="Anilia", tgt="Anilia"}, [12]={hint="Kill Geltharis and return the Branch of Cenarius to Illiyana at Forest Song."}, [13]={npc="Kayneth Stillwind", tgt="Kayneth Stillwind"}, [14]={npc="Maseara Autumnmoon", tgt="Maseara Autumnmoon"}, [15]={hint="Maseara Autumnmoon wants you to search west of Forest Song, amongst the Satyrnaar demons. Report any signs of her husband Kurothel upon your return."}, [16]={npc="Maseara Autumnmoon", tgt="Maseara Autumnmoon"}, [17]={node="Talrendis Point", desc="From Forest Song, follow the road east into Azshara; the camp is right by the entrance."}, [18]={to="Astranaar"}, [19]={npc="Pelturas Whitemoon", tgt="Pelturas Whitemoon"}, [20]={npc="Sentinel Melyria Frostshadow", tgt="Sentinel Melyria Frostshadow"}, [21]={npc="Sentinel Melyria Frostshadow", tgt="Sentinel Melyria Frostshadow", tag="Optional"}, [22]={npc="Illiyana", tgt="Illiyana"}, [23]={npc="Delgren the Purifier", tgt="Delgren the Purifier"}}},
    ["03-29"] = {grind={[1]={mob="Saltstone Gazer", note="South end of the Shimmering Flats; normal mobs, in the same area as the basilisks for A Bump in the Road."}, [2]={mob="Saltstone Crystalhide", note="Mixed in with the Gazers; more of them, slightly lower level."}}, steps={[1]={to="Rut'theran Village", tag="Optional", desc="Little XP in the Darnassus section. Skip if you're in a hurry."}, [2]={text="Step into the portal in Rut'theran Village to Darnassus.", tag="Optional"}, [3]={npc="Thyn'tel Bladeweaver", tgt="Thyn'tel Bladeweaver", tag="Optional"}, [4]={npc="Thyn'tel Bladeweaver", tgt="Thyn'tel Bladeweaver", tag="Optional"}, [5]={hint="Search through Velinde's chest for her journal, then return it along with the key to Thyn'tel Bladeweaver in Darnassus.", tag="Optional"}, [6]={npc="Thyn'tel Bladeweaver", tgt="Thyn'tel Bladeweaver", tag="Optional"}, [7]={npc="Thyn'tel Bladeweaver", tgt="Thyn'tel Bladeweaver", tag="Optional"}, [8]={text="Step into the portal in Darnassus back to Rut'theran Village.", tag="Optional"}, [9]={text="If you did the optional Darnassus quests, fly from Rut'theran Village to Ratchet (changing at Auberdine and Talrendis Point); if you skipped them, fly from Astranaar (changing at Talrendis Point). Follow the main road south, avoid Camp Taurajo, and take the Great Lift down into Thousand Needles. Only use Mor'shan Rampart if neither point is unlocked."}, [10]={text="Ride the Great Lift all the way down."}, [11]={node="Thalanaar"}, [12]={npc="Wizzle Brassbolts", tgt="Wizzle Brassbolts"}, [13]={npc="Wizzle Brassbolts", tgt="Wizzle Brassbolts"}, [14]={npc="Fizzle Brassbolts", tgt="Fizzle Brassbolts"}, [15]={npc="Kravel Koalbeard", tgt="Kravel Koalbeard"}, [16]={npc="Kravel Koalbeard", tgt="Kravel Koalbeard"}, [17]={npc="Kravel Koalbeard", tgt="Kravel Koalbeard"}, [18]={npc="Pozzik", tgt="Pozzik"}, [19]={npc="Trackmaster Zherin", tgt="Trackmaster Zherin"}, [20]={hint="Get 10 Hollow Vulture Bones for Pozzik in the Shimmering Flats."}, [21]={hint="Kill 10 Saltstone Basilisks, 10 Saltstone Crystalhides and 6 Saltstone Gazers for Trackmaster Zherin on the Shimmering Flats."}, [22]={hint="Bring 9 Hardened Tortoise Shells to Wizzle Brassbolts in the Shimmering Flats."}, [23]={hint="Bring 30 Rocket Car Parts to Kravel Koalbeard in the Shimmering Flats."}, [24]={hint="Bring 6 Salty Scorpid Venoms to Fizzle Brassbolts in the Shimmering Flats."}, [25]={npc="Pozzik", tgt="Pozzik"}, [26]={npc="Trackmaster Zherin", tgt="Trackmaster Zherin"}, [27]={npc="Wizzle Brassbolts", tgt="Wizzle Brassbolts"}, [28]={npc="Fizzle Brassbolts", tgt="Fizzle Brassbolts"}, [29]={npc="Kravel Koalbeard", tgt="Kravel Koalbeard"}, [30]={desc="If you're not level 35 before leaving the Shimmering Flats, grind Saltstone Gazers and Saltstone Crystalhides south of the racetrack to 35."}, [31]={text="From Shimmering Flats, follow the road south into Tanaris and unlock the flight point at Gadgetzan.", tag="Flight path locked. Travel there on foot the first time."}, [32]={node="Gadgetzan"}}},
    ["05-d17"] = {name="Razorfen Kraul", entrance="The Barrens (1413), near the portal in the thorn tunnel, about 42.30, 89.90.", pickup="When you fly to Ratchet on your first Thousand Needles trip, get Blueleaf Tubers from Mebok Mizzyrix and pick up the crate, command stick and manual next to him. At the bottom of the Great Lift, pick up Henrig Lonebrow's Journal, hand it to Falfindel Waywarder in Thalanaar, then take The Crone of the Kraul.", pickupS={{"When you fly to Ratchet on your first Thousand Needles trip, get Blueleaf Tubers from Mebok Mizzyrix and pick up the crate, command stick and manual next to him"}, {"At the bottom of the Great Lift, pick up Henrig Lonebrow's Journal, hand it to Falfindel Waywarder in Thalanaar, then take The Crone of the Kraul"}}, tips={{k="取捨", text="Mortality Wanes is turned in at Darnassus. If you don't want a special trip, hand it in the next time you pass through Darnassus."}, {k="說明", text="Razorfen Kraul is west of the Great Lift. Razorfen Downs is east. The Forever client marks the entrance at 42.30, 89.90. Follow the west thorn tunnel from the main road to the dungeon portal.", s={{"Razorfen Kraul is west of the Great Lift"}, {"Razorfen Downs is east"}, {"The Forever client marks the entrance at 42.30, 89.90"}, {"Follow the west thorn tunnel from the main road to the dungeon portal"}}}}, steps={[1]={npc="Mebok Mizzyrix", tgt="Mebok Mizzyrix", desc="Get the crate, command stick and manual by the Ratchet NPC before entering."}, [2]={npc="Henrig Lonebrow's Journal", npcObj=true, desc="Pick up Henrig Lonebrow's Journal at the bottom of the Great Lift and right-click it to start the quest."}, [3]={npc="Falfindel Waywarder", tgt="Falfindel Waywarder"}, [4]={npc="Falfindel Waywarder", tgt="Falfindel Waywarder"}, [5]={text="Optional: from Gadgetzan go north back to the Shimmering Flats, ride the Great Lift up to the Barrens and follow the west thorn tunnel to the dungeon portal. After the dungeon, rejoin {s:03-38}.", tag="Optional"}, [6]={text="Razorfen Kraul entrance"}, [7]={hint="Grab a Crate with Holes.", desc="Location: Dig up tubers along the bramble path or while escorting Willix back.", spot="Dig up tubers along the bramble path or while escorting Willix back."}, [8]={npc="Heralath Fallowbrook", tgt="Heralath Fallowbrook", spot="Behind the last boss, next to Willix"}, [9]={hint="Find and return Treshala's Pendant to Treshala Fallowbrook in Darnassus.", desc="Once you have the quest, quilboar and bosses in the dungeon can all drop the pendant."}, [10]={hint="Bring Razorflank's Medallion to Falfindel Waywarder in Thalanaar.", desc="Location: Leave the bat cave, climb the platform and kill Charlga in the last hut.", spot="Leave the bat cave, climb the platform and kill Charlga in the last hut."}, [11]={npc="Willix the Importer", tgt="Willix the Importer", desc="The escort starts at the tent beside the last boss. Clear the way back to the entrance first, then accept."}, [12]={hint="Escort Willix the Importer out of Razorfen Kraul.", desc="Clear the way back to the entrance first, then accept the Willix escort. Protect him on the walk back to the entrance. Location: Starts at the tent beside the last boss; walk back to the entrance with Willix.", spot="Find Willix in a tent by the last boss and escort him back to the entrance."}, [13]={npc="Willix the Importer", tgt="Willix the Importer", desc="Start the escort from the NPC inside the dungeon.", spot="At the dungeon entrance, where the escort ends"}, [14]={npc="Mebok Mizzyrix", tgt="Mebok Mizzyrix"}, [15]={npc="Falfindel Waywarder", tgt="Falfindel Waywarder"}, [16]={npc="Treshala Fallowbrook", tgt="Treshala Fallowbrook"}}},
    ["03-38"] = {tips={{k="取捨", text="1440 needs you to escort Dalinda through the ambush at the fortress gate, and Book of the Ancients and Reagents for Reclaimers Inc. need elites or packs of demons, so skip them solo."}}, grind={[1]={mob="Kolkar Centaur", note="East valley; top up while doing the bounty."}, [2]={mob="Burning Blade Reaver", note="Outside Thunder Axe Fortress; normal mobs."}}, steps={[1]={text="First visit to Gadgetzan and you can't fly to Stonetalon Peak yet: if your hearthstone is ready, hearth to Stormwind, take the boat at the Stormwind Harbor dock to Auberdine, then fly to Stonetalon Peak; only if your hearthstone is on cooldown, walk north from Gadgetzan back to Shimmering Flats, take the Great Lift up to the Barrens, skirt Camp Taurajo to Ratchet and fly from there."}, [2]={to="Stonetalon Peak", desc="If you've unlocked Nijel's Point, fly straight there (via Theramore) and skip the next step. If Stonetalon Peak isn't unlocked, fly to Astranaar and enter the Stonetalon Mountains through the cave south of Ashenvale."}, [3]={text="From Stonetalon Peak, follow the road south down the mountain, steer clear of the Horde camp as you pass Sun Rock Retreat, and enter Desolace from the southwest of the Stonetalon Mountains. Nijel's Point is in the north of Desolace.", tag="Flight path locked. Travel there on foot the first time."}, [4]={to="Nijel's Point"}, [5]={node="Nijel's Point"}, [6]={npc="Kreldig Ungor", tgt="Kreldig Ungor"}, [7]={npc="Kreldig Ungor", tgt="Kreldig Ungor"}, [8]={npc="Kreldig Ungor", tgt="Kreldig Ungor"}, [9]={npc="Vahlarriel Demonslayer", tgt="Vahlarriel Demonslayer"}, [10]={hint="Bring 10 Hatefury Claws, and 10 Hatefury Horns to Kreldig Ungor in Desolace."}, [11]={npc="Malem Chest", npcObj=true, desc="Follow the northern road west; the chest is beside the overturned wagon by the road."}, [12]={npc="Malem Chest", npcObj=true}, [13]={npc="Vahlarriel Demonslayer", tgt="Vahlarriel Demonslayer"}, [14]={npc="Vahlarriel Demonslayer", tgt="Vahlarriel Demonslayer"}, [15]={npc="Vahlarriel Demonslayer", tgt="Vahlarriel Demonslayer"}, [16]={npc="Kreldig Ungor", tgt="Kreldig Ungor"}, [17]={npc="Kreldig Ungor", tgt="Kreldig Ungor"}, [18]={text="Follow the northern road west to Ethel Rethor, go down to the shipwreck on the west coast, then head back east to Thunder Axe Fortress."}, [19]={npc="Azore Aldamort", tgt="Azore Aldamort"}, [20]={npc="Karnitol's Chest", npcObj=true}, [21]={npc="Karnitol's Chest", npcObj=true}, [22]={npc="Dalinda Malem", tgt="Dalinda Malem"}, [23]={npc="Dalinda Malem", tgt="Dalinda Malem"}, [24]={hint="Find Tyranis Malem in Desolace."}, [25]={hint="Get the Sceptre of Light and then return it to Azore Aldamort at the tower in Ethel Rethor."}, [26]={hint="Slay Burning Blade orcs at Thunder Axe Fortress in the Desolace, then return to Vahlarriel Demonslayer at Nijel's Point."}, [27]={npc="Dalinda Malem", tgt="Dalinda Malem"}, [28]={npc="Kreldig Ungor", tgt="Kreldig Ungor"}, [29]={npc="Kreldig Ungor", tgt="Kreldig Ungor"}, [30]={npc="Vahlarriel Demonslayer", tgt="Vahlarriel Demonslayer"}, [31]={npc="Corporal Melkins", tgt="Corporal Melkins"}, [32]={npc="Captain Pentigast", tgt="Captain Pentigast"}, [33]={npc="Brother Anton", tgt="Brother Anton"}, [34]={text="From Nijel's Point, follow the eastern road south to the Kolkar centaur valley."}, [35]={hint="Bring 15 Centaur Ears to Corporal Melkins at Nijel's Point in Desolace."}, [36]={hint="Acquire 5 Carved Centaur Totems by slaying centaur of any clan throughout Desolace, then return them to Captain Pentigast at Nijel's Point."}, [37]={npc="Bibbly F'utzbuckle", tgt="Bibbly F'utzbuckle"}, [38]={hint="Bring 7 vials of Scorpashi Venom and 3 Aged Kodo Hides to Kreldig Ungor in Desolace."}, [39]={npc="Smeed Scrabblescrew", tgt="Smeed Scrabblescrew"}, [40]={hint="Bring five Tamed Kodos and the Kodo Kombobulator back to Smeed Scrabblescrew at Scrabblescrew's Camp.", desc="Lead each kodo to Smeed, wait until he asks to check it, then right-click the tamed kodo; only go for the next one after the count goes up. Pick up the Bone Collector kodo bones on the way, and watch for the kodo apparitions the bones can draw out."}, [41]={hint="Bring 10 Kodo Bones from the Kodo Graveyard to Bibbly F'utzbuckle at Kormek's Hut."}, [42]={npc="Smeed Scrabblescrew", tgt="Smeed Scrabblescrew"}, [43]={npc="Hornizz Brimbuzzle", tgt="Hornizz Brimbuzzle"}, [44]={text="From the Kodo Graveyard, follow the road south to the Valley of Bones. The demon camp east of the road is Mannoroc Coven; keep away from it."}, [45]={hint="Destroy 30 Undead Ravagers, then return to Brother Anton at Nijel's Point."}, [46]={hint="Bring 8 Ghost-o-plasms and the Crate of Ghost Magnets to Hornizz Brimbuzzle in Desolace.", desc="Place the ghost magnet crate between the two giant skeletons in the Valley of Bones, step back, and kill the centaur spirits one at a time as they are pulled in until you have 8 Ghost-o-plasm. Clear or avoid the level 38-40 mobs nearby; if you can't manage, skip Ghost-o-plasm Round Up."}, [47]={npc="Hornizz Brimbuzzle", tgt="Hornizz Brimbuzzle"}, [48]={npc="Bibbly F'utzbuckle", tgt="Bibbly F'utzbuckle"}, [49]={text="From Bibbly's hut, head northwest to Ethel Rethor to turn in the Sceptre of Light, go north to the coast for the Slitherblade naga, then take the northern road back to Nijel's Point and turn everything in at once."}, [50]={npc="Azore Aldamort", tgt="Azore Aldamort"}, [51]={hint="Find Karnitol's Satchel and return it to Kreldig Ungor in Desolace."}, [52]={npc="Corporal Melkins", tgt="Corporal Melkins"}, [53]={npc="Captain Pentigast", tgt="Captain Pentigast"}, [54]={npc="Kreldig Ungor", tgt="Kreldig Ungor"}, [55]={npc="Brother Anton", tgt="Brother Anton"}, [56]={npc="Brother Anton", tgt="Brother Anton", tag="Optional, Group"}, [57]={npc="Kreldig Ungor", tgt="Kreldig Ungor"}, [58]={npc="Kreldig Ungor", tgt="Kreldig Ungor", desc="Keep the satchel and turn it in at Ironforge after the Badlands."}, [59]={bind="Stormwind"}}},
    ["03-30"] = {name="Arathi Highlands", grind={[1]={mob="Drywhisker Kobold", note="Around the entrance of Drywhisker Gorge; normal mobs, right next to where you finish The Princess Trapped."}, [2]={mob="Drywhisker Digger", note="By the crystal deep in the gorge; a better level match."}, [3]={mob="Boulderfist Brute", note="Ogres around the outside of Boulderfist Hall; on your way when you get the wand."}, [4]={mob="Witherbark Shadow Hunter", note="Witherbark Village in the southeast; the same trolls as for Worth Its Weight in Gold."}}, steps={[1]={to="Refuge Pointe", desc="If Refuge Pointe isn't unlocked, fly to Menethil Harbor, follow the road northeast through the Wetlands, cross Thandol Span into Arathi Highlands and then follow the road to Refuge Pointe."}, [2]={npc="Captain Nials", tgt="Captain Nials"}, [3]={npc="Wanted Board", npcObj=true, tag="Group, Optional"}, [4]={npc="Wanted Board", npcObj=true, tag="Group, Optional", desc="Otto and Falconcrest are level 38 and 40 elites."}, [5]={npc="Skuerto", tgt="Skuerto"}, [6]={npc="Apprentice Kryten", tgt="Apprentice Kryten"}, [7]={npc="Shards of Myzrael", npcObj=true}, [8]={hint="Gather 12 Motes of Myzrael, then bring them to the Iridescent Shards in Drywhisker Gorge."}, [9]={npc="Iridescent Shards", npcObj=true}, [10]={desc="Level to about three-quarters of the way through 36; kill Drywhisker Kobolds and Drywhisker Diggers right here in Drywhisker Gorge."}, [11]={npc="Iridescent Shards", npcObj=true, desc="The Stone of East Binding is on your way west, so get it first; get the Stone of Outer Binding on the way to Refuge Pointe."}, [12]={npc="Quae", tgt="Quae"}, [13]={npc="Quae", tgt="Quae"}, [14]={hint="Find the Forsaken Courier and bring back her Sealed Folder to Quae near the Go'Shek Farm.", desc="The Forsaken Courier patrols the road around Go'Shek Farm; kill her when you see her and take the Sealed Folder."}, [15]={hint="Find 10 Witherbark Tusks, 4 Witherbark Medicine Pouches and a Shadow Hunter Knife for Apprentice Kryten at Refuge Pointe.", desc="Watch out for the patrolling Forsaken Courier."}, [16]={npc="Apprentice Kryten", tgt="Apprentice Kryten"}, [17]={npc="Captain Nials", tgt="Captain Nials", desc="Turn in to Demar Brant at Farholde Keep in the Riverglades; you'll go there at the next stop."}, [18]={npc="Skuerto", tgt="Skuerto"}, [19]={desc="If you're not level 37 before fighting Kor'gresh Coldrage (level 39), kill Boulderfist Brutes outside Boulderfist Hall, or go to Witherbark Village in the east and kill Witherbark Trolls until 37."}, [20]={hint="Find Trelane's Wand of Invocation and return it to Skuerto at Refuge Pointe."}, [21]={npc="Quae", tgt="Quae"}, [22]={npc="Quae", tgt="Quae"}, [23]={npc="Kinelory", tgt="Kinelory"}, [24]={npc="Kinelory", tgt="Kinelory"}, [25]={hint="Protect Kinelory until she returns to Quae.", desc="Escort quest; follow Kinelory. There will be ambushes along the way."}, [26]={npc="Quae", tgt="Quae"}, [27]={npc="Quae", tgt="Quae"}, [28]={npc="Skuerto", tgt="Skuerto"}, [29]={npc="Skuerto", tgt="Skuerto", tag="Group, Optional"}, [30]={hint="Gather the Burning Key, the Cresting Key and the Thundering Key from the Stone of West Binding, the Stone of East Binding and the Stone of Outer Binding."}, [31]={hint="Kill 10 Syndicate Highwaymen and 6 Syndicate Mercenaries."}, [32]={npc="Captain Nials", tgt="Captain Nials"}, [33]={npc="Captain Nials", tgt="Captain Nials", tag="Group, Optional"}, [34]={npc="Stone of Inner Binding", npcObj=true}, [35]={hint="Bring Marez's head to Captain Nials at Refuge Pointe.", tag="Group, Optional"}, [36]={hint="Bring Otto's Head and Falconcrest's Head to Captain Nials at Refuge Pointe.", tag="Group, Optional"}, [37]={hint="Bring 7 Stromgarde Badges to Captain Nials at Refuge Pointe.", tag="Group, Optional"}, [38]={hint="Find an Azure Agate and bring it to Apprentice Kryten at Refuge Pointe.", tag="Group, Optional"}, [39]={npc="Captain Nials", tgt="Captain Nials", tag="Group, Optional"}, [40]={npc="Captain Nials", tgt="Captain Nials", tag="Group, Optional"}, [41]={npc="Captain Nials", tgt="Captain Nials", tag="Group, Optional"}, [42]={npc="Apprentice Kryten", tgt="Apprentice Kryten", tag="Group, Optional"}, [43]={npc="Apprentice Kryten", tgt="Apprentice Kryten"}, [44]={npc="Skuerto", tgt="Skuerto"}, [45]={npc="Skuerto", tgt="Skuerto"}, [46]={hint="Find Trelane's Phylactery, Trelane's Orb, and Trelane's Ember Agate, and return them to Skuerto at Refuge Pointe.", tag="Later, on the way"}, [47]={npc="Skuerto", tgt="Skuerto"}, [48]={npc="Skuerto", tgt="Skuerto"}, [49]={hint="Steal a Syndicate uniform from Northfold Manor to infiltrate Stromgarde Keep.", desc="Steal a Syndicate uniform from Northfold Manor in Arathi Highlands."}, [50]={npc="Syndicate Footlocker", npcObj=true}, [51]={npc="Syndicate Footlocker", npcObj=true}, [52]={hint="While disguised as a member of the Syndicate, find someone inside Stromgarde Keep who knows about the secret deal."}, [53]={npc="Anastasia Miller", tgt="Anastasia Miller"}, [54]={npc="Anastasia Miller", tgt="Anastasia Miller"}, [55]={hint="Find something within Stromgarde Keep to convince Anastasia to give up details of the secret deal."}, [56]={npc="Anastasia Miller", tgt="Anastasia Miller"}, [57]={npc="Anastasia Miller", tgt="Anastasia Miller"}, [58]={hint="Break up the secret deal, and take the object being traded to the Syndicate. Then, return to Myrokos Silentform at Ravenholdt Manor."}, [59]={npc="Myrokos Silentform", tgt="Myrokos Silentform"}, [60]={npc="Veyric Thunderhame", tgt="Veyric Thunderhame"}, [61]={npc="Veyric Thunderhame", tgt="Veyric Thunderhame", tag="Group, Optional", desc="Requires Razorfen Kraul (the dungeon in the southern Barrens); do it once you have a group; skip the follow-up Storm, Earth, and Fire along with it."}, [62]={hint="Defeat Charlga Razorflank in Razorfen Kraul and collect information on the quilboar's plans.", tag="Group, Optional"}, [63]={npc="Veyric Thunderhame", tgt="Veyric Thunderhame", tag="Group, Optional", desc="Veyric Thunderhame can also be found in Ironforge (47.10, 13.79)."}, [64]={npc="Veyric Thunderhame", tgt="Veyric Thunderhame", tag="Optional", desc="The four Twisted Totems drop from mobs in Dustwallow Marsh, the Badlands, the Swamp of Sorrows and Desolace; collect them along the way over the next few stops; finally turn in to Veyric Thunderhame in Ironforge."}, [65]={to="Southshore"}, [66]={npc="Phin Odelic", tgt="Phin Odelic"}, [67]={npc="Magistrate Henry Maleb", tgt="Magistrate Henry Maleb"}, [68]={npc="Raleigh the Devout", tgt="Raleigh the Devout", tag="Optional"}, [69]={bind="Stormwind", desc="If your hearthstone is on cooldown, fly from Southshore to Ironforge and take the Deeprun Tram back to Stormwind."}}},
    ["05-d8"] = {name="Scarlet Monastery", entrance="Tirisfal Glades 82.60, 33.80", pickup="Pick up the pre-dungeon quests when you reach Wetlands (2nd visit); no need for a special trip back before the dungeon.", pickupS={{"Pick up the pre-dungeon quests when you reach Wetlands (2nd visit); no need for a special trip back before the dungeon"}}, steps={[1]={npc="Librarian Mae Paledust", tgt="Librarian Mae Paledust"}, [2]={to="Southshore", desc="You'll connect through Ironforge."}, [3]={npc="Raleigh the Devout", tgt="Raleigh the Devout", tag="Optional"}, [4]={npc="Raleigh the Devout", tgt="Raleigh the Devout", tag="Optional, Group"}, [5]={npc="Magus Olvek", tgt="Magus Olvek", tag="Optional"}, [6]={text="From Hillsbrad go west to Silverpine, then follow the main road north into Tirisfal. Skirt the guards at the Sepulcher, Undercity and Brill, then continue to Scarlet Monastery in the northeast."}, [7]={text="Scarlet Monastery entrance"}, [8]={hint="Retrieve Mythology of the Titans from the Monastery and bring it to Librarian Mae Paledust in Ironforge.", desc="Location: Bookshelf in the back rooms of the Library.", spot="Bookshelf in the back rooms of the Library."}, [9]={hint="Retrieve the book The Lost Magic of the Runemasters from the Scarlet Monastery.", tag="Optional"}, [10]={hint="Kill High Inquisitor Whitemane, Scarlet Commander Mograine, Herod, the Scarlet Champion and Houndmaster Loksey and then report back to Raleigh the Devout in Southshore.", tag="Optional", desc="Defeat Loksey in the Library, Herod in the Armory, and Mograine and Whitemane in the Cathedral. You can finish the wings on separate runs."}, [11]={npc="Magus Olvek", tgt="Magus Olvek", tag="Optional"}, [12]={npc="Raleigh the Devout", tgt="Raleigh the Devout", tag="Optional, When you have the items"}, [13]={npc="Librarian Mae Paledust", tgt="Librarian Mae Paledust", tag="Optional", desc="Retrace your route through Tirisfal and Silverpine to Southshore. Fly to Ironforge if the route is available. Otherwise take the boat to Menethil Harbor, follow the mountain road in the southern Wetlands into Loch Modan, then take the tunnel into Dun Morogh and continue to Ironforge. If your Hearthstone is ready and bound to Stormwind, you can hearth there and take the Deeprun Tram."}}},
    ["03-31"] = {tips={{k="提醒", text="Rog'mar in the middle of the map is a Horde town; don't go near it.", s={{"Rog'mar in the middle of the map is a Horde town; don't go near it"}}}}, steps={[1]={to="Lakeshire", tag="Before heading to the Riverglades, you can buy 8 Solid Sharpening Stone (for The Sharpest of Blades) at the Auction House, or have an alt mail them.", desc="Farholde Keep has no flight point yet, so on your first visit walk east along the main road from Lakeshire into the western entrance of the Riverglades."}, [2]={npc="Dorin Songblade", tgt="Dorin Songblade", tag="Optional, Group"}, [3]={text="The entrance east of Redridge Mountains leads into Bristle Hills; the level 36-38 gnolls around the entrance hit hard.", tag="Flight path locked. Travel there on foot the first time."}, [4]={npc="Scout Bolain", tgt="Scout Bolain"}, [5]={npc="Cedric Dalton", tgt="Cedric Dalton"}, [6]={npc="Cedric Dalton", tgt="Cedric Dalton"}, [7]={npc="Cedric Dalton", tgt="Cedric Dalton"}, [8]={npc="Cedric Dalton", tgt="Cedric Dalton", tag="Optional, Group", desc="Snargl is a level 40 elite; skip him if you can't win."}, [9]={npc="Curly", tgt="Curly"}, [10]={npc="Halligan Turner", tgt="Halligan Turner"}, [11]={npc="Halligan Turner", tgt="Halligan Turner"}, [12]={npc="Hurley", tgt="Hurley"}, [13]={npc="Hurley", tgt="Hurley"}, [14]={hint="Go with Hurley to save Curly.", desc="Follow Hurley to rescue Curly."}, [15]={hint="Kill 8 Redridge Mystics, 8 Redridge Trappers, and 6 Redridge Brutes for Cedric Dalton at Southern Watch."}, [16]={hint="Recover 8 Saw Blades from the gnoll camps in Bristle Hills for Halligan Turner at the lumber mill.", desc="Saw blades are scattered on the ground in the gnoll camp."}, [17]={hint="Locate Snargl in the Bristle Hills, kill him, and bring his snout to Cedric Dalton at Southern Watch.", tag="Optional, Group", desc="Snargl is a level 40 elite; skip him if you can't win."}, [18]={npc="Halligan Turner", tgt="Halligan Turner"}, [19]={npc="Halligan Turner", tgt="Halligan Turner"}, [20]={npc="Eleanor Holmsby", tgt="Eleanor Holmsby"}, [21]={npc="Robbie Holmsby", tgt="Robbie Holmsby"}, [22]={npc="Watcher Fredericks", tgt="Watcher Fredericks"}, [23]={npc="Cedric Dalton", tgt="Cedric Dalton"}, [24]={npc="Cedric Dalton", tgt="Cedric Dalton", tag="Optional"}, [25]={npc="Benjy Wheeler", tgt="Benjy Wheeler"}, [26]={hint="Kill 8 Mudfin Oracles and 8 Mudfin Warriors along the river near Wheeler's Grange."}, [27]={hint="Gather 4 Jumbo Crawfish Shells, 4 pieces of Fresh Manure, and 8 Mudfin Murloc Heads for Halligan Turner.", desc="Kill the Mudsnout murlocs for the heads together with the freshwater fiends, then go north to kill the giant crayfish and pick up Fresh Fertilizer."}, [28]={hint="Find Robbie's Hat somewhere along the river near the murlocs.", desc="Find the hats in the Mudsnout murloc camp."}, [29]={node="Farholde Keep"}, [30]={npc="Demar Brant", tgt="Demar Brant"}, [31]={npc="Demar Brant", tgt="Demar Brant"}, [32]={npc="Demar Brant", tgt="Demar Brant"}, [33]={npc="Demar Brant", tgt="Demar Brant"}, [34]={npc="Ashe Amberhall", tgt="Ashe Amberhall"}, [35]={npc="Ashe Amberhall", tgt="Ashe Amberhall"}, [36]={npc="Ember Bladewhisper", tgt="Ember Bladewhisper"}, [37]={npc="Sister Rowland", tgt="Sister Rowland"}, [38]={npc="Bertrand Ironbrow", tgt="Bertrand Ironbrow"}, [39]={npc="Cassandra Wheeler", tgt="Cassandra Wheeler"}, [40]={hint="Kill 5 Roosting Duskbats in the Farholde Cathedral for Sister Rowland."}, [41]={npc="Sister Rowland", tgt="Sister Rowland"}, [42]={npc="Sister Rowland", tgt="Sister Rowland", tag="Optional, When you have the items", desc="Requires 5 Holy Candles, which reagent vendors sell. If you don't have them, skip this quest and the next one."}, [43]={npc="Sister Rowland", tgt="Sister Rowland", tag="Optional"}, [44]={npc="Sister Rowland", tgt="Sister Rowland"}, [45]={hint="Place 3 Memorial Candles on graves in the chapel graveyard for Sister Rowland at Farholde Keep.", desc="The grave is next to the chapel at Far Watch Post."}, [46]={npc="Sister Rowland", tgt="Sister Rowland"}, [47]={hint="Collect 3 Bundles of Hay for Ember at the training grounds.", desc="The hay bales are in the fields near Far Watch Post."}, [48]={npc="Ember Bladewhisper", tgt="Ember Bladewhisper"}, [49]={npc="Ember Bladewhisper", tgt="Ember Bladewhisper", tag="Optional, When you have the items", desc="Needs 8 Solid Sharpening Stone. Buy them at the Auction House or ask a blacksmith. Skip it if you don't have them."}, [50]={npc="Ember Bladewhisper", tgt="Ember Bladewhisper", tag="Optional"}, [51]={npc="Benjy Wheeler", tgt="Benjy Wheeler"}, [52]={npc="Benjy Wheeler", tgt="Benjy Wheeler"}, [53]={npc="Benjy Wheeler", tgt="Benjy Wheeler"}, [54]={hint="Search near the stables at Wheeler's Grange for evidence of the missing horses' whereabouts.", desc="Look for evidence around the farm's animal pens."}, [55]={npc="Benjy Wheeler", tgt="Benjy Wheeler"}, [56]={npc="Benjy Wheeler", tgt="Benjy Wheeler"}, [57]={npc="Benjy Wheeler", tgt="Benjy Wheeler"}, [58]={hint="Kill the coyote known as Sootfur, and bring its pelt back to Benjy Wheeler."}, [59]={hint="Find one of the horses that fled Wheeler's Grange after the coyote attack and give it some feed.", desc="The runaway horse is near the farm."}, [60]={npc="Lost Horse", tgt="Lost Horse"}, [61]={npc="Lost Horse", tgt="Lost Horse"}, [62]={hint="Bring the lost horse back to Wheeler's Grange.", desc="Bring the runaway horse back to the grange."}, [63]={npc="Benjy Wheeler", tgt="Benjy Wheeler"}, [64]={npc="Benjy Wheeler", tgt="Benjy Wheeler"}, [65]={npc="Robbie Holmsby", tgt="Robbie Holmsby"}, [66]={npc="Halligan Turner", tgt="Halligan Turner"}, [67]={npc="Halligan Turner", tgt="Halligan Turner"}, [68]={npc="Halligan Turner", tgt="Halligan Turner"}, [69]={hint="Plant 5 saplings around the lumber camp with Halligan Turner's tree sprouting kit."}, [70]={npc="Halligan Turner", tgt="Halligan Turner"}, [71]={hint="Locate the Foreman's Crate and return it to Bertrand Ironbrow in Farholde Keep.", desc="The foreman's crate is at Turner's Mill."}, [72]={npc="Farmer Elbrim", tgt="Farmer Elbrim"}, [73]={npc="Fuzzle", tgt="Fuzzle"}, [74]={hint="Defeat 8 Twilight Raiders, 8 Twilight Shadowmancers, and 8 Twilight Neophytes within Sunnyglade for Demar Brant."}, [75]={hint="Collect 5 Farmers' Mementos from Twilight Raiders and place them on the graves west of Elbrim's Farm.", desc="Kill Twilight Raiders for the mementos, then place them on the graves west of Elbrim's Farm."}, [76]={hint="Retrieve 25 Twilight Charms from Twilight Shadowmancers and Twilight Neophytes in Sunnyglade for Ashe Amberhall in Farholde Keep."}, [77]={hint="Collect 5 Twilight Pages from within Sunnyglade for Ashe Amberall in Farholde Keep.", desc="The Twilight pages are scattered across Sunnyglade."}, [78]={npc="Field Marshal's Log", npcObj=true, tag="If it drops, Optional", desc="Twilight mobs drop the Field Marshal's Log; right-click the log in your bags to start the quest."}, [79]={hint="Bring 20 Twilight Finger Bones to Fuzzle.", desc="Twilight Finger Bones come from the same Twilight mobs as Saving Sunnyglade."}, [80]={npc="Fuzzle", tgt="Fuzzle"}, [81]={npc="Fuzzle", tgt="Fuzzle", desc="Follow Fuzzle as he flees. At the end he turns on you with 2 gnolls; defeat them, then go open the treasure."}, [82]={npc="Fuzzle's Treasure", npcObj=true, desc="Fuzzle's Treasure is about 6 map squares west of Sunnyglade."}, [83]={npc="Apprentice Claire", tgt="Apprentice Claire"}, [84]={npc="Apprentice Claire", tgt="Apprentice Claire"}, [85]={hint="Absorb 25 samples into the Crystal Catalyst from Twilight's Hammer cultists and Twilight Ritual Circles in the cave underneath Sunnyglade for Apprentice Claire.", desc="In the cave beneath Sunnyglade, use the Crystal Catalyst on the Twilight's Hammer Cultists and the ritual circles to draw samples."}, [86]={hint="Kill 5 Twilight Ritualists and 5 Empowered Brutes within the caves underneath Sunnyglade."}, [87]={npc="Apprentice Claire", tgt="Apprentice Claire"}, [88]={npc="Apprentice Claire", tgt="Apprentice Claire"}, [89]={npc="Apprentice Claire", tgt="Apprentice Claire", tag="Optional, Group", desc="Chogg'Zac is a level 41 elite deep in the cave."}, [90]={hint="Kill Chogg'Zac in the caves beneath Sunnyglade and retrieve their heads for Apprentice Claire.", tag="Optional, Group", desc="Chogg'Zac is a level 41 elite deep in the cave."}, [91]={npc="Apprentice Claire", tgt="Apprentice Claire", tag="Optional, Group", desc="Chogg'Zac is a level 41 elite deep in the cave."}, [92]={npc="Apprentice Claire", tgt="Apprentice Claire", desc="You must kill Chogg'Zac first."}, [93]={npc="Farmer Elbrim", tgt="Farmer Elbrim"}, [94]={npc="Farmer Elbrim", tgt="Farmer Elbrim"}, [95]={hint="Find Farmer Elbrim's family's possessions in the nearby barn and return them to him."}, [96]={npc="Farmer Elbrim", tgt="Farmer Elbrim"}, [97]={text="The Picked Carcass is on the roadside toward Terral's Watch."}, [98]={npc="Picked Carcass", tgt="Picked Carcass"}, [99]={npc="Watcher Cornelius", tgt="Watcher Cornelius"}, [100]={npc="Watcher Cornelius", tgt="Watcher Cornelius"}, [101]={npc="Watcher Cornelius", tgt="Watcher Cornelius"}, [102]={npc="Watcher Cornelius", tgt="Watcher Cornelius"}, [103]={hint="Bring an Intact Tallstrider Beak to Watcher Cornelius at Terral's Watch."}, [104]={hint="Bring 8 Prized Lion Hides to Watcher Terral."}, [105]={hint="Kill 12 Rog'mar Poachers for Watcher Cornelius.", desc="The poachers are south of Rog'mar; stay away from Rog'mar itself, which is a Horde town."}, [106]={npc="Watcher Cornelius", tgt="Watcher Cornelius"}, [107]={npc="Watcher Cornelius", tgt="Watcher Cornelius"}, [108]={npc="Watcher Cornelius", tgt="Watcher Cornelius"}, [109]={npc="Watcher Cornelius", tgt="Watcher Cornelius"}, [110]={npc="Watcher Cornelius", tgt="Watcher Cornelius", tag="Optional, Group", desc="Ombassa is a level 41 elite."}, [111]={hint="Use the Tallstrider Call to call forth the leader of the lion pride. Slay the beast and retrieve its hide for Watcher Cornelius at Terral's Watch.", tag="Optional, Group", desc="Ombassa is a level 41 elite."}, [112]={npc="Watcher Cornelius", tgt="Watcher Cornelius", tag="Optional, Group", desc="Ombassa is a level 41 elite."}, [113]={text="Head back south to Farholde Keep."}, [114]={npc="Ashe Amberhall", tgt="Ashe Amberhall"}, [115]={npc="Ashe Amberhall", tgt="Ashe Amberhall"}, [116]={npc="Ashe Amberhall", tgt="Ashe Amberhall", desc="You must kill Chogg'Zac first."}, [117]={npc="Demar Brant", tgt="Demar Brant"}, [118]={npc="Demar Brant", tgt="Demar Brant"}, [119]={npc="Bertrand Ironbrow", tgt="Bertrand Ironbrow"}}},
    ["03-32"] = {steps={[1]={to="Menethil Harbor", desc="You'll change flights at Thelsamar."}, [2]={to="Theramore", from="Menethil Harbor", desc="Board the boat at the south dock in Menethil Harbor."}, [3]={node="Theramore"}, [4]={to="Ratchet"}, [5]={npc="Wharfmaster Dizzywig", tgt="Wharfmaster Dizzywig"}, [6]={npc="Wharfmaster Dizzywig", tgt="Wharfmaster Dizzywig"}, [7]={npc="Wharfmaster Dizzywig", tgt="Wharfmaster Dizzywig", tag="Optional"}, [8]={to="Gadgetzan", desc="You'll connect through Theramore. If you didn't unlock Gadgetzan at {s:03-29}, go southwest from Ratchet across the Barrens, take the Great Lift down into Thousand Needles and then head east to Shimmering Flats."}, [9]={text="From Gadgetzan follow the road north into the Shimmering Flats in Thousand Needles."}, [10]={npc="Kravel Koalbeard", tgt="Kravel Koalbeard"}, [11]={npc="Kravel Koalbeard", tgt="Kravel Koalbeard"}, [12]={npc="Fizzle Brassbolts", tgt="Fizzle Brassbolts"}, [13]={npc="Fizzle Brassbolts", tgt="Fizzle Brassbolts"}, [14]={npc="Wizzle Brassbolts", tgt="Wizzle Brassbolts", tag="Optional, Group"}, [15]={npc="Kravel Koalbeard", tgt="Kravel Koalbeard"}, [16]={text="Head south into Tanaris and take a flight from Gadgetzan."}, [17]={to="Theramore"}, [18]={text="Soothing Spices"}, [19]={npc="Guard Byron", tgt="Guard Byron"}, [20]={npc="Captain Garran Vimes", tgt="Captain Garran Vimes"}, [21]={npc="Commander Samaul", tgt="Commander Samaul"}, [22]={npc="Commander Samaul", tgt="Commander Samaul"}, [23]={npc="Tabetha", tgt="Tabetha"}, [24]={npc="Tabetha", tgt="Tabetha"}, [25]={npc="Magus Tirth", tgt="Magus Tirth"}, [26]={npc="Magus Tirth", tgt="Magus Tirth"}, [27]={hint="Find the phrase to Tirth's strongbox, then return to Tirth."}, [28]={npc="Magus Tirth", tgt="Magus Tirth"}, [29]={npc="Magus Tirth", tgt="Magus Tirth", tag="Group, Optional", desc="The book is in the Scarlet Monastery Library; do it once you have a group; Mage's Wand requires turning this in first."}, [30]={hint="Bring the book Rituals of Power to Tabetha in Dustwallow Marsh.", tag="Group, Optional"}, [31]={npc="Tabetha", tgt="Tabetha", tag="Group, Optional"}, [32]={npc="Tabetha", tgt="Tabetha", desc="Jade ×1 can be bought at the Auction House."}, [33]={hint="Bring 1 Jade and the Bolt Charged Bramble to Tabetha in Dustwallow Marsh."}, [34]={npc="Tabetha", tgt="Tabetha"}, [35]={npc="Tabetha", tgt="Tabetha", tag="Optional", desc="Rewards a mage wand."}, [36]={npc="Tabetha", tgt="Tabetha", tag="Optional", desc="Rewards a mage wand."}}},
    ["05-d19"] = {name="Razorfen Downs", entrance="The Barrens (1413), portal deep in the thorn tunnel, about 49.10, 93.40.", tips={{k="取捨", text="The Coldbringer's Eye is picked up in the Alterac Mountains, which the Alliance route doesn't pass, so it's not listed."}, {k="說明", text="Five-player group, no key needed. The entrance is on the eastern path north of the Great Lift, separate from Razorfen Kraul to the west.", s={{"Five-player group, no key needed"}, {"The entrance is on the eastern path north of the Great Lift, separate from Razorfen Kraul to the west"}}}}, steps={[1]={npc="Archbishop Benedictus", tgt="Archbishop Benedictus", tag="Optional", desc="Pick it up when you pass through Stormwind at level 39 or higher; skip it if you miss it."}, [2]={text="Optional: fly from Theramore to Thalanaar, walk east to the Great Lift, ride it up to the Barrens and follow the eastern thorn path to the dungeon portal. After the dungeon, fly back to Theramore and rejoin {s:03-33}.", tag="Optional"}, [3]={npc="Myriam Moonsinger", tgt="Myriam Moonsinger", desc="Accept from Myriam (49.01, 94.94) in the south Barrens. Clear outside before entering."}, [4]={hint="Kill 8 Razorfen Battleguard, 8 Razorfen Thornweavers, and 8 Death's Head Cultists and return to Myriam Moonsinger near the entrance to Razorfen Downs."}, [5]={npc="Myriam Moonsinger", tgt="Myriam Moonsinger"}, [6]={text="Razorfen Downs entrance"}, [7]={npc="Belnistrasz", tgt="Belnistrasz", desc="Find Belnistrasz in the cells. Everyone should finish the oath before the escort."}, [8]={hint="If you agree to aid Belnistrasz, speak with him again and hand the Oathstone he gave you back to him.", desc="Location: Go to the cell near Mordresh Fire Eye and find Belnistrasz. Order: The whole group turns in at the Oath Stone first, then takes the escort.", spot="Find Belnistrasz in the cells near Mordresh Fire Eye."}, [9]={npc="Belnistrasz", tgt="Belnistrasz", spot="Cell near Mordresh Fire Eye: Belnistrasz"}, [10]={npc="Belnistrasz", tgt="Belnistrasz", desc="Wait for the whole group before starting, then stay close to the NPC.", preText="Scourge of the Downs"}, [11]={hint="Escort Belnistrasz to the Quilboar's idol in Razorfen Downs.", desc="Location: Escort Belnistrasz from his cell to the idol and protect him.", spot="Escort Belnistrasz from his cell to the idol and protect him."}, [12]={npc="Belnistrasz's Brazier", npcObj=true, spot="Next to the idol, Belnistrasz's Brazier."}, [13]={hint="Archbishop Bendictus wants you to slay Amnennar the Coldbringer in Razorfen Downs.", tag="Optional", desc="Location: Leave the cells and take the spiral ramp up to Amnennar.", spot="Leave the cells and take the spiral ramp up to Amnennar."}, [14]={npc="Archbishop Benedictus", tgt="Archbishop Benedictus", tag="Optional"}}},
    ["03-33"] = {steps={[1]={text="Set your hearthstone at the inn in Theramore (66.60, 45.20).", bind="Theramore"}, [2]={text="Search Sentry Point for news of Private Hendel. Reaching it completes the quest; then return to Theramore to turn it in."}, [3]={npc="Archmage Tervosh", tgt="Archmage Tervosh"}, [4]={npc="Archmage Tervosh", tgt="Archmage Tervosh"}, [5]={npc="Clerk Lendry", tgt="Clerk Lendry"}, [6]={npc="Morgan Stern", tgt="Morgan Stern"}, [7]={hint="Bring 8 Forked Mudrock Tongues to Morgan Stern in Theramore."}, [8]={npc="\"Swamp Eye\" Jarl", tgt="Swamp Eye Jarl"}, [9]={npc="\"Swamp Eye\" Jarl", tgt="Swamp Eye Jarl"}, [10]={npc="\"Swamp Eye\" Jarl", tgt="Swamp Eye Jarl"}, [11]={npc="Loose Dirt", npcObj=true}, [12]={npc="Stinky Ignatz", tgt="Stinky Ignatz"}, [13]={npc="Private Hendel", tgt="Private Hendel"}, [14]={npc="Private Hendel", tgt="Private Hendel"}, [15]={hint="Defeat Private Hendel in Dustwallow Marsh.", desc="After you talk to Private Hendel he turns hostile; fight him until he surrenders, and turn in once the quest completes."}, [16]={npc="Archmage Tervosh", tgt="Archmage Tervosh"}, [17]={npc="Lady Jaina Proudmoore", tgt="Lady Jaina Proudmoore"}, [18]={npc="Lady Jaina Proudmoore", tgt="Lady Jaina Proudmoore"}, [19]={hint="Bring 40 Unpopped Darkmist Eyes to \"Swamp Eye\" Jarl at the Swamplight Manor."}, [20]={npc="Mudcrush Durtfeet", tgt="Mudcrush Durtfeet"}, [21]={npc="Hoofprints", npcObj=true}, [22]={npc="Theramore Guard Badge", npcObj=true}, [23]={npc="Black Shield", npcObj=true}, [24]={bind="Theramore"}, [25]={npc="Morgan Stern", tgt="Morgan Stern"}, [26]={npc="Morgan Stern", tgt="Morgan Stern"}, [27]={npc="Theramore Lieutenant", tgt="Theramore Lieutenant"}, [28]={npc="Theramore Lieutenant", tgt="Theramore Lieutenant"}, [29]={npc="Captain Garran Vimes", tgt="Captain Garran Vimes"}, [30]={npc="Captain Garran Vimes", tgt="Captain Garran Vimes"}, [31]={npc="Captain Garran Vimes", tgt="Captain Garran Vimes"}, [32]={npc="Captain Garran Vimes", tgt="Captain Garran Vimes"}, [33]={npc="Captain Garran Vimes", tgt="Captain Garran Vimes"}, [34]={npc="Captain Garran Vimes", tgt="Captain Garran Vimes"}, [35]={npc="Adjutant Tesoran", tgt="Adjutant Tesoran"}, [36]={npc="Adjutant Tesoran", tgt="Adjutant Tesoran"}, [37]={npc="Captain Garran Vimes", tgt="Captain Garran Vimes"}, [38]={npc="Captain Garran Vimes", tgt="Captain Garran Vimes"}, [39]={npc="Caz Twosprocket", tgt="Caz Twosprocket"}, [40]={npc="Caz Twosprocket", tgt="Caz Twosprocket"}, [41]={hint="Mudcrush Durtfeet in northern Dustwallow wants 12 Mirefin Heads."}, [42]={npc="\"Swamp Eye\" Jarl", tgt="Swamp Eye Jarl"}, [43]={npc="Mudcrush Durtfeet", tgt="Mudcrush Durtfeet"}, [44]={npc="Balos Jacken", tgt="Balos Jacken"}, [45]={npc="Balos Jacken", tgt="Balos Jacken"}, [46]={npc="Captain Garran Vimes", tgt="Captain Garran Vimes"}, [47]={npc="Captain Garran Vimes", tgt="Captain Garran Vimes"}, [48]={to="Ratchet"}, [49]={to="Booty Bay", from="Ratchet", desc="Board at the Ratchet dock."}, [50]={npc="First Mate Crazz", tgt="First Mate Crazz"}, [51]={npc="\"Sea Wolf\" MacKinley", tgt="Sea Wolf MacKinley"}}},
    ["03-34"] = {name="Stranglethorn Vale", steps={[1]={text="Set your hearthstone at the inn in Booty Bay (27.00, 77.00).", bind="Booty Bay"}, [2]={npc="Krazek", tgt="Krazek"}, [3]={npc="Krazek", tgt="Krazek"}, [4]={npc="Crank Fizzlebub", tgt="Crank Fizzlebub"}, [5]={npc="Kebok", tgt="Kebok"}, [6]={npc="Bloodsail Correspondence", npcObj=true}, [7]={npc="Bloodsail Correspondence", npcObj=true}, [8]={hint="Bring 5 Mistvale Giblets to \"Shaky\" Phillipe in Booty Bay."}, [9]={text="Leave Mistvale Valley to the northwest first, then head north."}, [10]={hint="Sir S. J. Erlgadin of Nesingwary's Expedition wants you to kill 10 Shadowmaw Panthers."}, [11]={hint="Retrieve 8 Tumbled Crystals and return them to Kebok in Booty Bay."}, [12]={hint="Hemet Nesingwary wants you to kill 10 Lashtail Raptors."}, [13]={hint="Acquire 15 Bloodscalp Ears and return them to Kebok in Booty Bay."}, [14]={npc="Thoroughly Scavenged Supplies", npcObj=true, desc="You have to recover 8 stolen goods in the Ruins of Zul'Kunda; look for them along the way through the ruins; skip it if you can't find them all."}, [15]={npc="Zimmix Sputterspark", tgt="Zimmix Sputterspark", desc="The goblin held captive in the Ruins of Zul'Kunda."}, [16]={hint="Bring the Primitive Key obtained from the trolls at the Ruins of Zul'kunda in Stranglethorn Vale to Zimmix Sputterspark."}, [17]={npc="Zimmix Sputterspark", tgt="Zimmix Sputterspark"}, [18]={npc="Zimmix Sputterspark", tgt="Zimmix Sputterspark", tag="Escort", desc="Escort him out of the ruins, then return to Booty Bay and report to the dockmaster."}, [19]={hint="Escort Zimmix Sputterspark away from the Ruins of Zul'Kunda then tell Wharfmaster Lozgil in Booty Bay of your successful rescue.", tag="Escort", desc="Follow Zimmix out of the ruins and protect him from attackers; go hunt the tiger only after your quest log shows it complete."}, [20]={hint="Ajeck Rouack of Nesingwary's Expedition wants you to kill Sin'Dall and return with her paw."}, [21]={hint="Bring 10 Singing Crystal Shards to Crank Fizzlebub."}, [22]={hint="Bring 2 Large River Crocolisk Skins to Drizzlik in Booty Bay."}, [23]={npc="Sir S. J. Erlgadin", tgt="Sir S. J. Erlgadin"}, [24]={npc="Sir S. J. Erlgadin", tgt="Sir S. J. Erlgadin", tag="Group, Optional"}, [25]={npc="Ajeck Rouack", tgt="Ajeck Rouack"}, [26]={npc="Hemet Nesingwary", tgt="Hemet Nesingwary"}, [27]={npc="Hemet Nesingwary", tgt="Hemet Nesingwary"}, [28]={npc="Hemet Nesingwary", tgt="Hemet Nesingwary"}, [29]={hint="Find the haunted island for Baron Revilgaz in Booty Bay.", tag="Optional", desc="This is a dedicated detour with no other objectives nearby. Skip it if you're in a hurry."}, [30]={hint="Hemet Nesingwary wants you to kill 10 Jungle Stalkers."}, [31]={bind="Booty Bay"}, [32]={npc="\"Shaky\" Phillipe", tgt="Shaky Phillipe"}, [33]={npc="\"Shaky\" Phillipe", tgt="Shaky Phillipe"}, [34]={npc="Wharfmaster Lozgil", tgt="Wharfmaster Lozgil"}, [35]={npc="Wharfmaster Lozgil", tgt="Wharfmaster Lozgil"}, [36]={npc="Wharfmaster Lozgil", tgt="Wharfmaster Lozgil", desc="Only available after turning in both Anything of Value and Zimmix's Great Escape; delivery only: turn it in to Wharfmaster Whizzbuzz at Powderfuse Port in the Riverglades."}, [37]={npc="\"Sea Wolf\" MacKinley", tgt="Sea Wolf MacKinley"}, [38]={npc="\"Sea Wolf\" MacKinley", tgt="Sea Wolf MacKinley"}, [39]={npc="First Mate Crazz", tgt="First Mate Crazz"}, [40]={npc="First Mate Crazz", tgt="First Mate Crazz"}, [41]={npc="Drizzlik", tgt="Drizzlik"}, [42]={npc="Drizzlik", tgt="Drizzlik"}, [43]={npc="Crank Fizzlebub", tgt="Crank Fizzlebub"}, [44]={npc="Fleet Master Seahorn", tgt="Fleet Master Seahorn"}, [45]={npc="Baron Revilgaz", tgt="Baron Revilgaz", tag="Optional"}, [46]={npc="Baron Revilgaz", tgt="Baron Revilgaz", tag="Optional"}, [47]={npc="Kebok", tgt="Kebok"}, [48]={npc="Kebok", tgt="Kebok"}, [49]={to="Stormwind"}}},
    ["05-d18"] = {name="The Drowned City", entrance="Stranglethorn Vale 21.50, 27.70", pickup="On your second Stranglethorn visit, when you hand in The Rumormonger to Krazek in Booty Bay, take Shady Saltseers and The Saltseer Captain from him too.", pickupS={{"On your second Stranglethorn visit, when you hand in The Rumormonger to Krazek in Booty Bay, take Shady Saltseers and The Saltseer Captain from him too"}}, tips={{k="取捨", text="Loremaster Dibbs's rubbing and idol quests in Southshore need Kurzen's Mystery and Troll Witchery from the Rebel Camp first. The route doesn't include those, so they're not listed."}, {k="說明", text="The portal is in an underwater cave west of Grom'gol. Bring Water Breathing potions or ask a teammate to cast it.", s={{"The portal is in an underwater cave west of Grom'gol"}, {"Bring Water Breathing potions or ask a teammate to cast it"}}}}, steps={[1]={npc="Krazek", tgt="Krazek"}, [2]={npc="Krazek", tgt="Krazek"}, [3]={text="Optional: it fits best before the Stormwind flight at Stranglethorn Vale. From Booty Bay, follow the west coast north past Grom'gol to the west side of the reef and dive into the underwater cave to find the portal. After the dungeon, hand in at Booty Bay and rejoin {s:03-35}.", tag="Optional"}, [4]={text="The Drowned City entrance"}, [5]={hint="Collect 10 Voodoo Infused Artifacts from Saltseer pirates in the Drowned City.", desc="If you cannot collect enough, keep clearing pirates in the ship area. Location: Enter the Saltseer pirate ship area and loot artifacts from the pirates along the way. Order: Clear it in the same area as the Saltseer Captain.", spot="Clear Saltseer pirates by the ships and loot the artifacts."}, [6]={hint="Slay 3 Saltseer Coroners and Captain Dreadrise in the Drowned City.", desc="Location: Go to the ship area and clear coroners along the passages near the captain. Order: Interact with the glowing pearl after killing the captain.", spot="Clear coroners along the passages near the captain in the ship area."}, [7]={npc="Krazek", tgt="Krazek"}, [8]={npc="Krazek", tgt="Krazek"}}},
    ["03-35"] = {grind={[1]={mob="Feral Crag Coyote", note="The wasteland south of the camp; scattered normal mobs you can kill one at a time."}, [2]={mob="Stonevault Bonesnapper", note="South of Agmond's End; a better level match. When they're in packs, pull from the edge."}}, steps={[1]={npc="Jennea Cannon", tgt="Jennea Cannon", desc="Turn it in to Tabetha in Dustwallow Marsh."}, [2]={npc="Archmage Malin", tgt="Archmage Malin"}, [3]={npc="Brohann Caskbelly", tgt="Brohann Caskbelly"}, [4]={npc="High Sorcerer Andromath", tgt="High Sorcerer Andromath"}, [5]={to="Thelsamar"}, [6]={npc="Ghak Healtouch", tgt="Ghak Healtouch"}, [7]={npc="Prospector Ironband", tgt="Prospector Ironband"}, [8]={npc="Prospector Ironband", tgt="Prospector Ironband"}, [9]={text="From the south road in Loch Modan, go south out of the pass into the Badlands and follow the road south to the Dig Site.", tag="There's no Alliance flight point in the Badlands."}, [10]={npc="Prospector Ryedol", tgt="Prospector Ryedol", desc="From now on, kill any buzzards and wolves you see. A quest needs them."}, [11]={npc="Sigrun Ironhew", tgt="Sigrun Ironhew"}, [12]={npc="Martek the Exiled", tgt="Martek the Exiled"}, [13]={npc="Martek the Exiled", tgt="Martek the Exiled"}, [14]={npc="Rigglefuzz", tgt="Rigglefuzz"}, [15]={npc="Lotwil Veriatus", tgt="Lotwil Veriatus"}, [16]={hint="Find 10 Small Stone Shards and bring them to Lotwil Veriatus in the Badlands."}, [17]={npc="Lotwil Veriatus", tgt="Lotwil Veriatus"}, [18]={npc="Lotwil Veriatus", tgt="Lotwil Veriatus"}, [19]={hint="Bring 3 Large Stone Slabs to Lotwil Veriatus in the Badlands."}, [20]={npc="Lotwil Veriatus", tgt="Lotwil Veriatus"}, [21]={npc="Lotwil Veriatus", tgt="Lotwil Veriatus", tag="Hard, Optional"}, [22]={hint="Find Ryedol's Lucky Pick and return it to Prospector Ryedol south of Hammertoe's Dig Site."}, [23]={hint="Retrieve the Supply Crate for Sigrun Ironhew."}, [24]={npc="Crumpled Map", npcObj=true}, [25]={npc="Prospector Ryedol", tgt="Prospector Ryedol"}, [26]={npc="Prospector Ryedol", tgt="Prospector Ryedol"}, [27]={npc="Sigrun Ironhew", tgt="Sigrun Ironhew"}, [28]={npc="Sigrun Ironhew", tgt="Sigrun Ironhew"}, [29]={desc="If you're not level 40 yet, kill Feral Crag Coyotes south of the camp, or go south to the Stonevault area and kill Stonevault Bonesnappers until 40."}, [30]={npc="Garek", tgt="Garek"}, [31]={npc="Battered Dwarven Skeleton", npcObj=true, desc="Watch out for the patrolling Boss Tho'grun."}, [32]={npc="Battered Dwarven Skeleton", npcObj=true}, [33]={hint="Slay Agmond's killer, Murdaloc."}, [34]={hint="Bring 10 Indurium Flakes to Martek the Exiled in the Badlands."}, [35]={hint="Bring 5 Bracers of Rock Binding to Lotwil Veriatus in the Badlands.", tag="Hard, Optional", desc="This is harder for melee. Come back later if needed."}, [36]={hint="Retrieve the Sign of the Earth for Garek."}, [37]={hint="Get 7 pieces of Scrap Metal for Sigrun."}, [38]={npc="Lotwil Veriatus", tgt="Lotwil Veriatus"}, [39]={npc="Rigglefuzz", tgt="Rigglefuzz"}, [40]={npc="Martek the Exiled", tgt="Martek the Exiled"}, [41]={npc="Martek the Exiled", tgt="Martek the Exiled"}, [42]={npc="Garek", tgt="Garek"}, [43]={npc="Sigrun Ironhew", tgt="Sigrun Ironhew"}, [44]={npc="Prospector Ironband", tgt="Prospector Ironband"}, [45]={npc="Ghak Healtouch", tgt="Ghak Healtouch"}, [46]={to="Ironforge"}, [47]={text="Silver Bar"}, [48]={npc="Roetten Stonehammer", tgt="Roetten Stonehammer"}, [49]={npc="Briarthorn", tgt="Briarthorn", desc="Take it to Ratchet and turn in to Menara Voidrender, then accept Fragments of the Orb of Orahil."}, [50]={npc="Briarthorn", tgt="Briarthorn", desc="Summon Felsteed: turn it in to Strahad Farsan in Ratchet."}, [51]={npc="Brandur Ironhammer", tgt="Brandur Ironhammer", tag="Optional", desc="The intro quest is optional: go straight to Duthorian Rall in Stormwind and accept The Tome of Nobility."}, [52]={npc="Duthorian Rall", tgt="Duthorian Rall", tag="Optional", desc="The intro quest is optional: go straight to Duthorian Rall in Stormwind and accept The Tome of Nobility."}, [53]={npc="Duthorian Rall", tgt="Duthorian Rall"}, [54]={npc="Duthorian Rall", tgt="Duthorian Rall"}}},
    ["05-d9"] = {name="Uldaman", entrance="Badlands 44.60, 12.10", steps={[1]={npc="Krom Stoutarm", tgt="Krom Stoutarm", tag="Group, Optional"}, [2]={npc="Prospector Stormpike", tgt="Prospector Stormpike", tag="Group, Optional"}, [3]={npc="Advisor Belgrum", tgt="Advisor Belgrum", tag="Optional, Group"}, [4]={npc="Rigglefuzz", tgt="Rigglefuzz", tag="Optional"}, [5]={npc="Crumpled Map", npcObj=true, tag="Dungeon prereq"}, [6]={npc="Prospector Ryedol", tgt="Prospector Ryedol", tag="Dungeon prereq"}, [7]={npc="Prospector Ryedol", tgt="Prospector Ryedol", tag="Optional"}, [8]={npc="Theldurin the Lost", tgt="Theldurin the Lost", tag="Optional"}, [9]={npc="Prospector Ironband", tgt="Prospector Ironband", tag="Dungeon prereq"}, [10]={npc="Battered Dwarven Skeleton", npcObj=true, tag="Dungeon prereq"}, [11]={npc="Battered Dwarven Skeleton", npcObj=true, tag="Dungeon prereq"}, [12]={hint="Slay Agmond's killer, Murdaloc.", tag="Dungeon prereq"}, [13]={npc="Prospector Ironband", tgt="Prospector Ironband", tag="Dungeon prereq"}, [14]={npc="Prospector Ironband", tgt="Prospector Ironband", tag="Optional"}, [15]={npc="Ghak Healtouch", tgt="Ghak Healtouch", tag="Dungeon prereq"}, [16]={hint="Acquire the reagents Ghak Healtouch needs from the Badlands, then return to him in Thelsamar.", tag="Dungeon prereq"}, [17]={npc="Ghak Healtouch", tgt="Ghak Healtouch", tag="Dungeon prereq"}, [18]={npc="Ghak Healtouch", tgt="Ghak Healtouch", tag="Optional"}, [19]={text="Uldaman entrance"}, [20]={npc="Hammertoe Grez", tgt="Hammertoe Grez"}, [21]={npc="Hammertoe Grez", tgt="Hammertoe Grez"}, [22]={hint="Find Hammertoe's Amulet and return it to him in Uldaman."}, [23]={npc="Hammertoe Grez", tgt="Hammertoe Grez"}, [24]={npc="Hammertoe Grez", tgt="Hammertoe Grez"}, [25]={hint="Bring 8 Dentrium Power Stones and 8 An'Alleum Power Stones to Rigglefuzz in the Badlands."}, [26]={hint="Bring 12 Magenta Fungus Caps to Ghak Healtouch in Thelsamar."}, [27]={hint="Bring the Tablet of Ryun'eh to Theldurin the Lost."}, [28]={hint="Get Krom Stoutarm's treasured possession from his chest in the North Common Hall of Uldaman, and bring it to him in Ironforge.", tag="Group, Optional"}, [29]={npc="Shattered Necklace", npcObj=true, tag="If it drops, Optional", desc="Right-click the Shattered Necklace in your bags to start the quest. The necklace questline needs two trips back to Ironforge; the later part is done on a second dungeon run after you exit."}, [30]={npc="Baelog", tgt="Baelog", tag="Group, Optional"}, [31]={npc="Baelog", tgt="Baelog"}, [32]={hint="Find the Tablet of Will, and return them to Advisor Belgrum in Ironforge.", tag="Optional, Group"}, [33]={npc="The Discs of Norgannon", npcObj=true}, [34]={npc="The Discs of Norgannon", npcObj=true}, [35]={npc="The Discs of Norgannon", npcObj=true}, [36]={npc="Prospector Ryedol", tgt="Prospector Ryedol"}, [37]={npc="Prospector Ryedol", tgt="Prospector Ryedol"}, [38]={npc="Rigglefuzz", tgt="Rigglefuzz"}, [39]={npc="Theldurin the Lost", tgt="Theldurin the Lost"}, [40]={npc="Theldurin the Lost", tgt="Theldurin the Lost"}, [41]={npc="Prospector Ironband", tgt="Prospector Ironband"}, [42]={npc="Ghak Healtouch", tgt="Ghak Healtouch"}, [43]={npc="Talvash del Kissel", tgt="Talvash del Kissel", tag="Optional"}, [44]={npc="Talvash del Kissel", tgt="Talvash del Kissel", tag="Optional", desc="Requires 5 Silver Bars."}, [45]={npc="Talvash del Kissel", tgt="Talvash del Kissel", tag="Optional"}, [46]={npc="Talvash del Kissel", tgt="Talvash del Kissel", tag="Optional"}, [47]={npc="Gerrig Bonegrip", tgt="Gerrig Bonegrip"}, [48]={npc="Krom Stoutarm", tgt="Krom Stoutarm", tag="Group, Optional"}, [49]={npc="Prospector Stormpike", tgt="Prospector Stormpike"}, [50]={npc="Historian Karnik", tgt="Historian Karnik"}, [51]={npc="Historian Karnik", tgt="Historian Karnik"}, [52]={npc="Advisor Belgrum", tgt="Advisor Belgrum"}, [53]={npc="Advisor Belgrum", tgt="Advisor Belgrum", tag="Optional, Group"}, [54]={npc="Advisor Belgrum", tgt="Advisor Belgrum"}, [55]={npc="Historian Karnik", tgt="Historian Karnik"}, [56]={npc="Historian Karnik", tgt="Historian Karnik"}, [57]={npc="High Explorer Magellas", tgt="High Explorer Magellas"}, [58]={npc="High Explorer Magellas", tgt="High Explorer Magellas"}, [59]={npc="Dinita Stonemantle", tgt="Dinita Stonemantle"}, [60]={text="Second Uldaman run: fly from Ironforge to Thelsamar, head southeast into the Badlands, and enter the dungeon from the north entrance.", tag="Optional, Group", desc="Later part of the necklace questline. If your group doesn't want another run, skip it to the end."}, [61]={npc="Remains of a Paladin", tgt="Remains of a Paladin", tag="Optional, Group", desc="Clear Uldaman all the way to Grimlok."}, [62]={npc="Remains of a Paladin", tgt="Remains of a Paladin", tag="Optional, Group"}, [63]={npc="Talvash's Scrying Bowl", npcObj=true, tag="Optional, Group"}, [64]={npc="Talvash's Scrying Bowl", npcObj=true, tag="Optional, Group"}, [65]={hint="Obtain a power source from the most powerful construct you can find in Uldaman, and deliver it to Talvash del Kissel in Ironforge.", tag="Optional, Group", desc="The power source is on the final boss, Archaedas."}, [66]={to="Ironforge", tag="Optional", desc="After the dungeon, walk back to Thelsamar and fly to Ironforge."}, [67]={npc="Advisor Belgrum", tgt="Advisor Belgrum", tag="Optional, Group"}, [68]={npc="Talvash del Kissel", tgt="Talvash del Kissel", tag="Optional"}, [69]={npc="Talvash del Kissel", tgt="Talvash del Kissel", tag="Optional"}, [70]={npc="Talvash del Kissel", tgt="Talvash del Kissel", tag="Optional"}}},
    ["03-36"] = {steps={[1]={to="Darkshire"}, [2]={npc="Watchmaster Sorigal", tgt="Watchmaster Sorigal"}, [3]={text="From Darkshire, head east through Deadwind Pass into the Swamp of Sorrows."}, [4]={npc="Watcher Biggs", tgt="Watcher Biggs"}, [5]={hint="Bring 10 Specks of Dream Dust to Krazek in Booty Bay. Dream Dust is gathered from the dragon whelps of the Swamp of Sorrows."}, [6]={hint="Kill 8 Young Sawtooth Crocolisks, 10 Sorrow Spinners and 10 Swamp Jaguars then return to Watcher Biggs in the Swamp of Sorrows."}, [7]={npc="Watcher Biggs", tgt="Watcher Biggs"}, [8]={npc="Watcher Biggs", tgt="Watcher Biggs"}, [9]={npc="Noboru's Cudgel", npcObj=true, tag="Optional", desc="Right-click Noboru's Cudgel in your bags to start the quest. Kill Noboru the Cudgel for a gray cudgel and right-click it to start the quest."}, [10]={npc="Magtoor", tgt="Magtoor", tag="Optional"}, [11]={npc="Magtoor", tgt="Magtoor"}, [12]={hint="Bring 6 Draenethyst crystals to Magtoor at The Harborage in the Swamp of Sorrows."}, [13]={hint="Find the Caravan Chest in the Fallow Sanctuary, obtain the Wizards' Reagents and bring to Watcher Biggs."}, [14]={npc="Galen Goodward", tgt="Galen Goodward"}, [15]={hint="Escort Galen out of danger, then find his camp in the Swamp of Sorrows and open his strongbox.", tag="Escort", desc="Follow Galen out of the Fallow Sanctuary (the Lost Ones' camp); mobs on the way attack him and you have to protect him; after the escort, go to his camp and open the strongbox."}, [16]={npc="Galen's Strongbox", npcObj=true}, [17]={npc="Magtoor", tgt="Magtoor"}, [18]={npc="Watcher Biggs", tgt="Watcher Biggs"}, [19]={npc="Watcher Biggs", tgt="Watcher Biggs"}, [20]={hint="Bring 8 pieces of Sundried Driftwood to Watcher Biggs in the Swamp of Sorrows."}, [21]={hint="Brohann Caskbelly in Stormwind wants you to search for the Temple of Atal'Hakkar.", desc="Completes when you approach the Sunken Temple."}, [22]={npc="Watcher Biggs", tgt="Watcher Biggs"}, [23]={npc="Watcher Biggs", tgt="Watcher Biggs"}, [24]={npc="Watcher Biggs", tgt="Watcher Biggs", desc="A delivery quest; turn it in to Dyma Brant at Farwatch Keep at the next stop."}, [25]={text="From the south of the Swamp of Sorrows, enter the Blasted Lands and follow the road south to Nethergarde Keep.", tag="Flight path locked. Travel there on foot the first time."}, [26]={npc="Quartermaster Lungertz", tgt="Quartermaster Lungertz"}, [27]={node="Nethergarde Keep"}, [28]={hint="Collect 5 Twisted Fire Totems, 5 Twisted Earth Totems, 5 Twisted Air Totems, and 5 Twisted Water Totems for Veyric Thunderhame in Arathi Highlands.", tag="Optional", desc="The Wind Totem comes from the Maraudine centaurs in Desolace; you have already been through Desolace, so it takes a separate trip. The Water Totem comes from the Mirefin murlocs in northern Dustwallow Marsh, the Fire Totem from the Stonevault troggs in the Badlands, and the Earth Totem from the Lost Ones in the Swamp of Sorrows. Collect them as you pass through."}}},
    ["03-37"] = {tips={{k="提醒", text="Rog'mar in the middle of the map is a Horde town; don't go near it.", s={{"Rog'mar in the middle of the map is a Horde town; don't go near it"}}}}, steps={[1]={to="Farholde Keep", tag="Before heading to the Riverglades, you can buy 20 Mageweave Cloth (for Wound Dressings) at the Auction House, or have an alt mail them.", desc="You'll change flights at Darkshire and Lakeshire."}, [2]={npc="Demar Brant", tgt="Demar Brant"}, [3]={npc="Demar Brant", tgt="Demar Brant"}, [4]={npc="Demar Brant", tgt="Demar Brant"}, [5]={npc="Demar Brant", tgt="Demar Brant", desc="You must first turn in the drop-triggered Field Marshal's Log before you can pick this up."}, [6]={npc="Ashe Amberhall", tgt="Ashe Amberhall"}, [7]={npc="Bertrand Ironbrow", tgt="Bertrand Ironbrow"}, [8]={npc="Brother Lowley", tgt="Brother Lowley", tag="Optional, When you have the items", desc="Needs 20 Mageweave Cloth. Buy it at the Auction House. Skip it if you don't have them."}, [9]={npc="Brother Lowley", tgt="Brother Lowley", tag="Optional"}, [10]={npc="Brother Lowley", tgt="Brother Lowley"}, [11]={hint="Bandage up 3 Wounded Soldiers for Brother Lowley.", desc="The Wounded Soldiers are right next to Brother Lowley."}, [12]={npc="Brother Lowley", tgt="Brother Lowley"}, [13]={npc="Brother Lowley", tgt="Brother Lowley"}, [14]={npc="Sister Rowland", tgt="Sister Rowland"}, [15]={npc="Tessa Dawnbright", tgt="Tessa Dawnbright"}, [16]={hint="Collect 6 Fresh Apples for Tessa Dawnbright in Farholde Keep.", desc="The fresh apples are under the fruit trees near Far Watch Post."}, [17]={npc="Tessa Dawnbright", tgt="Tessa Dawnbright"}, [18]={npc="Tessa Dawnbright", tgt="Tessa Dawnbright"}, [19]={hint="Collect 3 Coyote Pelts for Tessa Dawnbright in Farholde Keep."}, [20]={npc="Tessa Dawnbright", tgt="Tessa Dawnbright"}, [21]={npc="Tessa Dawnbright", tgt="Tessa Dawnbright"}, [22]={npc="Watcher Cornelius", tgt="Watcher Cornelius"}, [23]={text="From Terral's Watch go west, passing south of Sunnyglade, to Sergeant Riftan in front of Twilight's Hood. Pick up the lumber as you pass Turner's Logging Camp."}, [24]={hint="Collect 10 Wood Bundles from Turner's Logging Camp for Bertrand Ironbrow in Farholde Keep.", desc="The lumber piles are at Turner's Mill."}, [25]={npc="Sergeant Riftan", tgt="Sergeant Riftan"}, [26]={npc="Sergeant Riftan", tgt="Sergeant Riftan"}, [27]={npc="Sergeant Riftan", tgt="Sergeant Riftan"}, [28]={npc="Sergeant Riftan", tgt="Sergeant Riftan"}, [29]={hint="Summon a Twilight's Thrall from a conduit within the Twilight Shroud and capture it with Amberhall's Soulstone.", desc="At the conduit in Twilight's Hood, summon a Twilight Thrall and capture it with a Soulstone."}, [30]={npc="Marshal Ryan", tgt="Marshal Ryan"}, [31]={npc="Marshal Ryan", tgt="Marshal Ryan"}, [32]={hint="Rescue 5 Farholde Scouts within the Twilight's Shroud for Sergeant Riftan.", desc="Scouts are imprisoned all over Twilight's Shroud."}, [33]={hint="Defeat 8 Twilight Fanatics, 8 Twilight Corrupters, and 8 Twilight Champions within the Twilight's Shroud for Sergeant Riftan."}, [34]={hint="Defeat 5 Ogre Miners and 5 Twilight Subjugators in the cave near the Twilight's Shroud for Sergeant Riftan."}, [35]={npc="Sergeant Riftan", tgt="Sergeant Riftan"}, [36]={npc="Sergeant Riftan", tgt="Sergeant Riftan"}, [37]={npc="Sergeant Riftan", tgt="Sergeant Riftan"}, [38]={npc="Sergeant Riftan", tgt="Sergeant Riftan", tag="Optional, Group", desc="Overlord Kilgar is a level 46 elite."}, [39]={hint="Defeat Overlord Kilgar within the Twilight's Shroud and bring his head to Sergeant Riftan.", tag="Optional, Group", desc="Overlord Kilgar is a level 46 elite."}, [40]={npc="Sergeant Riftan", tgt="Sergeant Riftan", tag="Optional, Group", desc="Overlord Kilgar is a level 46 elite."}, [41]={npc="Sergeant Riftan", tgt="Sergeant Riftan", desc="You must kill Overlord Kilgar first."}, [42]={text="Head east through Sunnyglade and south of Terral's Watch to Powderfuse Port, avoiding the Horde town of Rog'mar. Powderfuse Port has no Alliance flight point."}, [43]={npc="Sleebo Fizzlespout", tgt="Sleebo Fizzlespout", desc="Sleebo is a little north of the road to Powderfuse Port."}, [44]={hint="Gather 8 Marsh Gas Vials for Sleebo Fizzlespout.", desc="Collect the swamp gas at the vents near Sleebo."}, [45]={npc="Sleebo Fizzlespout", tgt="Sleebo Fizzlespout"}, [46]={npc="Sleebo Fizzlespout", tgt="Sleebo Fizzlespout"}, [47]={hint="Help Sleebo test his creation."}, [48]={npc="Sleebo Fizzlespout", tgt="Sleebo Fizzlespout"}, [49]={npc="Painted Hide", npcObj=true, desc="Before entering Powderfuse Port, detour south to pick it up here (about 12 map units off the main road), then turn it in to Argo Brinewhistle when you reach the port."}, [50]={npc="Gray Dawnbright", tgt="Gray Dawnbright"}, [51]={npc="Friz Frazzlespark", tgt="Friz Frazzlespark"}, [52]={npc="Friz Frazzlespark", tgt="Friz Frazzlespark"}, [53]={npc="Friz Frazzlespark", tgt="Friz Frazzlespark"}, [54]={npc="Wharfmaster Whizzbuzz", tgt="Wharfmaster Whizzbuzz"}, [55]={npc="Wharfmaster Whizzbuzz", tgt="Wharfmaster Whizzbuzz"}, [56]={npc="Wharfmaster Whizzbuzz", tgt="Wharfmaster Whizzbuzz"}, [57]={npc="Fimbo Greasemitz", tgt="Fimbo Greasemitz"}, [58]={npc="WANTED!", npcObj=true, desc="Trapclaw is on the coast east of Powderfuse Port."}, [59]={npc="WANTED!", npcObj=true, tag="Group, Optional", desc="Old Rot-Chum is a level 42 elite murloc that roams around the murloc isles south of Powderfuse Port."}, [60]={npc="Trapclaw", tgt="Argo Brinewhistle"}, [61]={npc="Trapclaw", tgt="Argo Brinewhistle"}, [62]={hint="Bring Trapclaw's Pincer to Fimbo Greasemitz."}, [63]={hint="Kill 10 Eastsea Buccaneers and 10 Eastsea Musketeers along the Eastwind Shore, north of Powderfuse Port."}, [64]={hint="Collect 8 Smuggled Goods for Friz Frazzlespark at Powderfuse Port.", desc="Kill the Eastsea Buccaneers and Musketeers together with Unfriendly Competition."}, [65]={npc="Fimbo Greasemitz", tgt="Fimbo Greasemitz"}, [66]={npc="Wharfmaster Whizzbuzz", tgt="Wharfmaster Whizzbuzz"}, [67]={npc="Wharfmaster Whizzbuzz", tgt="Wharfmaster Whizzbuzz"}, [68]={npc="Wharfmaster Whizzbuzz", tgt="Wharfmaster Whizzbuzz"}, [69]={npc="Friz Frazzlespark", tgt="Friz Frazzlespark"}, [70]={npc="Friz Frazzlespark", tgt="Friz Frazzlespark"}, [71]={hint="Steal 5 Eastsea Powder Kegs for Wharfmaster Whizzbuzz.", desc="The Powder Kegs are inside the buildings of the Windbreak ruins."}, [72]={hint="Kill 8 Eastsea Raiders and 8 Eastsea Bombardiers for Wharfmaster Whizzbuzz."}, [73]={hint="Collect 15 Beast Entrails and 8 Rotflesh Mushrooms for Argo Brinewhistle.", desc="Collect the entrails from beasts along the way; the Rotflesh Mushrooms are in the cave next to Windbreak, and there are ogres inside."}, [74]={npc="Wharfmaster Whizzbuzz", tgt="Wharfmaster Whizzbuzz"}, [75]={npc="Wharfmaster Whizzbuzz", tgt="Wharfmaster Whizzbuzz"}, [76]={npc="Trapclaw", tgt="Argo Brinewhistle"}, [77]={npc="Trapclaw", tgt="Argo Brinewhistle"}, [78]={hint="Kill 8 Murloc Oracles and 8 Murloc Warriors along the Eastwind Shore."}, [79]={hint="Gather 12 Murloc Eyes and 6 pieces of Sand Crawler Meat for Fimbo Greasemitz."}, [80]={hint="Bring proof of Old Rot-Chum's demise to Wharfmaster Whizzbuzz.", tag="Group, Optional"}, [81]={hint="Use the Big Ball o' Bait to lure out the sea monster. Then, bring its head to Argo Brinewhistle.", desc="Use the bait next to the underwater shipwreck at the murloc island to summon the sea monster, then defeat it and loot the head. Do it on the same trip as the murlocs and crabs on the south shore."}, [82]={npc="Fimbo Greasemitz", tgt="Fimbo Greasemitz"}, [83]={npc="Trapclaw", tgt="Argo Brinewhistle"}, [84]={npc="Wharfmaster Whizzbuzz", tgt="Wharfmaster Whizzbuzz"}, [85]={npc="Wharfmaster Whizzbuzz", tgt="Wharfmaster Whizzbuzz", tag="Group, Optional"}, [86]={npc="Wharfmaster Whizzbuzz", tgt="Wharfmaster Whizzbuzz"}, [87]={npc="Wharfmaster Whizzbuzz", tgt="Wharfmaster Whizzbuzz", tag="Optional", desc="Quest level 45. If it's 3 or more levels above you, you can skip it for now."}, [88]={hint="Plant a remote explosive charge on each of the Eastsea's three boats.", desc="Place one explosive on each of the three Eastsea Buccaneer ships."}, [89]={hint="Deliver The Friz Special to Captain Bentcoin in Eastwind Shore.", desc="After blowing up the ships, take it along the coast to the northeast to turn in."}, [90]={npc="Captain Haynes", tgt="Captain Bentcoin"}, [91]={npc="Captain Haynes", tgt="Captain Haynes"}, [92]={hint="Slay Admiral Lamora, locate his stash of loot, and return it to Wharfmaster Whizzbuzz.", tag="Optional", desc="Quest level 45. If it's 3 or more levels above you, you can skip it for now."}, [93]={npc="Wharfmaster Whizzbuzz", tgt="Wharfmaster Whizzbuzz"}, [94]={npc="Wharfmaster Whizzbuzz", tgt="Wharfmaster Whizzbuzz", tag="Optional"}, [95]={npc="Friz Frazzlespark", tgt="Friz Frazzlespark"}, [96]={npc="Friz Frazzlespark", tgt="Friz Frazzlespark", desc="Turn in to Caravaneer Ruzzgot in Booty Bay; it's on the way the next time you go to Stranglethorn Vale."}, [97]={npc="Friz Frazzlespark", tgt="Friz Frazzlespark", desc="Turn in to Wharfmaster Steamfizzle at Steamwheedle Port in Tanaris; it's on the way when you go to Tanaris later."}, [98]={npc="Friz Frazzlespark", tgt="Friz Frazzlespark", desc="Turn in at Feathermoon Stronghold in Feralas. It is on the way when you go to Feralas later."}, [99]={text="From Powderfuse Port, head southwest back to Farholde Keep."}, [100]={npc="Bertrand Ironbrow", tgt="Bertrand Ironbrow"}, [101]={npc="Ashe Amberhall", tgt="Ashe Amberhall"}, [102]={npc="Ashe Amberhall", tgt="Ashe Amberhall", desc="You must kill Overlord Kilgar first."}, [103]={npc="Demar Brant", tgt="Demar Brant"}, [104]={npc="Demar Brant", tgt="Demar Brant"}, [105]={npc="Demar Brant", tgt="Demar Brant"}, [106]={npc="Demar Brant", tgt="Demar Brant", desc="You must kill Overlord Kilgar first."}, [107]={to="Stormwind", desc="You'll change flights at Lakeshire. If you don't have Delivering Closure or The Twilight Threat, skip Stormwind: if your Hearthstone is ready, hearth straight back to Booty Bay; if your Hearthstone is on cooldown, fly from Farholde Keep via Lakeshire and Stormwind to Booty Bay."}, [108]={npc="Abigail Lawson", tgt="Abigail Lawson"}, [109]={npc="Highlord Bolvar Fordragon", tgt="Highlord Bolvar Fordragon", desc="You must kill Overlord Kilgar first."}, [110]={bind="Booty Bay", desc="If your Hearthstone isn't set to Booty Bay or is still on cooldown: from Stormwind, fly straight to Booty Bay; if you're still at Farholde Keep, change flights at Lakeshire and Stormwind."}, [111]={npc="Krazek", tgt="Krazek"}, [112]={npc="Krazek", tgt="Krazek"}}},
    ["05-d20"] = {name="Krol'dok Stronghold", entrance="Riverglades 37.50, 37.90", pickup="On your second visit to Farholde Keep, take Eye of Mugg from Demar Brant, and after handing in A Small Favor, take Tome of Twilight from Ashe Amberhall.", pickupS={{"On your second visit to Farholde Keep, take Eye of Mugg from Demar Brant, and after handing in A Small Favor, take Tome of Twilight from Ashe Amberhall"}}, tips={{k="取捨", text="Twilight Mementos needs the level 46 elite Overlord Kilgar killed first (optional on the main route), so it's not listed."}, {k="說明", text="The portal is at 37.50, 37.90 and the meeting stone is nearby at 39.10, 38.80. The fortress's outer gate is not the entrance.", s={{"The portal is at 37.50, 37.90 and the meeting stone is nearby at 39.10, 38.80"}, {"The fortress's outer gate is not the entrance"}}}}, steps={[1]={npc="Demar Brant", tgt="Demar Brant"}, [2]={npc="Ashe Amberhall", tgt="Ashe Amberhall", tag="Dungeon prereq"}, [3]={hint="Retrieve 25 Twilight Charms from Twilight Shadowmancers and Twilight Neophytes in Sunnyglade for Ashe Amberhall in Farholde Keep.", tag="Dungeon prereq"}, [4]={npc="Ashe Amberhall", tgt="Ashe Amberhall", tag="Dungeon prereq"}, [5]={npc="Ashe Amberhall", tgt="Ashe Amberhall", tag="Dungeon prereq"}, [6]={hint="Summon a Twilight's Thrall from a conduit within the Twilight Shroud and capture it with Amberhall's Soulstone.", tag="Dungeon prereq"}, [7]={npc="Ashe Amberhall", tgt="Ashe Amberhall", tag="Dungeon prereq"}, [8]={npc="Ashe Amberhall", tgt="Ashe Amberhall"}, [9]={text="Optional: it fits best before the Stormwind flight at {s:03-37}. If you've already left, fly to Farholde Keep (via Lakeshire) first; the portal is at 37.50, 37.90. After the dungeon, hand in at Farholde Keep and rejoin {s:03-39}.", tag="Optional"}, [10]={text="Krol'dok Stronghold entrance"}, [11]={npc="Krol'dok Moulding", npcObj=true, tag="Optional", desc="Tunk drops the mold. Right-click to start the quest. Tunk is in the smithy beside War Manager Ashka. Right-click the mold after looting it."}, [12]={hint="Kill Nar'gurk within Krol'dok Stronghold and recover any valuable information.", desc="Location: Pass Ashka and look for Nar'gurk in the Twilight caster area.", spot="Pass Ashka and look for Nar'gurk in the Twilight caster area."}, [13]={hint="Infiltrate Krol'dok Stronghold and return to Commander Brant with proof of their leader's demise.", desc="Location: Cross Bossman Toof's bridge. Kill Overlord Mugg in the last room.", spot="Cross Bossman Toof's bridge. Kill Overlord Mugg in the last room."}, [14]={npc="Demar Brant", tgt="Demar Brant"}, [15]={npc="Ashe Amberhall", tgt="Ashe Amberhall"}, [16]={npc="Alphonse Dumas", tgt="Alphonse Dumas", tag="Optional"}, [17]={npc="Alphonse Dumas", tgt="Alphonse Dumas", tag="Optional", desc="Buy the materials ahead of time at the Auction House."}, [18]={hint="Bring 4 Thick Leather and 12 Iron Bars to Alphonse Dumas.", tag="Optional", desc="Buy the materials ahead of time at the Auction House."}, [19]={npc="Alphonse Dumas", tgt="Alphonse Dumas", tag="Optional", desc="Buy the materials ahead of time at the Auction House."}}},
    ["03-39"] = {grind={[1]={mob="Naga Explorer", note="Coast north of Booty Bay; normal mobs, tightly grouped."}, [2]={mob="Bloodsail Deckhand", note="The Bloodsail camp on the southern beach; the same mobs as for the Bloodsail quests."}}, steps={[1]={bind="Booty Bay", desc="If your hearthstone is on cooldown, fly from Nijel's Point to Ratchet (via Theramore), then take the boat to Booty Bay."}, [2]={text="Still in Stonetalon Mountains: hearth to Booty Bay if your hearthstone is ready; otherwise fly from Stonetalon Peak to Ratchet (via Astranaar and Talrendis Point) and take the boat to Booty Bay."}, [3]={to="Booty Bay", from="Ratchet"}, [4]={npc="Crank Fizzlebub", tgt="Crank Fizzlebub"}, [5]={npc="Crank Fizzlebub", tgt="Crank Fizzlebub"}, [6]={npc="Deeg", tgt="Deeg"}, [7]={npc="Kebok", tgt="Kebok"}, [8]={npc="Fleet Master Seahorn", tgt="Fleet Master Seahorn"}, [9]={npc="Privateer Bloads", tgt="Privateer Bloads"}, [10]={npc="Sea Wolf MacKinley", tgt="Sea Wolf MacKinley"}, [11]={npc="Dizzy One-Eye", tgt="Dizzy One-Eye"}, [12]={npc="Caravaneer Ruzzgot", tgt="Caravaneer Ruzzgot"}, [13]={hint="Fleet Master Seahorn in Booty Bay wants you to kill 10 Bloodsail Swashbucklers and bring back the Bloodsail Charts and the Bloodsail Orders.", desc="Look for bottles along the beach. Picking one up starts a quest."}, [14]={hint="Deeg in Booty Bay wants you to bring him 15 shares of Snuff."}, [15]={hint="Dizzy One-Eye in Booty Bay wants you to retrieve his eye from the Bloodsail Buccaneers."}, [16]={hint="Bring 10 Bundles of Akiris Reed to Privateer Bloads in Booty Bay."}, [17]={hint="Acquire 6 Water Elemental Bracers for Baron Revilgaz in Booty Bay.", tag="Optional"}, [18]={npc="Privateer Bloads", tgt="Privateer Bloads"}, [19]={npc="Privateer Bloads", tgt="Privateer Bloads"}, [20]={npc="Whiskey Slim", tgt="Whiskey Slim"}, [21]={npc="Deeg", tgt="Deeg"}, [22]={npc="Fleet Master Seahorn", tgt="Fleet Master Seahorn"}, [23]={npc="Fleet Master Seahorn", tgt="Fleet Master Seahorn", tag="Optional"}, [24]={npc="Dizzy One-Eye", tgt="Dizzy One-Eye", desc="Buy any missing pages of The Green Hills of Stranglethorn at the Auction House: 1, 4, 6, 8, 10, 11, 14, 16, 18, 20, 21, 24, 25, 26, 27."}, [25]={desc="If you're not level 43 yet, kill Naga Explorers on the coast north of Booty Bay, or Bloodsail pirates on the beach to the south, until 43."}, [26]={hint="Fleet-Master Seahorn in Booty Bay wants you to kill Captain Stillwater, Captain Keelhaul and Fleet Master Firallon.", tag="Group, Optional", desc="Cortello's Riddle can spawn on the lower deck of any of the three ships. Right-click it to accept once you have it."}, [27]={hint="Bring 12 samples of Zanzil's Mixture to Crank Fizzlebub in Booty Bay."}, [28]={hint="Bring Maury's Clubbed Foot, Jon-Jon's Golden Spyglass, and Chucky's Huge Ring to \"Sea Wolf\" MacKinley in Booty Bay."}, [29]={hint="Bring 5 Snapjaw Crocolisks Skins to Drizzlik in Booty Bay."}, [30]={npc="Hemet Nesingwary", tgt="Hemet Nesingwary"}, [31]={npc="Hemet Nesingwary", tgt="Hemet Nesingwary", tag="Group, Optional"}, [32]={hint="Hemet Nesingwary wants you to kill Tethis, an elusive, dangerous raptor in Stranglethorn.", tag="Later, on the way, Group, Optional"}, [33]={hint="Bring 10 Singing Blue Crystals to Crank Fizzlebub in Booty Bay."}, [34]={hint="Acquire 18 Skullsplitter Tusks and return them to Kebok."}, [35]={hint="Sir S. J. Erlgadin of Nesingwary's Expedition wants you to bring him the Fang of Bhag'thera.", tag="Group, Optional"}, [36]={npc="Sir S. J. Erlgadin", tgt="Sir S. J. Erlgadin", tag="Group, Optional"}, [37]={npc="Barnil Stonepot", tgt="Barnil Stonepot", tag="Optional"}, [38]={npc="Barnil Stonepot", tgt="Barnil Stonepot", tag="Optional"}, [39]={npc="Barnil Stonepot", tgt="Barnil Stonepot", tag="Optional"}, [40]={npc="Barnil Stonepot", tgt="Barnil Stonepot", tag="Optional"}, [41]={npc="Barnil Stonepot", tgt="Barnil Stonepot", tag="Optional"}, [42]={npc="Hemet Nesingwary", tgt="Hemet Nesingwary", tag="Group, Optional"}, [43]={npc="Hemet Nesingwary", tgt="Hemet Nesingwary", tag="Group, Optional"}, [44]={hint="Hemet Nesingwary wants you to bring him the head of King Bangalash, the great white tiger.", tag="Later, on the way, Group, Optional"}, [45]={npc="Hemet Nesingwary", tgt="Hemet Nesingwary", tag="Group, Optional"}, [46]={bind="Booty Bay"}, [47]={npc="Crank Fizzlebub", tgt="Crank Fizzlebub"}, [48]={npc="Crank Fizzlebub", tgt="Crank Fizzlebub"}, [49]={npc="Kebok", tgt="Kebok"}, [50]={npc="Fleet Master Seahorn", tgt="Fleet Master Seahorn"}, [51]={npc="\"Sea Wolf\" MacKinley", tgt="Sea Wolf MacKinley"}, [52]={npc="Drizzlik", tgt="Drizzlik"}, [53]={npc="Baron Revilgaz", tgt="Baron Revilgaz", tag="Optional"}, [54]={to="Ratchet", from="Booty Bay"}, [55]={npc="Klannoc Macleod", tgt="Klannoc Macleod"}, [56]={npc="Klannoc Macleod", tgt="Klannoc Macleod", desc="Defeat four waves of opponents in a row at the arena on Fray Island."}, [57]={hint="Kill Big Will, then speak to Klannoc Macleod on Fray Island.", desc="Defeat four waves of opponents in a row at the arena on Fray Island."}, [58]={npc="Klannoc Macleod", tgt="Klannoc Macleod", desc="Defeat four waves of opponents in a row at the arena on Fray Island."}, [59]={npc="Klannoc Macleod", tgt="Klannoc Macleod"}, [60]={npc="Menara Voidrender", tgt="Menara Voidrender", desc="You need Robes of Arcana. Ask a tailor to make them or buy them at the Auction House."}, [61]={npc="Menara Voidrender", tgt="Menara Voidrender", desc="You need Robes of Arcana. Ask a tailor to make them or buy them at the Auction House."}, [62]={npc="Menara Voidrender", tgt="Menara Voidrender", desc="Gold Bar ×1 can be bought at the Auction House."}, [63]={hint="Bring a Gold Bar to Xizk Goodstitch in Stranglethorn Vale."}, [64]={npc="Xizk Goodstitch", tgt="Xizk Goodstitch", desc="Take the boat from Ratchet to Booty Bay."}, [65]={npc="Xizk Goodstitch", tgt="Xizk Goodstitch"}, [66]={npc="Menara Voidrender", tgt="Menara Voidrender", desc="Take the boat from Booty Bay back to Ratchet."}, [67]={npc="Menara Voidrender", tgt="Menara Voidrender"}, [68]={hint="Bring 10 Vials of Hatefury Blood and 1 Lesser Infernal Stone to Menara Voidrender in the Barrens."}, [69]={npc="Menara Voidrender", tgt="Menara Voidrender"}, [70]={npc="Xizk Goodstitch", tgt="Xizk Goodstitch", desc="Take the boat from Ratchet to Booty Bay."}, [71]={npc="Xizk Goodstitch", tgt="Xizk Goodstitch"}, [72]={npc="Menara Voidrender", tgt="Menara Voidrender", desc="Take the boat from Booty Bay back to Ratchet."}, [73]={hint="Bring some Fine Gold Thread, 2 Smoldering Coals, and a Soul Shard to Menara Voidrender in the Barrens.", desc="Arathi leg: take the boat from Ratchet to Booty Bay, then fly to Refuge Pointe (changing at Stormwind and Ironforge). Reverse the trip on the way back."}, [74]={npc="Menara Voidrender", tgt="Menara Voidrender"}, [75]={npc="Menara Voidrender", tgt="Menara Voidrender", desc="Rewards Enchanted Gold Bloodrobe."}, [76]={hint="Wait for Menara Voidrender to complete your robe and then speak to her again.", desc="Rewards Enchanted Gold Bloodrobe."}, [77]={npc="Menara Voidrender", tgt="Menara Voidrender", desc="Rewards Enchanted Gold Bloodrobe."}, [78]={npc="Menara Voidrender", tgt="Menara Voidrender"}, [79]={npc="Menara Voidrender", tgt="Menara Voidrender"}, [80]={npc="Acolyte Wytula", tgt="Acolyte Wytula", desc="Felhound shard. Choose either this or Shard of an Infernal."}, [81]={npc="Acolyte Magaz", tgt="Acolyte Magaz", tag="Optional", desc="Infernal shard. Choose either this or Shard of a Felhound."}, [82]={hint="Speak to Menara's acolytes inside the tower above Ratchet and choose one of their paths to follow."}, [83]={hint="Take the Felhas Ruby and use it on one of the Felhounds found in Desolace. After successful, bring the Felhas Ruby and the Imprisoned Felhound Spirit back to Menara Voidrender in the Barrens.", desc="Felhound shard. Choose either this or Shard of an Infernal."}, [84]={hint="Take the Infus Emerald and use it on one of the Infernals found in Desolace. After successful, bring the Infus Emerald and the Imprisoned Infernal Spirit back to Menara Voidrender in the Barrens.", tag="Optional", desc="Infernal shard. Choose either this or Shard of a Felhound."}, [85]={npc="Menara Voidrender", tgt="Menara Voidrender", desc="Felhound shard. Choose either this or Shard of an Infernal."}, [86]={npc="Menara Voidrender", tgt="Menara Voidrender", tag="Optional", desc="Infernal shard. Choose either this or Shard of a Felhound."}, [87]={npc="Tabetha", tgt="Tabetha"}, [88]={npc="Tabetha", tgt="Tabetha", tag="Group, Optional"}, [89]={hint="Kill the Demon of the Orb, then speak with Tabetha.", tag="Group, Optional", desc="The Demon of the Orb is a level 40 elite; find a group for it."}, [90]={npc="Tabetha", tgt="Tabetha", tag="Group, Optional"}, [91]={npc="Tabetha", tgt="Tabetha", tag="Optional"}, [92]={npc="Menara Voidrender", tgt="Menara Voidrender", tag="Optional"}, [93]={npc="Menara Voidrender", tgt="Menara Voidrender", tag="Optional", desc="Do this one if you chose the felhound shard."}, [94]={hint="Wait for Menara Voidrender to complete the Orb of Dar'Orahil and then speak to her again.", tag="Optional", desc="Do this one if you chose the felhound shard."}, [95]={npc="Menara Voidrender", tgt="Menara Voidrender", tag="Optional", desc="Do this one if you chose the felhound shard."}, [96]={npc="Menara Voidrender", tgt="Menara Voidrender", tag="Optional", desc="Do this one if you chose the infernal shard."}, [97]={hint="Wait for Menara Voidrender to complete the Orb of Noh'Orahil and then speak to her again.", tag="Optional", desc="Do this one if you chose the infernal shard."}, [98]={npc="Menara Voidrender", tgt="Menara Voidrender", tag="Optional", desc="Do this one if you chose the infernal shard."}, [99]={npc="Strahad Farsan", tgt="Strahad Farsan"}, [100]={npc="Strahad Farsan", tgt="Strahad Farsan", desc="Turn in to learn Summon Felsteed."}, [101]={npc="Strahad Farsan", tgt="Strahad Farsan", desc="Turn in to learn Summon Felsteed."}, [102]={to="Theramore"}, [103]={npc="Privateer Groy", tgt="Privateer Groy"}, [104]={npc="Tabetha", tgt="Tabetha"}, [105]={npc="Tabetha", tgt="Tabetha"}, [106]={hint="Bring an Infernal Orb to Tabetha in Dustwallow Marsh."}, [107]={npc="Tabetha", tgt="Tabetha"}, [108]={npc="Tabetha", tgt="Tabetha", tag="Group, Optional", desc="The Demon of the Orb is a level 40 elite; find a group for it."}, [109]={hint="Kill the Demon of the Orb, then speak with Tabetha.", tag="Group, Optional"}, [110]={npc="Tabetha", tgt="Tabetha", tag="Group, Optional"}, [111]={npc="Tabetha", tgt="Tabetha", tag="Group, Optional", desc="Inside the Uldaman dungeon."}, [112]={hint="Retrieve an Obsidian Power Source and bring it to Tabetha in Dustwallow Marsh.", tag="Group, Optional", desc="Inside the Uldaman dungeon."}, [113]={npc="Tabetha", tgt="Tabetha", tag="Group, Optional", desc="Inside the Uldaman dungeon."}, [114]={npc="Tabetha", tgt="Tabetha", tag="Optional"}, [115]={hint="Kill 12 Mana Surges in the allowed time limit.", tag="Optional"}, [116]={npc="Tabetha", tgt="Tabetha", tag="Optional"}, [117]={npc="Tabetha", tgt="Tabetha", tag="Optional"}, [118]={npc="Tabetha", tgt="Tabetha", tag="Optional"}}},
    ["03-40"] = {grind={[1]={mob="Wastewander Rogue", note="The Wastewander camp southeast of Gadgetzan; the same mobs as for Wastewander Justice."}, [2]={mob="Wastewander Shadow Mage", note="Same camp; casters, so pull them one at a time."}}, steps={[1]={to="Gadgetzan"}, [2]={npc="Kravel Koalbeard", tgt="Kravel Koalbeard"}, [3]={npc="Kravel Koalbeard", tgt="Kravel Koalbeard"}, [4]={npc="Fizzle Brassbolts", tgt="Fizzle Brassbolts"}, [5]={npc="Pozzik", tgt="Pozzik"}, [6]={npc="Zamek", tgt="Zamek"}, [7]={npc="Zamek", tgt="Zamek"}, [8]={npc="Rizzle's Unguarded Plans", npcObj=true, desc="Wait until Rizzle Brassbolts leaves the building before you act."}, [9]={npc="Rizzle's Unguarded Plans", npcObj=true}, [10]={npc="Pozzik", tgt="Pozzik"}, [11]={npc="Wanted Poster", npcObj=true}, [12]={npc="Wanted Poster", npcObj=true}, [13]={npc="Spigot Operator Luglunket", tgt="Spigot Operator Luglunket"}, [14]={npc="Chief Engineer Bilgewhizzle", tgt="Chief Engineer Bilgewhizzle"}, [15]={npc="Jhordy Lapforge", tgt="Jhordy Lapforge"}, [16]={hint="Jhordy Lapforge wants you to return to him after you have dumped the Crate of Radioactive Refuse in the desert of Tanaris a safe distance away from Gadgetzan and other trash.", desc="Find an open spot on the way to the Wastewander camp and use the quest item there."}, [17]={hint="Take down 10 Wastewander Bandits and Thieves east of Gadgetzan, then report back to Chief Engineer Bilgewhizzle."}, [18]={desc="If you're not level 44 yet, stay at the Wastewander camp and kill Wastewander Rogues and Wastewander Shadow Mages until 44."}, [19]={npc="Haughty Modiste", tgt="Haughty Modiste"}, [20]={npc="Yeh'kinya", tgt="Yeh'kinya"}, [21]={npc="Stoley", tgt="Stoley"}, [22]={npc="Stoley", tgt="Stoley"}, [23]={npc="Security Chief Bilgewhizzle", tgt="Security Chief Bilgewhizzle", desc="Save it for your second visit to Tanaris, when you fight the Dunemaul ogres."}, [24]={npc="Security Chief Bilgewhizzle", tgt="Security Chief Bilgewhizzle"}, [25]={npc="Wharfmaster Steamfizzle", tgt="Wharfmaster Steamfizzle", desc="Only available after you've accepted it at Powderfuse Port."}, [26]={hint="Bring Andre's Head to Security Chief Bilgewhizzle in Steamwheedle Port."}, [27]={hint="Haughty Modiste wants you to collect 20 Southsea Pirate Hats and return them to her at Steamwheedle Port in Tanaris."}, [28]={hint="Security Chief Bilgewhizzle of Steamwheedle Port in Tanaris wants you to kill 10 Southsea Pirates, 10 Southsea Freebooters, 10 Southsea Dock Workers and 10 Southsea Swashbucklers."}, [29]={hint="Bring Stoley's Shipment to Stoley in Steamwheedle Port."}, [30]={npc="Jhordy Lapforge", tgt="Jhordy Lapforge"}, [31]={npc="Chief Engineer Bilgewhizzle", tgt="Chief Engineer Bilgewhizzle"}, [32]={npc="Chief Engineer Bilgewhizzle", tgt="Chief Engineer Bilgewhizzle"}, [33]={npc="Spigot Operator Luglunket", tgt="Spigot Operator Luglunket"}, [34]={hint="Take down 10 Wastewander Shadow Mages, 8 Wastewander Rogues, and 6 Wastewander Assassins for Chief Engineer Bilgewhizzle in Gadgetzan."}, [35]={hint="Bring the head of Caliph Scorpidsting to Chief Engineer Bilgewhizzle in Gadgetzan."}, [36]={npc="Stoley", tgt="Stoley"}, [37]={npc="Stoley", tgt="Stoley"}, [38]={npc="Security Chief Bilgewhizzle", tgt="Security Chief Bilgewhizzle"}, [39]={npc="Security Chief Bilgewhizzle", tgt="Security Chief Bilgewhizzle"}, [40]={npc="Haughty Modiste", tgt="Haughty Modiste"}, [41]={npc="Chief Engineer Bilgewhizzle", tgt="Chief Engineer Bilgewhizzle"}, [42]={npc="Chief Engineer Bilgewhizzle", tgt="Chief Engineer Bilgewhizzle"}, [43]={npc="Curgle Cranklehop", tgt="Curgle Cranklehop"}}},
    ["05-d10"] = {name="Zul'Farrak", entrance="Tanaris 38.70, 20.10", pickup="Pick up the pre-dungeon quests when you reach Stranglethorn Vale (3rd visit); no need for a special trip back before the dungeon.", pickupS={{"Pick up the pre-dungeon quests when you reach Stranglethorn Vale (3rd visit); no need for a special trip back before the dungeon"}}, steps={[1]={npc="Wizzle Brassbolts", tgt="Wizzle Brassbolts", tag="Optional, Group"}, [2]={npc="Tabetha", tgt="Tabetha", tag="Optional, Group"}, [3]={npc="Krazek", tgt="Krazek"}, [4]={npc="Yeh'kinya", tgt="Yeh'kinya", tag="Dungeon prereq"}, [5]={hint="Capture the spirits of 3 screechers in Feralas, then return to Yeh'kinya in Steamwheedle Port.", tag="Dungeon prereq", desc="Kill Vale Screamers on the coast of the Isle of Dread in Feralas. Use Yeh'kinya's Bramble on each corpse, then speak to the spirit that appears. Repeat until your quest log shows three spirits."}, [6]={npc="Yeh'kinya", tgt="Yeh'kinya", tag="Dungeon prereq"}, [7]={npc="Yeh'kinya", tgt="Yeh'kinya", tag="Optional"}, [8]={npc="Tran'rek", tgt="Tran'rek", tag="Optional"}, [9]={npc="Chief Engineer Bilgewhizzle", tgt="Chief Engineer Bilgewhizzle", tag="Optional"}, [10]={npc="Trenton Lighthammer", tgt="Trenton Lighthammer", tag="Optional"}, [11]={text="Zul'Farrak entrance"}, [12]={hint="Bring the Tiara of the Deep to Tabetha in Dustwallow Marsh.", tag="Optional, Group", spot="Defeat Hydromancer Velratha at the pool and loot her tiara."}, [13]={hint="Bring Gahz'rilla's Electrified Scale to Wizzle Brassbolts in the Shimmering Flats.", tag="Optional, Group", spot="One party member needs the Mallet of Zul'Farrak to summon Gahz'rilla at the pool gong. If the boss is already present, defeat it and loot the scale."}, [14]={hint="Bring Nekrum's Medallion to Thadius Grimshade in the Blasted Lands.", tag="Optional, Group", spot="Defeat Nekrum on the pyramid steps and loot his medallion."}, [15]={npc="Tran'rek", tgt="Tran'rek"}, [16]={npc="Trenton Lighthammer", tgt="Trenton Lighthammer", tag="Optional"}, [17]={npc="Chief Engineer Bilgewhizzle", tgt="Chief Engineer Bilgewhizzle", tag="Optional"}, [18]={npc="Tran'rek", tgt="Tran'rek", tag="Optional"}, [19]={npc="Yeh'kinya", tgt="Yeh'kinya", tag="Optional"}, [20]={npc="Wizzle Brassbolts", tgt="Wizzle Brassbolts", tag="Optional"}, [21]={npc="Tabetha", tgt="Tabetha", tag="Optional"}, [22]={npc="Thadius Grimshade", tgt="Thadius Grimshade", tag="Optional, Group"}}},
    ["03-41"] = {steps={[1]={to="Thalanaar"}, [2]={text="From Thalanaar, head west through Feralas to the dock on the coast and take the boat to Feathermoon Stronghold."}, [3]={node="Feathermoon Stronghold"}, [4]={npc="Pratt McGrubben", tgt="Pratt McGrubben"}, [5]={npc="Mardrack Greenwell", tgt="Mardrack Greenwell"}, [6]={text="Set your hearthstone at the inn in Feathermoon Stronghold (31.00, 43.20).", bind="Feathermoon Stronghold"}, [7]={npc="Shandris Feathermoon", tgt="Shandris Feathermoon"}, [8]={npc="Latronicus Moonspear", tgt="Latronicus Moonspear"}, [9]={npc="Troyas Moonbreeze", tgt="Troyas Moonbreeze"}, [10]={npc="Angelas Moonbreeze", tgt="Angelas Moonbreeze"}, [11]={npc="Ginro Hearthkindle", tgt="Ginro Hearthkindle"}, [12]={npc="Ginro Hearthkindle", tgt="Ginro Hearthkindle"}, [13]={npc="Solarsal Gazebo", npcObj=true}, [14]={npc="Solarsal Gazebo", npcObj=true}, [15]={npc="Shandris Feathermoon", tgt="Shandris Feathermoon"}, [16]={npc="Shandris Feathermoon", tgt="Shandris Feathermoon"}, [17]={npc="Latronicus Moonspear", tgt="Latronicus Moonspear"}, [18]={npc="Latronicus Moonspear", tgt="Latronicus Moonspear"}, [19]={hint="Bring 10 Hatecrest Naga Scales to Latronicus Moonspear in Feathermoon Stronghold.", desc="The Naga along the coast south of Feathermoon Stronghold all drop scales; collect them and return to the stronghold."}, [20]={npc="Latronicus Moonspear", tgt="Latronicus Moonspear"}, [21]={npc="Latronicus Moonspear", tgt="Latronicus Moonspear", tag="Hard, Optional"}, [22]={hint="Eliminate Lord Shalzaru, and then bring the Mysterious Relic he uncovered to Latronicus Moonspear in Feathermoon Stronghold.", tag="Hard, Optional"}, [23]={text="Isle of Dread coast: use the bramble on a corpse, then speak to its spirit."}, [24]={hint="Capture the spirits of 3 screechers in Feralas, then return to Yeh'kinya in Steamwheedle Port.", desc="Kill Vale Screamers on the coast of the Isle of Dread in Feralas. Use Yeh'kinya's Bramble on each corpse, then speak to the spirit that appears. Repeat until your quest log shows three spirits."}, [25]={npc="Wrecked Row Boat", npcObj=true}, [26]={npc="Wrecked Row Boat", npcObj=true}, [27]={bind="Feathermoon Stronghold"}, [28]={npc="Ginro Hearthkindle", tgt="Ginro Hearthkindle"}, [29]={npc="Ginro Hearthkindle", tgt="Ginro Hearthkindle"}, [30]={npc="Quintis Jonespyre", tgt="Quintis Jonespyre"}, [31]={npc="Quintis Jonespyre", tgt="Quintis Jonespyre"}, [32]={npc="Ginro Hearthkindle", tgt="Ginro Hearthkindle"}, [33]={npc="Ginro Hearthkindle", tgt="Ginro Hearthkindle"}, [34]={hint="Bring 10 Thick Yeti Hides to Pratt McGrubben in Feathermoon Stronghold."}, [35]={hint="Angelas Moonbreeze wants you to kill 8 Gordunni Warlocks, 8 Gordunni Shaman, and 8 Gordunni Brutes."}, [36]={npc="Kindal Moonweaver", tgt="Kindal Moonweaver"}, [37]={hint="Using the Bamboo Cage Key, free the Sprite Darters from the pen in the Grimtotem camp. At least 6 Sprite Darters and Kindal Moonweaver must survive.", desc="Time limit of 6 minutes; before accepting, restore full health and clear the monsters near the pen."}, [38]={npc="Kindal Moonweaver", tgt="Kindal Moonweaver"}, [39]={npc="Jer'kai Moonweaver", tgt="Jer'kai Moonweaver"}, [40]={hint="Kill 12 Grimtotem Naturalists, 10 Grimtotem Raiders, and 6 Grimtotem Shamans before returning to Jer'kai Moonweaver in Feralas."}, [41]={npc="Jer'kai Moonweaver", tgt="Jer'kai Moonweaver"}, [42]={npc="Jer'kai Moonweaver", tgt="Jer'kai Moonweaver"}, [43]={npc="Large Leather Backpacks", npcObj=true}, [44]={npc="Large Leather Backpacks", npcObj=true}, [45]={text="The cocoon is inside the Writhing Deep cave; walk in from the entrance (73.20, 63.90 → 72.30, 64.20)."}, [46]={npc="Zukk'ash Pod", npcObj=true}, [47]={npc="Zukk'ash Pod", npcObj=true}, [48]={hint="Free Raschal from the Zukk'ash hive."}, [49]={npc="OOX-22/FE Distress Beacon", npcObj=true, tag="If it drops, Optional", desc="Right-click OOX-22/FE Distress Beacon in your bags to start the quest."}, [50]={npc="Homing Robot OOX-22/FE", tgt="Homing Robot OOX-22/FE", tag="Optional"}, [51]={npc="Homing Robot OOX-22/FE", tgt="Homing Robot OOX-22/FE", tag="Optional"}, [52]={hint="Escort OOX-22/FE to the dock along the Forgotten Coast, then report to Oglethorpe Obnoticus in Booty Bay.", tag="Optional", desc="Escort the robot chicken to the dock on the Forgotten Coast to the northwest; there are ambushes along the way; the turn-in is in Booty Bay."}, [53]={hint="Escort OOX-22/FE to the dock along the Forgotten Coast, then report to Oglethorpe Obnoticus in Booty Bay.", tag="Optional", desc="Escort failed: abandon the quest in your quest log, then accept it again from the robot."}, [54]={npc="Angelas Moonbreeze", tgt="Angelas Moonbreeze"}, [55]={npc="Ginro Hearthkindle", tgt="Ginro Hearthkindle"}, [56]={npc="Ginro Hearthkindle", tgt="Ginro Hearthkindle"}, [57]={npc="Shandris Feathermoon", tgt="Shandris Feathermoon"}, [58]={npc="Shandris Feathermoon", tgt="Shandris Feathermoon"}, [59]={npc="Latronicus Moonspear", tgt="Latronicus Moonspear"}, [60]={npc="Latronicus Moonspear", tgt="Latronicus Moonspear"}, [61]={npc="Vestia Moonspear", tgt="Vestia Moonspear"}, [62]={npc="Pratt McGrubben", tgt="Pratt McGrubben"}, [63]={to="Rut'theran Village"}}},
    ["05-d21"] = {name="Maraudon", entrance="Desolace 29.10, 62.50", pickup="If you're level 39 during the Dustwallow Marsh stop, take Shadowshard Fragments from Archmage Tervosh in Theramore. Pick up the rest in Desolace: Talendria and Keeper Marandis at Nijel's Point, Willow, the Centaur Pariah, and finally Cavindra at the cave mouth.", pickupS={{"If you're level 39 during the Dustwallow Marsh stop, take Shadowshard Fragments from Archmage Tervosh in Theramore"}, {"Pick up the rest in Desolace: Talendria and Keeper Marandis at Nijel's Point, Willow, the Centaur Pariah, and finally Cavindra at the cave mouth"}}, tips={{k="取捨", text="Do both orange and purple wings to get the scepter on your first run. If you only want the princess and crocodile, use a party member's scepter to enter the inner wing. Skip the shortcut if you need the shadow mobs outside or objectives in another wing."}, {k="說明", text="29.10, 62.50 is the outdoor cave entrance; to find the orange and purple dungeon portals, follow the tunnel of the matching color. The purple and orange routes meet near the poison falls.", s={{"29.10, 62.50 is the outdoor cave entrance; to find the orange and purple dungeon portals, follow the tunnel of the matching color"}, {"The purple and orange routes meet near the poison falls"}}}}, steps={[1]={npc="Archmage Tervosh", tgt="Archmage Tervosh"}, [2]={text="Optional: fly from Feathermoon Stronghold to Nijel's Point for the quests, then head south for Willow and the Centaur Pariah, and finally to the Maraudon cave in the southwest. After the dungeon, fly to Rut'theran Village and rejoin {s:04-42}.", tag="Optional"}, [3]={npc="Talendria", tgt="Talendria"}, [4]={npc="Keeper Marandis", tgt="Keeper Marandis"}, [5]={npc="Willow", tgt="Willow"}, [6]={npc="Centaur Pariah", tgt="Centaur Pariah", desc="Centaur Pariah patrols southern Desolace."}, [7]={npc="Shen'dralar Pylon", npcObj=true, tag="Optional"}, [8]={hint="Explore Shen'dralas in an effort to find other pylons like the one you found.", tag="Optional"}, [9]={npc="Mordent Evenshade", tgt="Mordent Evenshade", tag="Optional"}, [10]={npc="Mordent Evenshade", tgt="Mordent Evenshade", tag="Optional", preText="Strange Pylons"}, [11]={hint="Recover shards and fragments of the pylons, found guarded at the Magram and Gelkis villages. Return them to Mordent Evenshade.", tag="Optional", desc="Pins mark the two items in the Magram and Gelkis centaur villages, in that order."}, [12]={npc="Mordent Evenshade", tgt="Mordent Evenshade", tag="Optional"}, [13]={npc="Mordent Evenshade", tgt="Mordent Evenshade", tag="Optional", desc="Check the quest log for the amount of mana you need.", preText="Fragments of the Pylons"}, [14]={hint="Acquire the Mana Sieve from within the temple in Shen'dralas and use it to collect Ancient Mana Crystals. Once you have acquired enough mana, empower the pylons and return to Mordent Evenshade.", tag="Optional", desc="The mana amount depends on your quest log. Take the sieve from the highest floor of the temple, collecting 8 Mana in total, 4 from each tower. The west and east towers can be used while stealthed."}, [15]={npc="Mordent Evenshade", tgt="Mordent Evenshade", tag="Optional", desc="Check the quest log for the amount of mana you need."}, [16]={npc="Mordent Evenshade", tgt="Mordent Evenshade", tag="Optional", preText="Powering the Pylons"}, [17]={hint="Speak with Mordent Evenshade in Shen'dralas for information about the crystals you repaired.", tag="Optional"}, [18]={npc="Mordent Evenshade", tgt="Mordent Evenshade", tag="Optional"}, [19]={npc="Mordent Evenshade", tgt="Mordent Evenshade", tag="Optional", preText="A Brief History Lesson"}, [20]={hint="Locate Magister Kirandis inside the temple of Shen'dralas.", tag="Optional"}, [21]={npc="Magister Kirandis", tgt="Magister Kirandis", tag="Optional"}, [22]={npc="Mithera", tgt="Mithera", tag="Optional", preText="Meeting the Magister"}, [23]={hint="Investigate the Forlorn Gardens near Shen'dralas and then return to Mithera at the nearby temple.", tag="Optional"}, [24]={npc="Mithera", tgt="Mithera", tag="Optional"}, [25]={npc="Mithera", tgt="Mithera", tag="Optional", preText="Forlorn Gardens"}, [26]={npc="Woodwyrd", tgt="Woodwyrd", tag="Optional"}, [27]={npc="Woodwyrd", tgt="Woodwyrd", tag="Optional", desc="Turn in Word of the Woods first. Bring this into inner Maraudon.", preText="Word of the Woods"}, [28]={npc="Cavindra", tgt="Cavindra", desc="Cavindra is outside the orange portal. Loot one item from each side's boss."}, [29]={hint="Collect 10 Shadowshard Fragments from Maraudon and return them to Archmage Tervosh in Theramore on the coast of Dustwallow Marsh."}, [30]={text="Maraudon entrance"}, [31]={text="Orange side: Foulspore Cavern (45-53). Look for orange crystals and the pool deep in the cave. Fill the vial before entering the portal."}, [32]={hint="Fill the Coated Cerulean Vial at the orange crystal pool in Maraudon.", desc="Location: Fill the vial at the pool outside the orange portal. Find vines inside.", spot="Fill the vial at the pool outside the orange portal. Find vines inside."}, [33]={text="Purple side: Wicked Grotto (45-53). Take the purple crystal passage at the three-way fork. Loot the diamond from Lord Vyletongue."}, [34]={hint="Collect 15 Theradric Crystal Carvings for Willow in Desolace.", desc="Go by the amount shown in your quest log. Location: Kill the centaurs in the orange and purple outer caves first, then loot statues all the way after entering.", spot="Kill centaurs outside both portals and loot statues as you go."}, [35]={hint="Read the Pariah's Instructions. Afterwards, obtain the Amulet of Union from Maraudon and return it to the Centaur Pariah in southern Desolace.", desc="The first is between the orange and purple lines. The second and third are in the passages outside the doors. The fourth and fifth are inside the orange and purple doors, each on patrol. Location: Find the first three at the orange/purple fork and the two outer caves, and one inside each door.", spot="Find three khans at the fork and outer caves, then one inside each portal."}, [36]={hint="Recover the two parts of the Scepter of Celebras: the Celebrian Rod and the Celebrian Diamond.", desc="Location: Take the wand on the orange line and the diamond on the purple line, then fight Celebras at the meeting point. Order: Both the orange and purple lines are required. Turn in only once all the materials are collected.", spot="Get the rod on orange and the diamond on purple. Kill Celebras where they meet."}, [37]={npc="Celebras the Redeemed", tgt="Celebras the Redeemed", desc="After defeating the boss, talk to Celebras the Redeemed. After the defeat, hand it in to the Redeemed in the room.", spot="In the Celebras the Cursed boss room: Celebras the Redeemed"}, [38]={npc="Celebras the Redeemed", tgt="Celebras the Redeemed", desc="The Redeemed is in the boss's room; follow him during the ritual.", preText="Legends of Maraudon"}, [39]={hint="Assist Celebras the Redeemed while he creates the Scepter of Celebras.", desc="The Redeemed is in the boss room. Follow him during the ritual. Location: Celebras's boss room: follow the Redeemed through the ritual.", spot="Follow Celebras the Redeemed through the ritual in his boss room."}, [40]={npc="Celebras the Redeemed", tgt="Celebras the Redeemed", desc="The Redeemed is in the boss's room; follow him during the ritual.", spot="In the Celebras the Cursed boss room: Celebras the Redeemed"}, [41]={text="Inner route: Earth Song Falls (48-57). Descend from the orange/purple junction or have a player with the scepter open the shortcut."}, [42]={hint="Venture to Maraudon and recover a Vial of Earth Song Water and return it to Woodwyrd at the Forlorn Gardens in Desolace.", tag="Optional", desc="Rotgrip patrols the pool; the small fountain is on the pool's surface. Drop into Rotgrip's pool below the Princess. Find the spring at the surface. Use the fountain on the surface first, then dive.", spot="Drop into Rotgrip's pool below the Princess. Find the spring at the surface."}, [43]={hint="Slay Princess Theradras and return to Keeper Marandis at Nijel's Point in Desolace.", desc="Location: Follow Earth Song Falls into Zaetar's cavern and reach the Princess's platform.", spot="Follow Earth Song Falls into Zaetar's cavern and reach the Princess's platform."}, [44]={npc="Zaetar's Spirit", tgt="Zaetar's Spirit", desc="Zaetar's Spirit appears after the Princess dies. Pick up now and turn in outside."}, [45]={npc="Keeper Marandis", tgt="Keeper Marandis"}, [46]={npc="Talendria", tgt="Talendria"}, [47]={npc="Willow", tgt="Willow"}, [48]={npc="Centaur Pariah", tgt="Centaur Pariah"}, [49]={npc="Archmage Tervosh", tgt="Archmage Tervosh"}, [50]={hint="Venture to Maraudon and recover a Vial of Earth Song Water and return it to Woodwyrd at the Forlorn Gardens in Desolace.", tag="Optional"}, [51]={npc="Woodwyrd", tgt="Woodwyrd", tag="Optional"}, [52]={hint="Seek out Remulos in Moonglade and give him the Seed of Life.", desc="Save for when you pass through Moonglade."}, [53]={npc="Keeper Remulos", tgt="Keeper Remulos", desc="Save for Moonglade."}}},
    ["04-42"] = {grind={[1]={mob="Coast Crawl Snapclaw", note="The beach across from Feathermoon Stronghold; you're there as soon as you get off the boat."}, [2]={mob="Hatecrest Warrior", note="Naga at the south end of Sardor Isle; close to the stronghold, slightly lower level."}}, steps={[1]={npc="Erelas Ambersky", tgt="Erelas Ambersky"}, [2]={npc="Erelas Ambersky", tgt="Erelas Ambersky"}, [3]={npc="Daryn Lightwind", tgt="Daryn Lightwind"}, [4]={npc="Feralas: A History", npcObj=true}, [5]={npc="Daryn Lightwind", tgt="Daryn Lightwind"}, [6]={npc="Daryn Lightwind", tgt="Daryn Lightwind"}, [7]={text="Step into the portal in Rut'theran Village to Darnassus.", tag="You can buy 15 Silk Cloth at the Auction House now, or have an alt mail it (for Caught! in the Searing Gorge later)."}, [8]={npc="Gracina Spiritmight", tgt="Gracina Spiritmight"}, [9]={npc="Tyrande Whisperwind", tgt="Tyrande Whisperwind"}, [10]={bind="Feathermoon Stronghold"}, [11]={desc="The Sunken Temple can't be accepted until level 46; if you're just short, grind mobs near Feathermoon Stronghold to 46; The Stone Circle follows on from it."}, [12]={npc="Angelas Moonbreeze", tgt="Angelas Moonbreeze"}, [13]={to="Gadgetzan"}, [14]={npc="Curgle Cranklehop", tgt="Curgle Cranklehop"}, [15]={npc="Curgle Cranklehop", tgt="Curgle Cranklehop"}, [16]={npc="Senior Surveyor Fizzledowser", tgt="Senior Surveyor Fizzledowser"}, [17]={hint="Use the untapped dowsing widget near the pool of water by Sandsorrow Watch. Once you have collected the sample, return the tapped dowsing widget to Senior Surveyor Fizzledowser in Gadgetzan."}, [18]={npc="Senior Surveyor Fizzledowser", tgt="Senior Surveyor Fizzledowser"}, [19]={npc="Senior Surveyor Fizzledowser", tgt="Senior Surveyor Fizzledowser"}}},
    ["04-43"] = {steps={[1]={npc="Marin Noggenfogger", tgt="Marin Noggenfogger"}, [2]={npc="Andi Lynn", tgt="Andi Lynn", tag="Optional"}, [3]={npc="Tran'rek", tgt="Tran'rek", tag="Hard, Optional"}, [4]={npc="Marvon Rivetseeker", tgt="Marvon Rivetseeker"}, [5]={npc="Marvon Rivetseeker", tgt="Marvon Rivetseeker"}, [6]={npc="Marvon Rivetseeker", tgt="Marvon Rivetseeker"}, [7]={hint="Andi Lynn in Gadgetzan wants you to destroy the Dunemaul Compound by killing 10 Dunemaul Brutes, 10 Dunemaul Enforcers, and Gor'marok the Ravager.", tag="Optional", desc="This is a dedicated detour with no other objectives nearby. Skip it if you're in a hurry."}, [8]={hint="Security Chief Bilgewhizzle of Steamwheedle Port in Tanaris wants you to recover a particularly shiny bangle bracelet lost near the Dunemaul ogre compound."}, [9]={hint="Bring five Centipaar insect parts from the Noxious Lair to Alchemist Pestlezugg in Gadgetzan."}, [10]={hint="Marvon Rivetseeker in Tanaris wants you to collect 30 Gahz'ridian Ornaments."}, [11]={hint="Collect a Laden Dew Gland and bring it to Marin Noggenfogger in Gadgetzan."}, [12]={hint="Tran'rek in Gadgetzan wants you to kill 8 Gnarled Thistleshrubs and 8 Thistleshrub Rootshapers.", tag="Hard, Optional"}, [13]={npc="OOX-17/TN Distress Beacon", npcObj=true, tag="If it drops, Optional", desc="Right-click OOX-17/TN Distress Beacon in your bags to start the quest."}, [14]={npc="Tooga", tgt="Tooga", tag="Optional, Escort, If you see it", desc="Accept only if you meet Tooga and are ready to escort him on foot."}, [15]={hint="Show Tooga the way back to his wife, Torta.", tag="Optional, Escort", desc="Escort Tooga on foot to Torta, southwest of Steamwheedle Port. Watch for ambushes."}, [16]={npc="Homing Robot OOX-17/TN", tgt="Homing Robot OOX-17/TN", tag="Optional", desc="Escort quest: in a group, wait until everyone is at the same step before accepting, and turn off auto-accept."}, [17]={npc="Homing Robot OOX-17/TN", tgt="Homing Robot OOX-17/TN", tag="Optional"}, [18]={hint="Escort OOX-17/TN to Steamwheedle Port, then report to Oglethorpe Obnoticus in Booty Bay.", tag="Optional"}, [19]={hint="Escort OOX-17/TN to Steamwheedle Port, then report to Oglethorpe Obnoticus in Booty Bay.", tag="Optional", desc="Escort failed: abandon the quest in your quest log, then accept it again from the robot."}, [20]={npc="Yeh'kinya", tgt="Yeh'kinya"}, [21]={npc="Torta", tgt="Torta", tag="Optional, Escort"}, [22]={text="Tooga's escort failed. Continue with the main route, or abandon the quest and find Tooga again if you want to retry."}, [23]={npc="Security Chief Bilgewhizzle", tgt="Security Chief Bilgewhizzle"}, [24]={npc="Andi Lynn", tgt="Andi Lynn", tag="Optional"}, [25]={npc="Marin Noggenfogger", tgt="Marin Noggenfogger"}, [26]={npc="Marin Noggenfogger", tgt="Marin Noggenfogger"}, [27]={npc="Sprinkle", tgt="Sprinkle"}, [28]={npc="Sprinkle", tgt="Sprinkle"}, [29]={npc="Alchemist Pestlezugg", tgt="Alchemist Pestlezugg"}, [30]={npc="Senior Surveyor Fizzledowser", tgt="Senior Surveyor Fizzledowser"}, [31]={npc="Tran'rek", tgt="Tran'rek"}, [32]={npc="Marvon Rivetseeker", tgt="Marvon Rivetseeker"}, [33]={text="Scrimshank is down in the cave; follow the ramp down from the entrance (55.00, 70.00 → 54.20, 72.90 → 56.30, 72.20)."}, [34]={hint="Discover the fate of Junior Surveyor Scrimshank, and bring either him or his surveying equipment to Senior Surveyor Fizzledowser in Gadgetzan."}, [35]={npc="Senior Surveyor Fizzledowser", tgt="Senior Surveyor Fizzledowser"}, [36]={npc="Senior Surveyor Fizzledowser", tgt="Senior Surveyor Fizzledowser"}, [37]={npc="Alchemist Pestlezugg", tgt="Alchemist Pestlezugg"}, [38]={npc="Alchemist Pestlezugg", tgt="Alchemist Pestlezugg"}, [39]={npc="Senior Surveyor Fizzledowser", tgt="Senior Surveyor Fizzledowser"}, [40]={npc="Senior Surveyor Fizzledowser", tgt="Senior Surveyor Fizzledowser"}, [41]={to="Theramore"}, [42]={to="Menethil Harbor", from="Theramore", desc="The boat from the Theramore dock goes straight to Menethil Harbor."}, [43]={to="Stormwind", desc="If you didn't pick up In Search of The Temple, you don't need to go to Stormwind; fly straight from Menethil Harbor to Southshore."}, [44]={npc="Brohann Caskbelly", tgt="Brohann Caskbelly"}, [45]={npc="Brohann Caskbelly", tgt="Brohann Caskbelly"}}},
    ["04-44"] = {grind={[1]={mob="Savage Owlbeast", note="Woods in the central Hinterlands; plenty of mobs, the same ones as for the Wildkin Feathers."}, [2]={mob="Silvermane Stalker", note="The wolf packs farther east; spread out, so you can kill them one at a time."}}, steps={[1]={to="Southshore", desc="If Southshore isn't unlocked, fly to Menethil Harbor, take the boat to Auberdine from the north dock and get off at Southshore."}, [2]={npc="Raleigh the Devout", tgt="Raleigh the Devout", tag="Optional"}, [3]={npc="Raleigh the Devout", tgt="Raleigh the Devout", tag="Optional, Group", desc="Defeat Loksey in the Library, Herod in the Armory, and Mograine and Whitemane in the Cathedral. You can finish the wings on separate runs."}, [4]={npc="Raleigh the Devout", tgt="Raleigh the Devout", tag="Optional, When you have the items"}, [5]={text="Take the mountain path northeast into the Hinterlands."}, [6]={npc="Falstad Wildhammer", tgt="Falstad Wildhammer"}, [7]={node="Aerie Peak"}, [8]={npc="Falstad Wildhammer", tgt="Falstad Wildhammer"}, [9]={npc="Gryphon Master Talonaxe", tgt="Gryphon Master Talonaxe"}, [10]={npc="Gryphon Master Talonaxe", tgt="Gryphon Master Talonaxe"}, [11]={npc="Gryphon Master Talonaxe", tgt="Gryphon Master Talonaxe"}, [12]={npc="Fraggar Thundermantle", tgt="Fraggar Thundermantle"}, [13]={npc="Fraggar Thundermantle", tgt="Fraggar Thundermantle"}, [14]={text="Set your hearthstone at the inn in Aerie Peak (13.80, 41.60).", bind="Aerie Peak"}, [15]={npc="Rhapsody Shindigger", tgt="Rhapsody Shindigger", desc="On the way to the owlbeasts; the follow-up needs you to bring liquor, so don't take it."}, [16]={hint="Collect 15 Wildkin Feathers from the Hinterlands for Erelas Ambersky in Rut'theran Village."}, [17]={hint="Check the cages at the two Witherbark villages, then return to Gryphon Master Talonaxe."}, [18]={desc="If you're not level 47 yet, head east and kill Savage Owlbeasts and Silvermane Stalkers until 47, collecting Wildkin Feathers as you go."}, [19]={hint="Bring 5 Troll Tribal Necklaces to Fraggar Thundermantle in Aerie Peak."}, [20]={hint="Sprinkle in Gadgetzan wants you to collect a Violet Tragan and return it to her."}, [21]={hint="Kill 10 Green Sludges and 10 Jade Oozes, and then report back to Fraggar Thundermantle in Aerie Peak."}, [22]={npc="Fraggar Thundermantle", tgt="Fraggar Thundermantle"}, [23]={npc="Fraggar Thundermantle", tgt="Fraggar Thundermantle"}, [24]={npc="Gryphon Master Talonaxe", tgt="Gryphon Master Talonaxe"}, [25]={npc="Gryphon Master Talonaxe", tgt="Gryphon Master Talonaxe"}, [26]={hint="Check the top of the Altar of Zul, then return to Gryphon Master Talonaxe."}, [27]={npc="OOX-09/HL Distress Beacon", npcObj=true, tag="If it drops, Optional", desc="Right-click OOX-09/HL Distress Beacon in your bags to start the quest."}, [28]={npc="Homing Robot OOX-09/HL", tgt="Homing Robot OOX-09/HL", tag="Optional"}, [29]={npc="Homing Robot OOX-09/HL", tgt="Homing Robot OOX-09/HL", tag="Optional"}, [30]={hint="Escort OOX-09/HL to the shoreline beyond Overlook Cliff, then report to Oglethorpe Obnoticus in Booty Bay.", tag="Optional"}, [31]={hint="Escort OOX-09/HL to the shoreline beyond Overlook Cliff, then report to Oglethorpe Obnoticus in Booty Bay.", tag="Optional", desc="Escort failed: abandon the quest in your quest log, then accept it again from the robot."}, [32]={hint="Use the Super Snapper FX to take a snapshot of Gammerita, then return to Daryn Lightwind in Rut'theran Village."}, [33]={hint="Whiskey Slim in Booty Bay wants you to bring him the bottles of Pupellyverbos Port he lost."}, [34]={bind="Aerie Peak"}, [35]={npc="Gryphon Master Talonaxe", tgt="Gryphon Master Talonaxe"}, [36]={npc="Gryphon Master Talonaxe", tgt="Gryphon Master Talonaxe"}, [37]={to="Thelsamar"}, [38]={text="Set your hearth in the Thelsamar inn (35.40, 48.40).", bind="Thelsamar"}, [39]={text="Leave Loch Modan to the south and take the mountain path here into the Badlands."}, [40]={npc="Veyric Thunderhame", tgt="Veyric Thunderhame", tag="Group, Optional", desc="You have to finish Elemental Aid (Razorfen Kraul) and Storm, Earth, and Fire before you can accept this."}, [41]={hint="Use the Twisted Totems to put an end to the quilboar ritual.", tag="Group, Optional", desc="Fly from Refuge Pointe to Menethil Harbor, take the boat from the south dock to Theramore, fly to Thalanaar, then walk east into Thousand Needles."}, [42]={npc="Veyric Thunderhame", tgt="Veyric Thunderhame", tag="Group, Optional", desc="Fly from Thalanaar to Theramore, take the boat to Menethil Harbor, then fly to Refuge Pointe."}, [43]={npc="Veyric Thunderhame", tgt="Veyric Thunderhame", tag="Optional"}, [44]={npc="Bath'rah the Windwatcher", tgt="Bath'rah the Windwatcher", tag="Optional"}, [45]={npc="Bath'rah the Windwatcher", tgt="Bath'rah the Windwatcher"}, [46]={npc="Bath'rah the Windwatcher", tgt="Bath'rah the Windwatcher", desc="Needs Bloodscalp Tusk ×30, Liferoot ×8, and Essence of the Exile ×1. For Essence of the Exile, bring 8 each of Burning Charm, Thundering Charm, and Cresting Charm to the cauldron next to him. Liferoot and the three charms can be bought at the Auction House."}, [47]={hint="Bring the items on Bath'rah's Parchment to Bath'rah the Windwatcher in Alterac."}, [48]={npc="Bath'rah the Windwatcher", tgt="Bath'rah the Windwatcher"}, [49]={npc="Bath'rah the Windwatcher", tgt="Bath'rah the Windwatcher"}, [50]={hint="Bring the Whirlwind Heart to Bath'rah Windwatcher."}, [51]={npc="Bath'rah the Windwatcher", tgt="Bath'rah the Windwatcher"}, [52]={npc="Bath'rah the Windwatcher", tgt="Bath'rah the Windwatcher", desc="Rewards a Whirlwind weapon."}, [53]={npc="Bath'rah the Windwatcher", tgt="Bath'rah the Windwatcher", desc="Rewards a Whirlwind weapon."}}},
    ["04-45"] = {tips={{k="取捨", text="Do the five gathering quests together. Turning in all of them takes jawbones x5, boar lungs x6, scorpid stingers x6, lizard brains x11 and vulture gizzards x14. Each quest turn-in consumes the materials."}, {k="取捨", text="If the vultures or basilisks are heavily contested, leave The Basilisk's Bite or Vulture's Vigor unfinished and head north to Swamp of Sorrows as planned."}}, grind={[1]={mob="Dark Iron Taskmaster", note="Dark Iron dwarves around the outside of the Cauldron; a good level match."}, [2]={mob="Dark Iron Slaver", note="South side of the Cauldron; slightly lower level, spread out."}}, steps={[1]={npc="Sigrun Ironhew", tgt="Sigrun Ironhew", tag="Optional", desc="You usually get Fiery Blaze Enchantments along the way. If none drop, abandon it."}, [2]={npc="Garek", tgt="Garek", tag="Group, Optional", desc="You have to kill two level 50 elite black drakes; skip it if you have no group."}, [3]={hint="Use the Sign of the Earth to activate the Pillars of Amethyst, Opal, and Diamond and obtain the Runestones.", tag="Later, on the way, Group, Optional"}, [4]={npc="Seal of the Earth", npcObj=true, tag="Group, Optional"}, [5]={npc="Seal of the Earth", npcObj=true, tag="Group, Optional"}, [6]={npc="Garek", tgt="Garek", tag="Group, Optional"}, [7]={npc="Sigrun Ironhew", tgt="Sigrun Ironhew", tag="Optional"}, [8]={hint="Kill Ambassador Infernus in Angor Fortress and bring proof of his death to Advisor Belgrum in Ironforge.", tag="Group, Optional"}, [9]={text="From the Badlands, head west and take the mountain path next to the Horde camp of Kargath into the Searing Gorge. Steer clear of Kargath.", tag="Flight path locked. Travel there on foot the first time."}, [10]={npc="Wooden Outhouse", npcObj=true, desc="Silk Cloth can be bought at the Auction House. You need 15."}, [11]={hint="Kill 8 Dark Iron Geologists and bring 15 pieces of Silk Cloth to the person locked in the outhouse in Searing Gorge."}, [12]={text="Kill Margol the Rager for a lot of experience.", tag="Optional", desc="Margol's Horn starts the Key to Searing Gorge quest line; skip it if you don't want to fight him. The related later steps are then skipped automatically, and you end by flying from Ironforge back to Thorium Point."}, [13]={npc="Margol's Horn", npcObj=true, tag="Optional, Group", desc="Right-click Margol's Horn in your bags to start the quest."}, [14]={npc="Wooden Outhouse", npcObj=true}, [15]={npc="Wooden Outhouse", npcObj=true, tag="Optional", desc="The turn-in needs four things: the ledger by the outhouse, Glassweb Spider legs ×20, the overdue package from Dustwallow Marsh, and Jarquia's sword from the Swamp of Sorrows. Don't make a special trip for any you're missing."}, [16]={hint="Take the copy of Goodsteel's Ledger and then find the items listed in it before seeking Krinkle Goodsteel in Tanaris.", tag="When you have the items"}, [17]={npc="Dorius Stonetender", tgt="Dorius Stonetender"}, [18]={hint="Help Dorius get back to Ironforge.", tag="Escort", desc="Follow Dorius north; after the ambush, once your quest log shows it complete, pick up the charred letter on the spot and turn it in."}, [19]={npc="Singed Letter", npcObj=true}, [20]={npc="Singed Letter", npcObj=true}, [21]={npc="Kalaran Windblade", tgt="Kalaran Windblade"}, [22]={npc="Kalaran Windblade", tgt="Kalaran Windblade"}, [23]={npc="Kalaran Windblade", tgt="Kalaran Windblade"}, [24]={node="Thorium Point"}, [25]={npc="Wanted/Missing/Lost & Found", npcObj=true, tag="Group, Optional", desc="Overseer Maltorius is a level 50 elite; skip it if you have no group."}, [26]={npc="Wanted/Missing/Lost & Found", npcObj=true}, [27]={npc="Wanted/Missing/Lost & Found", npcObj=true}, [28]={npc="Hansel Heavyhands", tgt="Hansel Heavyhands"}, [29]={npc="Hansel Heavyhands", tgt="Hansel Heavyhands", tag="Optional"}, [30]={npc="Hansel Heavyhands", tgt="Hansel Heavyhands"}, [31]={npc="Master Smith Burninate", tgt="Master Smith Burninate"}, [32]={bind="Thelsamar"}, [33]={npc="Mountaineer Pebblebitty", tgt="Mountaineer Pebblebitty", tag="Optional"}, [34]={npc="Mountaineer Pebblebitty", tgt="Mountaineer Pebblebitty"}, [35]={to="Ironforge"}, [36]={npc="Veyric Thunderhame", tgt="Veyric Thunderhame", tag="Optional"}, [38]={npc="Curator Thorius", tgt="Curator Thorius"}, [39]={npc="Curator Thorius", tgt="Curator Thorius"}, [40]={npc="Curator Thorius", tgt="Curator Thorius", tag="Optional"}, [41]={npc="Curator Thorius", tgt="Curator Thorius"}, [42]={npc="Advisor Belgrum", tgt="Advisor Belgrum", tag="Group, Optional"}, [43]={npc="Advisor Belgrum", tgt="Advisor Belgrum", tag="Optional, Group"}, [44]={to="Thelsamar", tag="Optional", desc="Go back to Pebblebitty for the key only if you have At Last!; if not, skip it and fly straight from Ironforge back to Thorium Point."}, [45]={npc="Mountaineer Pebblebitty", tgt="Mountaineer Pebblebitty", tag="Optional"}, [46]={text="Use the Searing Gorge key you just got to open the gate next to Mountaineer Pebblebitty and go through the tunnel into the Searing Gorge.", tag="Optional"}, [47]={to="Thorium Point", desc="If you don't have the Searing Gorge key, fly straight back to Searing Gorge from Ironforge. If you already came in through the tunnel, skip this."}, [48]={hint="Collect 4 Hearts of Flame and 4 globes of Golem Oil and return the items to Kalaran Windblade."}, [49]={npc="Kalaran Windblade", tgt="Kalaran Windblade"}, [50]={npc="Kalaran Windblade", tgt="Kalaran Windblade"}, [51]={hint="Find and return the Smithing Tuyere and Lookout's Spyglass to Taskmaster Scrange in the Searing Gorge."}, [52]={hint="Slay 15 Dark Iron Taskmasters and 15 Dark Iron Slavers. Return to Taskmaster Scrange in the Searing Gorge once you have accomplished this task."}, [53]={hint="Hansel Heavyhands wants you to kill 20 Heavy War Golems."}, [54]={hint="Hansel Heavyhands wants you to kill 20 Greater Lava Spiders in the Searing Gorge. You can find Greater Lava Spiders in the plateaus and lava pools of the Searing Gorge.", tag="Optional", desc="This is a dedicated detour with no other objectives nearby. Skip it if you're in a hurry."}, [55]={text="From the eastern entrance with the miners, turn right and follow the lower passage beside the lava to the Incendosaur cavern."}, [56]={hint="Hansel Heavyhands wants you to kill 20 Incendosaurs."}, [57]={desc="If you still need XP, stay in the mine where you fought the Incendosaurs and pull normal Incendosaurs one at a time along the passage you cleared. If there are no safe pulls inside, retrace your steps and finish level 48 on Dark Iron taskmasters or slavers around the Cauldron."}, [58]={hint="Deep within the Slag Pit of the Cauldron, in the Searing Gorge, you will find the traitorous Dark Iron dwarf named Overseer Maltorius.", tag="Later, on the way, Group, Optional"}, [59]={text="On the eastern approach to the plans, cross the bridge into the large room and turn left. The plans are on the upper platform, on the table behind the overseer. If elites guard it, skip this step and restore it when clear or with a group."}, [60]={hint="Somewhere in the Slag Pit of the Cauldron you will find the Secret Plans: Fiery Flux that Overseer Maltorius stole. Find those plans and return them to Master Smith Burninate in the Searing Gorge.", desc="Overseer Maltorius or an elite Black Iron Sentry may guard the upper platform. Check the table before approaching solo. Only the bounty requires killing the overseer."}, [61]={hint="Bring 8 Thorium Plated Daggers to Kalaran Windblade."}, [62]={npc="Dying Archaeologist", tgt="Dying Archaeologist"}, [63]={npc="Dying Archaeologist", tgt="Dying Archaeologist"}, [64]={npc="Kalaran Windblade", tgt="Kalaran Windblade"}, [65]={npc="Kalaran Windblade", tgt="Kalaran Windblade", tag="Optional"}, [66]={hint="Find the Mysterious Artifact being guarded by the Twilight's Hammer Idolaters in the northwest quadrant of the Searing Gorge and bring it to the Altar of Suntara in the Slag Pit.", tag="Later, on the way", desc="The artifact is in the Twilight camp beside the northern lava pool, guarded by level 49-51 elite Twilight Idolaters. Wait for the elites to move away, grab it and leave. If you can't, skip this step and the Release Them turn-in."}, [67]={hint="Find and return a Symbol of Ragnaros to Kalaran Windblade.", tag="Group, Optional, Later, on the way", desc="Only elites drop the Symbol of Ragnaros."}, [68]={npc="Zamael Lunthistle", tgt="Zamael Lunthistle"}, [69]={npc="Zamael Lunthistle", tgt="Zamael Lunthistle"}, [70]={npc="Zamael Lunthistle", tgt="Zamael Lunthistle", tag="Group, Optional"}, [71]={npc="Lookout Captain Lolo Longstriker", tgt="Lookout Captain Lolo Longstriker", tag="Group, Optional"}, [72]={npc="Hansel Heavyhands", tgt="Hansel Heavyhands"}, [73]={npc="Hansel Heavyhands", tgt="Hansel Heavyhands", tag="Optional"}, [74]={npc="Hansel Heavyhands", tgt="Hansel Heavyhands"}, [75]={npc="Taskmaster Scrange", tgt="Taskmaster Scrange"}, [76]={npc="Taskmaster Scrange", tgt="Taskmaster Scrange"}, [77]={npc="Master Smith Burninate", tgt="Master Smith Burninate"}, [78]={npc="Kalaran Windblade", tgt="Kalaran Windblade", tag="Optional"}, [79]={npc="Kalaran Windblade", tgt="Kalaran Windblade"}, [80]={npc="Kalaran Windblade", tgt="Kalaran Windblade"}, [81]={npc="Kalaran Windblade", tgt="Kalaran Windblade"}, [82]={npc="Torch of Retribution", npcObj=true}, [83]={npc="Kalaran Windblade", tgt="Kalaran Windblade"}, [84]={npc="Squire Maltrake", tgt="Squire Maltrake"}, [85]={npc="Squire Maltrake", tgt="Squire Maltrake"}, [86]={hint="Set the North, South, East, and West Sentry Towers on fire by using the Torch of Retribution inside each of the buildings."}, [87]={npc="Altar of Suntara", npcObj=true}, [88]={npc="Dying Archaeologist", tgt="Dying Archaeologist", tag="Group, Optional", desc="Lathoric the Black and Obsidion are both level 52 elites; find a group for it."}, [89]={hint="Slay Lathoric the Black and Obsidion, and return to Thorius in Ironforge with the Head of Lathoric the Black and the Heart of Obsidion.", tag="Group, Optional"}, [90]={npc="Squire Maltrake", tgt="Squire Maltrake"}, [91]={npc="Hoard of the Black Dragonflight", npcObj=true}, [92]={npc="Hoard of the Black Dragonflight", npcObj=true, desc="Keep the Black Dragonflight Molt and turn it in to Cyrus Therepentous in the Burning Steppes."}, [93]={tag="Optional, Group", desc="Level here to 52 only with a Blackrock Depths group. Skip if solo."}, [94]={to="Ironforge", desc="If your hearthstone is ready, hearth back to Thelsamar and fly from there; otherwise, go back to Thorium Point (37.90, 30.40) and find the flight master."}, [95]={npc="Curator Thorius", tgt="Curator Thorius", tag="Group, Optional"}, [96]={npc="High Explorer Magellas", tgt="High Explorer Magellas"}, [97]={npc="High Explorer Magellas", tgt="High Explorer Magellas", desc="Only available after you've done The Platinum Discs in Uldaman."}, [98]={npc="Historian Karnik", tgt="Historian Karnik"}, [99]={npc="Historian Karnik", tgt="Historian Karnik"}, [100]={text="Set your hearth in the Ironforge inn (18.60, 51.60).", bind="Ironforge"}, [101]={to="Nethergarde Keep", desc="If Nethergarde Keep isn't unlocked, fly to Darkshire, head east through Deadwind Pass into the Swamp of Sorrows, then south into the Blasted Lands to Nethergarde Keep."}, [102]={npc="Thadius Grimshade", tgt="Thadius Grimshade"}, [103]={npc="Thadius Grimshade", tgt="Thadius Grimshade", tag="Optional, Group"}, [104]={npc="Bloodmage Drazial", tgt="Bloodmage Drazial"}, [105]={npc="Bloodmage Drazial", tgt="Bloodmage Drazial"}, [106]={npc="Bloodmage Drazial", tgt="Bloodmage Drazial"}, [107]={npc="Bloodmage Lynnore", tgt="Bloodmage Lynnore"}, [108]={npc="Bloodmage Lynnore", tgt="Bloodmage Lynnore"}, [109]={hint="Bring three Snickerfang Jowls, two Blasted Boar Lungs, and one Scorpok Pincer to Bloodmage Drazial."}, [110]={hint="Bring three Blasted Boar Lungs, two Scorpok Pincers, and one Basilisk Brain to Bloodmage Drazial."}, [111]={hint="Bring three Scorpok Pincers, two Vulture Gizzards, and one Blasted Boar Lung to Bloodmage Drazial."}, [112]={hint="Bring ten Basilisk Brains and two Vulture Gizzards to Bloodmage Lynnore."}, [113]={hint="Bring ten Vulture Gizzards and two Snickerfang Jowls to Bloodmage Lynnore."}, [114]={npc="Bloodmage Drazial", tgt="Bloodmage Drazial"}, [115]={npc="Bloodmage Drazial", tgt="Bloodmage Drazial"}, [116]={npc="Bloodmage Drazial", tgt="Bloodmage Drazial"}, [117]={npc="Bloodmage Lynnore", tgt="Bloodmage Lynnore"}, [118]={npc="Bloodmage Lynnore", tgt="Bloodmage Lynnore"}, [119]={npc="Cortello's Riddle", npcObj=true, tag="If it drops, Optional", desc="Right-click Cortello's Riddle in your bags to start the quest."}, [120]={text="From the blood mage camp, rejoin the northern road, leave the Blasted Lands north into the Swamp of Sorrows, then follow the road west to the western side of the swamp."}, [121]={npc="A Soggy Scroll", npcObj=true}, [122]={npc="A Soggy Scroll", npcObj=true}}},
    ["04-46"] = {grind={[1]={mob="Skymane Gorilla", note="The small island where Mukla is; normal mobs. Clear them on your way after killing the king."}, [2]={mob="Jaguero Stalker", note="West side of the same island."}}, steps={[1]={to="Booty Bay", desc="The Swamp of Sorrows has no Alliance flight point: head west through Deadwind Pass back to Darkshire and fly from there."}, [2]={npc="Crank Fizzlebub", tgt="Crank Fizzlebub"}, [3]={npc="Crank Fizzlebub", tgt="Crank Fizzlebub"}, [4]={npc="Whiskey Slim", tgt="Whiskey Slim"}, [5]={npc="\"Sea Wolf\" MacKinley", tgt="Sea Wolf MacKinley"}, [6]={npc="Fin Fizracket", tgt="Fin Fizracket"}, [7]={npc="Oglethorpe Obnoticus", tgt="Oglethorpe Obnoticus", tag="Optional"}, [8]={npc="Oglethorpe Obnoticus", tgt="Oglethorpe Obnoticus", tag="Optional"}, [9]={npc="Oglethorpe Obnoticus", tgt="Oglethorpe Obnoticus", tag="Optional"}, [10]={npc="Oglethorpe Obnoticus", tgt="Oglethorpe Obnoticus", tag="Optional"}, [11]={npc="Oglethorpe Obnoticus", tgt="Oglethorpe Obnoticus", tag="Optional"}, [12]={npc="Carefully Folded Note", npcObj=true, desc="Right-click Carefully Folded Note in your bags to start the quest. Right-click the folded note you got earlier to start the quest now."}, [13]={npc="Princess Poobah", tgt="Princess Poobah"}, [14]={npc="Princess Poobah", tgt="Princess Poobah", tag="Group, Optional"}, [15]={hint="Slay King Mukla and return to Princess Poobah with the Key to free her.", tag="Group, Optional"}, [16]={npc="Princess Poobah", tgt="Princess Poobah", tag="Group, Optional"}, [17]={npc="Witch Doctor Unbagwa", tgt="Witch Doctor Unbagwa", desc="Accept Stranglethorn Fever before turning in the tusks to trigger the event."}, [18]={hint="Loot from: Mistvale Gorilla, Jungle Thunderer, Enraged Silverback Gorilla", desc="Accept Stranglethorn Fever before turning in the tusks to trigger the event."}, [19]={npc="Witch Doctor Unbagwa", tgt="Witch Doctor Unbagwa", desc="Accept Stranglethorn Fever before turning in the tusks to trigger the event."}, [20]={hint="Seek out Witch Doctor Unbagwa and have him summon Mokk the Savage. Bring the Heart of Mokk to Fin Fizracket.", desc="Turning in Stranglethorn Fever summons Mokk. If you are short of gorilla fangs or can't hold off the gorilla waves, skip this step and the Stranglethorn Fever turn-in below; nothing later depends on it."}, [21]={desc="If you're not level 49 yet, keep killing gorillas in Mistvale Valley until 49."}, [22]={npc="Fin Fizracket", tgt="Fin Fizracket"}, [23]={to="Ratchet", from="Booty Bay"}, [24]={hint="Retrieve the Stone Circle from Marvon Rivetseeker's workshop in Ratchet."}, [25]={to="Theramore"}, [26]={npc="Musty Scroll", npcObj=true}, [27]={npc="Musty Scroll", npcObj=true, tag="Optional"}}},
    ["05-d22"] = {name="Alcaz Prison", entrance="Dustwallow Marsh 75.30, 14.10", pickup="At {s:04-46}, before flying from Darkshire to Booty Bay, fly to Stormwind first if you're level 48 and take Our Man in Theramore from Master Mathias Shaw. When {s:04-46} ends with the flight to Theramore, find Sully McCleary for the follow-ups.", pickupS={{"At {s:04-46}, before flying from Darkshire to Booty Bay, fly to Stormwind first if you're level 48 and take Our Man in Theramore from Master Mathias Shaw"}, {"When {s:04-46} ends with the flight to Theramore, find Sully McCleary for the follow-ups"}}, tips={{k="提醒", text="Optional at level 48: agree before entering to leave The Questioner alive. After defeating the final boss, speak to the shackled prisoner. Once you have the quest, go back to kill The Questioner for the key and return it to the prisoner.", s={{"Optional at level 48: agree before entering to leave The Questioner alive"}, {"After defeating the final boss, speak to the shackled prisoner"}, {"Once you have the quest, go back to kill The Questioner for the key and return it to the prisoner"}}}}, steps={[1]={npc="Master Mathias Shaw", tgt="Master Mathias Shaw"}, [2]={npc="Sully McCleary", tgt="Sully McCleary"}, [3]={npc="Sully McCleary", tgt="Sully McCleary"}, [4]={npc="Sully McCleary", tgt="Sully McCleary"}, [5]={npc="Sully McCleary", tgt="Sully McCleary"}, [6]={hint="Use the SI:7 Disguise Kit to eavesdrop on Jaina and her inner circle at the Theramore Mage Tower."}, [7]={npc="Sully McCleary", tgt="Sully McCleary"}, [8]={npc="Sully McCleary", tgt="Sully McCleary"}, [9]={npc="Sully McCleary", tgt="Sully McCleary", tag="Optional"}, [10]={text="Optional: from Theramore, follow the east coast north to the northeastern shore of Dustwallow Marsh and swim to Alcaz Island; the dungeon portal is in the corridor under the island tower. After the dungeon, hand in at Theramore and rejoin {s:04-47}.", tag="Optional"}, [11]={text="Alcaz Prison entrance"}, [12]={hint="Enter the Alcaz Prison and slay 15 Strashasz Soldiers, 8 Strashaz Enchantresses, and bring the head of Tidemistress Ca'zass to Sully McCleary.", tag="Optional", desc="Location: Find Tidemistress Ca'zass by the upper cells. Clear naga along the hall.", spot="Find Tidemistress Ca'zass by the upper cells. Clear naga along the hall."}, [13]={hint="Enter Alcaz Prison and learn what became of the King of Stormwind.", desc="Location: Open the lower gate and kill the last boss, then enter the back chamber and find the note on the floor. Order: Get the key from the warden first.", spot="Open the lower door and kill the last boss, then enter the hidden room behind him and find the note on the floor."}, [14]={npcObj=true, spot="Note on the floor of the hidden room behind Blazeroar"}, [15]={npcObj=true}, [16]={tag="Optional", desc="After the last boss, talk to the shackled prisoner next to it. The interrogator must still be alive for you to get the key."}, [17]={hint="Recover the Alcaz Shackle Key from The Questioner in Alcaz Prison.", tag="Optional"}, [18]={tag="Optional", spot="Next to the last boss, the shackled prisoner"}, [19]={npc="Sully McCleary", tgt="Sully McCleary", tag="Optional"}, [20]={npc="Sully McCleary", tgt="Sully McCleary"}, [21]={npc="Sully McCleary", tgt="Sully McCleary"}, [22]={npc="Master Mathias Shaw", tgt="Master Mathias Shaw", desc="Hand it in the next time you pass through Stormwind."}}},
    ["04-47"] = {steps={[1]={to="Gadgetzan", desc="The scroll is in the raptor cave southwest of Dustwallow Marsh. Walk back east to Theramore (67.48, 51.30) first, then fly."}, [2]={npc="Krinkle Goodsteel", tgt="Krinkle Goodsteel", tag="When you have the items"}, [3]={npc="Sprinkle", tgt="Sprinkle"}, [4]={npc="Sprinkle", tgt="Sprinkle"}, [5]={npc="Marin Noggenfogger", tgt="Marin Noggenfogger"}, [6]={npc="Marin Noggenfogger", tgt="Marin Noggenfogger"}, [7]={npc="Marin Noggenfogger", tgt="Marin Noggenfogger"}, [8]={text="From Gadgetzan follow the road north into the Shimmering Flats in Thousand Needles."}, [9]={npc="Kravel Koalbeard", tgt="Kravel Koalbeard"}, [10]={npc="Kravel Koalbeard", tgt="Kravel Koalbeard"}, [11]={npc="Gnome Pit Boss", tgt="Gnome Pit Boss"}, [12]={npc="Wizzle Brassbolts", tgt="Wizzle Brassbolts", tag="Optional"}, [13]={npc="Wizzle Brassbolts", tgt="Wizzle Brassbolts", tag="Optional, Group"}, [14]={npc="Marvon Rivetseeker", tgt="Marvon Rivetseeker"}, [15]={npc="Uldum Pedestal", npcObj=true}, [16]={npc="Stone Watcher of Norgannon", tgt="Stone Watcher of Norgannon"}, [17]={npc="Uldum Pedestal", npcObj=true}, [18]={npc="Uldum Pedestal", npcObj=true}, [19]={text="Head northwest to the start of the path down to Un'Goro Crater."}}},
    ["04-48"] = {grind={[1]={mob="Bloodpetal Lasher", note="The plant mobs on the east side; kill them when you first enter the crater."}, [2]={mob="Un'Goro Gorilla", note="Outside the gorilla cave in the northeast; the same mobs as for the gorilla pelts."}, [3]={mob="Pterrordax", note="The cliffs east of Marshal's Refuge."}, [4]={mob="Tar Lurker", note="The tar pits south of the camp; on the high side for level, so pull one at a time."}}, steps={[1]={text="From the mountain road west of Tanaris, take the ramp down into Un'Goro Crater. Torwa Pathfinder is right by the entrance at the bottom of the ramp.", tag="Flight path locked. Travel there on foot the first time."}, [2]={npc="Torwa Pathfinder", tgt="Torwa Pathfinder", tag="Hard, Optional"}, [3]={npc="Torwa Pathfinder", tgt="Torwa Pathfinder"}, [4]={npc="A Wrecked Raft", npcObj=true, desc="Collect 7 each of red, blue, green and yellow crystals, and get A Mangled Journal from the raptors."}, [5]={npc="A Small Pack", npcObj=true}, [6]={npc="A Small Pack", npcObj=true}, [7]={hint="Find the carcass of Lar'korwi's freshest kill and steal a Piece of Threshadon Carcass before returning to Torwa Pathfinder in Un'Goro Crater."}, [8]={npc="Torwa Pathfinder", tgt="Torwa Pathfinder"}, [9]={npc="Torwa Pathfinder", tgt="Torwa Pathfinder"}, [10]={hint="Bring 2 Ravasaur Pheromone Glands to Torwa Pathfinder near the entrance to Un'Goro Crater."}, [11]={npc="Crystal Infused Scale", npcObj=true, tag="Optional"}, [12]={npc="Torwa Pathfinder", tgt="Torwa Pathfinder", tag="Optional, When you have the items"}, [13]={text="Use the Crystal Infused Scale in your bag to start Microcrystal Contamination, then turn in both quests to Torwa."}, [14]={npc="Torwa Pathfinder", tgt="Torwa Pathfinder"}, [15]={npc="Torwa Pathfinder", tgt="Torwa Pathfinder", tag="Optional"}, [16]={hint="Using the contents of Torwa's Pouch, summon Lar'korwi and defeat him. Then bring Lar'korwi's Head to Torwa Pathfinder near the entrance to Un'Goro Crater.", tag="Group, Optional", desc="This one is harder. You can save it for when you return to Un'Goro."}, [17]={npc="Karna Remtravel", tgt="Karna Remtravel"}, [18]={npc="Linken", tgt="Linken"}, [19]={npc="Linken", tgt="Linken"}, [20]={node="Marshal's Refuge"}, [21]={npc="Williden Marshal", tgt="Williden Marshal"}, [22]={npc="Hol'anyee Marshal", tgt="Hol'anyee Marshal"}, [23]={npc="Spark Nilminer", tgt="Spark Nilminer"}, [24]={npc="J.D. Collie", tgt="J.D. Collie", desc="Collect Power Crystals as you travel. If you have seven of each color when you first meet J.D. Collie, turn them in on the spot. Otherwise, finish on your next visit."}, [25]={npc="Beware of Pterrordax", npcObj=true}, [26]={npc="Muigin", tgt="Muigin"}, [27]={npc="Shizzle", tgt="Shizzle"}, [28]={hint="Bring 8 Dinosaur Bones to Spark Nilminer in Un'Goro Crater."}, [29]={hint="Bring 2 Un'Goro Gorilla Pelts, 2 Un'Goro Stomper Pelts, and 2 Un'Goro Thunderer Pelts to Torwa Pathfinder at the entrance of Un'Goro Crater.", tag="Hard, Optional"}, [30]={desc="If you're not level 50 yet, stay outside the gorilla cave and kill Un'Goro Gorillas until 50."}, [31]={hint="Collect 15 Bloodpetals and return to Muigin."}, [32]={text="Loot the crate of foodstuffs at the eastern camp."}, [33]={npc="Torwa Pathfinder", tgt="Torwa Pathfinder"}, [34]={npc="Torwa Pathfinder", tgt="Torwa Pathfinder"}, [35]={npc="Torwa Pathfinder", tgt="Torwa Pathfinder"}, [36]={text="Into the hive for the sample: head southwest to the cave entrance and go inside (50.40, 78.80 → 48.70, 85.20)."}, [37]={hint="Use the Scraping Vial to collect a Hive Wall Sample from one of the Gorishi hive hatcheries in Un'Goro Crater. Look for the chambers with the hanging larval spawns."}, [38]={text="Finish the kill and collection quests you have."}, [39]={hint="Bring a Crate of Foodstuffs and Research Equipment to Williden Marshal in Un'Goro Crater.", desc="The Crate of Foodstuffs is in the east (on the way to the gorilla cave and Torwa), and the Research Equipment is in the southwest (on the way from the hive to the pterrordax), so grab one of each as you pass."}, [40]={hint="Collect 8 Webbed Diemetradon Scales and 8 Webbed Pterrordax Scales for Shizzle in Marshal's Refuge."}, [41]={hint="Kill 10 Pterrordax and 15 Frenzied Pterrordax, then speak to Spraggle Frock at Marshal's Refuge."}, [42]={npc="Shizzle", tgt="Shizzle"}, [43]={npc="Muigin", tgt="Muigin"}, [44]={npc="Muigin", tgt="Muigin"}, [45]={npc="Spraggle Frock", tgt="Spraggle Frock"}, [46]={npc="Spark Nilminer", tgt="Spark Nilminer"}, [47]={npc="Hol'anyee Marshal", tgt="Hol'anyee Marshal"}, [48]={npc="Williden Marshal", tgt="Williden Marshal"}, [49]={npc="A Mangled Journal", npcObj=true, tag="Optional", desc="Right-click to start only if you loot A Mangled Journal from mobs."}, [50]={npc="Williden Marshal", tgt="Williden Marshal", tag="Optional"}, [51]={desc="If you're not level 51 yet, kill pterrordax east of the camp, or Tar Lurkers at the tar pits to the south, until 51."}, [52]={bind="Ironforge", desc="If your Hearthstone is bound to Ironforge, use it when available. Priests can accept Cenarion Aid from High Priest Rohan; mages can take the optional Magecraft from Dink."}, [53]={text="Go only if you want the Stormwind breadcrumb: take the Deeprun Tram from Ironforge to Stormwind.", tag="Optional"}, [54]={npc="Maginor Dumas", tgt="Maginor Dumas", tag="Optional", desc="You can skip the Stormwind introduction. You still need to find Sanath Lim-yo first to be teleported up the cliff when you reach Azshara."}, [55]={text="Fly from Stormwind to Menethil Harbor and rejoin the route.", tag="Optional"}, [56]={npc="High Priest Rohan", tgt="High Priest Rohan", tag="You can buy 1 Ichor of Undeath at the Auction House now, or have an alt mail it (for The Ichor of Undeath in Azshara later).", desc="Turn it in to Ogtinc in Azshara."}, [57]={to="Menethil Harbor", desc="Check the flight map at Marshal's Refuge. Fly to Auberdine or Rut'theran Village if offered. Otherwise, take the southeast ramp into Tanaris and check flights at Gadgetzan."}, [58]={to="Auberdine", from="Menethil Harbor", desc="This boat stops at Southshore on the way. Don't get off until Auberdine."}, [59]={to="Rut'theran Village", desc="Transfer at Auberdine for Rut'theran Village. If aboard, get off when the ship docks. Fly if offered, or take the ship from the north pier (33.3, 39.8)."}, [60]={npc="Erelas Ambersky", tgt="Erelas Ambersky"}, [61]={npc="Daryn Lightwind", tgt="Daryn Lightwind"}, [62]={npc="Daryn Lightwind", tgt="Daryn Lightwind"}, [63]={text="Step into the portal in Rut'theran Village to Darnassus.", tag="You can buy 1 Mithril Casing at the Auction House now, or have an alt mail it (for Chasing A-Me 01 in Un'Goro later)."}, [64]={npc="Gracina Spiritmight", tgt="Gracina Spiritmight"}, [65]={npc="Gracina Spiritmight", tgt="Gracina Spiritmight"}, [66]={npc="Astarii Starseeker", tgt="Astarii Starseeker", tag="Group, Optional"}, [67]={npc="Dorion", tgt="Dorion", desc="Accept it in Darnassus (or Ironforge or Stormwind) and turn it in to Ogtinc in Azshara."}, [68]={text="Step into the portal in Darnassus back to Rut'theran Village."}, [69]={to="Astranaar"}, [70]={text="Set your hearth in the Astranaar inn (37.00, 49.20).", bind="Astranaar"}, [71]={text="Check your location. If aboard, wait for your destination before getting off. At Auberdine, transfer to Rut'theran Village. Once ashore at Rut'theran, turn in your quests."}, [72]={text="For your class quest in the Eastern Kingdoms, check flights to Auberdine at Marshal's Refuge. If none is available, take the southeast ramp into Tanaris and check at Gadgetzan. From Auberdine, take the direct ship to Stormwind."}, [73]={text="Take the direct ship from Auberdine to Stormwind. If you are still aboard another ship, get off when it docks and wait at the Stormwind pier (30.5, 40.9)."}, [74]={text="Return to Auberdine from Stormwind Harbor. Wait at the Auberdine pier (21.8, 56.9); once ashore, continue your route in Kalimdor."}, [75]={text="Check your location and quest log. Leave a free slot before crossing for the class quest. If aboard, stay on the ship until it docks at your destination."}, [76]={text="Disembark once the ship docks in Stormwind Harbor, then visit your class quest giver in the city. If still at sea, stay aboard."}, [77]={npc="Brother Joshua", tgt="Brother Joshua"}, [78]={npc="Dink", tgt="Dink", tag="Optional"}, [79]={text="Check with the Ironforge flight master for a flight to Menethil Harbor. If none is available, take the Deeprun Tram to Stormwind and sail from Stormwind Harbor to Auberdine."}, [80]={to="Talrendis Point"}, [81]={npc="Loh'atu", tgt="Loh'atu"}, [82]={npc="Loh'atu", tgt="Loh'atu"}, [83]={hint="Destroy 6 Highborne Apparitions and 6 Highborne Lichlings before returning to Loh'atu in Azshara."}, [84]={hint="Kill 6 Haldarr Satyr, 2 Haldarr Tricksters, 2 Haldarr Felsworn and then return to Loh'atu on the border of Ashenvale."}, [85]={npc="Loh'atu", tgt="Loh'atu"}, [86]={npc="Loh'atu", tgt="Loh'atu"}, [87]={npc="Sanath Lim-yo", tgt="Sanath Lim-yo", tag="Optional", desc="Turn it in here only if you picked up the introduction."}, [88]={text="Talk to Sanath Lim-yo and ask him to teleport you up the cliff to find Archmage Xylem."}, [89]={npc="Archmage Xylem", tgt="Archmage Xylem"}, [90]={hint="Bring 10 Glittering Dust to Archmage Xylem."}, [91]={npc="Archmage Xylem", tgt="Archmage Xylem", desc="The dust is at the foot of the mountain; go back to Sanath Lim-yo the same way to be teleported up."}, [92]={npc="Archmage Xylem", tgt="Archmage Xylem"}, [93]={hint="Collect 6 Enchanted Coral and return them to Archmage Xylem."}, [94]={npc="Archmage Xylem", tgt="Archmage Xylem"}, [95]={npc="Archmage Xylem", tgt="Archmage Xylem", tag="Group, Optional", desc="Morphaz is in the Temple of Atal'Hakkar."}, [96]={hint="Retrieve the Arcane Shard from Morphaz and return to Archmage Xylem.", tag="Group, Optional", desc="Morphaz is in the Temple of Atal'Hakkar."}, [97]={npc="Archmage Xylem", tgt="Archmage Xylem", tag="Group, Optional", desc="Morphaz is in the Temple of Atal'Hakkar."}, [98]={text="Head to Felwood via Astranaar. If your Hearthstone is bound to Astranaar and ready, use it to return to the inn. Once safely down from the cliff, check the flight map at Talrendis Point. Fly to Astranaar if you can, or take the main road west through eastern Ashenvale. From Astranaar, follow the main road north into Felwood."}, [99]={npc="Ogtinc", tgt="Ogtinc"}, [100]={npc="Ogtinc", tgt="Ogtinc"}, [101]={hint="Acquire 4 Healthy Courser Glands and bring them to Ogtinc in Azshara. Ogtinc resides atop the cliffs northeast the Ruins of Eldarath."}, [102]={npc="Ogtinc", tgt="Ogtinc"}, [103]={npc="Ogtinc", tgt="Ogtinc", desc="Ichor of Undeath ×1 can be bought at the Auction House."}, [104]={hint="Acquire an Ichor of Undeath for Ogtinc in Azshara. Ogtinc resides atop the cliffs northeast the Ruins of Eldarath."}, [105]={npc="Ogtinc", tgt="Ogtinc"}, [106]={npc="Ogtinc", tgt="Ogtinc", tag="Group, Optional", desc="Morphaz is in the Temple of Atal'Hakkar."}, [107]={text="From Azshara, return to Talrendis Point, fly to Astranaar, and head north into Felwood. After the temple, go straight to Emerald Sanctuary in Felwood."}, [108]={npc="Ogtinc", tgt="Ogtinc", desc="Accept it in Darnassus (or Ironforge or Stormwind) and turn it in to Ogtinc in Azshara."}, [109]={npc="Ogtinc", tgt="Ogtinc"}, [110]={hint="Bring a pair of Perfect Courser Antlers to Ogtinc in Azshara. Ogtinc resides atop the cliffs northeast of the Ruins of Eldarath."}, [111]={npc="Ogtinc", tgt="Ogtinc"}, [112]={npc="Ogtinc", tgt="Ogtinc"}, [113]={hint="Bring 6 Wavethrasher Scales to Ogtinc in Azshara. Ogtinc resides atop the cliffs northeast the Ruins of Eldarath."}, [114]={npc="Ogtinc", tgt="Ogtinc"}, [115]={npc="Ogtinc", tgt="Ogtinc", tag="Group, Optional", desc="The green drake is in the Temple of Atal'Hakkar."}, [116]={hint="Bring the Tooth of Morphaz to Ogtinc in Azshara. Ogtinc resides atop the cliffs northeast the Ruins of Eldarath.", tag="Group, Optional", desc="The green drake is in the Temple of Atal'Hakkar."}, [117]={npc="Ogtinc", tgt="Ogtinc", tag="Group, Optional", desc="The green drake is in the Temple of Atal'Hakkar."}, [118]={text="Return to Talrendis Point and fly to Astranaar, then follow the road north into Felwood."}, [119]={to="Astranaar"}}},
    ["04-49"] = {grind={[1]={mob="Jaedenar Guardian", note="Around the entrance to Jaedenar; normal mobs."}, [2]={mob="Jaedenar Cultist", note="Mixed in with the Guardians; casters."}}, steps={[1]={text="From Astranaar, follow the road north into Felwood.", tag="Flight path locked. Travel there on foot the first time."}, [2]={npc="Arathandris Silversky", tgt="Arathandris Silversky"}, [3]={npc="Grazle", tgt="Grazle"}, [4]={npc="Greta Mosshoof", tgt="Greta Mosshoof"}, [5]={npc="Greta Mosshoof", tgt="Greta Mosshoof", tag="Group, Optional, When you have the items"}, [6]={npc="Eridan Bluewind", tgt="Eridan Bluewind"}, [7]={npc="Taronn Redfeather", tgt="Taronn Redfeather"}, [8]={hint="Grazle wants you to prove yourself by killing 6 Deadwood Warriors, 6 Deadwood Pathfinders, and 6 Deadwood Gardeners. Return to him in southern Felwood near the Emerald Sanctuary when you are done."}, [9]={npc="Grazle", tgt="Grazle"}, [10]={npc="Grazle", tgt="Grazle"}, [11]={hint="Kill 11 Jadefire Felsworns, 9 Jadefire Shadowstalkers, 9 Jadefire Rogues, and Xavathras. Return to Eridan Bluewind in Felwood when the task has been completed."}, [12]={hint="Enter Jaedenar and slay 4 Jaedenar Hounds, 4 Jaedenar Guardsmen, 6 Jaedenar Adepts, and 6 Jaedenar Cultists before returning to Greta Mosshoof in Felwood."}, [13]={npc="Eridan Bluewind", tgt="Eridan Bluewind"}, [14]={npc="Eridan Bluewind", tgt="Eridan Bluewind"}, [15]={npc="Greta Mosshoof", tgt="Greta Mosshoof"}, [16]={npc="Greta Mosshoof", tgt="Greta Mosshoof"}, [17]={hint="Take the Empty Canteen to the Moon Well in the center of Jaedenar and fill it before returning to Greta Mosshoof in Felwood."}, [18]={desc="Kill mobs around 35, 59 in Jaedenar."}, [19]={hint="Seek out and destroy 2 Entropic Beasts and 2 Entropic Horrors while exploring Shatter Scar Vale. After checking to see if the craters there are still filled with corrupt fel water, return to Taronn Redfeather in Felwood."}, [20]={hint="Eridan Bluewind in Felwood wants you to kill 8 Jadefire Hellcallers, 8 Jadefire Betrayers, 8 Jadefire Tricksters, and Xavaric. Return to Eridan when the task is completed."}, [21]={npc="Flute of Xavaric", npcObj=true, desc="Right-click Flute of Xavaric in your bags to start the quest."}, [22]={hint="Bring the Flute of Xavaric and 5 Jadefire Felbind samples to Eridan Bluewind in southern Felwood."}, [23]={hint="Bring 15 Blood Amber to Arathandris Silversky in Felwood."}, [24]={node="Talonbranch Glade"}, [25]={npc="Nafien", tgt="Nafien"}, [26]={npc="Nafien", tgt="Nafien"}, [27]={hint="Nafien would like you to kill 6 Deadwood Den Watchers, 6 Deadwood Avengers, and 6 Deadwood Shamans. Return to him in northern Felwood near the entrance to Timbermaw Hold."}, [28]={npc="Nafien", tgt="Nafien"}, [29]={npc="Nafien", tgt="Nafien", desc="Turn it in to Salfa when you come through Timbermaw Hold into Winterspring."}, [30]={text="Enter the Timbermaw Hold cave from here and pass through it to reach Winterspring."}, [31]={node="Moonglade", desc="A fork in the Timbermaw Hold cave leads to Moonglade; go over first to unlock the flight path, then return to the cave and head toward Winterspring. For the Mount Hyjal part later you'll fly to Moonglade."}, [32]={npc="Salfa", tgt="Salfa"}, [33]={npc="Salfa", tgt="Salfa"}, [34]={npc="Donova Snowden", tgt="Donova Snowden"}, [35]={npc="Donova Snowden", tgt="Donova Snowden"}, [36]={npc="Meggi Peppinrocker", tgt="Meggi Peppinrocker"}, [37]={npc="Jessica Redpath", tgt="Jessica Redpath"}, [38]={node="Everlook"}, [39]={npc="Niby the Almighty", tgt="Niby the Almighty"}, [40]={npc="Impsy", tgt="Impsy"}, [41]={npc="Impsy", tgt="Impsy", desc="Felcloth ×1 can be bought at the Auction House."}, [42]={hint="Bring a piece of felcloth to Impsy in Felwood."}, [43]={npc="Impsy", tgt="Impsy"}, [44]={npc="Impsy", tgt="Impsy"}, [45]={hint="Bring 10 Rotting Wood and 4 Bloodvenom Essence to Impsy in Felwood."}, [46]={npc="Impsy", tgt="Impsy"}, [47]={npc="Impsy", tgt="Impsy", tag="Group, Optional"}, [48]={hint="Bring a total of 6 Voodoo Feathers from the trolls in sunken temple.", tag="Group, Optional"}, [49]={npc="Impsy", tgt="Impsy", tag="Group, Optional"}, [50]={npc="Impsy", tgt="Impsy"}, [51]={hint="Impsy in Felwood has asked that you bring him three Flawless Fel Essences originating from three distinct locations."}, [52]={npc="Impsy", tgt="Impsy"}, [53]={npc="Impsy", tgt="Impsy", desc="Kroshius is in northern Felwood. You need a group."}, [54]={hint="Search Shatter Scar Vale in Felwood for the remains of Kroshius. When you locate the remains, use the Fel Fire near them and await Kroshius' return. When the infernal has awoken, slay him and take from his corpse Kroshius' Infernal Core.", desc="Kroshius is in northern Felwood. You need a group."}, [55]={npc="Niby the Almighty", tgt="Niby the Almighty", desc="Kroshius is in northern Felwood. You need a group."}}},
    ["05-d14"] = {name="The Temple of Atal'Hakkar", entrance="Swamp of Sorrows (1435), 69.50, 52.50. Marks the outside of the temple.", steps={[1]={npc="Angelas Moonbreeze", tgt="Angelas Moonbreeze", tag="Dungeon prereq"}, [2]={npc="Marvon Rivetseeker", tgt="Marvon Rivetseeker", tag="Dungeon prereq"}, [3]={npc="Marvon Rivetseeker", tgt="Marvon Rivetseeker", tag="Dungeon prereq"}, [4]={hint="Retrieve the Stone Circle from Marvon Rivetseeker's workshop in Ratchet.", tag="Dungeon prereq"}, [5]={npc="Marvon Rivetseeker", tgt="Marvon Rivetseeker", tag="Dungeon prereq"}, [6]={npc="Marvon Rivetseeker", tgt="Marvon Rivetseeker", preText="The Stone Circle"}, [7]={npc="Marvon Rivetseeker", tgt="Marvon Rivetseeker", preText="The Stone Circle"}, [8]={npc="Yeh'kinya", tgt="Yeh'kinya", tag="Dungeon prereq"}, [9]={hint="Capture the spirits of 3 screechers in Feralas, then return to Yeh'kinya in Steamwheedle Port.", tag="Dungeon prereq", desc="Kill Vale Screamers on the coast of the Isle of Dread in Feralas. Use Yeh'kinya's Bramble on each corpse, then speak to the spirit that appears. Repeat until your quest log shows three spirits."}, [10]={npc="Yeh'kinya", tgt="Yeh'kinya", tag="Dungeon prereq"}, [11]={npc="Yeh'kinya", tgt="Yeh'kinya", tag="Dungeon prereq"}, [12]={hint="Bring the First and Second Mosh'aru Tablets to Yeh'kinya in Tanaris.", tag="Dungeon prereq"}, [13]={npc="Yeh'kinya", tgt="Yeh'kinya", tag="Dungeon prereq"}, [14]={npc="Yeh'kinya", tgt="Yeh'kinya", tag="Dungeon prereq"}, [15]={hint="Bring the Ancient Egg to Yeh'kinya in Tanaris.", tag="Dungeon prereq"}, [16]={npc="Yeh'kinya", tgt="Yeh'kinya", tag="Dungeon prereq"}, [17]={npc="Yeh'kinya", tgt="Yeh'kinya", preText="The Ancient Egg"}, [18]={npc="Archmage Xylem", tgt="Archmage Xylem", tag="Dungeon prereq"}, [19]={hint="Bring 10 Glittering Dust to Archmage Xylem.", tag="Dungeon prereq"}, [20]={npc="Archmage Xylem", tgt="Archmage Xylem", tag="Dungeon prereq"}, [21]={npc="Archmage Xylem", tgt="Archmage Xylem", tag="Dungeon prereq"}, [22]={hint="Collect 6 Enchanted Coral and return them to Archmage Xylem.", tag="Dungeon prereq"}, [23]={npc="Archmage Xylem", tgt="Archmage Xylem", tag="Dungeon prereq"}, [24]={npc="Archmage Xylem", tgt="Archmage Xylem", tag="Optional", desc="Morphaz is in the Temple of Atal'Hakkar."}, [25]={npc="Brother Joshua", tgt="Brother Joshua", tag="Dungeon prereq"}, [26]={npc="Ogtinc", tgt="Ogtinc", tag="Dungeon prereq"}, [27]={npc="Ogtinc", tgt="Ogtinc", tag="Dungeon prereq"}, [28]={hint="Acquire 4 Healthy Courser Glands and bring them to Ogtinc in Azshara. Ogtinc resides atop the cliffs northeast the Ruins of Eldarath.", tag="Dungeon prereq"}, [29]={npc="Ogtinc", tgt="Ogtinc", tag="Dungeon prereq"}, [30]={npc="Ogtinc", tgt="Ogtinc", tag="Dungeon prereq"}, [31]={hint="Acquire an Ichor of Undeath for Ogtinc in Azshara. Ogtinc resides atop the cliffs northeast the Ruins of Eldarath.", tag="Dungeon prereq"}, [32]={npc="Ogtinc", tgt="Ogtinc", tag="Dungeon prereq"}, [33]={npc="Ogtinc", tgt="Ogtinc", tag="Optional", desc="Morphaz is in the Temple of Atal'Hakkar."}, [34]={npc="Dorion", tgt="Dorion", tag="Dungeon prereq"}, [35]={npc="Ogtinc", tgt="Ogtinc", tag="Dungeon prereq"}, [36]={npc="Ogtinc", tgt="Ogtinc", tag="Dungeon prereq"}, [37]={hint="Bring a pair of Perfect Courser Antlers to Ogtinc in Azshara. Ogtinc resides atop the cliffs northeast of the Ruins of Eldarath.", tag="Dungeon prereq"}, [38]={npc="Ogtinc", tgt="Ogtinc", tag="Dungeon prereq"}, [39]={npc="Ogtinc", tgt="Ogtinc", tag="Dungeon prereq"}, [40]={hint="Bring 6 Wavethrasher Scales to Ogtinc in Azshara. Ogtinc resides atop the cliffs northeast the Ruins of Eldarath.", tag="Dungeon prereq"}, [41]={npc="Ogtinc", tgt="Ogtinc", tag="Dungeon prereq"}, [42]={npc="Ogtinc", tgt="Ogtinc", tag="Optional", desc="The green drake is in the Temple of Atal'Hakkar."}, [43]={text="The Temple of Atal'Hakkar entrance"}, [44]={hint="Find the Altar of Hakkar in the Sunken Temple in Swamp of Sorrows.", desc="Location: Take the flat right route downstairs. Find the Altar of Hakkar on the ring.", spot="Take the flat right route downstairs. Find the Altar of Hakkar on the ring."}, [45]={npc="Altar of Hakkar", npcObj=true, spot="Altar of Hakkar on the lower level ring corridor"}, [46]={hint="Travel into the Sunken Temple and discover the secret hidden in the circle of statues.", desc="A wrong order triggers a trap. Location: Click the six statues in order along the lower ring corridor, then go to the center and kill the boss. Order: South → north → southwest → southeast → northwest → northeast.", spot="Activate the six statues on the lower ring, then kill the boss in the center."}, [47]={npc="Idol of Hakkar", npcObj=true, spot="Lower level center: the Hakkari statue"}, [48]={hint="Bring the Filled Egg of Hakkar to Yeh'kinya in Tanaris.", desc="Have the whole group enter the room before starting the event. Take the west passage to Hakkar's room. Location: From the Pit of Sacrifice take the west corridor into Hakkar's room, then gather and use the egg. Order: The west corridor leads to Hakkar and the east corridor to Jammal'an.", spot="Take the west hall from the Pit of Sacrifice. Group up before using the egg."}, [49]={hint="Retrieve the Arcane Shard from Morphaz and return to Archmage Xylem.", tag="Optional"}, [50]={hint="Kill Morphaz in the sunken temple of Atal'Hakkar, and return his blood to Greta Mosshoof in Felwood. The entrance to the sunken temple can be found in the Swamp of Sorrows.", tag="Optional"}, [51]={hint="Bring the Tooth of Morphaz to Ogtinc in Azshara. Ogtinc resides atop the cliffs northeast the Ruins of Eldarath.", tag="Optional"}, [52]={npc="Essence of Eranikus", npcObj=true, tag="Optional, Group", desc="After defeating the final boss, right-click the essence you looted to start the quest."}, [53]={hint="Place the Essence of Eranikus in the Essence Font located in this lair in the Sunken Temple.", tag="Optional, Group", spot="Place the essence in the Essence Font beside the final boss."}, [54]={npc="Essence Font", npcObj=true, tag="Optional, Group", spot="Place the essence in the Essence Font beside the final boss."}, [55]={npc="Yeh'kinya", tgt="Yeh'kinya"}, [56]={npc="Archmage Xylem", tgt="Archmage Xylem", tag="Optional", desc="Morphaz is in the Temple of Atal'Hakkar."}, [57]={npc="Ogtinc", tgt="Ogtinc", tag="Optional", desc="The green drake is in the Temple of Atal'Hakkar."}, [58]={npc="Greta Mosshoof", tgt="Greta Mosshoof", tag="Optional, When you have the items"}}},
    ["04-50"] = {steps={[1]={to="Feathermoon Stronghold"}, [2]={npc="Pratt McGrubben", tgt="Pratt McGrubben"}, [3]={npc="Troyas Moonbreeze", tgt="Troyas Moonbreeze"}, [4]={npc="Troyas Moonbreeze", tgt="Troyas Moonbreeze"}, [5]={npc="Gregan Brewspewer", tgt="Gregan Brewspewer"}, [6]={hint="Seek out Gregan Brewspewer in northern Feralas. From him, learn how you may acquire the Videre Elixir, then return to Donova Snowden in Winterspring.", desc="Gregan gives you bait: use it to lure Miblon away, grab the Evoroot, then come back and trade it for the Videre Elixir."}, [7]={npc="Rockbiter", tgt="Rockbiter"}, [8]={hint="Energize Troyas' Stave and find the Equinex Monolith.", desc="Further on, you can jump up to take a shortcut."}, [9]={npc="Equinex Monolith", npcObj=true, desc="Use the staff in your bags."}, [10]={npc="Equinex Monolith", npcObj=true}, [11]={npc="Shay Leafrunner", tgt="Shay Leafrunner"}, [12]={npc="Shay Leafrunner", tgt="Shay Leafrunner", tag="Escort"}, [13]={hint="Pick up Shay's Bell from the chest.", tag="Escort"}, [14]={npc="Rockbiter", tgt="Rockbiter"}, [15]={hint="Bring 10 Rage Scar Yeti Hides to Pratt McGrubben at Feathermoon Stronghold, Feralas."}, [16]={npc="Pristine Yeti Hide", npcObj=true, tag="Optional", desc="If a Pristine Yeti Hide drops while killing yetis, right-click it to accept."}, [17]={npc="Pratt McGrubben", tgt="Pratt McGrubben"}, [18]={npc="Pratt McGrubben", tgt="Pratt McGrubben", tag="Optional"}, [19]={npc="Troyas Moonbreeze", tgt="Troyas Moonbreeze"}}},
    ["04-51"] = {grind={[1]={mob="Winterfall Pathfinder", note="The Winterfall furbolg camp north of Donova; the same mobs as for the furbolg quest."}, [2]={mob="Winterfall Totemic", note="Same camp; casters."}}, steps={[1]={bind="Astranaar", desc="If your hearthstone is on cooldown, fly from Feathermoon Stronghold to Astranaar (via Auberdine), then walk north into Felwood."}, [2]={npc="Arathandris Silversky", tgt="Arathandris Silversky"}, [3]={npc="Arathandris Silversky", tgt="Arathandris Silversky"}, [4]={npc="Greta Mosshoof", tgt="Greta Mosshoof"}, [5]={npc="Greta Mosshoof", tgt="Greta Mosshoof", tag="Group, Optional, When you have the items"}, [6]={npc="Greta Mosshoof", tgt="Greta Mosshoof"}, [7]={npc="Eridan Bluewind", tgt="Eridan Bluewind"}, [8]={npc="Eridan Bluewind", tgt="Eridan Bluewind"}, [9]={npc="Eridan Bluewind", tgt="Eridan Bluewind"}, [10]={npc="Taronn Redfeather", tgt="Taronn Redfeather"}, [11]={hint="Loot from: Cursed Ooze, Tainted Ooze, Vile Ooze", desc="They only drop while the Cenarion Beacon is in your bags; the Ironbeak Owls are west of the sanctuary, and the oozes are at the pools to the northwest."}, [12]={npc="Arathandris Silversky", tgt="Arathandris Silversky"}, [13]={npc="Donova Snowden", tgt="Donova Snowden", desc="Return to Astranaar and fly to Talonbranch Glade, then head north through Timbermaw Hold into Winterspring."}, [14]={npc="Donova Snowden", tgt="Donova Snowden", desc="Drink the Videre Elixir at the graveyard outside Gadgetzan and find Gaeriyan as a ghost."}, [15]={npc="Donova Snowden", tgt="Donova Snowden"}, [16]={npc="Donova Snowden", tgt="Donova Snowden"}, [17]={desc="Kill furbolgs around 32, 36 in the Winterfall camp."}, [18]={npc="Gregor Greystone", tgt="Gregor Greystone"}, [19]={npc="Gregor Greystone", tgt="Gregor Greystone"}, [20]={to="Ratchet", desc="You'll connect through Talrendis Point."}, [21]={npc="Liv Rizzlefix", tgt="Liv Rizzlefix"}, [22]={npc="Islen Waterseer", tgt="Islen Waterseer"}, [23]={npc="Islen Waterseer", tgt="Islen Waterseer"}, [24]={to="Gadgetzan"}, [25]={npc="Alchemist Pestlezugg", tgt="Alchemist Pestlezugg"}, [26]={text="After drinking the Videre Elixir, stay dead and find the quest NPC as a ghost."}, [27]={npc="Gaeriyan", tgt="Gaeriyan"}, [28]={npc="Gaeriyan", tgt="Gaeriyan"}, [29]={text="Return to your corpse and resurrect."}, [30]={npc="A Conspicuous Gravestone", npcObj=true}, [31]={npc="A Conspicuous Gravestone", npcObj=true}, [32]={npc="Tran'rek", tgt="Tran'rek"}, [33]={npc="Alchemist Pestlezugg", tgt="Alchemist Pestlezugg", tag="Optional"}}},
    ["04-52"] = {name="Un'Goro Crater", steps={[1]={to="Marshal's Refuge"}, [2]={npc="Linken", tgt="Linken"}, [3]={npc="Linken", tgt="Linken"}, [4]={npc="J.D. Collie", tgt="J.D. Collie"}, [5]={npc="J.D. Collie", tgt="J.D. Collie"}, [6]={npc="Spraggle Frock", tgt="Spraggle Frock"}, [7]={npc="Hol'anyee Marshal", tgt="Hol'anyee Marshal", tag="Optional, If offered", desc="A book delivery quest: accept it if an NPC offers it, and take the book to the Summit of Eternity on Mount Hyjal to turn it in. Skip it for now if you don't see the quest."}, [8]={hint="Collect 12 samples of Super Sticky Tar for Tran'rek in Gadgetzan."}, [9]={npc="Krakle", tgt="Krakle"}, [10]={hint="Collect 9 samples of Un'Goro Ash from the fire elementals around the volcano in Un'Goro Crater, and return them to Liv Rizzlefix in Ratchet."}, [11]={hint="Krakle in Un'Goro Crater wants you to find the hottest area of Fire Plume Ridge.", desc="Follow the path up Fire Plume Ridge to take the temperature. Collect ash along the way if you have that quest. After taking the reading, follow the path to Ringo. After starting the escort, go straight north to Marshal's Refuge."}, [12]={npc="Ringo", tgt="Ringo", desc="Escort quest: in a group, wait until everyone is at the same step before accepting, and turn off auto-accept."}, [13]={npc="Ringo", tgt="Ringo"}, [14]={hint="Lead Ringo to Spraggle Frock at Marshal's Refuge.", tag="Escort", desc="Lead Ringo back to Marshal's Refuge. He'll pass out along the way; use Spraggle's Canteen on him when he does."}, [15]={npc="Spraggle Frock", tgt="Spraggle Frock"}, [16]={npc="A-Me 01", tgt="A-Me 01"}, [17]={npc="A-Me 01", tgt="A-Me 01"}, [18]={hint="Find a Mithril Casing and return to A-Me 01 in Un'Goro Crater.", desc="Buy the mithril casing at the auction house beforehand, or have an engineer make it."}, [19]={npc="A-Me 01", tgt="A-Me 01"}, [20]={hint="Bring U'cha's Pelt to Torwa Pathfinder at the entrance of Un'Goro Crater."}, [21]={npc="A-Me 01", tgt="A-Me 01"}, [22]={hint="Escort A-Me 01 back to Karna Remtravel in Un'Goro Crater.", tag="Escort", desc="Escort A-Me 01 back to Karna Remtravel; monsters along the way will attack it, so protect it."}, [23]={npc="Karna Remtravel", tgt="Karna Remtravel"}, [24]={hint="Collect 7 Power Crystals of each color: red, blue, yellow, and green. Bring them to J.D. Collie at Marshal's Refuge.", desc="Crystals in four colors are scattered on the ground all over the crater; top up any you were short on earlier."}, [25]={npc="J.D. Collie", tgt="J.D. Collie"}, [26]={npc="J.D. Collie", tgt="J.D. Collie"}, [27]={npc="J.D. Collie", tgt="J.D. Collie"}, [28]={npc="J.D. Collie", tgt="J.D. Collie"}, [29]={hint="Discover the location of the Northern Crystal Pylon in Un'Goro Crater."}, [30]={hint="Discover the location of the Eastern Crystal Pylon in Un'Goro Crater."}, [31]={hint="Bring a Gorishi Scent Gland and 5 Un'Goro Soil samples to Alchemist Pestlezugg in Gadgetzan.", tag="Optional", desc="Look for Gorishi Wasps or Workers at the southern hive for the scent gland. Pick up soil from dirt piles along the way until you have five. Solo players can pull isolated insects without going deeper to find the queen."}, [32]={hint="Bring a Gorishi Scent Gland and 5 Un'Goro Soil samples to Alchemist Pestlezugg in Gadgetzan.", tag="Optional", desc="Look for Gorishi Wasps or Workers at the southern hive for the scent gland. Pick up soil from dirt piles along the way until you have five. Solo players can pull isolated insects without going deeper to find the queen."}, [33]={hint="Discover the location of the Western Crystal Pylon."}, [34]={npc="Krakle", tgt="Krakle"}, [35]={npc="Krakle", tgt="Krakle"}, [36]={npc="J.D. Collie", tgt="J.D. Collie"}, [37]={npc="J.D. Collie", tgt="J.D. Collie"}, [38]={npc="J.D. Collie", tgt="J.D. Collie"}, [39]={npc="J.D. Collie", tgt="J.D. Collie"}, [40]={npc="J.D. Collie", tgt="J.D. Collie"}, [41]={npc="Torwa Pathfinder", tgt="Torwa Pathfinder"}, [42]={npc="Torwa Pathfinder", tgt="Torwa Pathfinder"}, [43]={hint="Collect 8 Bloodcap and 8 Gorishi Stings, and return to Torwa Pathfinder in Un'Goro Crater."}, [44]={npc="Torwa Pathfinder", tgt="Torwa Pathfinder"}, [45]={npc="Torwa Pathfinder", tgt="Torwa Pathfinder"}, [46]={npc="Torwa Pathfinder", tgt="Torwa Pathfinder"}, [47]={npc="Torwa Pathfinder", tgt="Torwa Pathfinder", tag="Group, Optional"}, [48]={hint="Retrieve a Putrid Vine from the guardian at the bottom of the Sunken Temple and return to Torwa Pathfinder.", tag="Group, Optional"}, [49]={npc="Torwa Pathfinder", tgt="Torwa Pathfinder", tag="Group, Optional"}, [50]={text="If you're still in the north and have no business with Torwa, check the flight map at Marshal's Refuge and fly to Gadgetzan if it's available. If you have U'cha's Pelt to deliver or want to do Torwa's druid quests, visit him in the southeast first. From Torwa, or if you can't fly, take the southeastern ramp into Tanaris and head northeast to Gadgetzan."}, [51]={npc="Tran'rek", tgt="Tran'rek"}, [52]={npc="Alchemist Pestlezugg", tgt="Alchemist Pestlezugg", tag="Optional"}, [53]={to="Ratchet", desc="You'll connect through Theramore."}, [54]={npc="Liv Rizzlefix", tgt="Liv Rizzlefix"}, [55]={bind="Astranaar"}, [56]={to="Auberdine"}, [57]={text="Set your hearth with Innkeeper Shaussiy in the Auberdine inn (37.04, 44.13).", bind="Auberdine"}, [58]={to="Rut'theran Village"}, [59]={npc="Erelas Ambersky", tgt="Erelas Ambersky"}, [60]={text="Step into the portal in Rut'theran Village to Darnassus."}, [61]={hint="Travel to Darnassus and use Eridan's Vial to collect a Vial of Blessed Water from the Temple of the Moon. Return to Eridan with the filled vial."}, [62]={text="Step into the portal in Darnassus back to Rut'theran Village."}, [63]={to="Astranaar"}, [64]={npc="Greta Mosshoof", tgt="Greta Mosshoof"}, [65]={npc="Greta Mosshoof", tgt="Greta Mosshoof", tag="Optional, If offered", desc="A letter delivery quest: accept it if an NPC offers it, and take it to Hermit Ketharas on Mount Hyjal. Skip it for now if you don't see the quest."}, [66]={npc="Eridan Bluewind", tgt="Eridan Bluewind"}, [67]={npc="Eridan Bluewind", tgt="Eridan Bluewind"}, [68]={npc="Eridan Bluewind", tgt="Eridan Bluewind"}, [69]={npc="Eridan Bluewind", tgt="Eridan Bluewind"}, [70]={npc="Eridan Bluewind", tgt="Eridan Bluewind"}, [71]={hint="Collect 11 Silvery Claws and 1 Irontree Heart for Eridan Bluewind in Felwood.", tag="Optional", desc="This is a dedicated detour with no other objectives nearby. Skip it if you're in a hurry."}, [72]={npc="Eridan Bluewind", tgt="Eridan Bluewind", tag="Optional"}, [73]={bind="Auberdine", desc="If it's on cooldown, walk back to Astranaar and fly to Auberdine."}, [74]={to="Menethil Harbor", from="Auberdine", desc="In Auberdine, board the boat to Menethil Harbor. Get off at the next stop."}, [75]={to="Ironforge"}, [76]={npc="Historian Karnik", tgt="Historian Karnik"}, [77]={npc="Historian Karnik", tgt="Historian Karnik"}, [78]={npc="High Explorer Magellas", tgt="High Explorer Magellas"}, [79]={npc="High Explorer Magellas", tgt="High Explorer Magellas"}, [80]={npc="Royal Historian Archesonus", tgt="Royal Historian Archesonus"}, [81]={npc="Royal Historian Archesonus", tgt="Royal Historian Archesonus"}, [82]={npc="Royal Historian Archesonus", tgt="Royal Historian Archesonus"}}},
    ["05-d11"] = {name="Blackrock Depths", entrance="Searing Gorge 34.80, 85.30", pickup="On the main route, form your group in Ironforge after your second visit to Un'Goro. The Burning Steppes are next. If you find a group earlier in Searing Gorge, enter Blackrock Mountain at the south end of the gorge.", pickupS={{"On the main route, form your group in Ironforge after your second visit to Un'Goro"}, {"The Burning Steppes are next"}, {"If you find a group earlier in Searing Gorge, enter Blackrock Mountain at the south end of the gorge"}}, tips={{k="動線", text="From Ironforge, fly to Thorium Point if you can and enter Blackrock Mountain at the south end of Searing Gorge. Without that flight, leave Dun Morogh to the east for Loch Modan. Go south into the Badlands, then west around Kargath into Searing Gorge. → If you find a group in Winterspring, fly to Auberdine. Without the flight, retrace your steps through Timbermaw Hold to Felwood and travel through Ashenvale to Auberdine in Darkshore. Take the boat to Stormwind, then fly to Thorium Point. Without the eastern flight paths, leave Stormwind through Elwynn Forest for Redridge. Take the road north from Lakeshire into the Burning Steppes, then head west into Blackrock Mountain. → To continue the Burning Steppes route, leave Blackrock Mountain by the south gate and follow the road east to Morgan's Vigil. → To return to Feathermoon Stronghold, hearth to Astranaar if you are bound there and your Hearthstone is ready. Otherwise, travel from the Burning Steppes through Redridge and Elwynn Forest to Stormwind Harbor. Take the boat to Auberdine, then fly to Feathermoon Stronghold. Without that flight, follow the road from Ashenvale through the Stonetalon Mountains and Desolace to Feralas, then take the boat from the west-coast dock to the island."}}, steps={[1]={npc="Franclorn Forgewright", tgt="Franclorn Forgewright", desc="Speak to Franclorn inside Blackrock Mountain as a ghost. Accept and turn in the first part and accept the second before resurrecting. See the route on this page for ways into the mountain."}, [2]={npc="Franclorn Forgewright", tgt="Franclorn Forgewright"}, [3]={npc="Franclorn Forgewright", tgt="Franclorn Forgewright"}, [4]={text="Blackrock Depths entrance"}, [5]={hint="Slay Fineous Darkvire and recover the great hammer, Ironfel. Take Ironfel to the Shrine of Thaurissan and place it on the statue of Franclorn Forgewright."}, [6]={npc="Monument of Franclorn Forgewright", npcObj=true, desc="Turn in Dark Iron Legacy here. Use Blackrock Mountain's south gate to continue in the Burning Steppes. To return to Kalimdor, follow this page's boat or Hearthstone directions."}}},
    ["04-54"] = {steps={[1]={text="If you've unlocked Morgan's Vigil, fly there directly from Ironforge. If not, fly to Lakeshire and follow the road north into the Burning Steppes; Morgan's Vigil is right by the entrance.", tag="Flight path locked. Travel there on foot the first time."}, [2]={node="Morgan's Vigil"}, [3]={npc="Oralius", tgt="Oralius"}, [4]={npc="Oralius", tgt="Oralius"}, [5]={npc="Helendis Riverhorn", tgt="Helendis Riverhorn", tag="Group, Optional"}, [6]={npc="Tinkee Steamboil", tgt="Tinkee Steamboil"}, [7]={npc="Maxwort Uberglint", tgt="Maxwort Uberglint"}, [8]={hint="Venture to the Ruins of Thaurissan in the Burning Steppes and recover information from the Thaurissan Relics. Return to Royal Historian Archesonus when you have recovered the information."}, [9]={hint="Bring the Tablet Transcript to Maxwort Uberglint in the Burning Steppes."}, [10]={hint="Slay 15 Firegut Ogre-Mages, 7 Firegut Ogres, and 7 Firegut Ogre Brutes, and return to Oralius when you are finished."}, [11]={hint="Bring 8 Broodling Essence and the Draco-Incarcinatrix 900 to Tinkee Steamboil at the Flame Crest in the Burning Steppes."}, [12]={hint="Slay 15 Black Broodlings, 10 Black Dragonspawn, 4 Black Wyrmkin and 1 Black Drake. Return to Helendis Riverhorn when the task is complete.", tag="Group, Optional", desc="The black dragonspawn and drakes are level 51-53 elites."}, [13]={npc="Cyrus Therepentous", tgt="Cyrus Therepentous"}, [14]={npc="Cyrus Therepentous", tgt="Cyrus Therepentous"}, [15]={npc="Tinkee Steamboil", tgt="Tinkee Steamboil"}, [16]={npc="Maxwort Uberglint", tgt="Maxwort Uberglint"}, [17]={npc="Oralius", tgt="Oralius"}, [18]={npc="Oralius", tgt="Oralius"}, [19]={npc="Helendis Riverhorn", tgt="Helendis Riverhorn", tag="Group, Optional"}, [20]={npc="Helendis Riverhorn", tgt="Helendis Riverhorn"}, [21]={hint="Find Gor'tesh, somewhere to the west of Dreadmaul Rock. Kill Gor'tesh and then take Gor'tesh's Lopped Off Head back to Oralius in Burning Steppes."}, [22]={hint="Oralius wants 50 Blackrock Medallions. Chances are high that these medallions can be found on the orcs in the Burning Steppes."}, [23]={npc="Oralius", tgt="Oralius"}, [24]={npc="Oralius", tgt="Oralius"}, [25]={to="Lakeshire", desc="If you're skipping The True Masters, fly straight to Stormwind and skip the next two steps."}, [26]={npc="Magistrate Solomon", tgt="Magistrate Solomon"}, [27]={npc="Magistrate Solomon", tgt="Magistrate Solomon"}, [28]={to="Stormwind"}, [29]={npc="Wu Shen", tgt="Wu Shen", tag="Optional"}, [31]={npc="Lord Grayson Shadowbreaker", tgt="Lord Grayson Shadowbreaker", desc="Turn it in at Chillwind Camp in the Western Plaguelands."}, [33]={npc="Highlord Bolvar Fordragon", tgt="Highlord Bolvar Fordragon"}, [34]={npc="Highlord Bolvar Fordragon", tgt="Highlord Bolvar Fordragon"}, [35]={npc="Highlord Bolvar Fordragon", tgt="Highlord Bolvar Fordragon"}, [36]={npc="Highlord Bolvar Fordragon", tgt="Highlord Bolvar Fordragon"}, [37]={npc="Crier Goodman", tgt="Crier Goodman"}, [38]={npc="Fallen Hero of the Horde", tgt="Fallen Hero of the Horde", tag="Optional"}, [39]={npc="Fallen Hero of the Horde", tgt="Fallen Hero of the Horde", tag="Optional"}, [40]={hint="Kill 7 Helboar in the Blasted Lands and return to the Fallen Hero of the Horde.", tag="Optional"}, [41]={npc="Fallen Hero of the Horde", tgt="Fallen Hero of the Horde", tag="Optional"}, [42]={npc="Fallen Hero of the Horde", tgt="Fallen Hero of the Horde", tag="Optional"}, [43]={hint="Slaughter the Shadowsworn in the Blasted Lands and return to the Fallen Hero of the Horde.", tag="Optional"}, [44]={npc="Fallen Hero of the Horde", tgt="Fallen Hero of the Horde", tag="Optional"}, [45]={npc="Fallen Hero of the Horde", tgt="Fallen Hero of the Horde", tag="Group, Optional"}, [46]={hint="Bring the Voodoo Feathers from the trolls in the Sunken Temple to the Fallen Hero of the Horde.", tag="Group, Optional"}, [47]={npc="Fallen Hero of the Horde", tgt="Fallen Hero of the Horde", tag="Group, Optional"}}},
    ["05-d26"] = {name="Lower Blackrock Spire", entrance="Burning Steppes 29.40, 38.30 (southern entrance to Blackrock Mountain).", pickup="Pick up quests at Morgan's Vigil and Flame Crest in Burning Steppes. If you're under level, pick them up before grouping. Weaponsmiths can get Snakestone of the Shadow Huntress in Everlook.", pickupS={{"Pick up quests at Morgan's Vigil and Flame Crest in Burning Steppes"}, {"If you're under level, pick them up before grouping"}, {"Weaponsmiths can get Snakestone of the Shadow Huntress in Everlook"}}, tips={{k="動線", text="Shared portal → down the right ramp → Omokk → Vosh'gajin and Bijou → Voone → Mother Smolderweb → Halycon → Wyrmthalak."}, {k="說明", text="Take Bijou's message to Maxwell first. Save the three bosses for your next run. One party member with the upper spire key is enough.", s={{"Take Bijou's message to Maxwell first"}, {"Save the three bosses for your next run"}, {"One party member with the upper spire key is enough"}}}}, steps={[1]={npc="Helendis Riverhorn", tgt="Helendis Riverhorn"}, [2]={npc="Kibler", tgt="Kibler"}, [3]={npc="Kibler", tgt="Kibler"}, [4]={npc="Ragged John", tgt="Ragged John", tag="Optional"}, [5]={npc="Kilram", tgt="Kilram", tag="Optional", desc="Take this only if you are a Weaponsmith going for Axesmithing."}, [6]={text="Prerequisite: The Lost Tablets of Mosh'aru", tag="Optional"}, [7]={npc="Prospector Ironboot", tgt="Prospector Ironboot", tag="Optional", preText="The Lost Tablets of Mosh'aru"}, [8]={text="Lower Blackrock Spire entrance"}, [9]={npc="Scarshield Infiltrator", tgt="Scarshield Infiltrator", tag="Optional", desc="Take the ramp down on the right, then climb the rubble to Vaelan's side room."}, [10]={npc="Warosh", tgt="Warosh", tag="Optional", desc="Across the first bridge from the lower entrance."}, [11]={hint="Travel to Blackrock Spire and slay Shadow Hunter Vosh'gajin. Recover Vosh'gajin's Snakestone and return to Kilram.", tag="Optional", desc="Location: Past Omokk, take the passage and find Shadow Hunter Vosh'gajin. Order: Kill Vosh'gajin first, then follow the slope in his room to find Bijou.", spot="Pass Omokk and follow the tunnel to Shadow Hunter Vosh'gajin."}, [12]={hint="Bring the Fifth and Sixth Mosh'aru Tablets to Prospector Ironboot in Tanaris.", tag="Optional", desc="Location: One near Vosh'gajin and one near Voone.", spot="One near Vosh'gajin and one near Voone."}, [13]={npc="Bijou", tgt="Bijou", desc="Follow the ramp near Vosh'gajin to Bijou."}, [14]={hint="Find Bijou's Belongings and return them to her. Good luck!", desc="Location: The passage from the lower orc area to the spiders.", spot="The passage from the lower orc area to the spiders."}, [15]={npc="Bijou", tgt="Bijou", spot="Bijou, on the ramp near Vosh'gajin"}, [16]={npc="Bijou", tgt="Bijou", preText="Bijou's Belongings"}, [17]={hint="Travel to Blackrock Spire and collect 15 Spire Spider Eggs for Kibler.", desc="Location: Near Mother Smolderweb. Watch for hatching spiders.", spot="Near Mother Smolderweb. Watch for hatching spiders."}, [18]={hint="In the heart of Blackrock Spire you will find Mother Smolderweb. Engage her and get her to poison you. Chances are good that you will have to kill her as well. Return to Ragged John when you are poisoned so that he can 'milk' you.", tag="Optional", desc="Location: Deep in the spider area.", spot="Deep in the spider area."}, [19]={hint="Travel to Blackrock Spire and find Bloodaxe Worg Pups. Use the cage to carry the ferocious little beasts. Bring back a Caged Worg Pup to Kibler.", desc="Location: In the worg area. Don't kill the pup.", spot="In the worg area. Don't kill the pup."}, [20]={hint="Travel to Blackrock Spire and destroy the source of the worg menace. As you left Helendis, he shouted a name: Halycon. It is what the orcs refer to in regards to the worg.", desc="Location: The worg area in the lower spire.", spot="The worg area in the lower spire."}, [21]={hint="Read Warosh's Scroll. Bring Warosh's Mojo to Warosh.", tag="Optional", desc="Location: The tribute pile before Wyrmthalak.", spot="The tribute pile before Wyrmthalak."}, [22]={npc="Warosh", tgt="Warosh", tag="Optional", spot="Warosh, just past the entrance bridge"}, [23]={hint="Travel to Blackrock Spire and destroy War Master Voone, Highlord Omokk, and Overlord Wyrmthalak. Return to Marshal Maxwell when the job is done.", tag="Optional", desc="Location: Kill all three lower spire bosses.", spot="Kill all three lower spire bosses."}, [24]={npc="General Drakkisath's Command", npcObj=true, tag="Optional", desc="Loot Wyrmthalak's orders and right-click them to start."}, [25]={hint="Find the three gemstones of command: The Gemstone of Smolderthorn, Gemstone of Spirestone, and Gemstone of Bloodaxe. Return them, along with the Unadorned Seal of Ascension, to Vaelan.", tag="Optional", desc="Gem and seal drop rates are limited; agree on how to distribute them with your teammates first. If you only run the upper level, one party member holding the finished item is enough. Location: Loot a gem from each of the three bosses, and look for the Unadorned Seal on the trash along the way. Order: Highlord Omokk → War Master Voone → Overlord Wyrmthalak.", spot="Loot one gem from each boss. Check trash for the Unadorned Seal."}, [26]={npc="Scarshield Infiltrator", tgt="Scarshield Infiltrator", tag="Optional"}, [27]={npc="Scarshield Infiltrator", tgt="Scarshield Infiltrator", tag="Optional", preText="Seal of Ascension"}, [28]={npc="Ragged John", tgt="Ragged John", tag="Optional", desc="Get back to John quickly while still poisoned."}, [29]={npc="Kibler", tgt="Kibler"}, [30]={npc="Kibler", tgt="Kibler"}, [31]={npc="Helendis Riverhorn", tgt="Helendis Riverhorn"}, [32]={npc="Kilram", tgt="Kilram", tag="Optional"}, [33]={npc="Prospector Ironboot", tgt="Prospector Ironboot", tag="Optional"}, [34]={npc="Marshal Maxwell", tgt="Marshal Maxwell"}, [35]={npc="Marshal Maxwell", tgt="Marshal Maxwell", tag="Optional"}, [36]={npc="Marshal Maxwell", tgt="Marshal Maxwell", tag="Optional", desc="Do this on a later run.", preText="Message to Maxwell"}, [37]={npc="Marshal Maxwell", tgt="Marshal Maxwell", tag="Optional"}, [38]={hint="Travel to the Wyrmbog in Dustwallow Marsh. Find the ancient drake, Emberstrife and beat him without mercy until his will is broken.", tag="Optional", desc="Group up for the elites. Stop attacking before you take control of the dragon, and keep your health high."}, [39]={npc="Scarshield Infiltrator", tgt="Scarshield Infiltrator", tag="Optional", desc="Find Vaelan inside the Lower Blackrock Spire entrance."}}},
    ["05-d25"] = {name="Dire Maul: North", entrance="Feralas (1444), 62.50, 24.90. North wing portal.", pickup="From Feathermoon Stronghold, head to the north wing in Feralas. Bring a Crescent Key. For tribute, bring Frost Oil, a Thorium Widget, Bolts of Runecloth, Rugged Leather and Rune Thread.", pickupS={{"From Feathermoon Stronghold, head to the north wing in Feralas"}, {"Bring a Crescent Key"}, {"For tribute, bring Frost Oil, a Thorium Widget, Bolts of Runecloth, Rugged Leather and Rune Thread"}}, tips={{k="動線", text="North gate → Fengus's courtyard → Knot and the trap → Kromcrush → King Gordok. For tribute, spare the guards and see Kreeg and Kromcrush after the king."}, {k="說明", text="Skip Unfinished Gordok Business if the tribute conditions were missed or Kromcrush is dead. Turn in class books and librams in the library.", s={{"Skip Unfinished Gordok Business if the tribute conditions were missed or Kromcrush is dead"}, {"Turn in class books and librams in the library"}}}}, steps={[1]={text="Dire Maul: North entrance"}, [2]={npc="Broken Trap", npcObj=true, tag="Optional"}, [3]={hint="Loot from: Anvilrage Marshal, Rage Talon Dragonspawn, Blackhand Iron Guard", tag="Optional", desc="Location: Past Fengus's courtyard, find the trap by Knot.", spot="Past Fengus's courtyard, find the trap by Knot."}, [4]={npc="Broken Trap", npcObj=true, tag="Optional"}, [5]={npc="Knot Thimblejack", tgt="Knot Thimblejack", tag="Optional"}, [6]={hint="Bring 4 Bolts of Runecloth, 8 Rugged Leather, 2 Rune Threads, and Ogre Tannin to Knot Thimblejack. He is currently chained inside the Gordok wing of Dire Maul.", tag="Optional", desc="Location: Loot tannin upstairs past Fengus. Find Knot by the trap.", spot="Loot tannin upstairs past Fengus. Find Knot by the trap."}, [7]={npc="Knot Thimblejack", tgt="Knot Thimblejack", tag="Optional", spot="Past Fengus, by the trap: Knot Thimblejack"}, [8]={npc="Knot Thimblejack", tgt="Knot Thimblejack", tag="Optional"}, [9]={hint="Loot from: Gordok Brute, Gordok Mage-Lord, Gordok Captain", tag="Optional", desc="Location: Past Fengus's courtyard, use the key on Knot next to the broken trap.", spot="Past Fengus's courtyard, use the key on Knot next to the broken trap."}, [10]={npc="Knot Thimblejack", tgt="Knot Thimblejack", tag="Optional", spot="Fengus' courtyard, by the broken trap: Knot Thimblejack"}, [11]={npc="Stomper Kreeg", tgt="Stomper Kreeg", tag="Optional", desc="Get King of the Gordok on the tribute run, then talk to Stomper Kreeg."}, [12]={npc="Stomper Kreeg", tgt="Stomper Kreeg", tag="Optional"}, [13]={npc="Captain Kromcrush", tgt="Captain Kromcrush", tag="Optional", desc="After a tribute run, talk to Kromcrush while he is still alive."}, [14]={npc="Captain Kromcrush", tgt="Captain Kromcrush", tag="Optional", desc="Keep Kromcrush alive on your next tribute run and turn it in to him."}, [15]={npc="Garona: A Study on Stealth and Treachery", npcObj=true, tag="Optional", desc="Loot your class book from a boss or tome and right-click it to start."}, [16]={npc="Lorekeeper Kildrath", tgt="Lorekeeper Kildrath", tag="Optional", desc="Take the side door off the north entrance courtyard to the library."}, [17]={npc="Codex of Defense", npcObj=true, tag="Optional", desc="Loot your class book from a boss or tome and right-click it to start."}, [18]={npc="Lorekeeper Kildrath", tgt="Lorekeeper Kildrath", tag="Optional", desc="Take the side door off the north entrance courtyard to the library."}, [19]={npc="The Arcanist's Cookbook", npcObj=true, tag="Optional", desc="Loot your class book from a boss or tome and right-click it to start."}, [20]={npc="Lorekeeper Kildrath", tgt="Lorekeeper Kildrath", tag="Optional", desc="Take the side door off the north entrance courtyard to the library."}, [21]={npc="The Light and How to Swing It", npcObj=true, tag="Optional", desc="Loot your class book from a boss or tome and right-click it to start."}, [22]={npc="Lorekeeper Mykos", tgt="Lorekeeper Mykos", tag="Optional", desc="Take the side door off the north entrance courtyard to the library."}, [23]={npc="Harnessing Shadows", npcObj=true, tag="Optional", desc="Loot your class book from a boss or tome and right-click it to start."}, [24]={npc="Lorekeeper Mykos", tgt="Lorekeeper Mykos", tag="Optional", desc="Take the side door off the north entrance courtyard to the library."}, [25]={npc="The Greatest Race of Hunters", npcObj=true, tag="Optional", desc="Loot your class book from a boss or tome and right-click it to start."}, [26]={npc="Lorekeeper Mykos", tgt="Lorekeeper Mykos", tag="Optional", desc="Take the side door off the north entrance courtyard to the library."}, [27]={npc="Holy Bologna: What the Light Won't Tell You", npcObj=true, tag="Optional", desc="Loot your class book from a boss or tome and right-click it to start."}, [28]={npc="Lorekeeper Javon", tgt="Lorekeeper Javon", tag="Optional", desc="Take the side door off the north entrance courtyard to the library."}, [29]={npc="Frost Shock and You", npcObj=true, tag="Optional", desc="Loot your class book from a boss or tome and right-click it to start."}, [30]={npc="Lorekeeper Javon", tgt="Lorekeeper Javon", tag="Optional", desc="Take the side door off the north entrance courtyard to the library."}, [31]={npc="The Emerald Dream", npcObj=true, tag="Optional", desc="Loot your class book from a boss or tome and right-click it to start."}, [32]={npc="Lorekeeper Javon", tgt="Lorekeeper Javon", tag="Optional", desc="Take the side door off the north entrance courtyard to the library."}, [33]={npc="Nostro's Compendium of Dragon Slaying", npcObj=true, tag="Optional", desc="Loot your class book from a boss or tome and right-click it to start."}, [34]={npc="Lorekeeper Lydros", tgt="Lorekeeper Lydros", tag="Optional", desc="Take the side door off the north entrance courtyard to the library."}, [35]={npc="Lorekeeper Lydros", tgt="Lorekeeper Lydros", tag="Optional", preText="Elven Legends"}, [36]={hint="Bring a Libram of Rapidity, 1 Pristine Black Diamond, 2 Large Brilliant Shards, and 2 Blood of Heroes to Lorekeeper Lydros in Dire Maul to receive an Arcanum of Rapidity.", tag="Optional"}, [37]={npc="Lorekeeper Lydros", tgt="Lorekeeper Lydros", tag="Optional"}, [38]={npc="Lorekeeper Lydros", tgt="Lorekeeper Lydros", tag="Optional", preText="Elven Legends"}, [39]={hint="Bring a Libram of Focus, 1 Pristine Black Diamond, 4 Large Brilliant Shards, and 2 Skin of Shadow to Lorekeeper Lydros in Dire Maul to receive an Arcanum of Focus.", tag="Optional"}, [40]={npc="Lorekeeper Lydros", tgt="Lorekeeper Lydros", tag="Optional"}, [41]={npc="Lorekeeper Lydros", tgt="Lorekeeper Lydros", tag="Optional", preText="Elven Legends"}, [42]={hint="Bring a Libram of Protection, 1 Pristine Black Diamond, 2 Large Brilliant Shards, and 1 Frayed Abomination Stitching to Lorekeeper Lydros in Dire Maul to receive an Arcanum of Protection.", tag="Optional"}, [43]={npc="Lorekeeper Lydros", tgt="Lorekeeper Lydros", tag="Optional"}}},
    ["05-d24"] = {name="Dire Maul: West", entrance="Feralas (1444), 60.30, 30.20. Portal on the west side of the courtyard.", pickup="At 54, take Elven Legends from Scholar Runethorn in Feathermoon Stronghold. West and North need the Crescent Key from Pusillin in East.", pickupS={{"At 54, take Elven Legends from Scholar Runethorn in Feathermoon Stronghold"}, {"West and North need the Crescent Key from Pusillin in East"}}, tips={{k="動線", text="West gate → Tendris Warpwood → Shen'dralar Ancient upstairs → clear five pylons → Immol'thar → Prince Tortheldrin in the library."}, {k="說明", text="Turn in class books at the library. For the north tribute quest, take it from Kromcrush before opening the prince's chest.", s={{"Turn in class books at the library"}, {"For the north tribute quest, take it from Kromcrush before opening the prince's chest"}}}}, steps={[1]={npc="Scholar Runethorn", tgt="Scholar Runethorn"}, [2]={text="Dire Maul: West entrance"}, [3]={npc="Shen'dralar Ancient", tgt="Shen'dralar Ancient", desc="Talk to the Shen'dralar Ancient on the upper level of Dire Maul West first."}, [4]={hint="You must destroy the guardians surrounding the 5 Pylons that power the Prison of Immol'thar. Once the Pylons have powered down, the force field surrounding Immol'thar will have dissipated.", desc="Clear the five crystal pylons first. Location: Clear the five pylons in the garden and upper floor, then pass the locked door and kill Immol'thar and the prince. Order: Five pylons → Immol'thar → the prince in the library.", spot="Clear five pylons, then go through the locked door to Immol'thar and the Prince."}, [5]={npc="Shen'dralar Ancient", tgt="Shen'dralar Ancient", spot="Library: Shen'dralar Ancient"}, [6]={npc="Shen'dralar Ancient", tgt="Shen'dralar Ancient", preText="The Madness Within"}, [7]={hint="Return to the Athenaeum and find the Treasure of the Shen'dralar. Claim your reward!", desc="Location: Go from Immol'thar's cage to the Library. Check under the stairs for the chest.", spot="Go from Immol'thar's cage to the Library. Check under the stairs for the chest."}, [8]={npc="Treasure of the Shen'dralar", npcObj=true, spot="Shen'dralar chest below the library stairs"}, [9]={hint="Search Dire Maul for Telmius Dreamseeker. Report back to Scholar Runethorn at Feathermoon with whatever information that you may find.", desc="Location: Follow the hall from the cage to the Library. Look for remains by the shelves.", spot="Follow the hall from the cage to the Library. Look for remains by the shelves."}, [10]={hint="Find the Gauntlet of Gordok Might and return it to Captain Kromcrush in Dire Maul.", tag="Optional", desc="Location: Behind the prince in the west wing library.", spot="Behind the prince in the west wing library."}, [11]={npc="Scholar Runethorn", tgt="Scholar Runethorn"}}},
    ["05-d23"] = {name="Dire Maul: East", entrance="Feralas 64.80, 30.20 (east-wall portal at the arena).", pickup="At 54, see Latronicus in Feathermoon Stronghold. Before entering East, stop at the Lariss Pavilion for Azj'Tordin. If you're under level, pick up the quests before grouping.", pickupS={{"At 54, see Latronicus in Feathermoon Stronghold"}, {"Before entering East, stop at the Lariss Pavilion for Azj'Tordin"}, {"If you're under level, pick up the quests before grouping"}}, tips={{k="動線", text="East gate → chase Pusillin for the key → Lethtendris → Alzzin. For the mage water quest, follow the waterway to Hydrospawn."}, {k="說明", text="East needs no key. The reliquary crosses zones, so do it if you're already on the chain. Pusillin drops the Crescent Key for West and North.", s={{"East needs no key"}, {"The reliquary crosses zones, so do it if you're already on the chain"}, {"Pusillin drops the Crescent Key for West and North"}}}}, steps={[1]={npc="Latronicus Moonspear", tgt="Latronicus Moonspear"}, [2]={npc="Azj'Tordin", tgt="Azj'Tordin"}, [3]={npc="Rabine Saturna", tgt="Rabine Saturna", tag="Optional"}, [4]={hint="Travel to Silithus and search for a Reliquary of Purity within the ruins of Southwind Village. If you are able to find it, return with it to Rabine Saturna in Nighthaven, Moonglade.", tag="Optional"}, [5]={npc="Rabine Saturna", tgt="Rabine Saturna", tag="Optional"}, [6]={npc="Rabine Saturna", tgt="Rabine Saturna", tag="Optional", preText="A Reliquary of Purity"}, [7]={npc="Lorekeeper Lydros", tgt="Lorekeeper Lydros", tag="Optional", desc="Take the side door off the north entrance courtyard to the library."}, [8]={text="Dire Maul: East entrance"}, [9]={hint="Travel to Dire Maul and locate the Imp, Pusillin. Convince Pusillin to give you Azj'Tordin's Book of Incantations through any means necessary.", desc="Talk to Pusillin from the east gate and chase him along the passage to the end. Talk to him every time he stops."}, [10]={hint="Bring Lethtendris' Web to Latronicus Moonspear at the Feathermoon Stronghold in Feralas.", desc="Location: Take the upper passage from the garden to Lethtendris's platform.", spot="Take the upper passage from the garden to Lethtendris's platform."}, [11]={hint="Find the Felvine in Dire Maul and acquire a shard from it. Chances are you'll only be able to procure one with the demise of Alzzin the Wildshaper. Use the Reliquary of Purity to securely seal the shard inside, and return it to Rabine Saturna in Nighthaven, Moonglade.", tag="Optional", desc="Location: Alzzin's room.", spot="Alzzin's room."}, [12]={hint="Travel to the Warpwood Quarter of Dire Maul and slay the water elemental, Hydrospawn. Return to Lorekeeper Lydros in the Athenaeum with the Hydrospawn Essence.", tag="Optional", desc="Location: Take the lower waterway in Dire Maul East. Kill Hydrospawn by the pool.", spot="Take the lower waterway in Dire Maul East. Kill Hydrospawn by the pool."}, [13]={npc="Latronicus Moonspear", tgt="Latronicus Moonspear"}, [14]={npc="Azj'Tordin", tgt="Azj'Tordin"}, [15]={npc="Rabine Saturna", tgt="Rabine Saturna", tag="Optional"}, [16]={npc="Lorekeeper Lydros", tgt="Lorekeeper Lydros", tag="Optional", desc="Take the side door off the north entrance courtyard to the library."}}},
    ["04-55"] = {steps={[1]={to="Aerie Peak", desc="If you've unlocked Chillwind Camp, fly straight there and skip the next step. If Aerie Peak isn't on your flight map, fly to Southshore and run east to Aerie Peak the same way as on the Hinterlands trip."}, [2]={text="From Aerie Peak, take the mountain road north into the southeast corner of the Western Plaguelands (65.30, 86.80), then follow the road west to Chillwind Camp.", tag="Flight path locked. Travel there on foot the first time."}, [3]={node="Chillwind Camp"}, [4]={npc="Commander Ashlam Valorfist", tgt="Commander Ashlam Valorfist"}, [5]={npc="Commander Ashlam Valorfist", tgt="Commander Ashlam Valorfist"}, [6]={hint="Collect 20 Minion's Scourgestones and bring them to High Priest Thel'danis in the Western Plaguelands."}, [7]={npc="High Priest Thel'danis", tgt="High Priest Thel'danis"}, [8]={npc="High Priest Thel'danis", tgt="High Priest Thel'danis"}, [9]={npc="Commander Ashlam Valorfist", tgt="Commander Ashlam Valorfist"}, [10]={npc="Commander Ashlam Valorfist", tgt="Commander Ashlam Valorfist", tag="Group, Optional", desc="Turn it in to get the Mightstone."}, [11]={hint="Bring the voodoo feathers to Ashlam Valorfist.", tag="Group, Optional", desc="Turn it in to get the Mightstone."}, [12]={npc="Commander Ashlam Valorfist", tgt="Commander Ashlam Valorfist", tag="Group, Optional", desc="Turn it in to get the Mightstone."}, [13]={npc="Commander Ashlam Valorfist", tgt="Commander Ashlam Valorfist"}, [14]={npc="Commander Ashlam Valorfist", tgt="Commander Ashlam Valorfist"}, [15]={npc="Argent Officer Pureheart", tgt="Argent Officer Pureheart"}, [16]={npc="Argent Officer Pureheart", tgt="Argent Officer Pureheart"}, [17]={npc="Argent Officer Pureheart", tgt="Argent Officer Pureheart"}, [18]={npc="Argent Officer Pureheart", tgt="Argent Officer Pureheart", desc="A letter delivery quest; turn it in near the entrance to Mount Hyjal."}, [19]={npc="Flint Shadowmore", tgt="Flint Shadowmore", tag="Optional"}, [20]={npc="Flint Shadowmore", tgt="Flint Shadowmore", tag="Optional"}, [21]={hint="Kill 10 Skeletal Flayers and 10 Slavering Ghouls in Sorrow Hill."}, [22]={npc="Commander Ashlam Valorfist", tgt="Commander Ashlam Valorfist"}, [23]={npc="Commander Ashlam Valorfist", tgt="Commander Ashlam Valorfist"}, [24]={npc="Commander Ashlam Valorfist", tgt="Commander Ashlam Valorfist"}, [25]={npc="High Priestess MacDonnell", tgt="High Priestess MacDonnell"}, [26]={npc="High Priestess MacDonnell", tgt="High Priestess MacDonnell"}, [27]={hint="Using the Beacon Torch, mark each tower in Andorhal; you will need to stand in the doorway of the tower to successfully mark it."}, [28]={hint="Go to Felstone Field in Western Plaguelands to locate and defeat the Cauldron Lord present there. It may have a key that will allow access to the cauldron. You must have the Empty Felstone Field Bottle with you to secure a sample of the poisons used inside the cauldron."}, [29]={npc="Scourge Cauldron", npcObj=true}, [30]={npc="Scourge Cauldron", npcObj=true}, [31]={npc="Janice Felstone", tgt="Janice Felstone"}, [32]={npc="Janice's Parcel", npcObj=true}, [33]={npc="Janice's Parcel", npcObj=true}, [34]={npc="Commander Ashlam Valorfist", tgt="Commander Ashlam Valorfist"}, [35]={npc="High Priestess MacDonnell", tgt="High Priestess MacDonnell"}, [36]={npc="High Priestess MacDonnell", tgt="High Priestess MacDonnell"}, [37]={hint="Go to Dalson's Tears in Western Plaguelands to locate and defeat the Cauldron Lord present there, and use its key to gain access to the cauldron. You must have the Empty Dalson's Tears Bottle with you to secure a sample of the poisons used inside the cauldron."}, [38]={npc="Scourge Cauldron", npcObj=true}, [39]={npc="Scourge Cauldron", npcObj=true}, [40]={npc="Mrs. Dalson's Diary", npcObj=true, desc="The diary in the barn next to the cauldron."}, [41]={hint="Complete the quest objectives."}, [42]={npc="Mrs. Dalson's Diary", npcObj=true}, [43]={npc="Outhouse", npcObj=true, desc="Read the journal, then find a Wandering Skeleton. Open the outhouse to spawn the farmer."}, [44]={hint="Loot from: Wandering Skeleton"}, [45]={npc="Outhouse", npcObj=true}, [46]={npc="Locked Cabinet", npcObj=true, desc="Clear around the outhouse. Open the cache and turn in right away."}, [47]={hint="Loot from: Farmer Dalson"}, [48]={npc="Locked Cabinet", npcObj=true}, [49]={npc="High Priestess MacDonnell", tgt="High Priestess MacDonnell"}, [50]={npc="High Priestess MacDonnell", tgt="High Priestess MacDonnell"}, [51]={npc="Nathaniel Dumah", tgt="Nathaniel Dumah"}, [52]={hint="Go to the Writhing Haunt in Western Plaguelands to locate and defeat the Cauldron Lord present there, and use its key to gain access to the cauldron. You must have the Empty Writhing Haunt Bottle with you to secure a sample of the poisons used inside the cauldron."}, [53]={npc="Scourge Cauldron", npcObj=true}, [54]={npc="Scourge Cauldron", npcObj=true}, [55]={npc="Mulgris Deepriver", tgt="Mulgris Deepriver"}, [56]={hint="Destroy 8 Diseased Wolves, and then return to Mulgris Deepriver at the Writhing Haunt, Western Plaguelands."}, [57]={npc="Mulgris Deepriver", tgt="Mulgris Deepriver"}, [58]={npc="Mulgris Deepriver", tgt="Mulgris Deepriver"}, [59]={hint="Destroy 8 Diseased Grizzlies, and then return to Mulgris Deepriver at the Writhing Haunt, Western Plaguelands."}, [60]={npc="Mulgris Deepriver", tgt="Mulgris Deepriver"}, [61]={npc="Mulgris Deepriver", tgt="Mulgris Deepriver"}, [62]={text="Head southeast and take the mountain path here into the Hinterlands."}, [63]={text="Set your hearth in the Aerie Peak inn (13.80, 41.60).", bind="Aerie Peak"}, [64]={npc="Cortello's Treasure", npcObj=true, tag="Optional", desc="The treasure is on the east coast of the Hinterlands, all the way across the map; use your Hearthstone to get back after turning in."}, [65]={bind="Aerie Peak"}}},
    ["04-56"] = {steps={[1]={text="From Aerie Peak, take the mountain road north into the Western Plaguelands, then head east across the Thondroril River into the Eastern Plaguelands. Tirion Fordring is in the cabin right by the entrance."}, [2]={npc="Tirion Fordring", tgt="Tirion Fordring"}, [3]={npc="Tirion Fordring", tgt="Tirion Fordring"}, [4]={npc="Tirion Fordring", tgt="Tirion Fordring"}, [5]={hint="Slay 20 Plaguehound Runts, 5 Plaguehounds and 5 Frenzied Plaguehounds. Return to Tirion Fordring when the task is complete."}, [6]={hint="Slay 30 Plaguebats and return to Tirion Fordring."}, [7]={hint="Seek out the Carrion Grubs and Devourers of the region. Slay them and harvest their meat. Return to Tirion Fordring when you have gathered 15 Slabs of Carrion Worm Meat."}, [8]={npc="Tirion Fordring", tgt="Tirion Fordring"}, [9]={npc="Tirion Fordring", tgt="Tirion Fordring"}, [10]={npc="Tirion Fordring", tgt="Tirion Fordring"}, [11]={npc="Tirion Fordring", tgt="Tirion Fordring"}, [12]={npc="Tirion Fordring", tgt="Tirion Fordring"}, [13]={npc="Tirion Fordring", tgt="Tirion Fordring"}, [14]={npc="Pamela Redpath", tgt="Pamela Redpath"}, [15]={npc="Pamela Redpath", tgt="Pamela Redpath"}, [16]={hint="Find Pamela's doll.", desc="In the ruined houses of Darrowshire, collect the head, left side and right side, then right-click to combine them."}, [17]={npc="Pamela Redpath", tgt="Pamela Redpath"}, [18]={npc="Pamela Redpath", tgt="Pamela Redpath"}, [19]={npc="Pamela Redpath", tgt="Pamela Redpath"}, [20]={npc="Duke Nicholas Zverenhoff", tgt="Duke Nicholas Zverenhoff"}, [21]={npc="Duke Nicholas Zverenhoff", tgt="Duke Nicholas Zverenhoff", tag="Optional, Group"}, [22]={npc="Betina Bigglezink", tgt="Betina Bigglezink", tag="Optional, Group"}, [23]={npc="Leonid Barthalomew the Revered", tgt="Leonid Barthalomew the Revered", tag="Optional, Group"}, [24]={npc="Smokey LaRue", tgt="Smokey LaRue", tag="Optional, Group"}, [25]={node="Light's Hope Chapel"}, [26]={npc="Carlin Redpath", tgt="Carlin Redpath"}, [27]={npc="Carlin Redpath", tgt="Carlin Redpath", tag="Optional"}, [28]={npc="Caretaker Alen", tgt="Caretaker Alen"}, [29]={hint="Free 15 Darrowshire Spirits and return to Carlin Redpath.", tag="Optional", desc="This is a dedicated detour with no other objectives nearby. Skip it if you're in a hurry."}, [30]={hint="Travel to the Undercroft - at the southernmost section of the Eastern Plaguelands - and recover Taelan's Hammer. Return to Tirion Fordring upon completion of your objective."}, [31]={hint="Bring Zaeldarr's Head to Caretaker Alen at Light's Hope Chapel."}, [32]={npc="Torn Scroll", npcObj=true}, [33]={hint="Scour the Eastern Plaguelands for clues as to the \"Blightcaller\" and the missing SI:7 agents. If you find any SI:7 Insignias, return them to Flint Shadowmore at Chillwind Camp.", tag="Optional", desc="Take one insignia from each of the three bodies. Once you have all three, check the scouting objective in your log. If it is incomplete, scout near the marked site and give the elite a wide berth."}, [34]={npc="Tirion Fordring", tgt="Tirion Fordring"}, [35]={npc="Tirion Fordring", tgt="Tirion Fordring"}, [36]={npc="Caretaker Alen", tgt="Caretaker Alen"}, [37]={npc="Carlin Redpath", tgt="Carlin Redpath", tag="Optional"}}},
    ["04-53"] = {steps={[1]={to="Southshore", desc="You'll connect through Chillwind Camp or Aerie Peak; if Southshore isn't on your flight map, fly to Stormwind as usual and take the boat to Auberdine from the harbor."}, [2]={npc="Raleigh the Devout", tgt="Raleigh the Devout", tag="Optional, When you have the items"}, [3]={to="Auberdine", from="Southshore", desc="Board the boat to Auberdine at the Southshore dock. If you fly to Stormwind instead, board at the Stormwind harbor."}, [4]={to="Everlook"}, [5]={hint="Donova Snowden in Winterspring wants you to kill 8 Winterfall Pathfinders, 8 Winterfall Den Watchers, and 8 Winterfall Totemics."}, [6]={hint="Salfa wants you to kill 8 Winterfall Shaman, 8 Winterfall Den Watchers, and 8 Winterfall Ursa. Salfa is located just outside the entrance to Timbermaw Hold in Winterspring."}, [7]={npc="Empty Firewater Flask", npcObj=true, tag="If it drops, Optional", desc="Winterfall furbolgs drop the Empty Firewater Flask; once you loot it, right-click it to accept the quest; if it hasn't dropped yet, keep killing furbolgs."}, [8]={npc="Donova Snowden", tgt="Donova Snowden"}, [9]={npc="Donova Snowden", tgt="Donova Snowden", tag="If it drops"}, [10]={npc="Donova Snowden", tgt="Donova Snowden"}, [11]={npc="Donova Snowden", tgt="Donova Snowden"}, [12]={npc="Donova Snowden", tgt="Donova Snowden", desc="Exploring Darkwhisper Gorge gets done on the way into Mount Hyjal at the next stop; turn it in before going back to Winterspring and on to Moonglade. Turn it in before going back to Winterspring and on to Moonglade."}, [13]={hint="Collect 10 Moontouched Feathers from Winterspring, then return to Erelas Ambersky in Rut'theran Village."}, [14]={npc="Salfa", tgt="Salfa"}, [15]={npc="Deadwood Cauldron", npcObj=true}, [16]={npc="Deadwood Cauldron", npcObj=true}, [17]={to="Rut'theran Village", desc="From the Deadwood Cauldron, head south to the Talonbranch Glade flight point (62.49, 24.24) and take off from there; you'll change flights at Auberdine."}, [18]={npc="Erelas Ambersky", tgt="Erelas Ambersky"}, [19]={npc="Erelas Ambersky", tgt="Erelas Ambersky"}, [20]={npc="Daryn Lightwind", tgt="Daryn Lightwind"}, [21]={to="Everlook"}, [22]={npc="Harlo Wigglesworth", tgt="Harlo Wigglesworth"}, [23]={npc="Harlo Wigglesworth", tgt="Harlo Wigglesworth", tag="Optional", desc="A talk-only quest inside town; the follow-up has you fight elite giants, so don't take it."}, [24]={npc="Witch Doctor Mau'ari", tgt="Witch Doctor Mau'ari", tag="Optional"}, [25]={npc="Umi Rumplesnicker", tgt="Umi Rumplesnicker", desc="Fight the yetis after you come back from Donova, before setting off south."}, [26]={npc="Wynd Nightchaser", tgt="Wynd Nightchaser"}, [27]={npc="Wynd Nightchaser", tgt="Wynd Nightchaser"}, [28]={npc="Jaron Stoneshaper", tgt="Jaron Stoneshaper"}, [29]={npc="Jaron Stoneshaper", tgt="Jaron Stoneshaper"}, [30]={npc="Jaron Stoneshaper", tgt="Jaron Stoneshaper"}, [31]={npc="Jaron Stoneshaper", tgt="Jaron Stoneshaper"}, [32]={hint="Use Jaron's Pick to find the four Highborne Relic Fragments. Bring them to Aurora Skycaller in Eastern Plaguelands."}, [33]={npc="Donova Snowden", tgt="Donova Snowden"}, [34]={hint="Collect 10 Thick Yeti Furs for Umi Rumplesnicker in Everlook."}, [35]={npc="Umi Rumplesnicker", tgt="Umi Rumplesnicker"}, [36]={npc="Umi Rumplesnicker", tgt="Umi Rumplesnicker", tag="Optional", desc="The horns only drop from the matriarchs and patriarchs in the cave, and the drop rate is low; do it if you want extra XP."}, [37]={hint="Collect 2 Pristine Yeti Horns for Umi Rumplesnicker in Everlook.", tag="Optional"}, [38]={npc="Umi Rumplesnicker", tgt="Umi Rumplesnicker", tag="Optional", desc="The follow-up sends you to Un'Goro and Gadgetzan; don't take it."}, [39]={npc="Damaged Crate", npcObj=true}, [40]={npc="Damaged Crate", npcObj=true}, [41]={npc="Jaron's Wagon", npcObj=true}, [42]={npc="Jaron's Wagon", npcObj=true}, [43]={hint="Pick up Jaron's Supplies from the snow, then find the wildkin that stole the amulet Jaron spoke of."}, [44]={npc="Ranshalla", tgt="Ranshalla"}, [45]={npc="Ranshalla", tgt="Ranshalla"}, [46]={hint="Protect Ranshalla while she attempts to reactivate the Altar of Elune. Report your findings to Erelas Ambersky in Rut'theran Village."}}},
    ["04-57"] = {danger={[1]="Ghansurok (level 61 elite chimaera) patrols from the tainted hibiscus to Kaylaena's workshop (about x55-62.5, y61.5-72.2); check its position when hitting bushes and when going back to the workshop.", [2]="Celastrus the Bitter (level 57 elite) wanders around the tainted hibiscus; watch for him when hitting bushes.", [3]="The bone pile summons a level 58 elite slime; don't click it a second time without a group."}, grind={[1]={note="The north part of the Felblood Scar; all of Felflick's quests are fought here."}}, supply={[1]={}}, steps={[1]={text="From Ranshalla, head south into Darkwhisper Gorge (59.82, 74.25) and follow the gorge west all the way to the end to enter Mount Hyjal. There are elite frost giants at the gorge mouth and elite demons inside; stick to the road and don't stop.", tag="Flight path locked. Travel there on foot the first time."}, [2]={hint="Follow Donova Snowden's instructions, then report back.", desc="Going through Mount Hyjal by the gorge completes it, so no extra detour is needed. It counts once the quest log shows it as complete."}, [3]={text="Enter Mount Hyjal at the southeast corner and follow the road west."}, [4]={npc="Quintus Wainworth", tgt="Quintus Wainworth"}, [5]={npc="Quintus Wainworth", tgt="Quintus Wainworth"}, [6]={npc="Loose Cog", npcObj=true, desc="A cog on the ground by the road; right-click to pick it up and start the quest."}, [7]={npc="Ketharas", tgt="Ketharas", tag="Optional", desc="Turn in only if you took this in Felwood earlier."}, [8]={npc="Ketharas", tgt="Ketharas"}, [9]={npc="Ketharas", tgt="Ketharas"}, [10]={npc="Ketharas", tgt="Ketharas"}, [11]={npc="Ketharas", tgt="Ketharas"}, [12]={npc="Ketharas", tgt="Ketharas"}, [13]={hint="Rescue 12 Hyjal Owl Eggs and bring them to Ketharas."}, [14]={hint="Collect 10 Untainted Seeds for Ketharas."}, [15]={npc="Ketharas", tgt="Ketharas"}, [16]={npc="Ketharas", tgt="Ketharas"}, [17]={npc="Ketharas", tgt="Ketharas"}, [18]={npc="Ketharas", tgt="Ketharas"}, [19]={hint="Collect 2 Hyjal Venison Cuts from untainted Hyjal Stags and 6 Scarlet Dart Tubers for the hermit's stew."}, [20]={hint="Plant the Enchanted Seeds near the Ruined Ballista, the Ruined Catapult, and the Ruined Flying Machine.", desc="The ballista, catapult and flying machine wrecks each count as one objective, and you have to plant all three. Look on the slope outside the Hermit's Cave."}, [21]={npc="Ketharas", tgt="Ketharas"}, [22]={npc="Ketharas", tgt="Ketharas"}, [23]={npc="Ketharas", tgt="Ketharas"}, [24]={hint="Bury the remains at Ketharas' shrine."}, [25]={npc="Ketharas", tgt="Ketharas"}, [26]={npc="Ketharas", tgt="Ketharas"}, [27]={node="Tainted Foothills", desc="Follow the road west; the flight point is beside the Ancients' Outpost."}, [28]={npc="Fraxinus", tgt="Fraxinus"}, [29]={npc="Hyacinth", tgt="Hyacinth"}, [30]={npc="Hyacinth", tgt="Hyacinth"}, [31]={npc="Thylaen", tgt="Thylaen", tag="Group, Optional", desc="The target is a level 57 elite; if you can't beat it solo, don't pick it up."}, [32]={hint="Collect 6 samples of Untainted Soil from around the foothills of Mount Hyjal."}, [33]={npc="Kaylaena Springwhisper", tgt="Kaylaena Springwhisper"}, [34]={npc="Kaylaena Springwhisper", tgt="Kaylaena Springwhisper"}, [35]={npc="Kaylaena Springwhisper", tgt="Kaylaena Springwhisper", desc="When you go to Everlook later, find Nami for the parts."}, [36]={hint="Destroy 15 Tainted Shrubbery for Kaylaena Springwhisper at the workshop in the Tainted Foothills.", desc="The same hibiscus bushes also drop the leaves that stop bleeding; kill them for both quests together. Turn it in at the workshop when you deliver the crate."}, [37]={hint="Collect 12 Verdant Leaves from Tainted Shrubbery in the foothills of Mount Hyjal."}, [38]={hint="Find and destroy Celastrus the Bitter, and return to Thylaen with its broken frond.", tag="Group, Optional"}, [39]={npc="Thylaen", tgt="Thylaen", tag="Group, Optional"}, [40]={npc="Hyacinth", tgt="Hyacinth"}, [41]={npc="Hyacinth", tgt="Hyacinth"}, [42]={npc="Hyacinth", tgt="Hyacinth"}, [43]={hint="Apply the poultice to Fraxinus."}, [44]={npc="Fraxinus", tgt="Fraxinus"}, [45]={npc="Fraxinus", tgt="Fraxinus", tag="Group, Optional", desc="The target, Sunderbark, is a level 56 elite ancient; do it when you have a group; without a group, skip it and the later turn-in is skipped automatically."}, [46]={npc="Fraxinus", tgt="Fraxinus"}, [47]={npc="Curious Crow", tgt="Curious Crow"}, [48]={npc="Curious Crow", tgt="Curious Crow"}, [49]={npc="Curious Crow", tgt="Curious Crow"}, [50]={npc="Felflick", tgt="Felflick"}, [51]={npc="Felflick", tgt="Felflick"}, [52]={hint="Slay 12 Ashen Acolytes.", desc="The notes drop from the same acolytes, so fight them for both quests."}, [53]={hint="Find 12 Fel Ash Experimentation Notes."}, [54]={npc="Felflick", tgt="Felflick"}, [55]={npc="Felflick", tgt="Felflick"}, [56]={hint="Gather 8 Fel-Slime Crystals and 1 Pristine Fel-Slime Crystal."}, [57]={npc="Curious Crow", tgt="Curious Crow"}, [58]={npc="Curious Crow", tgt="Curious Crow"}, [59]={npc="Curious Crow", tgt="Curious Crow"}, [60]={hint="Gather 8 Fel-Slime Ooze."}, [61]={hint="Collect 10 Prickly Pinecones under healthy trees."}, [62]={npc="Curious Crow", tgt="Curious Crow"}, [63]={npc="Curious Crow", tgt="Curious Crow"}, [64]={npc="Felflick", tgt="Felflick"}, [65]={npc="Felflick", tgt="Felflick"}, [66]={npc="Felflick", tgt="Felflick"}, [67]={hint="Retrieve the bones of Frezzlie Popwhiz, Tyaeha Darkoath and Dazka Shadowsleep."}, [68]={hint="Slay Brashann Grimdark and search his body for his soulstone."}, [69]={npc="Felflick", tgt="Felflick"}, [70]={npc="Felflick", tgt="Felflick"}, [71]={npc="Felflick", tgt="Felflick"}, [72]={npc="Bone Pile", npcObj=true, desc="Throw the warlock bones onto the bone pile beside the slime pool."}, [73]={npc="Bone Pile", npcObj=true, tag="Group, Optional", desc="It summons a level 58 elite slime; without a group, skip Amalgamated Marrow and its follow-up quests."}, [74]={hint="Slay the Awakened Fel Ash Slime.", tag="Group, Optional"}, [75]={npc="Velician", tgt="Velician"}, [76]={npc="Felflick", tgt="Felflick", tag="Group, Optional"}, [77]={npc="Felflick", tgt="Felflick"}, [78]={npc="Curious Crow", tgt="Curious Crow"}, [79]={npc="Curious Crow", tgt="Curious Crow"}, [80]={npc="Curious Crow", tgt="Curious Crow"}, [81]={npc="Curious Crow", tgt="Curious Crow"}, [82]={hint="Use the pinecones to destroy the Ashen Reign workstations."}, [83]={npc="Curious Crow", tgt="Curious Crow"}, [84]={npc="Curious Crow", tgt="Curious Crow", desc="Turn it in at Elderwild to the west at the next stop."}, [85]={hint="Hunt down and destroy the corrupted ancient Sunderbark, then plant a seed in his remains.", tag="Group, Optional", desc="On the way back east to the Hermit's Cave."}, [86]={npc="Ketharas", tgt="Ketharas"}, [87]={npc="Ketharas", tgt="Ketharas"}, [88]={npc="Fraxinus", tgt="Fraxinus", tag="Group, Optional"}, [89]={to="Everlook"}, [90]={npc="Nami", tgt="Nami", desc="The follow-up crate is time-limited, so pick it up after you're back from Moonglade."}, [91]={npc="Jaron Stoneshaper", tgt="Jaron Stoneshaper", desc="From Everlook follow the road west a short way to Starfall Village."}, [92]={text="From Starfall Village ride southwest along the road to the hot spring and find Donova."}, [93]={npc="Donova Snowden", tgt="Donova Snowden"}, [94]={to="Moonglade", desc="Ride back from the hot spring to the Everlook flight point and fly (the Moonglade flight path was unlocked at {s:04-49}). If your Timbermaw reputation is already neutral, ride north from the hot spring to the Timbermaw Hold entrance (27.70, 34.50); going through the cave to the Moonglade exit is closer; if you haven't unlocked the Moonglade flight path, take this route too, and unlock the flight path first when you arrive (48.10, 67.34); below neutral you'll be attacked. Druids can use Teleport: Moonglade directly; after arriving, go to the regular flight point (48.10, 67.34) and unlock it so you can fly back. If you haven't unlocked the Moonglade flight path, take this route too, and unlock the flight path first when you arrive (48.10, 67.34). Below neutral reputation you'll be attacked. Druids can use Teleport: Moonglade directly; after arriving, go to the regular flight point (48.10, 67.34) and unlock it so you can fly back."}, [95]={npc="Dendrite Starblaze", tgt="Dendrite Starblaze"}, [96]={npc="Dendrite Starblaze", tgt="Dendrite Starblaze"}, [97]={npc="Orokai", tgt="Orokai"}, [98]={npc="Orokai", tgt="Orokai"}, [99]={hint="Speak with Orokai when you are ready to see what he learned from the Faintly Glowing Branch."}, [100]={npc="Dendrite Starblaze", tgt="Dendrite Starblaze"}, [101]={npc="Dendrite Starblaze", tgt="Dendrite Starblaze"}, [102]={to="Everlook", desc="Take off from the regular Moonglade flight point (48.10, 67.34) and get off at Everlook to pick up the crate."}, [103]={npc="Nami", tgt="Nami", desc="The batteries in the crate fail after about two hours, so deliver it straight to Kaylaena from the flight point."}, [104]={to="Tainted Foothills", desc="From the flight point ride straight north to Kaylaena's workshop and deliver the crate first."}}},
    ["04-58"] = {danger={[1]="Ghansurok (level 61 elite chimaera) patrols east of the Shrine of Aviana; watch for him when fighting harpies."}, supply={[1]={}, [2]={}}, steps={[1]={hint="Gently transport the crate of parts and baubles to Kaylaena Springwhisper in Mount Hyjal.", desc="Bring the crate to Kaylaena at the workshop and follow her quest dialogue."}, [2]={npc="Kaylaena Springwhisper", tgt="Kaylaena Springwhisper", desc="From the flight point ride straight north to the workshop and deliver the crate first."}, [3]={npc="Kaylaena Springwhisper", tgt="Kaylaena Springwhisper"}, [4]={npc="Kaylaena Springwhisper", tgt="Kaylaena Springwhisper", desc="The materials are in the Horde camp wreckage at Dae'gun to the north; pick them up when you pass later."}, [5]={npc="Ketharas", tgt="Ketharas", desc="Ride southeast from the workshop back to the Hermit's Cave."}, [6]={npc="Ketharas", tgt="Ketharas"}, [7]={npc="Ketharas", tgt="Ketharas"}, [8]={npc="Skylord Omnuron", tgt="Skylord Omnuron", desc="Ride northwest from the Hermit's Cave to the Shrine of Aviana."}, [9]={npc="Skylord Omnuron", tgt="Skylord Omnuron"}, [10]={npc="Skylord Omnuron", tgt="Skylord Omnuron"}, [11]={npc="Phoebe Highfeather", tgt="Phoebe Highfeather"}, [12]={npc="Phoebe Highfeather", tgt="Phoebe Highfeather"}, [13]={hint="Slay 18 Wormwing harpies on Mount Hyjal and bring their feathers to Phoebe Highfeather."}, [14]={hint="Collect 8 Tarnished Highfeather Bangles from Wormwing Harpy nests."}, [15]={hint="Find the Jewel of the Horizon in the Wormwing harpy nests on Mount Hyjal and bring it to Ketharas."}, [16]={hint="Slay Zarrat Wormwing and return Omnuron's Spear."}, [17]={npc="Corrupted Growth", npcObj=true, desc="Right-click the corrupted growth on the tree to pick up the quest."}, [18]={hint="Find and remove 6 Corrupted Knots from the trees nearby."}, [19]={npc="Phoebe Highfeather", tgt="Phoebe Highfeather"}, [20]={npc="Phoebe Highfeather", tgt="Phoebe Highfeather"}, [21]={npc="Phoebe Highfeather", tgt="Phoebe Highfeather"}, [22]={npc="Skylord Omnuron", tgt="Skylord Omnuron"}, [23]={npc="Curious Crow", tgt="Curious Crow"}, [24]={npc="Curious Crow", tgt="Curious Crow", desc="You can only do it on the bridge at the Cradle of Tranquility to the north, so carry it with you for now."}, [25]={npc="Fenwick Togglespring", tgt="Fenwick Togglespring", desc="Follow the foothills west."}, [26]={hint="Locate a sturdy branch capable of reaching Fenwick Togglespring."}, [27]={npc="Fenwick Togglespring", tgt="Fenwick Togglespring"}, [28]={npc="Fenwick Togglespring", tgt="Fenwick Togglespring"}, [29]={hint="Break the tree branch to free Fenwick Togglespring."}, [30]={npc="Fenwick Togglespring", tgt="Fenwick Togglespring"}, [31]={npc="Fenwick Togglespring", tgt="Fenwick Togglespring"}, [32]={npc="Personal Survival Pack", tgt="Personal Survival Pack"}, [33]={npc="Personal Survival Pack", tgt="Personal Survival Pack"}, [34]={hint="Wait until you can safely open the Personal Survival Pack."}, [35]={npc="Personal Survival Pack", tgt="Personal Survival Pack"}, [36]={npc="Brerufa", tgt="Brerufa"}, [37]={hint="Defeat 9 Deadwood Den Guardians and return to Brerufa."}, [38]={npc="Brerufa", tgt="Brerufa"}, [39]={npc="Brerufa", tgt="Brerufa", tag="Optional, If offered", desc="Pick it up only if you can see the quest. Only turn it in if you already have 8 strings of beads; no need to farm more."}, [40]={npc="Brerufa", tgt="Brerufa"}, [41]={npc="Osi Mistpaw", tgt="Osi Mistpaw"}, [42]={npc="Osi Mistpaw", tgt="Osi Mistpaw"}, [43]={hint="Gather 30 Bear Berries from Hyjal and return to Osi Mistpaw."}, [44]={npc="Osi Mistpaw", tgt="Osi Mistpaw"}, [45]={npc="Osi Mistpaw", tgt="Osi Mistpaw"}, [46]={hint="Find and speak with Elder Mistpaw and Elder Pinespeaker within Barkskin Burrow."}, [47]={npc="Elder Mistpaw", tgt="Elder Mistpaw"}, [48]={npc="Elder Mistpaw", tgt="Elder Mistpaw"}, [49]={npc="Elder Pinespeaker", tgt="Elder Pinespeaker"}, [50]={npc="Suma Mossmane", tgt="Suma Mossmane"}, [51]={npc="Fennar Mossmane", tgt="Fennar Mossmane", tag="Optional, If offered", desc="Pick it up only if you can see the quest (requires Barkskin cave reputation)."}, [52]={npc="Fennar Mossmane", tgt="Fennar Mossmane", tag="Optional, If offered", desc="Pick it up only if you can see the quest (requires Barkskin cave reputation). Fill the waterskin at the pond outside the Deadwood den."}, [53]={hint="Collect 10 Dried Hanging Herbs from around Barkskin Burrow and return them to Fennar Mossmane.", tag="Optional"}, [54]={npc="Elder Mistpaw", tgt="Elder Mistpaw", tag="Optional, If offered", desc="Pick it up only if you can see the quest. You can only turn it in once your Barkskin cave reputation reaches neutral."}, [55]={hint="Bring 5 owl bodies to Elder Pinespeaker in Barkskin Burrow in Hyjal."}, [56]={hint="Gather 12 clumps of Moonveil Moss and return to Suma Mossmane."}, [57]={hint="Defeat 8 Deadwood Totemics and 8 Deadwood Fel-Tenders and return to Elder Pinespeaker."}, [58]={hint="Fill a waterskin provided by Fennar Mossmane at the pond outside of the Deadwood Furbolg den.", tag="Optional", desc="Look for the pond outside the Deadwood den."}, [59]={npc="Barkskin Matriarch", tgt="Barkskin Matriarch"}, [60]={hint="Recover a Deadwood Key from a Deadwood Warden and return to the Barkskin Cage."}, [61]={npc="Barkskin Matriarch", tgt="Barkskin Matriarch"}, [62]={npc="Barkskin Matriarch", tgt="Barkskin Matriarch"}, [63]={hint="Escort the Barkskin Matriarch out of Deadwood Den and return to Barkskin Burrow.", desc="An escort quest; when grouped, wait until everyone has accepted it before starting."}, [64]={npc="Brerufa", tgt="Brerufa"}, [65]={npc="Brerufa", tgt="Brerufa", tag="Optional", desc="Only turn it in if you have 8 strings of beads."}, [66]={npc="Suma Mossmane", tgt="Suma Mossmane"}, [67]={npc="Fennar Mossmane", tgt="Fennar Mossmane", tag="Optional"}, [68]={npc="Fennar Mossmane", tgt="Fennar Mossmane", tag="Optional"}, [69]={npc="Elder Mistpaw", tgt="Elder Mistpaw", tag="Optional", desc="Only turn it in once your reputation has reached neutral."}, [70]={npc="Elder Pinespeaker", tgt="Elder Pinespeaker"}, [71]={npc="Elder Pinespeaker", tgt="Elder Pinespeaker"}, [72]={npc="Elder Pinespeaker", tgt="Elder Pinespeaker", tag="Optional, If offered", desc="Pick it up only if you can see the quest. You can only turn it in once your Barkskin cave reputation reaches friendly."}, [73]={npc="Elder Pinespeaker", tgt="Elder Pinespeaker", tag="Optional", desc="Only turn it in once your reputation has reached friendly. If you don't have enough, keep it for now."}, [74]={npc="Eluneth", tgt="Eluneth", desc="Head north."}, [75]={npc="Veteran of the Third War", tgt="Veteran of the Third War"}, [76]={npc="Sefira Everbright", tgt="Sefira Everbright"}, [77]={npc="Sefira Everbright", tgt="Sefira Everbright"}, [78]={npc="Sefira Everbright", tgt="Sefira Everbright"}, [79]={npc="Mirt", tgt="Mirt"}, [80]={npc="Hnaz Blunderflame", tgt="Hnaz Blunderflame", desc="Beside the Elderwild inn; the owl nests are in the valley to the south, to collect on the way when you return to Eluneth later."}, [81]={hint="Capture and return 6 Escaped Sheep."}, [82]={npc="Mirt", tgt="Mirt"}, [83]={npc="Embroidered Scabbard", npcObj=true, desc="The overlook west of Elderwild."}, [84]={npc="Embroidered Scabbard", npcObj=true}, [85]={hint="Use the Embroidered Scabbard to speak with the war veteran and hear his story at the overlook in Elderwild."}, [86]={npc="Veteran of the Third War", tgt="Veteran of the Third War"}, [87]={npc="Unmarked Grave", npcObj=true, desc="By the roadside heading east, right-click the unmarked grave to pick up the quest."}, [88]={npc="Galvinquam Leafsyre", tgt="Galvinquam Leafsyre"}, [89]={hint="Fill Galvinquam Leafsyre's drinking gourd at the waterfall ahead.", desc="Fill water with the empty gourd the quest gives you at the waterfall ahead, not beside Galvinquam."}, [90]={npc="Galvinquam Leafsyre", tgt="Galvinquam Leafsyre"}, [91]={npc="Galvinquam Leafsyre", tgt="Galvinquam Leafsyre", desc="Take the baggage to the Summit of Eternity."}, [92]={npc="Lisbael Highfeather", tgt="Lisbael Highfeather", desc="Turn it in at the Shrine of Aviana afterward."}, [93]={hint="Touch the Crow Effigy on the bridge overlooking the Cradle of Tranquility to call the Wild God, Jereman."}, [94]={npc="Jereman", tgt="Jereman"}, [95]={npc="Jereman", tgt="Jereman"}, [96]={npc="Jereman", tgt="Jereman"}, [97]={npc="Jereman", tgt="Jereman"}, [98]={npc="Johun Punchy Dillas", tgt="Johun Punchy Dillas"}, [99]={hint="Make skunks leave the area around Johun's equipment without killing them."}, [100]={npc="Johun Punchy Dillas", tgt="Johun Punchy Dillas"}, [101]={npc="Johun Punchy Dillas", tgt="Johun Punchy Dillas"}, [102]={hint="Return 9 Rustleaf Fox Tails to Johun \"Punchy\" Dillas in Hyjal."}, [103]={npc="Johun Punchy Dillas", tgt="Johun Punchy Dillas"}, [104]={npc="Johun Punchy Dillas", tgt="Johun Punchy Dillas"}, [105]={npc="Kala'th", tgt="Kala'th", desc="Head west."}, [106]={npc="Kala'th", tgt="Kala'th"}, [107]={hint="Dissuade stags from acting as predators."}, [108]={hint="Look through the burned buildings in the Cradle of Tranquility for 6 Metal Brackets and 30 Nails and return to Johun \"Punchy\" Dillas in Hyjal."}, [109]={npc="Kala'th", tgt="Kala'th"}, [110]={npc="Marrosis", tgt="Marrosis"}, [111]={npc="Marrosis", tgt="Marrosis"}, [112]={npc="Marrosis", tgt="Marrosis"}, [113]={hint="Eliminate 3 Forgotten Soldiers and 12 Fleshflay Raveners."}, [114]={hint="Search the area for the grave's missing contents."}, [115]={hint="Acquire a Drop of Stolen Life from the Scourge in the ruins on Mount Hyjal, then return to Ketharas."}, [116]={hint="Use the Survivor's Torch on the Bone Pile, then collect the Reanimator's Amulet."}, [117]={hint="Collect 20 Sun-Bleached Bones."}, [118]={hint="Retrieve 8 Watcher's Eyes for Eluneth."}, [119]={npc="Marrosis", tgt="Marrosis"}, [120]={npc="Eluneth", tgt="Eluneth"}, [121]={hint="Head south into the valley and collect owl feathers from their nests.", desc="A short way south of Eluneth; killing Hyjal owls drops them too. Return to Elderwild after collecting them."}, [122]={npc="Hnaz Blunderflame", tgt="Hnaz Blunderflame"}, [123]={npc="Sefira Everbright", tgt="Sefira Everbright"}, [124]={npc="Sefira Everbright", tgt="Sefira Everbright"}, [125]={npc="Sefira Everbright", tgt="Sefira Everbright"}, [126]={npc="Sefira Everbright", tgt="Sefira Everbright"}, [127]={npc="Sefira Everbright", tgt="Sefira Everbright"}, [128]={npc="Daythor Brellan", tgt="Daythor Brellan"}, [129]={npc="Daythor Brellan", tgt="Daythor Brellan"}, [130]={npc="Sefira Everbright", tgt="Sefira Everbright"}, [131]={npc="Sefira Everbright", tgt="Sefira Everbright"}, [132]={npc="Daythor Brellan", tgt="Daythor Brellan"}}},
    ["04-60"] = {danger={[1]="Ghansurok (level 61 elite chimaera) wanders along the ridge south of Kaylaena's workshop.", [2]="Mazzogore (level 60 elite) patrols south of Dae'gun; go around him when fighting hounds.", [3]="Ve'han Talongrasp (level 60 elite) guards Nordrassil Lodge; don't get too close during the cultist quests."}, grind={[1]={mob="Felguard Sentry", note="The southern half of Dae'gun; pick up the abandoned supplies and Horde wreckage materials along the way."}, [2]={note="The cultist camp east of the Summit of Eternity; the summit quests are all fought here."}}, supply={[1]={}, [2]={}, [3]={}}, steps={[1]={npc="Johun Punchy Dillas", tgt="Johun Punchy Dillas", desc="Head back east along the road."}, [2]={npc="Johun Punchy Dillas", tgt="Johun Punchy Dillas"}, [3]={npc="Elaena Moonwhisper", tgt="Elaena Moonwhisper"}, [4]={npc="Witherbeard", tgt="Witherbeard"}, [5]={npc="Yashiro", tgt="Yashiro"}, [6]={hint="Light the two bonfires in Dae'gun and return to Yashiro."}, [7]={text="After lighting the campfire to the southeast, keep going southeast to Renalard; first turn in Clever Creature, pick up the ashes and the fox quest, then clear Dae'gun once more on the way back."}, [8]={npc="Renalard", tgt="Renalard"}, [9]={npc="Renalard", tgt="Renalard"}, [10]={npc="Renalard", tgt="Renalard"}, [11]={hint="Collect 8 Abandoned Supplies.", desc="Use the Tuft of Fox Fur you got from the quest to lure the demon away, then pick up 8 abandoned supplies. The supplies aren't beside Renalard."}, [12]={hint="Scavenge the remains of the Horde base and return 5 Frayed Wire, 5 Scrap Metal, and 5 Calcified Excrement to Kaylaena."}, [13]={hint="Retrieve 6 Ephemeral Essences for Elaena Moonwhisper."}, [14]={hint="Slay 12 Felguard Sentinels in Dae'gun."}, [15]={hint="Fetch a pinch of Azgalor's Ashes from the ruins of Dae'gun on Mount Hyjal."}, [16]={hint="Enter Dae'gun and locate a high vantage point, then report details to Johun."}, [17]={npc="Yashiro", tgt="Yashiro", desc="After clearing Dae'gun, come back here to Yashiro to turn in."}, [18]={npc="Yashiro", tgt="Yashiro", tag="Optional"}, [19]={hint="Fight your way through Dae'gun with Yashiro.", tag="Group, Optional", desc="Follow Yashiro as he clears the path; it's complete once you defeat Doomguard Xarkul at the end."}, [20]={npc="Yashiro", tgt="Yashiro", tag="Optional", desc="Turn it in to Yashiro where the event ends, which isn't necessarily back at the start."}, [21]={npc="Elaena Moonwhisper", tgt="Elaena Moonwhisper"}, [22]={npc="Elaena Moonwhisper", tgt="Elaena Moonwhisper", tag="Group, Optional", desc="Both targets are level 60 elite demons; without a group, skip it and the follow-ups are skipped automatically."}, [23]={hint="Use the Eye of Endless Influence on Bethra'zel and Mazzogore to siphon their power, then deliver the killing blow.", tag="Group, Optional"}, [24]={npc="Elaena Moonwhisper", tgt="Elaena Moonwhisper", tag="Group, Optional"}, [25]={npc="Elaena Moonwhisper", tgt="Elaena Moonwhisper"}, [26]={npc="Witherbeard", tgt="Witherbeard"}, [27]={npc="Johun Punchy Dillas", tgt="Johun Punchy Dillas"}, [28]={npc="Renalard", tgt="Renalard", desc="Head southeast."}, [29]={node="Summit of Eternity", desc="From Renalard go a short way up the mountain to the east and learn Fayran Elthas's flight path. Turn in the few quests you brought up the mountain first to lighten your quest log."}, [30]={npc="Marn Euhorn", tgt="Marn Euhorn"}, [31]={npc="Tiala Whitemane", tgt="Tiala Whitemane", tag="Optional", desc="Turn in only if you took this in Un'Goro Crater earlier."}, [32]={npc="Thisalee Crow", tgt="Thisalee Crow"}, [33]={npc="Sebelia", tgt="Sebelia", desc="Turn in the letter package in Everlook shortly, then do the mail chain."}, [34]={npc="Kaylaena Springwhisper", tgt="Kaylaena Springwhisper", desc="From the Summit of Eternity go down the mountain west past Renalard, then south to the workshop. If the mountain path is blocked, fly to the Tainted Foothills and ride north."}, [35]={npc="Kaylaena Springwhisper", tgt="Kaylaena Springwhisper"}, [36]={hint="Turn the two gears and connect the two battery terminals on both sides of Kaylaena's Glaive Thrower."}, [37]={npc="Kaylaena Springwhisper", tgt="Kaylaena Springwhisper"}, [38]={npc="Kaylaena Springwhisper", tgt="Kaylaena Springwhisper", tag="Group, Optional", desc="The Ghansurok you lure is a level 61 elite chimaera."}, [39]={hint="Walk to the ridge south of Kaylaena's workshop and find a way to make a loud distracting commotion to draw the chimaera Ghansurok in range to be attacked.", tag="Group, Optional", desc="Interact with the drum on the cliff south of the workshop and lure the chimaera into range of the blade-wheel thrower so the NPC operates it; don't pull it far away to fight it by force."}, [40]={npc="Kaylaena Springwhisper", tgt="Kaylaena Springwhisper", tag="Group, Optional"}, [41]={npc="Phoebe Highfeather", tgt="Phoebe Highfeather", desc="From the workshop, walk a short way southwest to the Shrine of Aviana."}, [42]={npc="Ketharas", tgt="Ketharas", desc="Ride southeast from the shrine back to the Hermit's Cave."}, [43]={npc="Ketharas", tgt="Ketharas"}, [44]={npc="Ketharas", tgt="Ketharas"}, [45]={npc="Ketharas", tgt="Ketharas"}, [46]={to="Everlook", desc="Ride west from the Hermit's Cave and take off from the Tainted Foothills flight point."}, [47]={npc="Innkeeper Vizzie", tgt="Innkeeper Vizzie"}, [48]={npc="Innkeeper Vizzie", tgt="Innkeeper Vizzie"}, [49]={hint="Find 4 pieces of Missing Mail in the hills north of Everlook and bring it back to Innkeeper Vizzie.", desc="The mail is scattered over the hills outside Everlook; follow the hints in the quest log to find it; if you can't find it, skip it for now."}, [50]={npc="Innkeeper Vizzie", tgt="Innkeeper Vizzie"}, [51]={npc="Innkeeper Vizzie", tgt="Innkeeper Vizzie", desc="Take the mail back to the top of Mount Hyjal to turn it in."}, [52]={to="Summit of Eternity", desc="You'll connect through the Tainted Foothills."}, [53]={npc="Sebelia", tgt="Sebelia"}, [54]={npc="Marn Euhorn", tgt="Marn Euhorn"}, [55]={npc="Toron Rockhoof", tgt="Toron Rockhoof"}, [56]={npc="Tiala Whitemane", tgt="Tiala Whitemane"}, [57]={npc="Tiala Whitemane", tgt="Tiala Whitemane"}, [58]={npc="Tiala Whitemane", tgt="Tiala Whitemane"}, [59]={npc="Thisalee Crow", tgt="Thisalee Crow"}, [60]={npc="Thisalee Crow", tgt="Thisalee Crow"}, [61]={hint="Find thorn seeds in the forests at the summit of Mount Hyjal and bring them back to Tiala Whitemane."}, [62]={hint="Use the Staff of the Mountain on 10 members of the Blackthorne Pact on the Summit of Eternity to remove their wards and then kill them.", desc="The same cultists also count for End the Frenzy and Twisted Tools; use the staff first and then kill them, and do all three together."}, [63]={hint="Kill 10 Blackthorne Adepts and 10 Wild-branded Cultists."}, [64]={hint="Recover a Wicked Ritualist's Kris and a Recoiling Gnarlybark Staff from Blackthorne cultists."}, [65]={hint="Collect 5 Grand Hippogryph Feathers and 3 Oily Chimaera Hair for Marn."}, [66]={npc="Tiala Whitemane", tgt="Tiala Whitemane"}, [67]={npc="Tiala Whitemane", tgt="Tiala Whitemane"}, [68]={npc="Tiala Whitemane", tgt="Tiala Whitemane"}, [69]={npc="Tiala Whitemane", tgt="Tiala Whitemane"}, [70]={hint="Plant thorn seeds near the inn, the storage tower, and the grouping of trees at the loyalist druid camp."}, [71]={npc="Tiala Whitemane", tgt="Tiala Whitemane"}, [72]={npc="Thisalee Crow", tgt="Thisalee Crow"}, [73]={npc="Thisalee Crow", tgt="Thisalee Crow", desc="After accepting it, first go to Marn to turn in Winds of Purification and pick up Archimonde's Pardon; do the two on the same trip."}, [74]={npc="Marn Euhorn", tgt="Marn Euhorn"}, [75]={npc="Marn Euhorn", tgt="Marn Euhorn"}, [76]={hint="Reactivate the sentinel stones north, west, and south around the Blackthorne cultists.", desc="The north, west and south stones each count as one objective, and you have to visit all three."}, [77]={hint="Use the Enchanted Branch to release 5 wisps around Nordrassil.", desc="Free the wisp that's already beneath the roots, rather than summoning it with an item in the clearing. Do it on the same trip as Archimonde's Pardon."}, [78]={hint="Take Marn's incense and allow the smoke to ward the air around Archimonde's remains."}, [79]={npc="Thisalee Crow", tgt="Thisalee Crow"}, [80]={npc="Tiala Whitemane", tgt="Tiala Whitemane"}, [81]={npc="Marn Euhorn", tgt="Marn Euhorn"}, [82]={npc="Toron Rockhoof", tgt="Toron Rockhoof"}, [83]={to="Rut'theran Village", desc="You'll connect through the Tainted Foothills and Everlook."}, [84]={npc="Erelas Ambersky", tgt="Erelas Ambersky"}, [85]={npc="Erelas Ambersky", tgt="Erelas Ambersky"}, [86]={text="Step into the portal in Rut'theran Village to Darnassus."}, [87]={npc="Arch Druid Fandral Staghelm", tgt="Arch Druid Fandral Staghelm"}, [88]={npc="Mathrengyl Bearwalker", tgt="Mathrengyl Bearwalker"}}},
    ["05-d30"] = {name="Blackmaw Hold", entrance="Azshara 38.70, 33.40 (tunnel mouth). Follow the tunnel to the portal.", pickup="Take Beneath Nordrassil on your first pass through Talrendis Point. Turn it in on your next visit to Darnassus and take the follow-up. From Talrendis, head northeast to the Azshara tunnel. Visit Archmage Timear only if you're already headed from Southshore to Dalaran.", pickupS={{"Take Beneath Nordrassil on your first pass through Talrendis Point"}, {"Turn it in on your next visit to Darnassus and take the follow-up"}, {"From Talrendis, head northeast to the Azshara tunnel"}, {"Visit Archmage Timear only if you're already headed from Southshore to Dalaran"}}, tips={{k="動線", text="Tunnel → gather root caps, pouches and totems below → take the two branches for Withermaw and Bonesnout → elder shaman → Varrox."}, {k="說明", text="The Twin Bears and the final boss quest require Neutral with Timbermaw Hold. Start with Ekkal's Legashi Threat, then see Rageroar, Korsa and Gorn One Eye. Defeat Prince Halanox outdoors and turn in the quest to unlock the dungeon follow-up. Loot Fel-Tainted Flesh for a seed pod: turn it in to the Flesh-Eating Lasher past the elder shaman.", s={{"The Twin Bears and the final boss quest require Neutral with Timbermaw Hold"}, {"Start with Ekkal's Legashi Threat, then see Rageroar, Korsa and Gorn One Eye"}, {"Defeat Prince Halanox outdoors and turn in the quest to unlock the dungeon follow-up"}, {"Loot Fel-Tainted Flesh for a seed pod: turn it in to the Flesh-Eating Lasher past the elder shaman"}}}}, steps={[1]={npc="Commander Truesong", tgt="Commander Truesong"}, [2]={npc="Mathrengyl Bearwalker", tgt="Mathrengyl Bearwalker"}, [3]={npc="Mathrengyl Bearwalker", tgt="Mathrengyl Bearwalker", preText="Beneath Nordrassil"}, [4]={npc="Archmage Timear", tgt="Archmage Timear", tag="Optional"}, [5]={npc="Ogtinc", tgt="Ogtinc"}, [6]={npc="Ekkal", tgt="Ekkal"}, [7]={npc="Lorekeeper Nok", tgt="Lorekeeper Nok", tag="Optional", desc="Requires Neutral with Timbermaw Hold."}, [8]={npc="Gatekeeper Rageroar", tgt="Gatekeeper Rageroar", tag="Optional", desc="Take this if you're already doing the Timbermaw quest chain.", preText="Blackmaw Counter-Offensive"}, [9]={text="Blackmaw Hold entrance"}, [10]={hint="Gather 10 Nordrassil Root Caps inside Blackmaw Hold for Mathrengyl Bearwalker in Darnassus.", desc="Location: The outer grove and tunnel.", spot="The outer grove and tunnel."}, [11]={hint="Enter Blackmaw Hold and recover 5 Blackmaw Pouches for Ekkal at the Ruins of Eldarath in Azshara.", desc="Location: Furbolg camps along the route.", spot="Furbolg camps along the route."}, [12]={hint="Find the Totem of Ursoc and the Totem of Ursol inside Blackmaw Hold. Then, return them to Lorekeeper Nok at Ursolan.", tag="Optional", desc="Location: Look for the totems down the two branches after entering.", spot="Look for the totems down the two branches after entering."}, [13]={hint="Bring the Claws of the Great Bear and the Tusks of the Unbroken to Ogtinc, in Azshara.", desc="Location: One in each branch.", spot="One in each branch."}, [14]={hint="Recover a Blackmaw Ritual Totem from Blackmaw Hold.", tag="Optional", desc="Location: The elder shaman in the furbolg area.", spot="The elder shaman in the furbolg area."}, [15]={npc="Feathered Charm Necklace", npcObj=true, tag="Optional", desc="Right-click the necklace after looting it."}, [16]={hint="Bring Varrox Bleakhoof's Head to Gatekeeper Rageroar at Ursolan.", tag="Optional", desc="Location: The final boss platform.", spot="The final boss platform."}, [17]={npc="Ogtinc", tgt="Ogtinc"}, [18]={npc="Ekkal", tgt="Ekkal"}, [19]={npc="Lorekeeper Nok", tgt="Lorekeeper Nok", tag="Optional"}, [20]={npc="Gatekeeper Rageroar", tag="Optional"}, [21]={npc="Unele", tgt="Unele", tag="Optional"}, [22]={npc="Mathrengyl Bearwalker", tgt="Mathrengyl Bearwalker"}, [23]={npc="Archmage Timear", tgt="Archmage Timear", tag="Optional"}}},
    ["04-59"] = {name="Western Plaguelands", steps={[1]={bind="Aerie Peak", desc="Only use your hearthstone if you're still bound to Aerie Peak and it's off cooldown. Otherwise take the boat backup: use the portal back to Rut'theran Village, fly to Auberdine, sail first to Menethil Harbor, then follow the northern boat route to Southshore and get off there, then fly to Chillwind Camp."}, [2]={to="Chillwind Camp", desc="Skip this if you're already at Chillwind Camp. If the flight map doesn't list Chillwind Camp, walk north along the mountain road from Aerie Peak into Western Plaguelands and then west to Chillwind Camp."}, [3]={npc="High Priestess MacDonnell", tgt="High Priestess MacDonnell"}, [4]={npc="Flint Shadowmore", tgt="Flint Shadowmore", tag="Optional"}, [5]={npc="Flint Shadowmore", tgt="Flint Shadowmore", tag="Optional"}, [6]={npc="High Priestess MacDonnell", tgt="High Priestess MacDonnell"}, [7]={npc="Commander Ashlam Valorfist", tgt="Commander Ashlam Valorfist"}, [8]={npc="Alchemist Arbington", tgt="Alchemist Arbington"}, [9]={npc="Alchemist Arbington", tgt="Alchemist Arbington", desc="Skeletal Fragments only start dropping once you've accepted this; collect them while killing skeletons at Sorrow Hill and Andorhal."}, [10]={npc="Marlene Redpath", tgt="Marlene Redpath"}, [11]={npc="Marlene Redpath", tgt="Marlene Redpath"}, [12]={hint="Bring Joseph's Wedding Ring to Chromie."}, [13]={hint="Bring 15 Skeletal Fragments to Alchemist Arbington at Chillwind Point, Western Plaguelands."}, [14]={npc="Chromie", tgt="Chromie"}, [15]={npc="Chromie", tgt="Chromie"}, [16]={npc="Chromie", tgt="Chromie"}, [17]={hint="Bring the Annals of Darrowshire to Chromie in Andorhal."}, [18]={hint="Use the Temporal Displacer near one of Andorhal's silos and uncover Temporal Parasites."}, [19]={npc="Chromie", tgt="Chromie"}, [20]={npc="Chromie", tgt="Chromie"}, [21]={npc="Chromie", tgt="Chromie"}, [22]={hint="Locate 5 Andorhal Watches, found in lockboxes amongst the rubble of the city. Return with them to Chromie in the Andorhal Inn, Western Plaguelands."}, [23]={npc="Chromie", tgt="Chromie"}, [24]={npc="Chromie", tgt="Chromie"}, [25]={to="Light's Hope Chapel", desc="Andorhal has no flight point. Walk back south to Chillwind Camp first and fly from there."}, [26]={npc="Duke Nicholas Zverenhoff", tgt="Duke Nicholas Zverenhoff", tag="Optional, Group"}, [27]={npc="Carlin Redpath", tgt="Carlin Redpath"}, [28]={npc="Carlin Redpath", tgt="Carlin Redpath", tag="Optional"}, [29]={npc="Carlin Redpath", tgt="Carlin Redpath"}, [30]={npc="Betina Bigglezink", tgt="Betina Bigglezink", tag="Optional, Group"}, [31]={npc="Betina Bigglezink", tgt="Betina Bigglezink", tag="Optional, Group", desc="Do this the next time your group runs the undead wing."}, [32]={npc="Leonid Barthalomew the Revered", tgt="Leonid Barthalomew the Revered", tag="Optional, Group"}, [33]={npc="Smokey LaRue", tgt="Smokey LaRue", tag="Optional, Group"}, [34]={hint="Travel to Northdale, in the northeastern region of the Eastern Plaguelands, and recover the Symbol of Lost Honor. Return to Tirion Fordring upon completion of your objective."}, [35]={hint="Kill Infiltrator Hameya. Use his key on the Mound of Dirt behind the Undercroft."}, [36]={npc="Aurora Skycaller", tgt="Aurora Skycaller"}, [37]={hint="Use the Empty Termite Jar on the Termite Mounds in Eastern Plaguelands. After you've gathered 100 Plagueland Termites, return to Nathaniel Dumah at Chillwind Camp in Western Plaguelands."}, [38]={hint="Bring the Skull of Horgus and the Shattered Sword of Marduk to Carlin Redpath at Light's Hope Chapel.", tag="Optional", desc="This is a dedicated detour with no other objectives nearby. Skip it if you're in a hurry."}, [39]={npc="Mound of Dirt", npcObj=true}, [40]={npc="Tirion Fordring", tgt="Tirion Fordring"}, [41]={npc="Tirion Fordring", tgt="Tirion Fordring"}, [42]={hint="Bring Davil's Libram and Redpath's Shield to Carlin Redpath."}, [43]={hint="Go to Gahrron's Withering in Western Plaguelands to locate and defeat the Cauldron Lord present there, and use its key to gain access to the cauldron. You must have the Empty Gahrron's Withering Bottle with you to secure a sample of the poisons used inside the cauldron."}, [44]={npc="Scourge Cauldron", npcObj=true}, [45]={npc="Scourge Cauldron", npcObj=true}, [46]={npc="Artist Renfray", tgt="Artist Renfray"}, [47]={npc="High Priestess MacDonnell", tgt="High Priestess MacDonnell"}, [48]={npc="Alchemist Arbington", tgt="Alchemist Arbington", desc="The follow-up goes into Scholomance; don't take it."}, [49]={npc="Commander Ashlam Valorfist", tgt="Commander Ashlam Valorfist"}, [50]={npc="Commander Ashlam Valorfist", tgt="Commander Ashlam Valorfist"}, [51]={npc="Nathaniel Dumah", tgt="Nathaniel Dumah"}, [52]={npc="Nathaniel Dumah", tgt="Nathaniel Dumah"}, [53]={npc="Termite Barrel", npcObj=true}, [54]={npc="Termite Barrel", npcObj=true}, [55]={hint="Release the Plagueland Termites in the Northridge Lumber Mill, then return with the Barrel of Plagueland Termites to Nathaniel Dumah at Chillwind Camp in Western Plaguelands."}, [56]={npc="Kirsta Deepshadow", tgt="Kirsta Deepshadow"}, [57]={hint="Kill 2 Scarlet Medics, 2 Scarlet Hunters, 2 Scarlet Magi and 2 Scarlet Knights before returning to Kirsta Deepshadow in Western Plaguelands."}, [58]={npc="Kirsta Deepshadow", tgt="Kirsta Deepshadow"}, [59]={npc="Kirsta Deepshadow", tgt="Kirsta Deepshadow"}, [60]={hint="Kill Huntsman Radley and Cavalier Durgen before returning to Kirsta Deepshadow in Western Plaguelands."}, [61]={npc="Kirsta Deepshadow", tgt="Kirsta Deepshadow"}, [62]={npc="Kirsta Deepshadow", tgt="Kirsta Deepshadow"}, [63]={hint="Enter Hearthglen and find a high vantage point from which you can see the town and gauge the Scarlet Crusade's forces, then return to Kirsta Deepshadow in Western Plaguelands.", desc="The coordinates are approximate. There are Scarlet Crusade guards at the entrance and by the tower; pull them one at a time."}, [64]={npc="Kirsta Deepshadow", tgt="Kirsta Deepshadow"}, [65]={npc="Nathaniel Dumah", tgt="Nathaniel Dumah"}, [66]={to="Light's Hope Chapel", desc="You're already at Chillwind Camp; just see the flight master."}, [67]={npc="Carlin Redpath", tgt="Carlin Redpath", tag="Optional"}, [68]={npc="Carlin Redpath", tgt="Carlin Redpath"}, [69]={to="Ironforge"}, [70]={npc="Royal Historian Archesonus", tgt="Royal Historian Archesonus"}, [71]={to="Stormwind"}, [72]={npc="Royal Factor Bathrilor", tgt="Royal Factor Bathrilor"}, [73]={npc="Royal Factor Bathrilor", tgt="Royal Factor Bathrilor"}, [74]={npc="Ol' Emma", tgt="Ol' Emma"}, [75]={npc="Highlord Bolvar Fordragon", tgt="Highlord Bolvar Fordragon", tag="Optional"}, [76]={npc="Master Mathias Shaw", tgt="Master Mathias Shaw", tag="Optional"}, [77]={npc="Master Mathias Shaw", tgt="Master Mathias Shaw", tag="Optional"}, [78]={npc="Master Mathias Shaw", tgt="Master Mathias Shaw", tag="Optional"}, [79]={to="Lakeshire", tag="Optional", desc="Go to Lakeshire only if you have The True Masters; if not, fly straight from Stormwind to Morgan's Vigil."}, [80]={npc="Magistrate Solomon", tgt="Magistrate Solomon"}, [81]={npc="Magistrate Solomon", tgt="Magistrate Solomon"}, [82]={to="Morgan's Vigil"}, [83]={npc="Marshal Maxwell", tgt="Marshal Maxwell"}, [84]={npc="Marshal Maxwell", tgt="Marshal Maxwell"}, [85]={npc="Oralius", tgt="Oralius", tag="Optional"}, [86]={hint="Speak with Ragged John to learn of Marshal Windsor's fate and return to Marshal Maxwell when you have completed this task."}, [87]={hint="Take Gor'tesh's Lopped Off Head and place it at the top of Dreadmaul Rock. Look for a soft dirt mound to plant the pike.", tag="Optional", desc="This is a dedicated detour with no other objectives nearby. Skip it if you're in a hurry."}, [88]={npc="Marshal Maxwell", tgt="Marshal Maxwell"}, [89]={npc="Oralius", tgt="Oralius", tag="Optional"}, [90]={text="Not 60 yet? Run Blackrock Depths once. If that's still not enough, farm Stratholme or Scholomance."}}},
    ["05-d29"] = {name="The Shaper's Terrace", entrance="Un'Goro Crater 48.10, 6.10 (outside the titan building).", pickup="At 55, see Curator Thorius in the Hall of Explorers in Ironforge. If you're under level on the return from Un'Goro, pick up the quests on a later city visit. Take a boat across continents, then head uphill north from Marshall's Refuge.", pickupS={{"At 55, see Curator Thorius in the Hall of Explorers in Ironforge"}, {"If you're under level on the return from Un'Goro, pick up the quests on a later city visit"}, {"Take a boat across continents, then head uphill north from Marshall's Refuge"}}, tips={{k="動線", text="Loot the journal by the first pool → map landmarks and kill ravasaurs → kill Venomridge → check landmarks and pages."}, {k="說明", text="All three quests fit in one run. Bring power crystals only if your party plans the extra boss.", s={{"All three quests fit in one run"}, {"Bring power crystals only if your party plans the extra boss"}}}}, steps={[1]={npc="Curator Thorius", tgt="Curator Thorius"}, [2]={npc="Curator Thorius", tgt="Curator Thorius"}, [3]={text="The Shaper's Terrace entrance"}, [4]={npc="Partially Digested Journal", npcObj=true, desc="Click the journal at the camp by the first pool."}, [5]={hint="Collect 15 Partially Digested Journal Pages from the Shaper's Terrace.", desc="Location: On the same path as the ravasaur kill quest.", spot="On the same path as the ravasaur kill quest."}, [6]={hint="Slay 6 Ravasaur Matriarchs, 9 Ironhide Ravasaurs and Venomridge in Shaper's Terrace.", desc="Location: Ravasaur packs along the route.", spot="Ravasaur packs along the route."}, [7]={hint="Find Interesting Landmarks in Shaper's Terrace and fill out the explorer's map at each.", desc="Location: Use the cartographer's kit at each of the five landmarks.", spot="Use the cartographer's kit at each of the five landmarks."}, [8]={npc="Curator Thorius", tgt="Curator Thorius"}, [9]={npc="Curator Thorius", tgt="Curator Thorius"}, [10]={npc="Curator Thorius", tgt="Curator Thorius"}}},
    ["05-d28"] = {name="Scholomance", entrance="Western Plaguelands 68.90, 72.80 (underground portal at Caer Darrow).", pickup="See Weldon at Chillwind Camp, Betina at Light's Hope Chapel and Eva by the bridge to Caer Darrow before entering. If you've left Western Plaguelands, fly back to Chillwind Camp.", pickupS={{"See Weldon at Chillwind Camp, Betina at Light's Hope Chapel and Eva by the bridge to Caer Darrow before entering"}, {"If you've left Western Plaguelands, fly back to Chillwind Camp"}}, tips={{k="動線", text="Porch → first hall for the deed → hatchery → Rattlegore → Ras Frostwhisper → six lower rooms → Darkmaster Gandling."}, {k="說明", text="One party member with the Skeleton Key can open the door. Do the Gadgetzan and Fire Plume Ridge chain only for your own key. On the first run, get the deeds, hatchlings and doctor. Dawn's Gambit takes two Upper Blackrock Spire egg runs. The Ras Frostwhisper chain goes through Stromgarde and the undead wing of Stratholme.", s={{"One party member with the Skeleton Key can open the door"}, {"Do the Gadgetzan and Fire Plume Ridge chain only for your own key"}, {"On the first run, get the deeds, hatchlings and doctor"}, {"Dawn's Gambit takes two Upper Blackrock Spire egg runs"}, {"The Ras Frostwhisper chain goes through Stromgarde and the undead wing of Stratholme"}}}}, steps={[1]={npc="Weldon Barov", tgt="Weldon Barov"}, [2]={npc="Betina Bigglezink", tgt="Betina Bigglezink"}, [3]={npc="Eva Sarkhoff", tgt="Eva Sarkhoff"}, [4]={npc="Commander Ashlam Valorfist", tgt="Commander Ashlam Valorfist", tag="Optional"}, [5]={hint="Kill 10 Skeletal Flayers and 10 Slavering Ghouls in Sorrow Hill.", tag="Optional"}, [6]={npc="Commander Ashlam Valorfist", tgt="Commander Ashlam Valorfist", tag="Optional"}, [7]={npc="Commander Ashlam Valorfist", tgt="Commander Ashlam Valorfist", tag="Optional"}, [8]={hint="Using the Beacon Torch, mark each tower in Andorhal; you will need to stand in the doorway of the tower to successfully mark it.", tag="Optional"}, [9]={npc="Commander Ashlam Valorfist", tgt="Commander Ashlam Valorfist", tag="Optional"}, [10]={npc="Commander Ashlam Valorfist", tgt="Commander Ashlam Valorfist", tag="Optional"}, [11]={npc="Alchemist Arbington", tgt="Alchemist Arbington", tag="Optional"}, [12]={npc="Alchemist Arbington", tgt="Alchemist Arbington", tag="Optional"}, [13]={hint="Bring 15 Skeletal Fragments to Alchemist Arbington at Chillwind Point, Western Plaguelands.", tag="Optional"}, [14]={npc="Alchemist Arbington", tgt="Alchemist Arbington", tag="Optional"}, [15]={npc="Alchemist Arbington", tgt="Alchemist Arbington", tag="Optional", preText="Skeletal Fragments"}, [16]={hint="Bring the Imbued Skeletal Fragments and 15 gold coins to Krinkle Goodsteel in Gadgetzan.", tag="Optional"}, [17]={npc="Krinkle Goodsteel", tgt="Krinkle Goodsteel", tag="Optional"}, [18]={npc="Krinkle Goodsteel", tgt="Krinkle Goodsteel", tag="Optional"}, [19]={hint="Take the Skeleton Key Mold and 2 Thorium Bars to the top of Fire Plume Ridge in Un'Goro Crater. Use the Skeleton Key Mold by the lava lake to forge the Unfinished Skeleton Key.", tag="Optional"}, [20]={npc="Alchemist Arbington", tgt="Alchemist Arbington", tag="Optional"}, [21]={npc="Alchemist Arbington", tgt="Alchemist Arbington", tag="Optional"}, [22]={hint="Destroy Araj the Summoner and bring Araj's Scarab to Alchemist Arbington at Chillwind Point, Western Plaguelands.", tag="Optional"}, [23]={npc="Alchemist Arbington", tgt="Alchemist Arbington", tag="Optional"}, [24]={npc="Alchemist Arbington", tgt="Alchemist Arbington", tag="Optional"}, [25]={npc="Alchemist Arbington", tgt="Alchemist Arbington", tag="Optional"}, [26]={text="Prerequisite: Dawn's Gambit", tag="Optional"}, [27]={text="Prerequisite: The Lich, Ras Frostwhisper", tag="Optional"}, [28]={text="Scholomance entrance"}, [29]={hint="Venture to the Scholomance and recover the Barov family fortune. Four deeds make up this fortune: The Deed to Caer Darrow; The Deed to Brill; The Deed to Tarren Mill; and The Deed to Southshore. Return to Weldon Barov when you have completed this task.", desc="Location: On tables or benches in the four rooms.", spot="On tables or benches in the four rooms."}, [30]={hint="Kill 20 Plagued Hatchlings, then return to Betina Bigglezink at the Light's Hope Chapel.", desc="Location: From the porch, pass the summoning hall to the hatchery.", spot="From the porch, pass the summoning hall to the hatchery."}, [31]={npc="Healthy Dragon Scale", npcObj=true, tag="Optional"}, [32]={hint="Locate Jandice Barov in the Scholomance and destroy her. From her corpse recover Krastinov's Bag of Horrors. Return the bag to Eva Sarkhoff.", tag="Optional", desc="Location: The Sunken Crypt below the first hall.", spot="The Sunken Crypt below the first hall."}, [33]={hint="Return to the Scholomance with the Blood of Innocents. Find the porch and place the Blood of Innocents in the brazier. Kirtonos will come to feast upon your soul.", tag="Optional", desc="Location: The instance porch.", spot="The instance porch."}, [34]={hint="Place Dawn's Gambit in the Viewing Room of the Scholomance. Defeat Vectus, then return to Betina Bigglezink.", tag="Optional", desc="Location: Get the key from Rattlegore, then return to the Viewing Room.", spot="Get the key from Rattlegore, then return to the Viewing Room."}, [35]={hint="Find Ras Frostwhisper in the Scholomance. When you have found him, use the Soulbound Keepsake on his undead visage. Should you succeed in reverting him to a mortal, strike him down and recover the Human Head of Ras Frostwhisper. Take the head back to Magistrate Marduke.", tag="Optional", desc="Location: The alchemy lab before the last six rooms.", spot="The alchemy lab before the last six rooms."}, [36]={hint="Find Doctor Theolen Krastinov inside the Scholomance. Destroy him, then burn the Remains of Eva Sarkhoff and the Remains of Lucien Sarkhoff. Return to Eva Sarkhoff when the task is complete.", desc="Location: Both sets of remains are in the doctor's room.", spot="Both sets of remains are in the doctor's room."}, [37]={npc="Eva Sarkhoff", tgt="Eva Sarkhoff"}, [38]={npc="Eva Sarkhoff", tgt="Eva Sarkhoff", tag="Optional", desc="Kill Jandice on your next run.", preText="Doctor Theolen Krastinov, the Butcher"}, [39]={npc="Eva Sarkhoff", tgt="Eva Sarkhoff", tag="Optional"}, [40]={npc="Eva Sarkhoff", tgt="Eva Sarkhoff", tag="Optional", desc="If the party is staying together, go back to the porch to summon him.", preText="Krastinov's Bag of Horrors"}, [41]={npc="Eva Sarkhoff", tgt="Eva Sarkhoff", tag="Optional"}, [42]={npc="Magistrate Marduke", tgt="Magistrate Marduke", tag="Optional", desc="Equip Spectral Essence to see the magistrate."}, [43]={npc="Weldon Barov", tgt="Weldon Barov"}, [44]={npc="Betina Bigglezink", tgt="Betina Bigglezink"}, [45]={npc="Betina Bigglezink", tgt="Betina Bigglezink", tag="Optional"}, [46]={npc="Betina Bigglezink", tgt="Betina Bigglezink", tag="Optional"}}},
    ["05-d27"] = {name="Upper Blackrock Spire", entrance="Burning Steppes 29.40, 38.30 (southern entrance to Blackrock Mountain).", pickup="Pick up quests at Morgan's Vigil and Flame Crest while crossing Burning Steppes. If you're under level, pick them up before grouping. After Lower, turn in General Drakkisath's Command at Morgan's Vigil and take the upper spire follow-up.", pickupS={{"Pick up quests at Morgan's Vigil and Flame Crest while crossing Burning Steppes"}, {"If you're under level, pick them up before grouping"}, {"After Lower, turn in General Drakkisath's Command at Morgan's Vigil and take the upper spire follow-up"}}, tips={{k="動線", text="Shared portal → upper ramp and locked door on the left → Emberseer → Rookery → arena → Drakkisath."}, {k="說明", text="Shares an entrance with Lower. Bring one Seal of Ascension to open the upper door. The two egg quests take separate runs and lead to Scholomance.", s={{"Shares an entrance with Lower"}, {"Bring one Seal of Ascension to open the upper door"}, {"The two egg quests take separate runs and lead to Scholomance"}}}}, steps={[1]={npc="Mayara Brightwing", tgt="Mayara Brightwing"}, [2]={text="Prerequisite: General Drakkisath's Command", tag="Optional"}, [3]={text="Prerequisite: The Dragon's Eye", tag="Optional"}, [4]={npc="Marshal Maxwell", tgt="Marshal Maxwell", tag="Optional", preText="General Drakkisath's Command"}, [5]={npc="Tinkee Steamboil", tgt="Tinkee Steamboil", tag="Optional"}, [6]={hint="Bring 8 Broodling Essence and the Draco-Incarcinatrix 900 to Tinkee Steamboil at the Flame Crest in the Burning Steppes.", tag="Optional"}, [7]={npc="Tinkee Steamboil", tgt="Tinkee Steamboil", tag="Optional"}, [8]={npc="Tinkee Steamboil", tgt="Tinkee Steamboil", tag="Optional"}, [9]={npc="Felnok Steelspring", tgt="Felnok Steelspring", tag="Optional"}, [10]={npc="Felnok Steelspring", tgt="Felnok Steelspring", tag="Optional"}, [11]={hint="Bring 8 Uncracked Chillwind Horns to Felnok Steelspring.", tag="Optional"}, [12]={npc="Felnok Steelspring", tgt="Felnok Steelspring", tag="Optional"}, [13]={npc="Felnok Steelspring", tgt="Felnok Steelspring", tag="Optional"}, [14]={npc="Tinkee Steamboil", tgt="Tinkee Steamboil", tag="Optional"}, [15]={npc="Tinkee Steamboil", tgt="Tinkee Steamboil", tag="Optional", preText="Return to Tinkee"}, [16]={npc="Tinkee Steamboil", tgt="Tinkee Steamboil", tag="Optional", desc="Do this on a later run.", preText="Egg Freezing"}, [17]={npc="Lorax", tgt="Lorax", tag="Optional", desc="Blacksmiths only."}, [18]={npc="Lorax", tgt="Lorax", tag="Optional"}, [19]={npc="Lorax", tgt="Lorax", tag="Optional", desc="Blacksmiths only.", preText="Lorax's Tale"}, [20]={npc="Haleh", tgt="Haleh", tag="Optional", desc="Bring this if you're doing Onyxia attunement.", preText="The Dragon's Eye"}, [21]={text="Upper Blackrock Spire entrance"}, [22]={hint="Bring Doomrigger's Clasp to Mayara Brightwing in the Burning Steppes.", desc="Location: Look for the chest in the Rookery after Emberseer.", spot="Look for the chest in the Rookery after Emberseer."}, [23]={hint="Use the Eggscilloscope Prototype on an egg in the Rookery.", tag="Optional", desc="Location: The upper spire Rookery.", spot="The upper spire Rookery."}, [24]={hint="Bring 8 Collected Dragon Eggs and the Collectronic Module to Tinkee Steamboil at Flame Crest in the Burning Steppes.", tag="Optional", desc="Location: The upper spire Rookery.", spot="The upper spire Rookery."}, [25]={hint="Travel to Blackrock Spire and find Goraluk Anvilcrack. Slay him and then use the Blood Stained Pike upon his corpse. After his soul has been siphoned, the pike will be Soul Stained.", tag="Optional", desc="Location: The upper spire forge.", spot="The upper spire forge."}, [26]={npc="Pip Quickwit", tgt="Pip Quickwit", tag="Optional", desc="Find Pip after the arena event."}, [27]={npc="Awbee", tgt="Awbee", tag="Optional", desc="Find Awbee on the upper balcony after the arena."}, [28]={hint="Travel to Blackrock Spire and destroy General Drakkisath. Return to Marshal Maxwell when the job is done.", tag="Optional", desc="Location: The final boss room in the upper spire.", spot="The final boss room in the upper spire."}, [29]={hint="You must retrieve the Blood of the Black Dragon Champion from General Drakkisath. Drakkisath can be found in his throne room behind the Halls of Ascension in Blackrock Spire.", tag="Optional", desc="Location: The final boss room in the upper spire.", spot="The final boss room in the upper spire."}, [30]={npc="Mayara Brightwing", tgt="Mayara Brightwing"}, [31]={npc="Mayara Brightwing", tgt="Mayara Brightwing", tag="Optional"}, [32]={npc="Count Remington Ridgewell", tgt="Count Remington Ridgewell", tag="Optional"}, [33]={npc="Marshal Maxwell", tgt="Marshal Maxwell", tag="Optional"}, [34]={npc="Tinkee Steamboil", tgt="Tinkee Steamboil", tag="Optional"}, [35]={npc="Tinkee Steamboil", tgt="Tinkee Steamboil", tag="Optional"}, [36]={npc="Tinkee Steamboil", tgt="Tinkee Steamboil", tag="Optional", preText="Egg Collection"}, [37]={npc="Leonid Barthalomew the Revered", tgt="Leonid Barthalomew the Revered", tag="Optional"}, [38]={npc="Leonid Barthalomew the Revered", tgt="Leonid Barthalomew the Revered", tag="Optional", preText="Leonid Barthalomew"}, [39]={npc="Betina Bigglezink", tgt="Betina Bigglezink", tag="Optional"}, [40]={npc="Lorax", tgt="Lorax", tag="Optional"}, [41]={npc="Malyfous Darkhammer", tgt="Malyfous Darkhammer", tag="Optional"}, [42]={npc="Haleh", tgt="Haleh", tag="Optional"}, [43]={npc="Haleh", tgt="Haleh", tag="Optional"}}},
    ["05-d13"] = {name="Stratholme", entrance="Eastern Plaguelands 26.52, 10.36 (Scarlet main gate; undead service entrance at 43.50, 19.40)", steps={[1]={text="Fly to Chillwind Camp if you need to see the painter on Caer Darrow in the Western Plaguelands for Of Love and Family. If you already have the quest or only need the chapel pickups, meet your group directly."}, [2]={npc="Tirion Fordring", tgt="Tirion Fordring", tag="Dungeon prereq"}, [3]={hint="Slay 20 Plaguehound Runts, 5 Plaguehounds and 5 Frenzied Plaguehounds. Return to Tirion Fordring when the task is complete.", tag="Dungeon prereq"}, [4]={npc="Tirion Fordring", tgt="Tirion Fordring", tag="Dungeon prereq"}, [5]={npc="Tirion Fordring", tgt="Tirion Fordring", tag="Dungeon prereq"}, [6]={hint="Slay 30 Plaguebats and return to Tirion Fordring.", tag="Dungeon prereq"}, [7]={npc="Tirion Fordring", tgt="Tirion Fordring", tag="Dungeon prereq"}, [8]={npc="Tirion Fordring", tgt="Tirion Fordring", tag="Dungeon prereq"}, [9]={hint="Seek out the Carrion Grubs and Devourers of the region. Slay them and harvest their meat. Return to Tirion Fordring when you have gathered 15 Slabs of Carrion Worm Meat.", tag="Dungeon prereq"}, [10]={npc="Tirion Fordring", tgt="Tirion Fordring", tag="Dungeon prereq"}, [11]={npc="Tirion Fordring", tgt="Tirion Fordring", tag="Dungeon prereq"}, [12]={hint="Listen to what Tirion Fordring has to say.", tag="Dungeon prereq"}, [13]={npc="Tirion Fordring", tgt="Tirion Fordring", tag="Dungeon prereq"}, [14]={npc="Tirion Fordring", tgt="Tirion Fordring", tag="Dungeon prereq"}, [15]={hint="Travel to the Undercroft - at the southernmost section of the Eastern Plaguelands - and recover Taelan's Hammer. Return to Tirion Fordring upon completion of your objective.", tag="Dungeon prereq"}, [16]={npc="Tirion Fordring", tgt="Tirion Fordring", tag="Dungeon prereq"}, [17]={npc="Tirion Fordring", tgt="Tirion Fordring", tag="Dungeon prereq"}, [18]={hint="Travel to Northdale, in the northeastern region of the Eastern Plaguelands, and recover the Symbol of Lost Honor. Return to Tirion Fordring upon completion of your objective.", tag="Dungeon prereq"}, [19]={npc="Tirion Fordring", tgt="Tirion Fordring", tag="Dungeon prereq"}, [20]={npc="Tirion Fordring", tgt="Tirion Fordring", tag="Dungeon prereq"}, [21]={npc="Artist Renfray", tgt="Artist Renfray", tag="Dungeon prereq"}, [22]={npc="Artist Renfray", tgt="Artist Renfray"}, [23]={npc="Duke Nicholas Zverenhoff", tgt="Duke Nicholas Zverenhoff", tag="Optional, Group"}, [24]={npc="Betina Bigglezink", tgt="Betina Bigglezink", tag="Optional, Group"}, [25]={npc="Leonid Barthalomew the Revered", tgt="Leonid Barthalomew the Revered", tag="Optional, Group"}, [26]={npc="Smokey LaRue", tgt="Smokey LaRue", tag="Optional, Group"}, [27]={text="From Light's Hope Chapel, join your group for Stratholme. The entrance pin marks the Scarlet main gate for the market and Scarlet Bastion. For an undead-only run, meet a party member who can open the eastern service entrance."}, [28]={text="Stratholme entrance"}, [29]={hint="Travel to Stratholme, in the north. Search the supply crates that litter the city and recover 5 Stratholme Holy Water. Return to Leonid Barthalomew the Revered when you have collected enough of the blessed fluid.", tag="Optional, Group", spot="Check supply crates along the streets in either wing. Keep five Stratholme Holy Water for your own turn-in and replace any you use."}, [30]={hint="Recover 20 Plagued Flesh Samples from Stratholme and return them to Betina Bigglezink. You suspect that any creature in Stratholme would have said flesh sample.", tag="Optional, Group", spot="Loot Plagued Flesh Samples as your group clears either wing. Keep what you have for next time and return to the chapel once you have twenty."}, [31]={hint="Find Ezra Grimm's smoke shop in Stratholme and recover a box of Grimm's Premium Tobacco. Return to Smokey LaRue when the job is done.", tag="Optional, Group", spot="In the Scarlet wing, go from the main gate into the market. Open the crate at the smoke shop, defeat Ezra Grimm and loot one box of his Premium Tobacco. Save this for another run if your group is only doing the undead side."}, [32]={hint="Travel to Stratholme, in the northern part of the Plaguelands. It is in the Scarlet Bastion that you will find the painting 'Of Love and Family,' hidden behind another painting depicting the twin moons of our world.", spot="Defeat Galford first. Ask your party to confirm that everyone who needs Of Love and Family has taken it from behind the twin-moons painting before anyone burns the archive. If nobody needs the painting, burn the archive now."}, [33]={hint="Travel to Stratholme and find Archivist Galford of the Scarlet Crusade. Destroy him and burn down the Scarlet Archive.", tag="Optional, Group", spot="Defeat Galford first. Ask your party to confirm that everyone who needs Of Love and Family has taken it from behind the twin-moons painting before anyone burns the archive. If nobody needs the painting, burn the archive now."}, [34]={npc="Head of Balnazzar", npcObj=true, tag="Optional, Group", desc="After turning in The Archivist, right-click the head you looted from Balnazzar to start this quest."}, [35]={hint="Travel to Stratholme and search the ziggurats. Find and return new Scourge Data to Betina Bigglezink.", tag="Optional, Group", spot="Search each of the three undead ziggurats for the small chest and loot the data yourself."}, [36]={hint="Venture to Stratholme and destroy Baron Rivendare. Take his head and return to Duke Nicholas Zverenhoff.", tag="Optional, Group", spot="Cross the Slaughterhouse in the undead wing, defeat Baron Rivendare and loot his head yourself."}, [37]={hint="Use Egan's Blaster on the ghostly and spectral citizens of Stratholme. When the restless souls break free from their ghostly shells, use the blaster again - freedom will be theirs!", tag="Optional, Group", spot="Find Ghostly or Spectral Citizens along the streets of Stratholme. Use Egan's Blaster on a citizen, then on the soul that appears. Free fifteen souls."}, [38]={npc="Tirion Fordring", tgt="Tirion Fordring", desc="Tirion Fordring is at the cabin on the riverbank on the west side of Eastern Plaguelands."}, [39]={text="Return to Light's Hope Chapel. If you have the painting for Of Love and Family, deliver it to Tirion on the western riverbank of the Eastern Plaguelands before returning to the chapel."}, [40]={npc="Duke Nicholas Zverenhoff", tgt="Duke Nicholas Zverenhoff", tag="Optional, Group"}, [41]={npc="Head of Balnazzar", npcObj=true, tag="Optional, Group", desc="After turning in The Archivist, right-click the head you looted from Balnazzar to start this quest."}, [42]={npc="Duke Nicholas Zverenhoff", tgt="Duke Nicholas Zverenhoff", tag="Optional, Group"}, [43]={npc="Duke Nicholas Zverenhoff", tgt="Duke Nicholas Zverenhoff", tag="Optional, Group", desc="Do this the next time your group runs the undead wing."}, [44]={npc="Duke Nicholas Zverenhoff", tgt="Duke Nicholas Zverenhoff", tag="Optional, Group"}, [45]={npc="Betina Bigglezink", tgt="Betina Bigglezink", tag="Optional, Group"}, [46]={npc="Betina Bigglezink", tgt="Betina Bigglezink", tag="Optional, Group", desc="Do this the next time your group runs the undead wing."}, [47]={npc="Betina Bigglezink", tgt="Betina Bigglezink", tag="Optional, Group"}, [48]={npc="Leonid Barthalomew the Revered", tgt="Leonid Barthalomew the Revered", tag="Optional, Group"}, [49]={npc="Smokey LaRue", tgt="Smokey LaRue", tag="Optional, Group"}, [50]={npc="Egan", tgt="Egan", tag="Optional, Group"}, [51]={to="Ironforge"}}},
    ["05-d12"] = {name="Blackrock Depths", entrance="Searing Gorge 34.80, 85.30", pickup="Pick up Kharan Mighthammer once you've turned in The Smoldering Ruins of Thaurissan at Ironforge. The Burning Steppes quests are accepted around Morgan's Vigil.", pickupS={{"Pick up Kharan Mighthammer once you've turned in The Smoldering Ruins of Thaurissan at Ironforge"}, {"The Burning Steppes quests are accepted around Morgan's Vigil"}}, steps={[1]={npc="Royal Historian Archesonus", tgt="Royal Historian Archesonus", tag="Dungeon prereq"}, [2]={hint="Listen to Royal Historian Archesonus recant the history of Thaurissan.", tag="Dungeon prereq"}, [3]={npc="Royal Historian Archesonus", tgt="Royal Historian Archesonus", tag="Dungeon prereq"}, [4]={npc="Royal Historian Archesonus", tgt="Royal Historian Archesonus", tag="Dungeon prereq"}, [5]={hint="Venture to the Ruins of Thaurissan in the Burning Steppes and recover information from the Thaurissan Relics. Return to Royal Historian Archesonus when you have recovered the information.", tag="Dungeon prereq"}, [6]={npc="Royal Historian Archesonus", tgt="Royal Historian Archesonus", tag="Dungeon prereq"}, [7]={npc="King Magni Bronzebeard", tgt="King Magni Bronzebeard", desc="The prerequisite is Ruins of Thaurissan (The Smoldering Ruins of Thaurissan); pick it up after turning in at Ironforge at Western Plaguelands."}, [8]={npc="Ragnar Thunderbrew", tgt="Ragnar Thunderbrew", tag="Optional", desc="Turn it in only once you've picked it up in the Blasted Lands."}, [9]={npc="Ragnar Thunderbrew", tgt="Ragnar Thunderbrew", tag="Optional", desc="Kharanos is out of the way; skip it unless you want to make the detour."}, [10]={npc="Oralius", tgt="Oralius"}, [11]={npc="Maxwort Uberglint", tgt="Maxwort Uberglint"}, [12]={npc="Kalaran Windblade", tgt="Kalaran Windblade", tag="Dungeon prereq"}, [13]={hint="Listen as Kalaran Windblade tells his story.", tag="Dungeon prereq"}, [14]={npc="Kalaran Windblade", tgt="Kalaran Windblade", tag="Dungeon prereq"}, [15]={npc="Kalaran Windblade", tgt="Kalaran Windblade", tag="Dungeon prereq"}, [16]={hint="Collect 4 Hearts of Flame and 4 globes of Golem Oil and return the items to Kalaran Windblade.", tag="Dungeon prereq"}, [17]={npc="Kalaran Windblade", tgt="Kalaran Windblade", tag="Dungeon prereq"}, [18]={npc="Kalaran Windblade", tgt="Kalaran Windblade", tag="Dungeon prereq"}, [19]={hint="Bring 8 Thorium Plated Daggers to Kalaran Windblade.", tag="Dungeon prereq"}, [20]={npc="Kalaran Windblade", tgt="Kalaran Windblade", tag="Dungeon prereq"}, [21]={npc="Kalaran Windblade", tgt="Kalaran Windblade", tag="Dungeon prereq"}, [22]={hint="Find and return a Symbol of Ragnaros to Kalaran Windblade.", tag="Dungeon prereq"}, [23]={npc="Kalaran Windblade", tgt="Kalaran Windblade", tag="Dungeon prereq"}, [24]={npc="Kalaran Windblade", tgt="Kalaran Windblade", tag="Dungeon prereq"}, [25]={hint="Wait for Kalaran Windblade to complete the Torch of Retribution.", tag="Dungeon prereq"}, [26]={npc="Kalaran Windblade", tgt="Kalaran Windblade", tag="Dungeon prereq"}, [27]={npc="Kalaran Windblade", tgt="Kalaran Windblade", tag="Dungeon prereq"}, [28]={npc="Torch of Retribution", npcObj=true, tag="Dungeon prereq"}, [29]={npc="Kalaran Windblade", tgt="Kalaran Windblade", tag="Dungeon prereq"}, [30]={npc="Squire Maltrake", tgt="Squire Maltrake", tag="Dungeon prereq"}, [31]={npc="Squire Maltrake", tgt="Squire Maltrake", tag="Dungeon prereq"}, [32]={hint="Set the North, South, East, and West Sentry Towers on fire by using the Torch of Retribution inside each of the buildings.", tag="Dungeon prereq"}, [33]={npc="Squire Maltrake", tgt="Squire Maltrake", tag="Dungeon prereq"}, [34]={npc="Hoard of the Black Dragonflight", npcObj=true, tag="Dungeon prereq"}, [35]={npc="Hoard of the Black Dragonflight", npcObj=true, tag="Dungeon prereq"}, [36]={npc="Cyrus Therepentous", tgt="Cyrus Therepentous", tag="Dungeon prereq"}, [37]={hint="Show Cyrus Therepentous the Black Dragonflight Molt you received from Kalara