trance"}, [60]={npc="Kharan Mighthammer", tgt="Kharan Mighthammer"}, [61]={npc="Kharan Mighthammer", tgt="Kharan Mighthammer", tag="Optional, Group"}, [62]={hint="Listen as Kharan Mighthammer tells his story.", tag="Optional, Group", spot="Listen to Kharan's full story."}, [63]={npc="Kharan Mighthammer", tgt="Kharan Mighthammer", tag="Optional, Group"}, [64]={hint="Bring the Lost Thunderbrew Recipe to Ragnar Thunderbrew in Kharanos.", tag="Optional"}, [65]={hint="Travel to Blackrock Depths and recover 20 Dark Iron Fanny Packs. Return to Oralius when you have completed this task. You assume that the Dark Iron dwarves inside Blackrock Depths carry these 'fanny pack' contraptions."}, [66]={hint="Bring the Heart of the Mountain to Maxwort Uberglint in the Burning Steppes."}, [67]={hint="Travel to Blackrock Depths and slay Bael'Gar."}, [68]={npc="Marshal Windsor", tgt="Marshal Windsor", tag="Optional"}, [69]={npc="Marshal Windsor", tgt="Marshal Windsor", tag="Optional, Group", desc="Turn in to Field Marshal Maxwell in Burning Steppes. Skip it if you won't go back to Burning Steppes."}, [70]={npc="Marshal Maxwell", tgt="Marshal Maxwell", tag="Optional, Group"}, [71]={npc="Oralius", tgt="Oralius"}, [72]={npc="Maxwort Uberglint", tgt="Maxwort Uberglint"}, [73]={npc="Cyrus Therepentous", tgt="Cyrus Therepentous"}, [74]={npc="Ragnar Thunderbrew", tgt="Ragnar Thunderbrew", tag="Optional"}}},
