    [4183] = {n="The True Masters", d="Travel to Lakeshire and deliver Helendis Riverhorn's Letter to Magistrate Solomon."},
    [4184] = {n="The True Masters", d="Travel to Stormwind and deliver Solomon's Plea to Highlord Bolvar Fordragon.\nBolvar resides in Stormwind Keep."},
    [4185] = {n="The True Masters", d="Speak with Highlord Bolvar Fordragon after speaking with Lady Katrana Prestor.", tgo={{"Lady Katrana Prestor"}}},
    [4186] = {n="The True Masters", d="Take Bolvar's Decree to Magistrate Solomon in Lakeshire."},
    [4223] = {n="The True Masters", d="Speak with Marshal Maxwell in the Burning Steppes."},
    [4224] = {n="The True Masters", d="Speak with Ragged John to learn of Marshal Windsor's fate and return to Marshal Maxwell when you have completed this task.\nYou recall Marshal Maxwell telling you to search for him in a cave to the north.", tgo={{"Ragged John"}}},
    [4241] = {n="Marshal Windsor", d="Travel to Blackrock Mountain in the northwest and enter Blackrock Depths. Find out what became of Marshal Windsor.\nYou recall Ragged John talking about Windsor being dragged off to a prison."},
    [4242] = {n="Abandoned Hope", d="Give Marshal Maxwell the bad news."},
    [4243] = {n="Chasing A-Me 01", d="Find A-Me 01 in Un'Goro Crater."},
    [4244] = {n="Chasing A-Me 01", d="Find a Mithril Casing and return to A-Me 01 in Un'Goro Crater.", tgo={{"Clunk", "Frostwolf Shredder Unit", "Stormpike Shredder Unit", "7:XT"}}},
    [4245] = {n="Chasing A-Me 01", d="Escort A-Me 01 back to Karna Remtravel in Un'Goro Crater."},
    [4265] = {n="Freed from the Hive", d="Free Raschal from the Zukk'ash hive.\nReturn to Ginro Hearthkindle in Feathermoon Stronghold and let him know that Raschal is alive and well."},
    [4266] = {n="A Hero's Welcome", d="Speak with Shandris Feathermoon in Feathermoon Stronghold."},
    [4267] = {n="Rise of the Silithid", d="Bring Raschal's Report to Gracina Spiritmight in Darnassus."},
    [4283] = {n="FIFTY! YEP!", d="Oralius wants 50 Blackrock Medallions. Chances are high that these medallions can be found on the orcs in the Burning Steppes.", tgo={{"Blackrock Soldier", "Blackrock Sorcerer", "Blackrock Slayer", "Blackrock Warlock", "Blackrock Battlemaster", "Blackrock Worg", "Ember Worg", "Slavering Ember Worg"}}},
    [4284] = {n="Crystals of Power", d="Collect 7 Power Crystals of each color: red, blue, yellow, and green. Bring them to J.D. Collie at Marshal's Refuge.", objs={"Red Power Crystal", "Yellow Power Crystal", "Green Power Crystal", "Blue Power Crystal"}},
    [4285] = {n="The Northern Pylon", d="Discover the location of the Northern Crystal Pylon in Un'Goro Crater.", objs={"Northern Crystal Pylon"}},
    [4286] = {n="The Good Stuff", d="Travel to Blackrock Depths and recover 20 Dark Iron Fanny Packs. Return to Oralius when you have completed this task. You assume that the Dark Iron dwarves inside Blackrock Depths carry these 'fanny pack' contraptions.", tgo={{"Anvilrage Overseer", "Anvilrage Warden", "Anvilrage Guardsman", "Anvilrage Footman", "Anvilrage Soldier", "Anvilrage Medic", "Anvilrage Officer", "Shadowforge Peasant"}}},
    [4287] = {n="The Eastern Pylon", d="Discover the location of the Eastern Crystal Pylon in Un'Goro Crater.", objs={"Eastern Crystal Pylon"}},
    [4288] = {n="The Western Pylon", d="Discover the location of the Western Crystal Pylon.", objs={"Western Crystal Pylon"}},
    [4289] = {n="The Apes of Un'Goro", d="Bring 2 Un'Goro Gorilla Pelts, 2 Un'Goro Stomper Pelts, and 2 Un'Goro Thunderer Pelts to Torwa Pathfinder at the entrance of Un'Goro Crater.", tgo={{"Un'Goro Gorilla", "Un'Goro Gorilla"}, {"Un'Goro Stomper"}, {"Un'Goro Thunderer"}}},
    [4290] = {n="The Fare of Lar'korwi", d="Find the carcass of Lar'korwi's freshest kill and steal a Piece of Threshadon Carcass before returning to Torwa Pathfinder in Un'Goro Crater.", objs={"Fresh Threshadon Carcass"}},
    [4291] = {n="The Scent of Lar'korwi", d="Bring 2 Ravasaur Pheromone Glands to Torwa Pathfinder near the entrance to Un'Goro Crater.", tgo={{"Lar'korwi Mate"}}},
    [4292] = {n="The Bait for Lar'korwi", d="Using the contents of Torwa's Pouch, summon Lar'korwi and defeat him. Then bring Lar'korwi's Head to Torwa Pathfinder near the entrance to Un'Goro Crater.", tgo={{"Lar'korwi"}}},
    [4296] = {n="Tablet of the Seven", d="Bring the Tablet Transcript to Maxwort Uberglint in the Burning Steppes.", objs={"Tablet of the Seven"}},
    [4301] = {n="The Mighty U'cha", d="Bring U'cha's Pelt to Torwa Pathfinder at the entrance of Un'Goro Crater.", tgo={{"U'cha"}}},
    [4321] = {n="Making Sense of It", d="Speak with J.D. Collie in a moment."},
    [4341] = {n="Kharan Mighthammer", d="Travel to Blackrock Depths and find Kharan Mighthammer.\nThe King mentioned that Kharan was being held prisoner there - perhaps you should try looking for a prison."},
    [4342] = {n="Kharan's Tale", d="Listen as Kharan Mighthammer tells his story.", tgo={{"Kharan Mighthammer"}}},
    [4421] = {n="The Corruption of the Jadefire", d="Kill 11 Jadefire Felsworns, 9 Jadefire Shadowstalkers, 9 Jadefire Rogues, and Xavathras. Return to Eridan Bluewind in Felwood when the task has been completed.", tgo={{"Jadefire Felsworn"}, {"Jadefire Shadowstalker"}, {"Jadefire Rogue"}, {"Xavathras"}}},
    [4441] = {n="Felbound Ancients", d="Travel to Darnassus and use Eridan's Vial to collect a Vial of Blessed Water from the Temple of the Moon. Return to Eridan with the filled vial.", objs={"Temple of the Moon Fountain"}},
    [4442] = {n="Purified!", d="Speak to Eridan again in a moment."},
    [4449] = {n="Caught!", d="Kill 8 Dark Iron Geologists and bring 15 pieces of Silk Cloth to the person locked in the outhouse in Searing Gorge.", tgo={{"Dark Iron Geologist"}, {}}, objs={"Alterac Granite", "Battered Chest", "Solid Chest"}},
    [4450] = {n="Ledger from Tanaris", d="Take the copy of Goodsteel's Ledger and then find the items listed in it before seeking Krinkle Goodsteel in Tanaris.", tgo={{}, {"Glassweb Spider"}, {}, {"Jarquia"}}, objs={"Goodsteel Ledger", "Damaged Crate"}},
    [4486] = {n="The Tome of Nobility", d="Speak to Duthorian Rall in Stormwind."},
    [4487] = {n="Summon Felsteed", d="Speak to Strahad Farsan in Ratchet."},
    [4490] = {n="Summon Felsteed", d="Speak to Strahad Farsan in Ratchet to learn the ability to summon a Felsteed."},
    [4491] = {n="A Little Help From My Friends", d="Lead Ringo to Spraggle Frock at Marshal's Refuge.\nIf Ringo faints, use Spraggle's Canteen to revive him."},
    [4492] = {n="Lost!", d="Find Ringo at Fire Plume Ridge."},
    [4493] = {n="March of the Silithid", d="Speak to Alchemist Pestlezugg in Gadgetzan."},
    [4495] = {n="A Good Friend", d="Find Iverron by the cave to the north."},
    [4496] = {n="Bungle in the Jungle", d="Bring a Gorishi Scent Gland and 5 Un'Goro Soil samples to Alchemist Pestlezugg in Gadgetzan.", tgo={{"Gorishi Wasp", "Gorishi Worker", "Gorishi Reaver", "Gorishi Stinger", "Gorishi Tunneler", "Gorishi Hive Guard", "Gorishi Hive Queen"}, {}}, objs={"Un'Goro Dirt Pile"}},
    [4501] = {n="Beware of Pterrordax", d="Kill 10 Pterrordax and 15 Frenzied Pterrordax, then speak to Spraggle Frock at Marshal's Refuge.", tgo={{"Pterrordax"}, {"Frenzied Pterrordax"}}},
    [4502] = {n="Volcanic Activity", d="Collect 9 samples of Un'Goro Ash from the fire elementals around the volcano in Un'Goro Crater, and return them to Liv Rizzlefix in Ratchet.", tgo={{"Scorching Elemental", "Living Blaze", "Blazerunner", "Blazing Invader", "Baron Charr"}}},
    [4503] = {n="Shizzle's Flyer", d="Collect 8 Webbed Diemetradon Scales and 8 Webbed Pterrordax Scales for Shizzle in Marshal's Refuge.", tgo={{"Young Diemetradon", "Diemetradon", "Elder Diemetradon"}, {"Fledgling Pterrordax", "Pterrordax", "Frenzied Pterrordax"}}},
    [4504] = {n="Super Sticky", d="Collect 12 samples of Super Sticky Tar for Tran'rek in Gadgetzan.", tgo={{"Tar Beast", "Tar Lurker", "Tar Lord", "Tar Creeper"}}},
    [4581] = {n="Kayneth Stillwind", d="Take Shindrell's Note to Kayneth Stillwind in Forest Song."},
    [4681] = {n="Washed Ashore", d="Recover the Sea Turtle Remains from the Skeletal Sea Turtle in the waters west of Auberdine, and then speak with Gwennyth Bly'Leggonde back in Auberdine.", objs={"Skeletal Sea Turtle"}},
    [4701] = {n="Put Her Down", d="Travel to Blackrock Spire and destroy the source of the worg menace. As you left Helendis, he shouted a name: Halycon. It is what the orcs refer to in regards to the worg.", tgo={{"Halycon"}}},
    [4722] = {n="Beached Sea Turtle", d="Take the Sea Turtle Remains to Gwennyth Bly'Leggonde in Auberdine."},
    [4723] = {n="Beached Sea Creature", d="Take the Sea Creature Bones to Gwennyth Bly'Leggonde in Auberdine."},
    [4725] = {n="Beached Sea Turtle", d="Take the Strangely Marked Box to Gwennyth Bly'Leggonde in Auberdine."},
    [4726] = {n="Broodling Essence", d="Bring 8 Broodling Essence and the Draco-Incarcinatrix 900 to Tinkee Steamboil at the Flame Crest in the Burning Steppes.", objs={"Broodling Essence"}},
    [4727] = {n="Beached Sea Turtle", d="Take the Sea Turtle Remains to Gwennyth Bly'Leggonde in Auberdine."},
    [4728] = {n="Beached Sea Creature", d="Take the Sea Creature Bones to Gwennyth Bly'Leggonde in Auberdine."},
    [4729] = {n="Kibler's Exotic Pets", d="Travel to Blackrock Spire and find Bloodaxe Worg Pups. Use the cage to carry the ferocious little beasts. Bring back a Caged Worg Pup to Kibler."},
    [4730] = {n="Beached Sea Creature", d="Take the Sea Creature Bones to Gwennyth Bly'Leggonde in Auberdine."},
    [4731] = {n="Beached Sea Turtle", d="Take the Strangely Marked Box to Gwennyth Bly'Leggonde in Auberdine."},
    [4732] = {n="Beached Sea Turtle", d="Take the Sea Turtle Remains to Gwennyth Bly'Leggonde in Auberdine."},
    [4733] = {n="Beached Sea Creature", d="Take the Sea Creature Bones to Gwennyth Bly'Leggonde in Auberdine."},
    [4734] = {n="Egg Freezing", d="Use the Eggscilloscope Prototype on an egg in the Rookery.", objs={"Rookery Egg"}},
    [4735] = {n="Egg Collection", d="Bring 8 Collected Dragon Eggs and the Collectronic Module to Tinkee Steamboil at Flame Crest in the Burning Steppes.", objs={"Rookery Egg"}},
    [4740] = {n="WANTED: Murkdeep!", d="Find and slay the murloc known as Murkdeep. The creature is thought to be defending the murloc huts south of Auberdine along the water.\nReport the death of Murkdeep to Sentinel Glynda Nal'Shea in Auberdine.", tgo={{"Murkdeep"}}},
    [4742] = {n="Seal of Ascension", d="Find the three gemstones of command: The Gemstone of Smolderthorn, Gemstone of Spirestone, and Gemstone of Bloodaxe. Return them, along with the Unadorned Seal of Ascension, to Vaelan.\nThe Generals, as told to you by Vaelan, are: War Master Voone of the Smolderthorn; Highlord Omokk of the Spirestone; and Overlord Wyrmthalak of the Bloodaxe.", tgo={{"Highlord Omokk"}, {"War Master Voone"}, {"Overlord Wyrmthalak"}, {"Scarshield Grunt", "Scarshield Sentry", "Scarshield Acolyte", "Scarshield Quartermaster", "Scarshield Legionnaire", "Scarshield Spellbinder", "Highlord Omokk", "Spirestone Battle Mage"}}},
    [4743] = {n="Seal of Ascension", d="Travel to the Wyrmbog in Dustwallow Marsh. Find the ancient drake, Emberstrife and beat him without mercy until his will is broken.\nIt is at that moment which you must place the Unforged Seal of Ascension before the great beast. You must then be quick to use the Orb of Draconic Energy on his weakened form and claim dominion over his mental faculties. Control the beast and force the Flames of the Black Dragonflight upon the Unforged Seal of Ascension!", objs={"Forged Seal of Ascension"}},
    [4761] = {n="Thundris Windweaver", d="Speak with Thundris Windweaver in Auberdine."},
    [4762] = {n="The Cliffspring River", d="Travel north of Auberdine to the first waterfall along the Cliffspring River and draw a sample from the pool there.\nReturn to Thundris Windweaver in Auberdine with the Cliffspring River Sample.", objs={"Cliffspring River Waterfall"}},
    [4763] = {n="The Blackwood Corrupted", d="Fill the Empty Cleansing Bowl at the Auberdine Moonwell.\nGather a sample of fruit, nut, and grain from the northern Blackwood furbolg camps.\nMix the bowl and place it near the bonfire closest to the Cliffspring River at the northern camp, thus summoning the satyr corruptor.\nTake the Talisman of Corruption and bring it to Thundris Windweaver in Auberdine.", objs={"Xabraxxis' Demon Bag"}},
    [4764] = {n="Doomrigger's Clasp", d="Bring Doomrigger's Clasp to Mayara Brightwing in the Burning Steppes.", objs={"Doomrigger's Coffer"}},
    [4765] = {n="Delivery to Ridgewell", d="Bring Ridgewell's Crate to Remington Ridgewell in Stormwind."},
    [4771] = {n="Dawn's Gambit", d="Place Dawn's Gambit in the Viewing Room of the Scholomance. Defeat Vectus, then return to Betina Bigglezink.", tgo={{"Vectus"}}},
    [4781] = {n="Components for the Enchanted Gold Bloodrobe", d="Bring a Gold Bar to Xizk Goodstitch in Stranglethorn Vale.", objs={"Battered Chest", "Solid Chest", "Alliance Strongbox"}},
    [4782] = {n="Components for the Enchanted Gold Bloodrobe", d="Return to Menara Voidrender in the Barrens."},
    [4783] = {n="Components for the Enchanted Gold Bloodrobe", d="Bring 10 Vials of Hatefury Blood and 1 Lesser Infernal Stone to Menara Voidrender in the Barrens.", tgo={{"Hatefury Rogue", "Hatefury Trickster", "Hatefury Felsworn", "Hatefury Betrayer", "Hatefury Shadowstalker", "Hatefury Hellcaller", "Prince Kellen"}, {"Lesser Infernal", "Demon Portal Guardian"}}},
    [4784] = {n="Components for the Enchanted Gold Bloodrobe", d="Bring some Fine Gold Thread, 2 Smoldering Coals, and a Soul Shard to Menara Voidrender in the Barrens.", tgo={{"Xizk Goodstitch"}, {"Burning Exile"}, {}}},
    [4785] = {n="Fine Gold Thread"},
    [4786] = {n="The Completed Robe", d="Wait for Menara Voidrender to complete your robe and then speak to her again.", tgo={{"Menara Voidrender"}}},
    [4787] = {n="The Ancient Egg", d="Bring the Ancient Egg to Yeh'kinya in Tanaris.", objs={"Ancient Egg"}},
    [4788] = {n="The Final Tablets", d="Bring the Fifth and Sixth Mosh'aru Tablets to Prospector Ironboot in Tanaris.", objs={"Fifth Mosh'aru Tablet", "Sixth Mosh'aru Tablet"}},
    [4808] = {n="Felnok Steelspring", d="Give Tinkee's Letter to Felnok Steelspring."},
    [4809] = {n="Chillwind Horns", d="Bring 8 Uncracked Chillwind Horns to Felnok Steelspring.", tgo={{"Fledgling Chillwind", "Chillwind Chimaera", "Chillwind Ravager"}}},
    [4810] = {n="Return to Tinkee", d="Bring Felnok's Package to Tinkee Steamboil in the Burning Steppes."},
    [4811] = {n="The Red Crystal", d="Travel east of Auberdine and look for a large, red crystal along Darkshore's eastern mountain range. Report back what you find to Sentinel Glynda Nal'Shea in Auberdine.", objs={"Mysterious Red Crystal"}},
    [4812] = {n="As Water Cascades", d="Fill the Empty Water Tube at the Auberdine moonwell, and then investigate the red crystal along Darkshore's eastern mountain wall.", objs={"Auberdine Moonwell"}},
    [4813] = {n="The Fragments Within", d="Report back what you have found to Sentinel Glynda Nal'Shea in Auberdine."},
    [4842] = {n="Strange Sources", d="Follow Donova Snowden's instructions, then report back."},
    [4861] = {n="Enraged Wildkin", d="Locate Jaron Stoneshaper's wrecked camp and supplies in southern Winterspring."},
    [4862] = {n="En-Ay-Es-Tee-Why", d="Travel to Blackrock Spire and collect 15 Spire Spider Eggs for Kibler.\nBy the sound of it, these eggs could be found near spiders.", objs={"Spire Spider Egg"}},
    [4863] = {n="Enraged Wildkin", d="Find Jaron Stoneshaper's wrecked wagon."},
    [4864] = {n="Enraged Wildkin", d="Pick up Jaron's Supplies from the snow, then find the wildkin that stole the amulet Jaron spoke of.\nBring Jaron's Supplies and the Blue-feathered Amulet to Jaron Stoneshaper at the lodge in Winterspring.", tgo={{}, {"Crazed Owlbeast", "Moontouched Owlbeast", "Berserk Owlbeast", "Guardian of Elune"}}, objs={"Jaron's Supplies"}},
    [4866] = {n="Mother's Milk", d="In the heart of Blackrock Spire you will find Mother Smolderweb. Engage her and get her to poison you. Chances are good that you will have to kill her as well. Return to Ragged John when you are poisoned so that he can 'milk' you.", tgo={{"Ragged John"}}},
    [4867] = {n="Urok Doomhowl", d="Read Warosh's Scroll. Bring Warosh's Mojo to Warosh.", tgo={{"Urok Doomhowl"}}},
    [4901] = {n="Guardians of the Altar", d="Protect Ranshalla while she attempts to reactivate the Altar of Elune. Report your findings to Erelas Ambersky in Rut'theran Village."},
    [4902] = {n="Wildkin of Elune", d="Speak with Arch Druid Fandral Staghelm in Darnassus."},
    [4906] = {n="Further Corruption", d="Eridan Bluewind in Felwood wants you to kill 8 Jadefire Hellcallers, 8 Jadefire Betrayers, 8 Jadefire Tricksters, and Xavaric. Return to Eridan when the task is completed.", tgo={{"Jadefire Hellcaller"}, {"Jadefire Betrayer"}, {"Jadefire Trickster"}, {"Xavaric"}}},
    [4961] = {n="Cleansing of the Orb of Orahil", d="Kill the Demon of the Orb, then speak with Tabetha.", tgo={{"Demon of the Orb"}}},
    [4962] = {n="Shard of a Felhound", d="Take the Felhas Ruby and use it on one of the Felhounds found in Desolace. After successful, bring the Felhas Ruby and the Imprisoned Felhound Spirit back to Menara Voidrender in the Barrens.", tgo={{"Mana Eater"}}},
    [4963] = {n="Shard of an Infernal", d="Take the Infus Emerald and use it on one of the Infernals found in Desolace. After successful, bring the Infus Emerald and the Imprisoned Infernal Spirit back to Menara Voidrender in the Barrens.", tgo={{"Lesser Infernal"}}},
    [4964] = {n="The Completed Orb of Dar'Orahil", d="Wait for Menara Voidrender to complete the Orb of Dar'Orahil and then speak to her again.", tgo={{"Menara Voidrender"}}},
    [4965] = {n="Knowledge of the Orb of Orahil", d="Speak to Menara Voidrender in the Barrens."},
    [4971] = {n="A Matter of Time", d="Use the Temporal Displacer near one of Andorhal's silos and uncover Temporal Parasites.\nSlay 10 Temporal Parasites, and then return the Temporal Displacer to Chromie in the Andorhal Inn, Western Plaguelands.", tgo={{"Temporal Parasite"}}},
    [4972] = {n="Counting Out Time", d="Locate 5 Andorhal Watches, found in lockboxes amongst the rubble of the city. Return with them to Chromie in the Andorhal Inn, Western Plaguelands.", objs={"Small Lockbox"}},
    [4975] = {n="The Completed Orb of Noh'Orahil", d="Wait for Menara Voidrender to complete the Orb of Noh'Orahil and then speak to her again.", tgo={{"Menara Voidrender"}}},
    [4976] = {n="Returning the Cleansed Orb", d="Return the Cleansed Infernal Orb to Menara Voidrender in the Barrens."},
    [4984] = {n="The Wildlife Suffers Too", d="Destroy 8 Diseased Wolves, and then return to Mulgris Deepriver at the Writhing Haunt, Western Plaguelands.", tgo={{"Diseased Wolf"}}},
    [4985] = {n="The Wildlife Suffers Too", d="Destroy 8 Diseased Grizzlies, and then return to Mulgris Deepriver at the Writhing Haunt, Western Plaguelands.", tgo={{"Diseased Grizzly"}}},
    [4986] = {n="Glyphed Oaken Branch", d="Based on the magic enchanted within the Glyphed Oaken Branch, its delivery to the Cenarion Circle in Darnassus is the next step the tauren druid sought. Seek one of the druids there for assistance."},
    [5001] = {n="Bijou's Belongings", d="Find Bijou's Belongings and return them to her. Good luck!", objs={"Bijou's Belongings"}},
    [5002] = {n="Message to Maxwell", d="Travel to the Burning Steppes and give Bijou's Information to Marshal Maxwell."},
    [5021] = {n="Better Late Than Never", d="The ramblings of the ghostly woman indicated that she needed a package delivered. She claimed that it was where her horse was. As to where the horse is or where the package was to be delivered - the ghost remains incomprehensible."},
    [5022] = {n="Better Late Than Never", d="Check with the Royal Factors of Stormwind to learn the whereabouts of an Emma Felstone. There is usually a census officer located in City Hall."},
    [5047] = {n="Pip Quickwit, At Your Service!", d="Talk to Malyfous Darkhammer in Everlook."},
    [5048] = {n="Good Natured Emma", d="Find Ol' Emma in Stormwind and see if she is in fact Emma Felstone. If she is, then perhaps she'd like the package Janice Felstone made for her."},
    [5058] = {n="Mrs. Dalson's Diary"},
    [5059] = {n="Locked Away", d="Loot from: Wandering Skeleton", tgo={{"Wandering Skeleton"}}},
    [5060] = {n="Locked Away", d="Loot from: Farmer Dalson", tgo={{"Farmer Dalson"}}},
    [5061] = {n="Aquatic Form", d="Return to Darnassus and show Mathrengyl Bearwalker the Pendant of the Sea Lion."},
    [5066] = {n="A Call to Arms: The Plaguelands!", d="Seek out Commander Ashlam Valorfist. His base camp is located at Chillwind Camp, north of the Alterac Mountains."},
    [5081] = {n="Maxwell's Mission", d="Travel to Blackrock Spire and destroy War Master Voone, Highlord Omokk, and Overlord Wyrmthalak. Return to Marshal Maxwell when the job is done.", tgo={{"War Master Voone"}, {"Highlord Omokk"}, {"Overlord Wyrmthalak"}}},
    [5082] = {n="Threat of the Winterfall", d="Donova Snowden in Winterspring wants you to kill 8 Winterfall Pathfinders, 8 Winterfall Den Watchers, and 8 Winterfall Totemics.", tgo={{"Winterfall Pathfinder"}, {"Winterfall Den Watcher"}, {"Winterfall Totemic"}}},
    [5083] = {n="Winterfall Firewater", d="Bring the Empty Firewater Flask to Donova Snowden in Winterspring."},
    [5084] = {n="Falling to Corruption", d="Search the Deadwood furbolg camp in northern Felwood for a clue."},
    [5085] = {n="Mystery Goo", d="Report back to Donova Snowden with your findings."},
    [5089] = {n="General Drakkisath's Command", d="Take General Drakkisath's Command to Marshal Maxwell in Burning Steppes."},
    [5092] = {n="Clear the Way", d="Kill 10 Skeletal Flayers and 10 Slavering Ghouls in Sorrow Hill.\nReturn to Commander Ashlam Valorfist at Chillwind Camp, Western Plaguelands.", tgo={{"Skeletal Flayer"}, {"Slavering Ghoul"}}},
    [5097] = {n="All Along the Watchtowers", d="Using the Beacon Torch, mark each tower in Andorhal; you will need to stand in the doorway of the tower to successfully mark it.\nOnce all four towers are marked, return the Beacon Torch to Commander Ashlam Valorfist in Chillwind Camp, Western Plaguelands.", tgo={{"Andorhal Tower One"}, {"Andorhal Tower Two"}, {"Andorhal Tower Three"}, {"Andorhal Tower Four"}}},
    [5102] = {n="General Drakkisath's Demise", d="Travel to Blackrock Spire and destroy General Drakkisath. Return to Marshal Maxwell when the job is done.", tgo={{"General Drakkisath"}}},
    [5126] = {n="Lorax's Tale", d="Speak with Lorax. Listen to what he has to say.", tgo={{"Lorax"}}},
    [5127] = {n="The Demon Forge", d="Travel to Blackrock Spire and find Goraluk Anvilcrack. Slay him and then use the Blood Stained Pike upon his corpse. After his soul has been siphoned, the pike will be Soul Stained.\nYou must also find the Unforged Rune Covered Breastplate.\nReturn both the Soul Stained Pike and the Unforged Rune Covered Breastplate to Lorax in Winterspring.", tgo={{"Goraluk Anvilcrack"}, {}}, objs={"Unforged Runic Breastplate"}},
    [5149] = {n="Pamela's Doll", d="Find Pamela's doll."},
    [5152] = {n="Auntie Marlene", d="Speak with Marlene, south of the Ruins of Andorhal."},
    [5153] = {n="A Strange Historian", d="Bring Joseph's Wedding Ring to Chromie.", objs={"Joseph Redpath's Monument"}},
    [5154] = {n="The Annals of Darrowshire", d="Bring the Annals of Darrowshire to Chromie in Andorhal.", objs={"Musty Tome"}},
    [5155] = {n="Forces of Jaedenar", d="Enter Jaedenar and slay 4 Jaedenar Hounds, 4 Jaedenar Guardsmen, 6 Jaedenar Adepts, and 6 Jaedenar Cultists before returning to Greta Mosshoof in Felwood.", tgo={{"Jaedenar Hound"}, {"Jaedenar Guardian"}, {"Jaedenar Adept"}, {"Jaedenar Cultist"}}},
    [5156] = {n="Verifying the Corruption", d="Seek out and destroy 2 Entropic Beasts and 2 Entropic Horrors while exploring Shatter Scar Vale. After checking to see if the craters there are still filled with corrupt fel water, return to Taronn Redfeather in Felwood.", tgo={{"Entropic Beast"}, {"Entropic Horror"}}},
    [5157] = {n="Collection of the Corrupt Water", d="Take the Empty Canteen to the Moon Well in the center of Jaedenar and fill it before returning to Greta Mosshoof in Felwood.", objs={"Corrupt Jaedenar Moonwell"}},
    [5158] = {n="Seeking Spiritual Aid", d="Take the Corrupt Moon Well Water to Islen Waterseer in the Barrens."},
    [5159] = {n="Cleansed Water Returns to Felwood", d="Take the Purified Moon Well Water to Greta Mosshoof in Felwood."},
    [5160] = {n="The Matron Protectorate", d="Travel to Winterspring and find Haleh. Give her Awbee's scale."},
    [5168] = {n="Heroes of Darrowshire", d="Bring Davil's Libram and Redpath's Shield to Carlin Redpath.", objs={"Davil's Libram", "Redpath's Shield"}},
    [5181] = {n="Villains of Darrowshire", d="Bring the Skull of Horgus and the Shattered Sword of Marduk to Carlin Redpath at Light's Hope Chapel.", objs={"Horgus' Skull", "Shattered Sword of Marduk"}},
    [5210] = {n="Brother Carlin", d="Bring the Extended Annals of Darrowshire to Carlin Redpath in Eastern Plaguelands."},
    [5211] = {n="Defenders of Darrowshire", d="Free 15 Darrowshire Spirits and return to Carlin Redpath.", tgo={{"Darrowshire Spirit"}}},
    [5212] = {n="The Flesh Does Not Lie", d="Recover 20 Plagued Flesh Samples from Stratholme and return them to Betina Bigglezink. You suspect that any creature in Stratholme would have said flesh sample.", tgo={{"Ravaged Cadaver", "Mangled Cadaver", "Plague Ghoul", "Ghoul Ravener", "Fleshflayer Ghoul", "Crypt Crawler", "Crypt Beast", "Patchwork Horror"}}},
    [5213] = {n="The Active Agent", d="Travel to Stratholme and search the ziggurats. Find and return new Scourge Data to Betina Bigglezink.", objs={"Scourge Data"}},
    [5214] = {n="The Great Ezra Grimm", d="Find Ezra Grimm's smoke shop in Stratholme and recover a box of Grimm's Premium Tobacco. Return to Smokey LaRue when the job is done.", tgo={{"Ezra Grimm"}}},
    [5215] = {n="The Scourge Cauldrons", d="Speak with High Priestess MacDonnell at Chillwind Point, Western Plaguelands."},
    [5216] = {n="Target: Felstone Field", d="Go to Felstone Field in Western Plaguelands to locate and defeat the Cauldron Lord present there. It may have a key that will allow access to the cauldron. You must have the Empty Felstone Field Bottle with you to secure a sample of the poisons used inside the cauldron.", tgo={{"Cauldron Lord Bilemaw"}}},
    [5217] = {n="Return to Chillwind Camp", d="Bring the Filled Felstone Field Bottle to High Priestess MacDonnell at Chillwind Camp, Western Plaguelands."},
    [5219] = {n="Target: Dalson's Tears", d="Go to Dalson's Tears in Western Plaguelands to locate and defeat the Cauldron Lord present there, and use its key to gain access to the cauldron. You must have the Empty Dalson's Tears Bottle with you to secure a sample of the poisons used inside the cauldron.", tgo={{"Cauldron Lord Malvinious"}}},
    [5220] = {n="Return to Chillwind Camp", d="Bring the Filled Dalson's Tears Bottle to High Priestess MacDonnell at Chillwind Camp, Western Plaguelands."},
    [5222] = {n="Target: Writhing Haunt", d="Go to the Writhing Haunt in Western Plaguelands to locate and defeat the Cauldron Lord present there, and use its key to gain access to the cauldron. You must have the Empty Writhing Haunt Bottle with you to secure a sample of the poisons used inside the cauldron.", tgo={{"Cauldron Lord Razarch"}}},
    [5223] = {n="Return to Chillwind Camp", d="Bring the Filled Writhing Haunt Bottle to High Priestess MacDonnell at Chillwind Camp, Western Plaguelands."},
    [5225] = {n="Target: Gahrron's Withering", d="Go to Gahrron's Withering in Western Plaguelands to locate and defeat the Cauldron Lord present there, and use its key to gain access to the cauldron. You must have the Empty Gahrron's Withering Bottle with you to secure a sample of the poisons used inside the cauldron.", tgo={{"Cauldron Lord Soulwrath"}}},
    [5226] = {n="Return to Chillwind Camp", d="Bring the Filled Gahrron's Withering Bottle to High Priestess MacDonnell at Chillwind Camp, Western Plaguelands."},
    [5237] = {n="Mission Accomplished!"},
    [5241] = {n="Uncle Carlin", d="Find Carlin Redpath."},
    [5243] = {n="Houses of the Holy", d="Travel to Stratholme, in the north. Search the supply crates that litter the city and recover 5 Stratholme Holy Water. Return to Leonid Barthalomew the Revered when you have collected enough of the blessed fluid.", objs={"Supply Crate", "Stratholme Supply Crate"}},
    [5244] = {n="The Ruins of Kel'Theril", d="Speak with Jaron Stoneshaper in Starfall Village."},
    [5245] = {n="Troubled Spirits of Kel'Theril", d="Use Jaron's Pick to find the four Highborne Relic Fragments. Bring them to Aurora Skycaller in Eastern Plaguelands.", objs={"Highborne Relic Fragment"}},
    [5250] = {n="Starfall", d="Find Starfall in Winterspring and speak with Wynd Nightchaser."},
    [5251] = {n="The Archivist", d="Travel to Stratholme and find Archivist Galford of the Scarlet Crusade. Destroy him and burn down the Scarlet Archive.", tgo={{"Archivist Galford"}, {}}, objs={"Scarlet Archive"}},
    [5261] = {n="Eagan Peltskinner", d="Speak with Eagan Peltskinner."},
    [5262] = {n="The Truth Comes Crashing Down", d="Take the Head of Balnazzar to Duke Nicholas Zverenhoff in the Eastern Plaguelands."},
    [5263] = {n="Above and Beyond", d="Venture to Stratholme and destroy Baron Rivendare. Take his head and return to Duke Nicholas Zverenhoff.", tgo={{"Baron Rivendare"}}},
    [5282] = {n="The Restless Souls", d="Use Egan's Blaster on the ghostly and spectral citizens of Stratholme. When the restless souls break free from their ghostly shells, use the blaster again - freedom will be theirs!\nFree 15 Restless Souls and return to Egan.", tgo={{"Restless Soul"}}},
    [5306] = {n="Snakestone of the Shadow Huntress", d="Travel to Blackrock Spire and slay Shadow Hunter Vosh'gajin. Recover Vosh'gajin's Snakestone and return to Kilram.", tgo={{"Shadow Hunter Vosh'gajin"}}},
    [5343] = {n="Barov Family Fortune", d="Venture to the Scholomance and recover the Barov family fortune. Four deeds make up this fortune: The Deed to Caer Darrow; The Deed to Brill; The Deed to Tarren Mill; and The Deed to Southshore. Return to Weldon Barov when you have completed this task.", objs={"The Deed to Brill", "The Deed to Caer Darrow", "The Deed to Southshore", "The Deed to Tarren Mill"}},
    [5382] = {n="Doctor Theolen Krastinov, the Butcher", d="Find Doctor Theolen Krastinov inside the Scholomance. Destroy him, then burn the Remains of Eva Sarkhoff and the Remains of Lucien Sarkhoff. Return to Eva Sarkhoff when the task is complete.", tgo={{"Doctor Theolen Krastinov"}, {}, {}}, objs={"Remains of Eva Sarkhoff", "Remains of Lucien Sarkhoff"}},
    [5384] = {n="Kirtonos the Herald", d="Return to the Scholomance with the Blood of Innocents. Find the porch and place the Blood of Innocents in the brazier. Kirtonos will come to feast upon your soul.\nFight valiantly, do not give an inch! Destroy Kirtonos and return to Eva Sarkhoff.", tgo={{"Kirtonos the Herald"}}},
    [5401] = {n="Argent Dawn Commission"},
    [5466] = {n="The Lich, Ras Frostwhisper", d="Find Ras Frostwhisper in the Scholomance. When you have found him, use the Soulbound Keepsake on his undead visage. Should you succeed in reverting him to a mortal, strike him down and recover the Human Head of Ras Frostwhisper. Take the head back to Magistrate Marduke.", tgo={{"Ras Frostwhisper"}}},
    [5501] = {n="Bone Collector", d="Bring 10 Kodo Bones from the Kodo Graveyard to Bibbly F'utzbuckle at Kormek's Hut.", objs={"Kodo Bones"}},
    [5505] = {n="The Key to Scholomance"},
    [5515] = {n="Krastinov's Bag of Horrors", d="Locate Jandice Barov in the Scholomance and destroy her. From her corpse recover Krastinov's Bag of Horrors. Return the bag to Eva Sarkhoff.", tgo={{"Jandice Barov"}}},
    [5518] = {n="The Gordok Ogre Suit", d="Bring 4 Bolts of Runecloth, 8 Rugged Leather, 2 Rune Threads, and Ogre Tannin to Knot Thimblejack. He is currently chained inside the Gordok wing of Dire Maul.", objs={"Felsteel Chest", "Ogre Tannin Basket", "Knot Thimblejack's Cache"}},
    [5522] = {n="Leonid Barthalomew", d="Bring the Frozen Eggs to Leonid Barthalomew in the Eastern Plaguelands."},
    [5525] = {n="Free Knot!", d="Loot from: Gordok Brute, Gordok Mage-Lord, Gordok Captain", tgo={{"Gordok Brute", "Gordok Mage-Lord", "Gordok Captain", "Gordok Warlock", "Gordok Reaver", "Guard Fengus", "Guard Slip'kik", "Captain Kromcrush"}}},
    [5526] = {n="Shards of the Felvine", d="Find the Felvine in Dire Maul and acquire a shard from it. Chances are you'll only be able to procure one with the demise of Alzzin the Wildshaper. Use the Reliquary of Purity to securely seal the shard inside, and return it to Rabine Saturna in Nighthaven, Moonglade."},
    [5527] = {n="A Reliquary of Purity", d="Travel to Silithus and search for a Reliquary of Purity within the ruins of Southwind Village. If you are able to find it, return with it to Rabine Saturna in Nighthaven, Moonglade.", objs={"Dusty Reliquary"}},
    [5528] = {n="The Gordok Taste Test"},
    [5529] = {n="Plagued Hatchlings", d="Kill 20 Plagued Hatchlings, then return to Betina Bigglezink at the Light's Hope Chapel.", tgo={{"Plagued Hatchling"}}},
    [5531] = {n="Betina Bigglezink", d="Bring the Frozen Eggs to Betina Bigglezink."},
    [5533] = {n="Scholomance", d="Speak with Alchemist Arbington at Chillwind Point, Western Plaguelands."},
    [5535] = {n="Spiritual Unrest", d="Destroy 6 Highborne Apparitions and 6 Highborne Lichlings before returning to Loh'atu in Azshara.", tgo={{"Highborne Apparition"}, {"Highborne Lichling"}}},
    [5536] = {n="A Land Filled with Hatred", d="Kill 6 Haldarr Satyr, 2 Haldarr Tricksters, 2 Haldarr Felsworn and then return to Loh'atu on the border of Ashenvale.", tgo={{"Haldarr Satyr"}, {"Haldarr Trickster"}, {"Haldarr Felsworn"}}},
    [5537] = {n="Skeletal Fragments", d="Bring 15 Skeletal Fragments to Alchemist Arbington at Chillwind Point, Western Plaguelands.", tgo={{"Skeletal Flayer", "Skeletal Sorcerer", "Skeletal Terror", "Skeletal Executioner", "Skeletal Warlord", "Skeletal Acolyte", "Skeletal Magelord"}}},
    [5538] = {n="Mold Rhymes With...", d="Bring the Imbued Skeletal Fragments and 15 gold coins to Krinkle Goodsteel in Gadgetzan."},
    [5541] = {n="Ammo for Rumbleshot", d="Bring Rumbleshot's Ammo to Hegnar Rumbleshot in Dun Morogh.", objs={"Ammo Crate"}},
    [5542] = {n="Demon Dogs", d="Slay 20 Plaguehound Runts, 5 Plaguehounds and 5 Frenzied Plaguehounds. Return to Tirion Fordring when the task is complete.", tgo={{"Plaguehound Runt"}, {"Plaguehound"}, {"Frenzied Plaguehound"}}},
    [5543] = {n="Blood Tinged Skies", d="Slay 30 Plaguebats and return to Tirion Fordring.", tgo={{"Plaguebat"}}},
    [5544] = {n="Carrion Grubbage", d="Seek out the Carrion Grubs and Devourers of the region. Slay them and harvest their meat. Return to Tirion Fordring when you have gathered 15 Slabs of Carrion Worm Meat.", tgo={{"Carrion Grub", "Carrion Devourer"}}},
    [5545] = {n="A Bundle of Trouble", d="Bring 8 Bundles of Wood to Raelen at the Eastvale Logging Camp.", objs={"Bundle of Wood"}},
    [5561] = {n="Kodo Roundup", d="Bring five Tamed Kodos and the Kodo Kombobulator back to Smeed Scrabblescrew at Scrabblescrew's Camp."},
    [5582] = {n="Healthy Dragon Scale", d="Bring the Healthy Dragon Scale to Betina Bigglezink at the Light's Hope Chapel in Eastern Plaguelands."},
    [5601] = {n="Sister Pamela", d="Find Pamela Redpath in Darrowshire."},
    [5621] = {n="Garments of the Moon", d="Find Sentinel Shaya and heal her wounds using Lesser Heal (Rank 2). Afterwards, grant her Power Word: Fortitude and then return to Laurna Morninglight in Dolanaar.", tgo={{"Sentinel Shaya"}}},
    [5622] = {n="In Favor of Elune", d="Speak to Laurna Morninglight in Teldrassil."},
    [5623] = {n="In Favor of the Light", d="Speak to Priestess Josetta in Elwynn Forest."},
    [5624] = {n="Garments of the Light", d="Find Guard Roberts and heal his wounds using Lesser Heal (Rank 2). Afterwards, grant him Power Word: Fortitude and then return to Priestess Josetta in Goldshire.", tgo={{"Guard Roberts"}}},
    [5625] = {n="Garments of the Light", d="Find Mountaineer Dolf and heal his wounds using Lesser Heal (Rank 2). Afterwards, grant him Power Word: Fortitude and then return to Maxan Anvol in Kharanos.", tgo={{"Mountaineer Dolf"}}},
    [5626] = {n="In Favor of the Light", d="Speak to Maxan Anvol in Dun Morogh."},
    [5627] = {n="Stars of Elune"},
    [5629] = {n="Returning Home", d="Speak to Priestess Alathea in Darnassus."},
    [5634] = {n="Desperate Prayer"},
    [5645] = {n="A Lack of Fear", d="Speak to High Priest Rohan in Ironforge."},
    [5672] = {n="Elune's Grace"},
    [5676] = {n="Arcane Feedback"},
    [5713] = {n="One Shot. One Kill.", d="Protect Sentinel Aynasha, then speak with Onaeya at Maestra's Post in Ashenvale."},
    [5741] = {n="Sceptre of Light", d="Get the Sceptre of Light and then return it to Azore Aldamort at the tower in Ethel Rethor.", tgo={{"Burning Blade Seer"}}},
    [5742] = {n="Redemption", d="Listen to what Tirion Fordring has to say.", tgo={{"Tirion Fordring"}}},
    [5762] = {n="Hemet Nesingwary", d="Take Kravel's Crate to Hemet Nesingwary in Stranglethorn."},
    [5781] = {n="Of Forgotten Memories", d="Travel to the Undercroft - at the southernmost section of the Eastern Plaguelands - and recover Taelan's Hammer. Return to Tirion Fordring upon completion of your objective.", tgo={{"Mercutio Filthgorger"}}},
    [5801] = {n="Fire Plume Forged", d="Take the Skeleton Key Mold and 2 Thorium Bars to the top of Fire Plume Ridge in Un'Goro Crater. Use the Skeleton Key Mold by the lava lake to forge the Unfinished Skeleton Key.\nBring the Unfinished Skeleton Key to Alchemist Arbington at Chillwind Point, Western Plaguelands.", objs={"Fire Plume Ridge Lava Lake"}},
    [5803] = {n="Araj's Scarab", d="Destroy Araj the Summoner and bring Araj's Scarab to Alchemist Arbington at Chillwind Point, Western Plaguelands.", objs={"Araj's Phylactery"}},
    [5845] = {n="Of Lost Honor", d="Travel to Northdale, in the northeastern region of the Eastern Plaguelands, and recover the Symbol of Lost Honor. Return to Tirion Fordring upon completion of your objective.", objs={"Symbol of Lost Honor"}},
    [5846] = {n="Of Love and Family", d="Travel to island of Caer Darrow, in the south-central region of the Plaguelands, and look for any clues as to the whereabouts of the painting."},
    [5848] = {n="Of Love and Family", d="Travel to Stratholme, in the northern part of the Plaguelands. It is in the Scarlet Bastion that you will find the painting 'Of Love and Family,' hidden behind another painting depicting the twin moons of our world.\nReturn the painting to Tirion Fordring.", objs={"Unfinished Painting"}},
    [5863] = {n="The Dunemaul Compound", d="Andi Lynn in Gadgetzan wants you to destroy the Dunemaul Compound by killing 10 Dunemaul Brutes, 10 Dunemaul Enforcers, and Gor'marok the Ravager.", tgo={{"Dunemaul Brute"}, {"Dunemaul Enforcer"}, {"Gor'marok the Ravager"}}},
    [5882] = {n="Salve via Hunting", d="Loot from: Cursed Ooze, Tainted Ooze, Vile Ooze", tgo={{"Cursed Ooze", "Tainted Ooze", "Vile Ooze", "Ironbeak Owl", "Ironbeak Screecher", "Ironbeak Hunter", "Warpwood Moss Flayer", "Warpwood Shredder"}}},
    [5903] = {n="A Plague Upon Thee", d="Use the Empty Termite Jar on the Termite Mounds in Eastern Plaguelands. After you've gathered 100 Plagueland Termites, return to Nathaniel Dumah at Chillwind Camp in Western Plaguelands.", objs={"Large Termite Mound"}},
    [5904] = {n="A Plague Upon Thee", d="Find someplace suitable in the center of the Northridge Lumber Mill in Western Plaguelands to place the Barrel of Plagueland Termites."},
    [5921] = {n="Moonglade", d="Use the spell \"Teleport: Moonglade\" to travel to Moonglade. When you arrive, speak with Dendrite Starblaze in the village of Nighthaven."},
    [5929] = {n="Great Bear Spirit", d="Seek out the Great Bear Spirit in northwestern Moonglade and learn what it has to share with you about the nature of the bear. When finished, return to Dendrite Starblaze in Nighthaven, Moonglade.", tgo={{"Great Bear Spirit"}}},
    [5931] = {n="Back to Darnassus", d="Return to Darnassus and speak with Mathrengyl Bearwalker in the Cenarion Enclave."},
    [6001] = {n="Body and Heart", d="Use the Cenarion Moondust on the Moonkin Stone of Auberdine to bring forth Lunaclaw. From there, you must face Lunaclaw and earn the strength of body and heart it possesses.\nSpeak with Mathrengyl Bearwalker in Darnassus when you are done.", tgo={{"Lunaclaw Spirit"}}},
    [6004] = {n="Unfinished Business", d="Kill 2 Scarlet Medics, 2 Scarlet Hunters, 2 Scarlet Magi and 2 Scarlet Knights before returning to Kirsta Deepshadow in Western Plaguelands.", tgo={{"Scarlet Medic"}, {"Scarlet Hunter"}, {"Scarlet Mage"}, {"Scarlet Knight"}}},
    [6021] = {n="Zaeldarr the Outcast", d="Bring Zaeldarr's Head to Caretaker Alen at Light's Hope Chapel.", tgo={{"Zaeldarr the Outcast"}}},
    [6023] = {n="Unfinished Business", d="Kill Huntsman Radley and Cavalier Durgen before returning to Kirsta Deepshadow in Western Plaguelands.", tgo={{"Huntsman Radley"}, {"Cavalier Durgen"}}},
    [6024] = {n="Hameya's Plea", d="Kill Infiltrator Hameya. Use his key on the Mound of Dirt behind the Undercroft.", tgo={{"Infiltrator Hameya"}}},
    [6025] = {n="Unfinished Business", d="Enter Hearthglen and find a high vantage point from which you can see the town and gauge the Scarlet Crusade's forces, then return to Kirsta Deepshadow in Western Plaguelands."},
    [6028] = {n="The Everlook Report", d="Deliver the Everlook Report to Argent Officer Pureheart at Chillwind Camp, Western Plaguelands."},
    [6030] = {n="Duke Nicholas Zverenhoff", d="Deliver the book, \"Studies in Spirit Speaking\", to Duke Nicholas Zverenhoff at Light's Hope Chapel, Eastern Plaguelands."},
    [6063] = {n="Taming the Beast", d="Use the Taming Rod to tame a Webwood Lurker. Practice your skills, then return the Taming Rod to Dazalar in Dolanaar.", tgo={{"Webwood Lurker"}}},
    [6064] = {n="Taming the Beast", d="Use the Taming Rod to tame a Large Crag Boar. Practice your skills, then return the Taming Rod to Grif Wildheart in Kharanos.", tgo={{"Large Crag Boar"}}},
    [6084] = {n="Taming the Beast", d="Use the Taming Rod to tame a Snow Leopard. Practice your skills, then return to Grif Wildheart in Kharanos.", tgo={{"Snow Leopard"}}},
    [6085] = {n="Taming the Beast", d="Use the Taming Rod to tame an Ice Claw Bear. Practice your skills, then return the Taming Rod to Grif Wildheart in Kharanos.", tgo={{"Ice Claw Bear"}}},
    [6086] = {n="Training the Beast", d="Speak with Belia Thundergranite in Ironforge."},
    [6101] = {n="Taming the Beast", d="Use the Taming Rod to tame a Nightsaber Stalker. Practice your skills, then return the Taming Rod to Dazalar in Dolanaar.", tgo={{"Nightsaber Stalker"}}},
    [6102] = {n="Taming the Beast", d="Use the Taming Rod to tame a Strigid Screecher. Practice your skills, then return the Taming Rod to Dazalar in Dolanaar.", tgo={{"Strigid Screecher"}}},
    [6103] = {n="Training the Beast", d="Speak to Jocaste in the Cenarion Enclave, in Darnassus."},
    [6121] = {n="Lessons Anew", d="Travel to Moonglade and speak with Dendrite Starblaze in the village of Nighthaven."},
    [6122] = {n="The Principal Source", d="Use the Empty Cliffspring Falls Sampler to draw a sample of water from the mouth of the cave by the falls.\nDeliver the Filled Cliffspring Falls Sampler to Alanndarian Nightsong in Auberdine, Darkshore.", objs={"Cliffspring Falls Cave Mouth"}},
    [6123] = {n="Gathering the Cure", d="Bring 5 Earthroot and 12 Lunar Funguses to Alanndarian Nightsong in Auberdine so she may make a curative salve.", tgo={{"Lasher Sproutling", "Wrathvine"}, {}}, objs={"Lunar Fungal Bloom"}},
    [6124] = {n="Curing the Sick", d="Use the Curative Animal Salve on 10 Sickly Deer that are located throughout Darkshore; doing so should cure them. Sickly Deer have been reported starting south of the Cliffspring River to the north of Auberdine and extending all the way into southern Darkshore where the edge of Ashenvale begins.", tgo={{"Sickly Deer"}}},
    [6125] = {n="Power over Poison", d="Return to Mathrengyl Bearwalker in the Cenarion Enclave, Darnassus."},
    [6134] = {n="Ghost-o-plasm Round Up", d="Bring 8 Ghost-o-plasms and the Crate of Ghost Magnets to Hornizz Brimbuzzle in Desolace.", tgo={{"Magrami Spectre"}}},
    [6182] = {n="The First and the Last", d="Speak with Mathias Shaw in Old Town Stormwind. He resides in the Barracks."},
    [6183] = {n="Honor the Dead", d="Speak with Mathias Shaw again if you wish to accept his task."},
    [6184] = {n="Flint Shadowmore", d="Travel to Chillwind Camp in the Western Plaguelands and meet up with your contact, Flint Shadowmore."},
    [6185] = {n="The Eastern Plagues", d="Scour the Eastern Plaguelands for clues as to the \"Blightcaller\" and the missing SI:7 agents. If you find any SI:7 Insignias, return them to Flint Shadowmore at Chillwind Camp.", objs={"Mangled Human Remains"}},
    [6341] = {n="The Bounty of Teldrassil", d="Bring Nessa's Collection to Vesprystus."},
    [6342] = {n="Flight to Auberdine", d="Ride a hippogryph to Auberdine from the hippogryph master Vesprystus, then bring Nessa's Collection to Laird."},
    [6343] = {n="Return to Nessa", d="Bring Laird's Response to Nessa Shadowsong."},
    [6344] = {n="Nessa Shadowsong", d="Speak with Nessa Shadowsong."},
    [6387] = {n="Honor Students", d="Bring Brock's List to Thorgrum Borrelson in Thelsamar."},
    [6388] = {n="Gryth Thurden", d="Bring the Honorary Picks to Gryth Thurden in Ironforge."},
    [6389] = {n="A Plague Upon Thee", d="Release the Plagueland Termites in the Northridge Lumber Mill, then return with the Barrel of Plagueland Termites to Nathaniel Dumah at Chillwind Camp in Western Plaguelands."},
    [6391] = {n="Ride to Ironforge", d="Buy a gryphon to Ironforge from the gryphon master Thorgrum Borrelson, then bring Brock's List to Golnir Bouldertoe in Ironforge."},
    [6392] = {n="Return to Brock", d="Buy a gryphon to Thelsamar from the gryphon master Gryth Thurden, then bring the Honorary Picks to Brock Stoneseeker in Thelsamar."},
    [6502] = {n="Drakefire Amulet", d="You must retrieve the Blood of the Black Dragon Champion from General Drakkisath. Drakkisath can be found in his throne room behind the Halls of Ascension in Blackrock Spire.", tgo={{"General Drakkisath"}}},
    [6603] = {n="Trouble in Winterspring!", d="Find Donova Snowden near the hot springs in Winterspring."},
    [6604] = {n="Enraged Wildkin", d="Speak with Jaron Stoneshaper at Starfall Village."},
    [6606] = {n="A Little Luck", d="Speak with Witch Doctor Mau'ari in Everlook."},
    [6626] = {n="A Host of Evil", d="Kill 8 Razorfen Battleguard, 8 Razorfen Thornweavers, and 8 Death's Head Cultists and return to Myriam Moonsinger near the entrance to Razorfen Downs.", tgo={{"Razorfen Battleguard"}, {"Razorfen Thornweaver"}, {"Death's Head Cultist"}}},
    [6681] = {n="The Manor, Ravenholdt", d="Take the Seal of Ravenholdt to Fahrad at Ravenholdt Manor, hidden away in the hills of Hillsbrad.\nYour cunning will be tested along the way. Be prepared.", tgo={{"Ravenholdt"}}},
    [6701] = {n="Syndicate Emblems", d="Loot from: Syndicate Assassin, Syndicate Conjuror, Syndicate Footpad", tgo={{"Syndicate Assassin", "Syndicate Conjuror", "Syndicate Footpad", "Syndicate Highwayman", "Syndicate Mercenary", "Syndicate Pathstalker", "Syndicate Prowler", "Syndicate Spy"}}},
    [7028] = {n="Twisted Evils", d="Collect 15 Theradric Crystal Carvings for Willow in Desolace.", tgo={{"Cursed Centaur", "Putridus Satyr", "Putridus Trickster", "Putridus Shadowstalker", "Celebrian Dryad", "Sister of Celebrian", "Princess Theradras", "Landslide"}}},
    [7041] = {n="Vyletongue Corruption", d="Fill the Coated Cerulean Vial at the orange crystal pool in Maraudon.\nUse the Filled Cerulean Vial on the Vylestem Vines to force the corrupted Noxxious Scion to emerge.\nHeal 8 plants by killing these Noxxious Scion, then return to Talendria in Nijel's Point.", tgo={{"Noxxious Scion"}, {}}, objs={"Maraudon Orange Crystal Pool"}},
    [7044] = {n="Legends of Maraudon", d="Recover the two parts of the Scepter of Celebras: the Celebrian Rod and the Celebrian Diamond.\nFind a way to speak with Celebras.", tgo={{"Lord Vyletongue"}, {"Noxxion", "Noxxion's Spawn"}}},
    [7046] = {n="The Scepter of Celebras", d="Assist Celebras the Redeemed while he creates the Scepter of Celebras.\nSpeak with him when the ritual is complete.", objs={"Incantation of Celebras"}},
    [7065] = {n="Corruption of Earth and Seed", d="Slay Princess Theradras and return to Keeper Marandis at Nijel's Point in Desolace.", tgo={{"Princess Theradras"}}},
    [7066] = {n="Seed of Life", d="Seek out Remulos in Moonglade and give him the Seed of Life."},
    [7067] = {n="The Pariah's Instructions", d="Read the Pariah's Instructions. Afterwards, obtain the Amulet of Union from Maraudon and return it to the Centaur Pariah in southern Desolace."},
    [7070] = {n="Shadowshard Fragments", d="Collect 10 Shadowshard Fragments from Maraudon and return them to Archmage Tervosh in Theramore on the coast of Dustwallow Marsh.", tgo={{"Shadowshard Rumbler", "Shadowshard Smasher", "Shadowshard Thunderer"}}},
    [7383] = {n="Crown of the Earth", d="Fill the Amethyst Phial and bring it back to Corithras Moonrage in Dolanaar.", objs={"Oracle Glade Moonwell"}},
    [7441] = {n="Pusillin and the Elder Azj'Tordin", d="Travel to Dire Maul and locate the Imp, Pusillin. Convince Pusillin to give you Azj'Tordin's Book of Incantations through any means necessary.\nReturn to Azj'Tordin at the Lariss Pavilion in Feralas should you recover the Book of Incantations.", tgo={{"Pusillin"}}},
    [7461] = {n="The Madness Within", d="You must destroy the guardians surrounding the 5 Pylons that power the Prison of Immol'thar. Once the Pylons have powered down, the force field surrounding Immol'thar will have dissipated.\nEnter the Prison of Immol'thar and eradicate the foul demon that stands at its heart. Finally, confront Prince Tortheldrin in Athenaeum.\nReturn to the Shen'dralar Ancient in the courtyard should you complete this quest.", tgo={{"Immol'thar"}, {"Prince Tortheldrin"}}},
    [7462] = {n="The Treasure of the Shen'dralar", d="Return to the Athenaeum and find the Treasure of the Shen'dralar. Claim your reward!"},
    [7463] = {n="Arcane Refreshment", d="Travel to the Warpwood Quarter of Dire Maul and slay the water elemental, Hydrospawn. Return to Lorekeeper Lydros in the Athenaeum with the Hydrospawn Essence.", tgo={{"Hydrospawn"}}},
    [7482] = {n="Elven Legends", d="Search Dire Maul for Telmius Dreamseeker. Report back to Scholar Runethorn at Feathermoon with whatever information that you may find.", objs={"Skeletal Remains of Telmius Dreamseeker"}},
    [7483] = {n="Libram of Rapidity", d="Bring a Libram of Rapidity, 1 Pristine Black Diamond, 2 Large Brilliant Shards, and 2 Blood of Heroes to Lorekeeper Lydros in Dire Maul to receive an Arcanum of Rapidity.", tgo={{"Gordok Brute", "Gordok Mage-Lord", "Gordok Captain", "Gordok Warlock", "Gordok Reaver", "Wildspawn Satyr", "Wildspawn Rogue", "Wildspawn Trickster"}, {"Skeletal Warlord", "Flesh Golem", "Scarlet Magus", "Scarlet Cavalier", "Foreman Jerris", "High Protector Lorik", "Araj the Summoner", "Cursed Justicar"}, {}, {}}, objs={"Blood of Heroes"}},
    [7484] = {n="Libram of Focus", d="Bring a Libram of Focus, 1 Pristine Black Diamond, 4 Large Brilliant Shards, and 2 Skin of Shadow to Lorekeeper Lydros in Dire Maul to receive an Arcanum of Focus.", tgo={{"Gordok Brute", "Gordok Mage-Lord", "Gordok Captain", "Gordok Warlock", "Gordok Reaver", "Wildspawn Satyr", "Wildspawn Rogue", "Wildspawn Trickster"}, {"Skeletal Warlord", "Flesh Golem", "Scarlet Magus", "Scarlet Cavalier", "Foreman Jerris", "High Protector Lorik", "Araj the Summoner", "Cursed Justicar"}, {}, {"Risen Construct", "Risen Bonewarder", "Lady Illucia Barov", "Instructor Malicia", "The Ravenian", "Lorekeeper Polkelt"}}},
    [7485] = {n="Libram of Protection", d="Bring a Libram of Protection, 1 Pristine Black Diamond, 2 Large Brilliant Shards, and 1 Frayed Abomination Stitching to Lorekeeper Lydros in Dire Maul to receive an Arcanum of Protection.", tgo={{"Gordok Brute", "Gordok Mage-Lord", "Gordok Captain", "Gordok Warlock", "Gordok Reaver", "Petrified Treant", "Ironbark Protector", "Eldreth Seether"}, {"Skeletal Warlord", "Flesh Golem", "Scarlet Magus", "Scarlet Cavalier", "Foreman Jerris", "High Protector Lorik", "Araj the Summoner", "Cursed Justicar"}, {}, {"Patchwork Horror", "Bile Spewer", "Venom Belcher", "Ramstein the Gorger"}}},
    [7488] = {n="Lethtendris's Web", d="Bring Lethtendris' Web to Latronicus Moonspear at the Feathermoon Stronghold in Feralas.", tgo={{"Lethtendris"}}},
    [7498] = {n="Garona: A Study on Stealth and Treachery", d="Return the book to its rightful owners."},
    [7499] = {n="Codex of Defense", d="Return the book to its rightful owners."},
    [7500] = {n="The Arcanist's Cookbook", d="Return the book to its rightful owners."},
    [7501] = {n="The Light and How To Swing It", d="Return the book to its rightful owners."},
    [7502] = {n="Harnessing Shadows", d="Return the book to its rightful owners."},
    [7503] = {n="The Greatest Race of Hunters", d="Return the book to its rightful owners."},
    [7504] = {n="Holy Bologna: What the Light Won't Tell You", d="Return the book to its rightful owners."},
    [7505] = {n="Frost Shock and You", d="Return the book to its rightful owners."},
    [7506] = {n="The Emerald Dream...", d="Return the book to its rightful owners."},
    [7507] = {n="Nostro's Compendium", d="Return Nostro's Compendium of Dragon Slaying to the Athenaeum."},
    [7601] = {n="What Niby Commands", d="Speak with Impsy in Felwood."},
    [7602] = {n="Flawless Fel Essence", d="Impsy in Felwood has asked that you bring him three Flawless Fel Essences originating from three distinct locations.\nThe Legashi Satyrs of Azshara hold the Flawless Fel Essence of their region. The Jaedenar Legionnaires of Jaedenar hold the Flawless Fel Essence of their region. The Felguard Sentries of the Blasted Lands hold the Flawless Fel Essence of their region.\nRecover the Flawless Fel Essences and return to Impsy in Felwood.", tgo={{"Legashi Satyr", "Legashi Rogue", "Legashi Hellcaller", "Legashi Soulstealer", "Legashi Hellraiser", "Legashi Blackguard"}, {"Jaedenar Legionnaire"}, {"Felguard Sentry"}}},
    [7603] = {n="Kroshius' Infernal Core", d="Search Shatter Scar Vale in Felwood for the remains of Kroshius. When you locate the remains, use the Fel Fire near them and await Kroshius' return. When the infernal has awoken, slay him and take from his corpse Kroshius' Infernal Core.\nReturn Kroshius' Infernal Core to Niby the Almighty in Felwood.", tgo={{"Kroshius"}, {"Kroshius"}}},
    [7701] = {n="WANTED: Overseer Maltorius", d="Deep within the Slag Pit of the Cauldron, in the Searing Gorge, you will find the traitorous Dark Iron dwarf named Overseer Maltorius.\nSlay Overseer Maltorius and take his head. Return the head to Lookout Captain Lolo Longstriker in the Searing Gorge for your reward.", tgo={{"Overseer Maltorius"}}},
    [7703] = {n="Unfinished Gordok Business", d="Find the Gauntlet of Gordok Might and return it to Captain Kromcrush in Dire Maul.\nAccording to Kromcrush, the \"old timey story\" says that Tortheldrin - a \"creepy\" elf who called himself a prince - stole it from one of the Gordok kings.", objs={"The Prince's Chest"}},
    [7722] = {n="What the Flux?", d="Somewhere in the Slag Pit of the Cauldron you will find the Secret Plans: Fiery Flux that Overseer Maltorius stole. Find those plans and return them to Master Smith Burninate in the Searing Gorge.", objs={"Secret Plans: Fiery Flux"}},
    [7723] = {n="Curse These Fat Fingers", d="Hansel Heavyhands wants you to kill 20 Heavy War Golems.\nThe Heavy War Golems wander the areas surrounding the Cauldron in the Searing Gorge. When you've killed enough, return to Hansel in Searing Gorge.", tgo={{"Heavy War Golem"}}},
    [7724] = {n="Fiery Menace!", d="Hansel Heavyhands wants you to kill 20 Greater Lava Spiders in the Searing Gorge. You can find Greater Lava Spiders in the plateaus and lava pools of the Searing Gorge.\nReturn to Hansel Heavyhands in the Searing Gorge when you have killed enough Greater Lava Spiders.", tgo={{"Greater Lava Spider"}}},
    [7727] = {n="Incendosaurs? Whateverosaur is More Like It", d="Hansel Heavyhands wants you to kill 20 Incendosaurs.\nYou will find Incendosaurs occupying the lava pools inside the Slag Pit. The Slag Pit can be found in the Cauldron of the Searing Gorge.\nReturn to Hansel Heavyhands in the Searing Gorge when you have killed enough Incendosaurs.", tgo={{"Incendosaur"}}},
    [7728] = {n="STOLEN: Smithing Tuyere and Lookout's Spyglass", d="Find and return the Smithing Tuyere and Lookout's Spyglass to Taskmaster Scrange in the Searing Gorge.\nThe only information you have about these items is the following: They were definitely stolen by Dark Iron dwarves. The Smithing Tuyere is a blacksmithing tool used by blacksmiths and the Lookout's Spyglass is an invaluable monitoring tool to lookouts.", tgo={{"Dark Iron Steamsmith"}, {"Dark Iron Lookout"}}},
    [7729] = {n="JOB OPPORTUNITY: Culling the Competition", d="Slay 15 Dark Iron Taskmasters and 15 Dark Iron Slavers. Return to Taskmaster Scrange in the Searing Gorge once you have accomplished this task.", tgo={{"Dark Iron Taskmaster"}, {"Dark Iron Slaver"}}},
    [7733] = {n="Improved Quality", d="Bring 10 Rage Scar Yeti Hides to Pratt McGrubben at Feathermoon Stronghold, Feralas.", tgo={{"Rage Scar Yeti", "Elder Rage Scar", "Ferocious Rage Scar", "Lurking Feral Scar"}}},
    [7735] = {n="Pristine Yeti Hide", d="Bring the Pristine Yeti Hide to Pratt McGrubben at the Feathermoon Stronghold, Feralas."},
    [7791] = {n="A Donation of Wool", d="Use/collect: Alterac Granite, Tattered Chest, Battered Chest", objs={"Alterac Granite", "Tattered Chest", "Battered Chest"}},
    [7793] = {n="A Donation of Silk", d="Use/collect: Alterac Granite, Battered Chest, Solid Chest", objs={"Alterac Granite", "Battered Chest", "Solid Chest"}},
    [8151] = {n="The Hunter's Charm", d="Speak to Ogtinc in Azshara."},
    [8153] = {n="Courser Antlers", d="Bring a pair of Perfect Courser Antlers to Ogtinc in Azshara. Ogtinc resides atop the cliffs northeast of the Ruins of Eldarath.", tgo={{"Mosshoof Courser"}}},
    [8231] = {n="Wavethrashing", d="Bring 6 Wavethrasher Scales to Ogtinc in Azshara. Ogtinc resides atop the cliffs northeast the Ruins of Eldarath.", tgo={{"Young Wavethrasher", "Wavethrasher", "Great Wavethrasher"}}},
    [8232] = {n="The Green Drake", d="Bring the Tooth of Morphaz to Ogtinc in Azshara. Ogtinc resides atop the cliffs northeast the Ruins of Eldarath.", tgo={{"Morphaz"}}},
    [8250] = {n="Magecraft", d="Seek out Sanath Lim-yo and gain passage to see Archmage Xylem."},
    [8251] = {n="Magic Dust", d="Bring 10 Glittering Dust to Archmage Xylem.", tgo={{"Blood Elf Surveyor", "Blood Elf Reclaimer", "Blood Elf Defender", "Blood Elf Arcanist", "Evin Schmidtt", "Lumina Windsinger"}}},
    [8252] = {n="The Siren's Coral", d="Collect 6 Enchanted Coral and return them to Archmage Xylem.", tgo={{"Spitelash Siren"}}},
    [8253] = {n="Destroy Morphaz", d="Retrieve the Arcane Shard from Morphaz and return to Archmage Xylem.", tgo={{"Morphaz"}}},
    [8254] = {n="Cenarion Aid", d="Seek out Ogtinc in Azshara."},
    [8255] = {n="Of Coursers We Know", d="Acquire 4 Healthy Courser Glands and bring them to Ogtinc in Azshara. Ogtinc resides atop the cliffs northeast the Ruins of Eldarath.", tgo={{"Mosshoof Courser"}}},
    [8256] = {n="The Ichor of Undeath", d="Acquire an Ichor of Undeath for Ogtinc in Azshara. Ogtinc resides atop the cliffs northeast the Ruins of Eldarath.", tgo={{"Zanzil Zombie", "Zanzil Hunter", "Skeletal Flayer", "Skeletal Sorcerer", "Skeletal Terror", "Skeletal Executioner", "Skeletal Warlord", "Skeletal Acolyte"}}},
    [8257] = {n="Blood of Morphaz", d="Kill Morphaz in the sunken temple of Atal'Hakkar, and return his blood to Greta Mosshoof in Felwood. The entrance to the sunken temple can be found in the Swamp of Sorrows.", tgo={{"Morphaz"}}},
    [8365] = {n="Pirate Hats Ahoy!", d="Haughty Modiste wants you to collect 20 Southsea Pirate Hats and return them to her at Steamwheedle Port in Tanaris.", tgo={{"Southsea Pirate", "Southsea Freebooter", "Southsea Dock Worker", "Southsea Swashbuckler", "Andre Firebeard", "Kregg Keelhaul"}}},
    [8366] = {n="Southsea Shakedown", d="Security Chief Bilgewhizzle of Steamwheedle Port in Tanaris wants you to kill 10 Southsea Pirates, 10 Southsea Freebooters, 10 Southsea Dock Workers and 10 Southsea Swashbucklers.", tgo={{"Southsea Pirate"}, {"Southsea Freebooter"}, {"Southsea Dock Worker"}, {"Southsea Swashbuckler"}}},
    [8414] = {n="Dispelling Evil", d="Collect 20 Minion's Scourgestones and bring them to High Priest Thel'danis in the Western Plaguelands.", tgo={{"Skeletal Flayer", "Skeletal Sorcerer", "Skeletal Terror", "Skeletal Executioner", "Skeletal Acolyte", "Slavering Ghoul", "Rotting Ghoul", "Soulless Ghoul"}}},
    [8415] = {n="Chillwind Point", d="Speak to Commander Ashlam Valorfist at Chillwind Camp."},
    [8416] = {n="Inert Scourgestones", d="Bring the Inert Scourgestone to Commander Ashlan Valorfist in Chillwind Point."},
    [8417] = {n="A Troubled Spirit", d="Speak with the Fallen Hero of the Horde at the entrance to the Blasted Lands."},
    [8418] = {n="Forging the Mightstone", d="Bring the voodoo feathers to Ashlam Valorfist.", tgo={{"Gasher", "Zul'Lor"}, {"Hukku", "Mijan"}, {"Zolo", "Loro"}}},
    [8420] = {n="Hot and Itchy", d="Bring a piece of felcloth to Impsy in Felwood.", tgo={{"Felhunter", "Felguard Sentry", "Legashi Satyr", "Legashi Rogue", "Legashi Hellcaller", "Master Feardred", "Jadefire Rogue", "Jadefire Trickster"}}},
    [8421] = {n="The Wrong Stuff", d="Bring 10 Rotting Wood and 4 Bloodvenom Essence to Impsy in Felwood.", tgo={{"Irontree Wanderer", "Irontree Stomper", "Withered Protector"}, {"Tainted Ooze"}}},
    [8422] = {n="Trolls of a Feather", d="Bring a total of 6 Voodoo Feathers from the trolls in sunken temple.", tgo={{"Gasher", "Zul'Lor", "Gasher"}, {"Hukku", "Mijan", "Hukku"}, {"Zolo", "Loro", "Loro"}}},
    [8423] = {n="Warrior Kinship", d="Kill 7 Helboar in the Blasted Lands and return to the Fallen Hero of the Horde.", tgo={{"Helboar"}}},
    [8424] = {n="War on the Shadowsworn", d="Slaughter the Shadowsworn in the Blasted Lands and return to the Fallen Hero of the Horde.", tgo={{"Shadowsworn Adept"}, {"Shadowsworn Cultist"}, {"Shadowsworn Thug"}}},
    [8425] = {n="Voodoo Feathers", d="Bring the Voodoo Feathers from the trolls in the Sunken Temple to the Fallen Hero of the Horde.", tgo={{"Gasher", "Zul'Lor", "Gasher"}, {"Hukku", "Mijan", "Hukku"}, {"Zolo", "Loro", "Loro"}}},
    [8460] = {n="Timbermaw Ally", d="Grazle wants you to prove yourself by killing 6 Deadwood Warriors, 6 Deadwood Pathfinders, and 6 Deadwood Gardeners. Return to him in southern Felwood near the Emerald Sanctuary when you are done.", tgo={{"Deadwood Warrior"}, {"Deadwood Pathfinder"}, {"Deadwood Gardener"}}},
    [8461] = {n="Deadwood of the North", d="Nafien would like you to kill 6 Deadwood Den Watchers, 6 Deadwood Avengers, and 6 Deadwood Shamans. Return to him in northern Felwood near the entrance to Timbermaw Hold.", tgo={{"Deadwood Den Watcher"}, {"Deadwood Avenger"}, {"Deadwood Shaman"}}},
    [8462] = {n="Speak to Nafien", d="Travel north along the main road in Felwood and speak with the furbolg named Nafien. He stands guard outside the entrance to Timbermaw Hold."},
    [8464] = {n="Winterfall Activity", d="Salfa wants you to kill 8 Winterfall Shaman, 8 Winterfall Den Watchers, and 8 Winterfall Ursa. Salfa is located just outside the entrance to Timbermaw Hold in Winterspring.", tgo={{"Winterfall Shaman"}, {"Winterfall Den Watcher"}, {"Winterfall Ursa"}}},
    [8465] = {n="Speak to Salfa", d="Travel through Timbermaw Hold and exit into Winterspring. Speak with Salfa, who stands guard outside the entrance to Timbermaw Hold."},
    [9051] = {n="Toxic Test", d="Stab a Devilsaur with the Devilsaur Barb. Return to Torwa Pathfinder in Un'Goro Crater when you have completed this task."},
    [9052] = {n="Bloodpetal Poison", d="Collect 8 Bloodcap and 8 Gorishi Stings, and return to Torwa Pathfinder in Un'Goro Crater.", tgo={{"Gorishi Wasp", "Gorishi Stinger"}, {}}, objs={"Bloodpetal Sprout"}},
    [9053] = {n="A Better Ingredient", d="Retrieve a Putrid Vine from the guardian at the bottom of the Sunken Temple and return to Torwa Pathfinder.", tgo={{"Atal'alarion"}}},
    [65602] = {n="What Is Love?", d="Retrieve the Wooden Figurine and bring it to Gakin the Darkbinder in the Mage Quarter of Stormwind.", objs={"Wooden Figurine"}},
    [65603] = {n="The Binding", d="Using the Wooden Figurine, summon and subdue an incubus, then return the Wooden Figurine to Gakin the Darkbinder in the Slaughtered Lamb.", tgo={{"Summoned Incubus"}}},
    [79358] = {n="Storm, Earth, and Fire", d="Collect 5 Twisted Fire Totems, 5 Twisted Earth Totems, 5 Twisted Air Totems, and 5 Twisted Water Totems for Veyric Thunderhame in Arathi Highlands.", tgo={{"Mirefin Puddlejumper", "Mirefin Murloc", "Mirefin Warrior", "Mirefin Muckdweller", "Mirefin Coastrunner", "Mirefin Oracle"}, {"Lost One Mudlurker", "Lost One Fisherman", "Lost One Hunter", "Lost One Muckdweller", "Lost One Seer", "Lost One Riftseeker", "Lost One Chieftain", "Lost One Cook"}, {"Stonevault Skullthumper", "Stonevault Bonesnapper", "Stonevault Shaman", "Dustbelcher Ogre", "Dustbelcher Brute", "Dustbelcher Wyrmhunter", "Dustbelcher Mauler", "Dustbelcher Shaman"}, {"Maraudine Wrangler", "Maraudine Mauler", "Maraudine Windchaser", "Maraudine Stormer", "Maraudine Marauder", "Maraudine Pack Runner", "Maraudine Scout"}}},
    [86574] = {n="Stonetalon Supply Run", d="Collect 6 Stonetalon Supplies from Pridewing Wyverns and deliver them to Innkeeper Faralia.", tgo={{"Young Pridewing", "Pridewing Wyvern", "Pridewing Skyhunter", "Pridewing Consort", "Pridewing Patriarch", "Freewind Post Wyvern"}}},
    [86585] = {n="Banner of the Fallen", d="Raise the standard of Ironforge, call out the trogg Headsplitter and kill it, then report to Captain Rugelfuss.", tgo={{"Headsplitter"}}},
    [86758] = {n="Twisting the Knife", d="Find and defeat the crocolisk Daggerfang and bring back Marek's knife.", tgo={{"Daggerfang"}}},
    [87288] = {n="Soft Saber Pelts", d="Bring 6 Soft Nightsaber Pelts to Aldria.", tgo={{"Nightsaber"}}},
    [87494] = {n="Microcrystal Contamination", d="Take the Crystal Infused Scale to Torwa Pathfinder.", tgo={{"Ravasaur", "Ravasaur Runner", "Ravasaur Hunter", "Venomhide Ravasaur", "Young Diemetradon", "Diemetradon", "Elder Diemetradon", "Fledgling Pterrordax"}}},
    [87760] = {n="Holy Diver", d="Find a Stormscale Beastmistress, slay her, and bring back her Rod of Deep Dominion.", tgo={{"Stormscale Beastmistress"}}},
    [90487] = {n="Ancient Allies", d="Travel west from the hermit's cave to find an outpost of ancients and dryads on the lower slopes of Mount Hyjal."},
    [90647] = {n="The Staff of the Mountain", d="Bring the Staff of the Mountain to Tiala Whitemane at the Summit of Eternity."},
    [90702] = {n="Disturbed Grave", d="Search the area for the grave's missing contents.", tgo={{"Fleshflay Ravener", "Fleshflayer Ravener"}}},
    [90750] = {n="More Work?", d="Speak with the peasant to let him know the job's done."},
    [90865] = {n="Eyes of the Watchers", d="Retrieve 8 Watcher's Eyes for Eluneth.", tgo={{"Eternal Sentry"}}},
    [91688] = {n="To the Summit of Eternity", d="Travel to the Summit of Eternity and speak with the druids about the survivor village."},
    [91696] = {n="Open Season", d="Escort the Barkskin Matriarch out of Deadwood Den and return to Barkskin Burrow."},
    [91697] = {n="Meet the Elders", d="Find and speak with Elder Mistpaw and Elder Pinespeaker within Barkskin Burrow."},
    [91698] = {n="Barkskin Breakout", d="Recover a Deadwood Key from a Deadwood Warden and return to the Barkskin Cage.", tgo={{"Deadwood Warden"}}},
    [91723] = {n="Delicate Instruments", d="Kill 8 Kobold Geomancers in Jasperlode Mine, then return to Hamish Bergwort in the Tower of Azora.", tgo={{"Kobold Geomancer"}}},
    [91732] = {n="Good Steel", d="Collect 4 Mining Tools from Jasperlode Mine, then return to Hagar Lowe in Eastvale Logging Camp.", objs={"Mining Tools"}},
    [91733] = {n="Downstream", d="Collect the Waterlogged Axe, Waterlogged Saw, and Waterlogged Toolbox that have washed downstream from Eastvale Logging Camp, then return to Ormin Pelford.", objs={"Waterlogged Axe", "Waterlogged Saw", "Waterlogged Toolbox"}},
    [91740] = {n="Croaky's Head", d="Deliver Croaky's Head to Merell Ross at Ridgepoint Tower."},
    [91741] = {n="Nibbled-On Book", d="Return the book to Brother Paxton."},
    [91743] = {n="Rascally Rodents", d="Retrieve 8 Stolen Books from kobolds in Northshire Valley and return them to Brother Paxton.", tgo={{"Kobold Vermin", "Kobold Laborer", "Kobold Worker"}}},
    [91745] = {n="Mining Consultant", d="Talk to Kelsey Fargo outside the Echo Ridge Mine in Northshire Valley."},
    [91752] = {n="The Big Picture", d="Retrieve a Sack of \"Picture\" Books from Shinyfinder Narf. Bring the sack to Marshal McBride just inside Northshire's Abbey.", tgo={{"Shinyfinder Narf"}}},
    [91753] = {n="An Enchanting Lesson", d="Kitta Firewind in the Tower of Azora wants you to collect 3 Luminous Residue.\nLuminous Residue can be obtained by disenchanting Crude Wax Effigies dropped by Kobold Geomancers."},
    [91754] = {n="Rub Some Dirt In It", d="Collect 6 samples of Untainted Soil from around the foothills of Mount Hyjal."},
    [91755] = {n="Leaves to Ligatures", d="Collect 12 Verdant Leaves from Tainted Shrubbery in the foothills of Mount Hyjal.", tgo={{"Tainted Shrubbery"}}},
    [91758] = {n="Follow That Kobold!", d="Speak to Tordrin Sternblade near the stable behind Northshire's Abbey."},
    [91770] = {n="Bark Bite", d="Apply the poultice to Fraxinus.", tgo={{"Fraxinus"}}},
    [91772] = {n="Shhh! We're Hunting Kobolds", d="Follow the kobold tracks and report to Marshal Dughan in Goldshire with your findings and the Kobold Tracking Kit.", objs={"Kobold Tracks"}},
    [91775] = {n="Book Return", d="Find 6 Lost Books and \"Fun with Elementals\" and return them to Marshal Dughan.", tgo={{"Nimsy"}, {"Kobold Miner", "Kobold Tunneler"}}},
    [91777] = {n="Rare Books", d="Recover \"Geomancy for Curious Young Wizards\" and \"Arcane Explainer: Magical Stuff in Simple Words\" and return them to Brother Paxton inside Northshire's Abbey.", tgo={{"Geosculptor Yip", "Kobold Geomancer"}, {"Mother Fang", "Kobold Geomancer"}}},
    [91881] = {n="The Western Post", d="Meet Sefira Everbright at the outpost."},
    [91883] = {n="Spear of the Skylord", d="Slay Zarrat Wormwing and return Omnuron's Spear.", tgo={{"Zarrat Wormwing"}}},
    [91923] = {n="Celastrus the Bitter", d="Find and destroy Celastrus the Bitter, and return to Thylaen with its broken frond.", tgo={{"Celastrus the Bitter"}}},
    [91952] = {n="The Source of the Corruption", d="Find the hermit Ketharas on Mount Hyjal."},
    [92008] = {n="Premiere Parts", d="Retrieve Kaylaena Springbolt's parts order from Nami in Everlook."},
    [92009] = {n="Crate Expectations", d="Gently transport the crate of parts and baubles to Kaylaena Springwhisper in Mount Hyjal."},
    [92011] = {n="Rubble Rummage", d="Scavenge the remains of the Horde base and return 5 Frayed Wire, 5 Scrap Metal, and 5 Calcified Excrement to Kaylaena."},
    [92014] = {n="Fox Hole", d="Return 9 Rustleaf Fox Tails to Johun \"Punchy\" Dillas in Hyjal.", tgo={{"Rustleaf Fox"}}},
